\subsection{Network architecture}\label{appen:network_architecture}

The neural network architecture considered herein is borrowed from \cite{François2025}. The RNN-FNN network is defined as a composition of two LSTM cells $\{ C_{l} \}_{l=1}^{2}$, two intermediary FFNN layers $\{ \mathcal{L}_{j} \}_{j=1}^{2}$ and a terminal FFNN layer $\mathcal{L}_{J}$, represented by the following functional form:
\begin{equation*}
    \tilde{\phi}_{\theta}(X_{t})=(\underbrace{ \mathcal{L}_{J} \circ \mathcal{L}_{2}\circ \mathcal{L}_{1}}_{\mbox{FFNN}}\circ \underbrace{C_{2}\circ  C_{1}}_{\mbox{LSTM}})(X_{t}).
\end{equation*}

Each LSTM cell $C_{l}$ maps a vector $Z^{(C,\,l-1)}_{t}$ of dimension $d^{(C,\, l-1)}$ to a new vector $Z^{(C,\, l)}_{t}$ of dimension $d^{(C,\, l)}$ based on the following equations, starting with $Z^{(C,\, 0)}_{t}=X_{t}$:
\begin{align*}
    i^{(l)} &= \mbox{sigm}(W_{i}^{(l)}Z_{t}^{(C,\, l-1)}+b_{i}^{(l)})\mbox{,}\\
    o^{(l)} &= \mbox{sigm}(W_{o}^{(l)}Z_{t}^{(C,\, l-1)}+b_{o}^{(l)})\mbox{,}\\
    c^{(l)} &= i^{(l)}\odot \mbox{tanh}(W_{c}^{(l)}Z_{t}^{(C,\, l-1)}+b_{c}^{(l)})\mbox{,}\\
    Z_{t}^{(C,\, l)} &= o_{t}^{(l)}\odot \mbox{tanh}(c^{(l)})\mbox{,}
\end{align*}
where $\mbox{sigm}(\cdot)$ and $\mbox{tanh}(\cdot)$ represent the sigmoid and hyperbolic tangent functions, applied element-wise, and $\odot$ denotes the Hadamard product. The FFNN layer $\mathcal{L}_{j}$ maps the input vector $Z^{(\mathcal{L},\, j-1)}_{t}$ of dimension $d^{(\mathcal{L},\, j-1)}$ to an output vector $Z^{(\mathcal{L},\, j)}_{t}$ of dimension $d^{(\mathcal{L},\, j)}$ by applying a linear transformation $T_{\mathcal{L}_{j}}(Z^{(\mathcal{L},\, j-1)}_{t})=W_{\mathcal{L}_{j}}Z^{(\mathcal{L},\, j-1)}_{t} + b_{\mathcal{L}_{j}}$ followed by a non-linear activation function $g_{\mathcal{L}_{j}}$. Thus, the operation for layer $\mathcal{L}_{j}$ is expressed as:
\[
\mathcal{L}_{j}(Z^{(\mathcal{L},\, j-1)}_{t})=(g_{\mathcal{L}_{j}} \circ T_{\mathcal{L}_{j}})(Z^{(\mathcal{L},\, j-1)}_{t})
\]
for $j\in\{1,...,L_{2},J\}$, where the initial input to the first FFNN layer is $Z^{(\mathcal{L},\, 0)}_{t}=Z^{(C,\, L_{1})}_{t}$.

The trainable parameters $\theta$ of the RNN-FNN network include:
\begin{itemize}
    \item For $L_{1}\geq l\geq 1$: $W_{i}^{(l)}$, $W_{o}^{(l)}$, $W_{c}^{(l)}\in \mathbb{R}^{d^{(C,\, l)}\times d^{(C,\, l-1)}}$ and $b_{i}^{(l)}$, $b_{o}^{(l)}$, $b_{c}^{(l)}\in \mathbb{R}^{d^{(C,\, l)}\times 1}$, with $d^{(C,\, 0)}$ representing the original dimension of the input vector.
    \item For $L_{2}\geq j\geq 1$: $W_{\mathcal{L}_{j}}\in \mathbb{R}^{d^{(\mathcal{L},\, j)}\times d^{(\mathcal{L},\, j-1)}}$ and $b_{\mathcal{L}_{j}}\in \mathbb{R}^{d^{(\mathcal{L},\, j)}}$, with $d^{(\mathcal{L},\, 0)}=d^{(C,\, L_{1})}$.
    \item For $j=J$: $W_{\mathcal{L}_{J}}\in \mathbb{R}^{2\times d^{(\mathcal{L},\, L_{2})}}$ and $b_{\mathcal{L}_{J}}\in \mathbb{R}$.
\end{itemize}

%For more details about the architecture, see \cite{François2025}.
The hyperparameter values chosen for our experiments are specified in Section \ref{subsub:network_architecture}.

