Observe that, with a slight abuse of notation, we denote with $f$ an equivalence class of functions $[f]\in\cH^{(1)}$. The space
$\cH^{(1)}$ is equipped with a complex structure induced by $\iota: X\to X$ which is completely identified by its action on $\mathcal{S}(\bR)$, namely $\mathcal{S}(\bR)\ni f\mapsto\widehat{\iota f} = i \,{\rm sign}(E)\widehat f(E)$.
In addition we consider a symplectic form $\beta$ on $X$ which is also defined starting from its action on $\mathcal{S}(\bR)$, namely
\begin{equation}\label{symp}
{\mathcal{S}(\bR)\times}\mathcal{S}(\bR)\ni (f,h)\mapsto\beta(f,h)=\frac{1}{2}\int_\RR f'(u)h(u)du.
\end{equation}

\noindent We exploit Equations \eqref{Eq: Real Scalar Product} and \eqref{symp} to identify the following complex scalar product on $\cH^{(1)}$:
\[
\langle f,h\rangle=\langle f,h\rangle_\bR+i \beta(f,h) ={ \int_0^{+\infty} \hat f(-E) \hat h(E) E\,dE = \lim\limits_{\epsilon\to 0^+}\frac 1 {2\pi} \int_{\RR\times\RR} \frac{f(u) h(u')}{(u-u'-i\epsilon)^2}du\,du' \,.}
\]
The space $\cH^{(1)}$ carries the irreducible, positive energy, unitary representation $U^{(1)}$ of $\mathrm{PSL}(2,\RR)$ with lowest weight $1$, whose action {is defined on real smooth functions on the one-point compactification of $\RR$ as}
\begin{equation}\label{Eq: U representation of PSL(2,R)}
(U^{(1)}(g)f)(u)=f(g^{-1}u)\, ,
\end{equation}
{and extended by density to $\cH^{(1)}$. In the above formula, the action on $\RR$ of }$g=\left(\begin{array}{cc} a&b\\c&d
\end{array}\right)\in\mathrm{SL}(2,\RR)$ {is defined by }$gu=\frac{au+b}{cu+d}$. In particular, we will make use of the 1-parameter subgroups of $\mathrm{SL}(2,\RR)$ of translations and dilations, defined respectively by
\begin{equation}\label{eq:transdil}
\tau_{\RR_+}(s)u := u+s, \qquad \delta_{\RR_+}(s)u := e^s u, \qquad u, s \in \RR.
\end{equation}

Denoting by $\cI_0$ the set of open intervals of the real line, the M\"obius covariant net $H^{(1)}$ of standard subspaces of $\cH^{(1)}$ associated with {the $U(1)$-current} is given by
\[
\cI_0\ni I\mapsto H^{(1)}(I)=\big\{[f] \in \cH^{(1)}:   f \in \cC^\infty_0(\RR), \,\mathrm{supp}\,f\subset I\big\}^-\,. 
\]
Here we have reintroduced equivalence classes to avoid a source of confusion.
\begin{remark}\label{rem:propertiescurrent}
Let $\cI$ be the set of {non-dense} open intervals of the compactified line $\overline{\RR}\equiv\bS^1$ and {for $I \in \cI$ let $I'$ be the interior of} $\bS^1\setminus I$.  We observe that the net
$$\cI_0\ni I\mapsto H^{(1)}(I){\subset \cH^{(1)}},$$
extends to a counterpart on $\bar \RR$ and it satisfies the following properties:
 \begin{enumerate}
\item \emph{Isotony:} $I_1 \subset  I_2 \implies H^{(1)}(I_1) \subset H^{(1)}(I_2)$ ; 
\item \emph{Locality:} $I_1 \subset I'_2 \implies H^{(1)}(I_1) \subset H^{(1)}(I_2)'$;
\item \emph{Möbius covariance:} There exists a unitary, positive energy representation $U^{(1)}$ of the M\"obius group on $\cH{^{(1)}}$ such that $U^{(1)}(g)H^{(1)}(I) = H^{(1)}(gI)$, $I\in\cI$;
\item \emph{Standardness:} $H^{(1)}(I) $ is standard for every $I\in\cI$;
\item \emph{Haag duality:} $H^{(1)}(I') = H^{(1)}(I)'$ for all $I\in \cI$; 
\item \emph{Bisognano-Wichmann property:} $U{^{(1)}}\big(\delta_I(-2\pi s)\big)=\Delta_{H^{(1)}(I)}^{is}$ where $\delta_I$ is the one-parameter group of ``dilations'' acting on $I${, i.e., $\delta_I(s) = g_I^{-1} \delta_{\RR_+}(s) g_I$, with $g_I \in \mathrm{SL}(2,\RR)$ such that $g_I I = \RR_+$}.
\end{enumerate}
It follows from the Bisognano-Wichmann property that, if $I_1\subset I_2$ is an inclusion of intervals on the circle with the same (anti-clockwise) endpoint,  then $H^{(1)}(I_1)\subset H^{(1)}(I_2)$ is an half-sided modular inclusion, see Equation \eqref{Eq: Half Sided Modular Inclusion}. Most notably, this result also applies in the real-line picture when $I_1\subset I_2\subset\RR$ where both $I_1$ and $I_2$ are half-lines.
\end{remark}

