\subsection{One particle net on $\Im^+$}
Recalling that on $\Im^+$ we are considering the Hilbert space $\mathcal{H}$ identified in Equation \eqref{eq:hilbsp}, we can define the real one particle subspace associated to an open region $\sO\subset\Im^+$ as
\begin{equation}\label{def:H}
\sO\longmapsto H(\sO)=\overline{\{\psi\in\cC_0^\infty(\Im^+)\;\textrm{such that}\;\textrm{supp} (\psi)\subset \sO\}}^{\|\cdot\|_\cH}\,.
\end{equation}
In the following we prove a result on the structure of the one-particle Hilbert space on $\scri$ in a setting which is slightly more general that the one needed in this work.

\begin{lemma}\label{lem:dirint} Consider $c_1,c_2\in \mathbb{R}\cup\{\pm\infty\}$ with $c_1< c_2$ as well as {an open set} $A\subset\bS^2$. If we denote by
$$\sR=\{(u,\theta,\varphi)\;|\; c_1<u<c_2\;\textrm{and}\;(\theta,\varphi)\in A\}\subset\scri,$$
then the local subspace $H(R)$ decomposes as
     \begin{align}\label{eq:disrect}
       H(\sR) = \int^{\oplus_\RR}_{A} H^{(1)}(c_1,c_2)\, d\bS^2\subseteq \int^{\oplus_\RR}_{\bS^2}\cH^{(1)} d\bS^2.
          \end{align}
 Then $H(\sR)$ is separating for any $\sR = (c_1,c_2)\times A$ where $(c_1,c_2)\subset\mathbb R$ is proper,
  and standard if {also $\bS^2 \setminus A$ is a null set}. 
\end{lemma}
\begin{proof}
On account of Equation~\eqref{eq:hilbsp}, the  Hilbert space $\cH$ can be identified with $\int_{\mathbb{S}^2}^{\oplus} \cH^{(1)}d\mathbb{S}^2$. Furthermore, setting $I := (c_1,c_2)$, there holds the following unitary equivalence: 
    $$H^{(1)}(I)\otimes_\RR L^2(A;d\mathbb{S}^2)\simeq\int^{{\oplus_\RR}}_{A}  H^{(1)}(I)d\mathbb{S}^2 \subset\cH.$$
However, notice that { the elements $f \otimes h$ with $f \in \cC^\infty_0(I)$, $h \in \cC_0^\infty(A)$, form a total set in $ H^{(1)}(I)\otimes_\RR L^2(A,d\mathbb{S}^2)$, and that} $H(\sR)$ contains all functions of the form {$(u,\theta,\varphi) \mapsto f(u)h(\theta,\varphi)$ for all such $f$ and $h$. It is then sufficient to show that these functions form a total set in $H(\sR)$ too. To this end, observe first that if $\psi \in H(\sR) \subset L^2(\RR_+\times \mathbb{S}^2, E\,dEd\mathbb{S}^2)$, there exists a sequence $\{\psi_k\} \subset \cC^\infty_0(\scri)$ with $\supp \psi_k \subset \sR$ such that
\[
\|\psi-\psi_k\|^2 = \int_{\bS^2} d\bS^2(\bn) \int_0^{+\infty} dE\,E |\hat\psi(E,\bn)-\hat\psi_k(E,\bn)|^2 \to 0.
\]
This entails, passing to a subsequence if necessary, that $\psi(\cdot,\bn)$ is the limit in $\cH^{(1)}$ of $\{\psi_k(\cdot,\bn)\} \subset \cC^\infty_0(I)$ for almost all $\bn \in \bS^2$. Therefore $\psi(\cdot,\bn) \in H^{(1)}(I)$ for almost all $\bn \in \bS^2$, and $\psi(\cdot,\bn) = 0$ for almost all $\bn \not\in A$.
Assume now that $\psi \in H(R)$ is such that, for all $f \in \cC^\infty_0(I)$, $h \in \cC_0^\infty(A)$,
\[
\langle \psi, f h \rangle_{\cH} = \int_{A}d\bS^2(\bn) h(\bn) \int_0^{+\infty}dE\,E \hat \psi(-E,\bn) \hat f(E) = 0.
\]
By the density of $\cC_0^\infty(A)$ in $L^2(A,\bS^2)$, it follows that for all $f \in\cC^\infty_0(I)$ there is a null set $N_f \subset \bS^2$ such that
\[
\int_0^{+\infty}dE \,E\hat\psi(-E,\bn) \hat f(E) = 0, \qquad \forall \bn \in \bS^2\setminus N_f.
\] 
In turn, since $\cC^\infty_0(I)$ is dense in $H^{(1)}(I)$ which is separable, we can find a sequence $\{f_k\} \subset \cC^\infty_0(I)$ dense in $H^{(1)}(I)$, so that the last equation together with the fact that $\psi(\cdot, \bn) \in H^{(1)}(I)$ finally implies that $\psi = 0$. Consequently the functions $(u,\theta,\varphi) \mapsto f(u)h(\theta,\varphi)$, $f \in \cC^\infty_0(I)$, $g \in \cC_0^\infty(A)$, form a total set in $H(\sR)$ and Equation~\eqref{eq:disrect} is proven.} 

The statements about the separating and cyclicity properties of $H(R)$ follow from the above direct integral decomposition and from Lemma \ref{lem:propertiesstandard}{, observing that
\[
H(\sR) = \int_{\bS^2}^{\oplus_\RR} H^{(1)}(I) \chi_A(\bn) \,d\bS^2(\bn) \quad \Rightarrow \quad H(\sR)' =  \int_{\bS^2}^{\oplus_\RR}[ H^{(1)}(I)' \chi_A(\bn)+\cH^{(1)}\chi_{\bS^2\setminus A}(\bn)] \,d\bS^2(\bn),
\]
and recalling that $H^{(1)}(I)$ is cyclic and separating for all proper intervals $I \subset \RR$, and that $H(\sR)$ is cyclic if and only if $H(\sR)'$ is separating.}
\end{proof}

Given $C\in\cC^0(\bS^2)$, we define a distorted lightlike translation as the following unitary operator on the direct integral picture of $\cH$:

   \begin{align}\label{eq:non-const-translation}
    (T_C \xi)(u,\theta,\varphi) =  \xi(u-C(\theta,\varphi), \theta,\varphi).
   \end{align}

\noindent Similarly, we define the distorted lightlike dilations as
   \begin{align}\label{eq:non-const-dilations}
    (D_C\xi)(u,\theta,\varphi) = \xi(e^{-C(\theta,\varphi)}u, \theta,\varphi).
   \end{align}
If $C$ is constant, these maps coincide with the usual translations and the dilations.

\begin{proposition}\label{pr:null-covariance}
The family of real subspaces $H(\sO)$, see Definition \ref{def:H}, indexed by open connected regions $\sO\subset\Im^+$, is covariant with respect to $T_C, D_C$, $C\in\cC^0(\bS^2)$, namely 
$$T_C H(\sO) = H(\sO+C)\quad\textrm{and}\quad D_{C} H(\sO) = H(e^{C}\cdot \sO),$$
where $\sO + C = \{(u + C(\theta,\varphi), \theta,\varphi): (u,\theta,\varphi) \in \sO\}$
and $e^C\cdot \sO = \{(e^{C(\theta,\varphi)}u, \theta,\varphi): (u, \theta,\varphi) \in \sO\}$ {are open subsets of $\scri$}.
\end{proposition}

\begin{proof}
On the Hilbert space $\cH=\int_{\mathbb{S}^2}^\oplus \cH^{(1)}\;d\mathbb{S}^2$ distorted translations and dilations act as
$$T_C= \int_{\mathbb{S}^2}^\oplus U^{(1)}(\tau_{\RR_+}(C(\theta,\varphi)))\;d\mathbb{S}^2 \;\;\text{and}\;\;D_C= \int_{\mathbb{S}^2}^\oplus U^{(1)}(\delta_{\RR_{+}}(C(\theta,\varphi)))\;d\mathbb{S}^2,$$
where $U^{(1)}$ {and $\tau_{\RR_+}$, $\delta_{\RR_+}$ are} defined in Equations\ \eqref{Eq: U representation of PSL(2,R)}, {\eqref{eq:transdil}.}
The operators $T_C$ and $D_C$ are unitaries on $\cH$ since they are defined as direct integrals of unitary operators. Considering  $\xi\in\cC_0^\infty(\Im^+)$ supported in $\sO$, in the direct integral picture we have that $(T_C\xi)(u,\theta,\varphi)=\xi(u-C(\theta,\varphi),\theta,\varphi)$ and $(D_C\xi)(u,\theta,\varphi)=\xi(e^{-C(\theta,\varphi)}u,\theta,\varphi)$  are smooth functions compactly supported in $\sO + C $ and $e^C\cdot \sO$ respectively. By a density argument {and unitarity} we can infer the covariance property.
\end{proof}

\noindent The net $\Im^+\supset\sO\mapsto H(\sO)$ satisfies the following properties:
\begin{enumerate}
\item \textit{Isotony:} $$\sO_1\subseteq \sO_2,\; \text{then }\;H(\sO_1)\subseteq H(\sO_2)\,;$$
\item \textit{Locality:} $$\sO_1\cap\sO_2=\emptyset\; \text{then }\;H(\sO_1)\subseteq H(\sO_2)'\,;$$
\item \textit{Standardness:} The subspaces  $H(\sO)$ are standard/cyclic/separating according to Lemma \ref{lem:dirint}; 
\item \textit{Covariance:} $$T_CH(\sO)=H(\sO+C)\,, \qquad D_C H(\sO)=H(e^C\cdot \sO)\,.$$
\end{enumerate}

\noindent As a direct consequence of the properties that $T_C$ is decomposable and $H(\sR+C)=T_C H(\sR)$, the following corollary holds true.

\begin{corollary}\label{cor:stripdis}
Consider $c_1,c_2\in \mathbb{R}\cup\{\pm\infty\}$ with $c_1< c_2$ as well as $A\subset\bS^2$ {open, and set $\sR := (c_1,c_2)\times A$}. Given $C\in\cC^0(\mathbb{S}^2)$, then 
$$H(\sR+C)=\int_A^{\oplus_\RR} H^{(1)}(c_1+C(\theta,\varphi),c_2+C(\theta,\varphi)) d\mathbb{S}^2\subseteq \int_{\mathbb{S}^2}^\oplus \cH^{(1)}d\mathbb{S}^2\,.$$
As in Lemma \ref{lem:dirint}, $H(\sR+C)$ is separating for any $\sR=(c_1,c_2)\times A$ where $(c_1,c_2)\subset \RR$ is proper, and standard if {$\mathbb{S}^2\setminus A$ is a null set}. In particular, for a continuous function $C:\bS^2\rightarrow \RR$,
\begin{gather}\label{eq:HSC}
H(\mathsf{S}_C)={T_C H((0,+\infty)\times\bS^2)=}\int_{\bS^2}^{\oplus_\RR} H^{(1)}(C(\theta,\varphi),+\infty) d\mathbb{S}^2(\theta,\varphi)
\end{gather}
is a standard subspace.
\end{corollary}

