\begin{lemma}
Given $(M,g)$ as in Section \ref{sec:geometry} and a conformal factor $\Omega = 2\chi^{-1} \cos V$ in a neighbourhood of $\Im^+$, 
where $V$ is defined as in Equation \eqref{Eq: U and V}, then, for $f \in \cC^\infty_0(M)$, it holds that
\[
\Upsilon_M([f])(u,\boldsymbol{n}) =  \int_{\RR^3} d\boldsymbol{x}\, (\chi^3 f)(u+\boldsymbol{n}\cdot \boldsymbol{x}, \boldsymbol{x}), \qquad (u,\boldsymbol{n}) \in \RR \times \mathbb{S}^2,
\]
where $\Upsilon_M$ is defined in Equation \eqref{Eq: Upsilon}.
\end{lemma}

\begin{proof}
Considering the operator $P$ as in Equation \eqref{eq:wave}, we denote by $\mathcal G_{\bM}$ its causal propagator on Minkowski spacetime, by $\mathcal G$ that on $M$ and by $\widetilde {\mathcal G}$ that on $\widetilde M$. They are connected by Equation \eqref{Eq:forseserveforseno}, namely
\[
\mathcal G = \chi^{-1} \circ \mathcal{G}_{\bM} \circ \chi^3, \qquad \widetilde{\mathcal G}|_{C_0^\infty(M)} = \Omega^{-1} \circ \mathcal G \circ \Omega^{3}.
\]
Consequently, on account of Equation \eqref{Eq: Upsilon}, $\Upsilon_M([f]) = (\Omega\chi)^{-1} \mathcal{G}_{\bM}(\chi^3 f)|_{\Im^+}$. Working in light cone coordinates $v = y_0 + r$, $u = y_0-r$, $\boldsymbol{n} = \frac1r \boldsymbol{y}$ and for $v > u$,
\[\begin{split}
\mathcal G_{\bM}(\chi^3 f)&(y_0,\boldsymbol{y}) \\
&= \frac2{v-u}\int_{\RR^3} \frac{d\boldsymbol{x}}{|\boldsymbol{n}- \frac{2\boldsymbol{x}}{v-u}|} \left[(\chi^3f)\left(\frac{v}2\left(1-\left|\boldsymbol{n}-\frac{2\boldsymbol{x}}{v-u}\right|\right)+\frac{u}2\left(1+\left|\boldsymbol{n}-\frac{2\boldsymbol{x}}{v-u}\right|\right),\boldsymbol{x}\right)\right.\\
&\phantom{\frac2{v-u}\int_{\RR^3} \frac{d\boldsymbol{x}}{|\boldsymbol{n}- \frac{2\boldsymbol{x}}{v-u}|} \left[\right.}-\left.  (\chi^3f)\left(\frac{v}2\left(1+\left|\boldsymbol{n}-\frac{2\boldsymbol{x}}{v-u}\right|\right)+\frac{u}2\left(1-\left|\boldsymbol{n}-\frac{2\boldsymbol{x}}{v-u}\right|\right),\boldsymbol{x}\right)\right].
\end{split}\]
Taking into account that, in a neighbourhood of $\Im^+$, $\Omega \chi = 2 \cos V = 2(1+v^2)^{-1/2}$, see Remark \ref{Rem: Trick Limit}, { that $|\bn-\frac{2\bx}{v-u}| =1- \frac{2\bn\cdot\bx}v+o(v^{-1})$ as $v \to +\infty$,} and that $\chi^3 f$ has compact support, it descends that the integrand of the above expression, divided by $\Omega \chi$, converges, as $v \to +\infty$, for fixed $u \in \RR$, to
\[
(\chi^3 f)(u+\boldsymbol{n}\cdot \boldsymbol{x},\boldsymbol{x}).
\]
Moreover, if we denote by $K \subset \RR^3$ the compact set which is the projection on $\RR^3$ of the support of $\chi^3 f$, we can find $c > 0$ such that the bit of the integrand between square brackets in the above integral is bounded by $c\chi_K(\bx)$, $\chi_K$ being the restriction of $\chi$ to $K$. In addition,  if $R > 0$ is such that $\bx \in K$ implies $|\bx| < R$, we can find $v$ such that
\[
\frac{2R}{v-u} < \frac12 \quad \Rightarrow \quad \left|\boldsymbol{n}-\frac{2\bx}{v-u}\right| \geq \left|1 - \frac{2|\bx|}{v-u}\right| > 1-\frac{2R}{v-u} > \frac12. 
\]
Therefore the statement follows by applying the dominated convergence theorem.
\end{proof}

