\section{Direct integrals of Hilbert spaces}\label{app:directintegral}

Since in our construction we also exploit the properties of direct integrals of standard subspaces, in this appendix we recollect some basic definitions and results, pointing an interested reader to \cite[Appendix B]{MT19} for additional details.


Let $X$ be a $\sigma$-compact, locally compact space endowed with $\nu$, the completion of a Borel measure thereon. In addition we consider a separable {complex (resp.\ real)} Hilbert space $\K$ together with $\{\K_\l  \}$ a family of separable  {complex (resp.\ real)} Hilbert spaces indexed by $\l\in X$. We also require that, to each $\xi\in \K$ there corresponds {linearly} a function $\l\mapsto \xi(\l) \in \K_\l$ such that 
\begin{enumerate}
	\item $\l\mapsto \langle\xi(\l),\eta(\l)\rangle$ is $\nu$-integrable and $\langle{\xi,\eta}\rangle=\int_X \langle\xi(\l),\eta(\l)\rangle d\nu(\l)$ for all $\xi, \eta \in \K$;
	\item if $\phi_\l \in \K_\l$ for all $\l$ and $\l\mapsto \langle{\phi_\l,\eta(\l)}\rangle$ is integrable for all $\eta\in \K$, there exists $\phi\in \K$ such that $\phi(\l)=\phi_\l$ for almost every $\l$.
\end{enumerate}
Under these assumptions $\K$ is the \textit{direct integral} of {the measurable field of Hilbert spaces} $\{ \K_\l\}$ over $(X,\nu)$, and we write
\begin{align*}
	\K=\int_X^{\oplus_{(\mathbb{R})}} \K_\l d\nu(\l),
\end{align*}
where we employ the subscript $\mathbb{R}$ when we consider direct integrals of real spaces. {The direct integral is uniquely determined, up to unitary equivalence, by $\{\K_\lambda\}$ and $\nu$. A $\xi \in \K$ corresponding as above to the function $\lambda \mapsto \xi(\lambda) \in \K_\lambda$, we will be written as $\xi = \int_X^\oplus \xi(\lambda)\,d\nu(\lambda)$.}

As a particular case, let $\mathcal{K}= \int_X^\oplus \mathcal{K}_0 d\nu$ be a direct integral Hilbert space over the constant field $\mathcal{K}_0$, where $\K$  is a separable Hilbert space. Then it holds that \cite[Proposition II.1.8.11, Corollary p. 175]{Dixmier81}
\begin{align}\label{integral=tensor-prod}
	\int_X^\oplus \mathcal{K}_0 d\nu(\l) \simeq L^2(X,\nu)\otimes \mathcal{K}_0.
\end{align}


\begin{lemma}\label{lem:propertiesstandard}\cite[Lemma B.3]{MT19}
	Given a separable Hilbert space $\cK$ which decomposes as $\cK=\int_X^\oplus \cK_\lambda d\nu(\lambda)$ then
	\begin{itemize}
		\item[(a)]
		given  $H=\int_X^{\oplus_\RR} H_\lambda d\nu(\lambda)\subset \cK$ such that  $H_\lambda\subset \cK_\lambda$ for all $\lambda \in X$,
		then $H'=\int_X^{\oplus_\RR} H'_\lambda d\nu(\lambda)$, $H^\prime$ being the symplectic complement;

		\item[(b)] let $\{H_k\}_{k\in\NN}$ be a countable family of real subspaces of $\cK$ such that  $H_k=\int_X^{\oplus_\RR} (H_k)_\lambda d\nu(\lambda)$
		and  $(H_k)_\lambda\subset \cK_\lambda$ {is a real subspace} for all $\lambda\in X$, then  $\bigcap_{k\in\NN} H_k=\int_X^{\oplus_\RR} \bigcap_{k\in\NN} (H_k)_\lambda d\nu(\lambda)$;

		\item[(c)]  Let $\{H_k\}_{k\in\NN}$ be a countable family of real subspaces of $\cK$ such that  $H_k=\int_X^{\oplus_\RR} (H_k)_\lambda d\nu(\lambda)$ and  $(H_k)_\lambda\subset \cK_\lambda$ {is a real subspace} for all $\lambda\in X$, then  $\overline{\Span_{k\in\NN} H_k}=\int_X^{\oplus_\RR} \overline{\Span_{k\in\NN} (H_k) }_\lambda d\nu(\lambda)$.
	\end{itemize}
\end{lemma}

A (possibily unbounded) operator $T$ on $\K = \int^{\oplus}_X \K_\lambda d\nu(\lambda)$ is said to be \textit{decomposable} if {there exist} (possibly unbounded) operators $T_\l$ on $\K_\lambda$ {, $\lambda \in X$, such that} for each $\xi \in D(T)$, one has $\xi(\lambda) \in D(T_\lambda)$ and $T_\l \xi(\l)=(T\xi)(\l)$ for $\nu$-almost every $\l$. {This is denoted by $T = \int_X^\oplus T_\l d\nu(\l)$.} In addition, if there exists $f\in L^\infty(X,\nu)$ such that $T_\l =f(\l)1$, we say that $T$ is \textit{diagonalizable}.

Let $G$ be a locally compact group and let $\pi$ be a strongly continuous unitary representation of $G$ on $\cK=\int^\oplus_X \cK_\lambda d\nu(\lambda)$. Suppose that, for each $g\in G$, $\pi(g)=\int^\oplus \pi_\lambda (g) d\mu(\lambda)$, then we say that $\pi$ is the \textit{direct integral} of $\pi_\lambda $, $\lambda\in X$: 
\begin{align*}
	\pi=\int^\oplus_X \pi_\lambda d\nu(\lambda).
\end{align*}
Equivalently, $\pi$ is a direct integral if each $\pi(g), \ g\in G$, is decomposable. Furthermore, if $H=\int_X^{\oplus_\RR} H_\lambda d\nu(\lambda)$ {is a standard subspace of $\K = \int_X^\oplus \K_\lambda d\nu(\lambda)$, with $H_\lambda$ standard in $\K_\lambda$, $\lambda \in X$}, we can apply these constructions to the modular data introduced in Section \ref{Sec: Standard Subspaces}:
$$\Delta^{it}_H=\int_X^\oplus\Delta^{it}_{H_\lambda}d\nu(\lambda),\quad J_H=\int_X^\oplus J_{H_\lambda}d\nu(\lambda),$$
where $( J_{H_\lambda},\Delta^{it}_{H_\lambda})$ are respectively the modular conjugation and the modular group associated to $H_\lambda $ as a standard subspace of $\cH_\lambda$. 
Given a Borel function $f:\RR_+\rightarrow\RR$, it holds that
	$$f(\Delta_H)=\int_{X}^\oplus f(\Delta_{H_\lambda})d\nu(\lambda),$$  
which entails in particular
	\begin{equation}\label{eq:logint}
		\log(\Delta_H)=\int_{X}^\oplus \log(\Delta_{H_\lambda})d\nu(\lambda),
		\end{equation}  
	see \cite[Thm.~A.1]{MTW}.


{In this context, it is worth observing the following decomposition result for the relative entropy of coherent states on a second quantization von Neumann algebra (cf.\ App.~\ref{app:secondquant}), whose proof is given in \cite[Lem.\ 5.1]{MTW}.

\begin{lemma}\label{lem:decomposableentropy}
Consider a standard subspace $H=\int_X^{\oplus_\RR}H_\lambda d\nu(\lambda)\subset \int_X^{\oplus} \K_\lambda d\nu(\lambda)=\K$, where $H_\lambda$ is standard in $\K_\lambda$, $\lambda \in X$. Given $\psi=\int_X^\oplus \psi(\lambda)d\nu(\lambda) \in \K$, the relative entropy between the coherent state $\omega_\psi$ and the Fock vacuum $\omega$ on the second quantization von Neumann algebra $R(H)$ can be written as
 $$S_{R(H)}(\omega_\psi\|\omega)=\int_X S_{R(H_\lambda)}(\omega_{\psi(\lambda)} \|\omega(\lambda))d\nu(\lambda)\,,$$ 
 where $\omega(\lambda)$ denotes the vacuum on the Fock space associated to $\K_\lambda$.
\end{lemma}
}

\section{Second quantization}\label{app:secondquant}
In this short appendix, we consider a complex Hilbert space $\cH$ and we recall some basic facts concerning the construction of the Weyl algebra associated to it. Our starting point is the Bosonic Fock space is $\mathcal{F}(\cH)=\bigoplus_{n=1}^\infty\cH^{\otimes^n_s}\oplus \bC$ where $\otimes^n_s$ is the $n$-times symmetrized tensor product. On top of it, one can define the Weyl unitary operators
$$\cH\ni h\mapsto W(h)\in \cF(\cH),$$
satisfying
$$W(h)W(k)=e^{-\frac12\Im(h,k)}W(h+k),\quad \omega(W(h))=(\Omega,W(h)\Omega)=e^{-\frac14\|h\|^2},$$
where $\Omega=(1,0,\dots)\in\mathcal{F}(\cH)$ is referred to as vacuum vector. Given a real subspace $H\subset \cH$, we denote by 
$R(H)$ the von Neumann algebra generated by the Weyl operators as 
\begin{equation}\label{Eq: VN algebras}
	R(H)=\{W(h):h\in H\}''\subset\cB(\cF(\cH)).
\end{equation}

\noindent Note that, by the strong continuity of Weyl operators, 
\[
R(H) = R(\overline{H})\ .
\]
Moreover $\Omega$ is cyclic (resp.\ separating) for $R(H)$ if and only if $\overline{H}$ is cyclic (resp.\ separating). If $H$ is standard, see Section \ref{Sec: Standard Subspaces}, we denote by $S_{R(H),\Omega}$, $J_{R(H),\Omega}$, $\Delta_{R(H),\Omega}$ the modular operators associated with $(R(H),\Omega)$, and by
$\mathit{\Gamma}(T)$  {the operator on $\cF(\cH)$ obtained by the multiplicative second quantization} of a one-particle operator $T$ on $\cH$. {Then one has the following properties, whose proof can be found, e.g., in~\cite{Lo08}.}

\begin{proposition}\label{prop:secquant}
	Let $H$ and $\{H_a\}_{a\in I}$ be {standard} subspaces of $\cH$. It holds that
	\begin{itemize}
		\item[$(a)$] $S_{R(H),\Omega} = \mathit{\Gamma}(S_H)$, \ $J_{R(H),\Omega} = \mathit{\Gamma}(J_H)$, \ $\Delta_{R(H),\Omega}= \mathit{\Gamma}(\Delta_H)$, 
		\item[$(b)$] $R(H)' = R(H')$, where $H^\prime$ is the symplectic complement,
		\item[$(c)$] $R(\sum_a H_a) = \bigvee_a R(H_a)$,
		\item[$(d)$] $R(\cap_a H_a) = \bigcap_a R(H_a)$,
	\end{itemize}
	where $\bigvee$ denotes the generated von Neumann algebra.
\end{proposition}

\section{Penrose Compactification of Minkowski space}\label{app:a}
{
In this appendix, we review succinctly the Penrose compactification of a four-dimensional, globally hyperbolic, spacetime $(M,g)$ such that $g=\chi^2\eta$ with $\chi\in \cC^\infty(\mathbb{R}^4,(0,\infty))$, hence providing an explicit example of the construction of $\scri$ sketched in Section \ref{sec:geometry}. We endow $M$ with the standard Cartesian coordinates $(t,\bx)\equiv (t,x_1,x_2,x_3)$ so that the line element reads
$$ds^2=\chi^2\left(-dt^2+dx_1^2+dx_2^2+dx_3^2.\right),$$ 
where we omit for simplicity of the notation the dependence of $\chi$ on the underlying coordinates, that is $\chi\equiv\chi(t,x_1,x_2,x_3)$. Switching to the standard spherical coordinates, namely 
\begin{equation}
\left\{ \begin{aligned} 
  x_1 &= r\cos\theta\sin\varphi\\
  x_2 &= r\sin\theta\sin\varphi\\
  x_3 &= r\cos\varphi
  \end{aligned} \right.
\end{equation}
where $r^2=\|\bx\|^2$ while $(\theta,\varphi)\in \mathbb{S}^2$, we obtain 
$$ds^2=\chi^2\left(-dt^2 + dr^2 + r^2(d\theta^2 + \sin^2\theta d \varphi^2)\right)$$ 
\noindent We introduce the advanced and retarded null coordinates 
\begin{equation}\label{eq:nullcoord}
\left\{ \begin{aligned} 
  u &= t-r\\
  v &= t+r
  \end{aligned} \right.
\end{equation}

\noindent In the new coordinates $(u,v,\theta,\varphi)$ the line element becomes 
$$ds^2 = \chi^2\left(-dudv + \frac{1}{4}(v-u)^2(d\theta^2 + \sin^2\theta d\varphi^2)\right)\,.$$ 
We rescale these new coordinates introducing $U,V \in (-\frac{\pi}{2},\frac{\pi}{2})$ such that 
\begin{equation}\label{Eq: U and V}
\left\{ \begin{aligned} 
  u &= \tan(U)\\
  v &= \tan(V)
  \end{aligned} \right. .
\end{equation}

\noindent With this choice we have $du=\frac{1}{\cos^2(U)}dU$, and analogously $dv=\frac{1}{\cos^2(V)}dV$; therefore
$$ds^2=\frac{\chi^2}{\cos^2(V)\cos^2(U)}\left(-dUdV + \frac{1}{4}\sin^2(V-U)(d\theta^2 + \sin^2\theta d\varphi^2) \right)\,.$$

\noindent In order to choose a conformal compactification of $M$, we set $\Omega(U,V,\theta,\varphi):=\chi^{-1}\cos(U)\cos(V)$ so that the line element associated to $\widetilde{g}:=\Omega^2 g$ reads
$$d\widetilde{s}^2=-dUdV + \frac{1}{4}\sin^2(V-U)(d\theta^2 + \sin^2\theta d\varphi^2)\,,$$
or, equivalently, introducing \begin{equation}
\left\{ \begin{aligned} 
  T&= V+U\\
  R &= V-U
  \end{aligned} \right. ,
\end{equation}
\begin{equation}\label{eq:einsteinstatic}
d\widetilde{s}^2=-dT^2+dR^2+\sin^2 R(d\theta^2 + \sin^2\theta d\varphi^2)\,.
\end{equation}
This allows to identify $(M,g)$ as a (conformal) subset of the Einstein static Universe. Observe that $R>0$ since $V-U=\arctan(v)-\arctan(u)$ and $v-u=2r>0$.}\\


\begin{lemma}\label{lem:limitcomponents}
Let $x=(t,\bx) \in M$ with $\bx=(x_1,x_2,x_3)$. Consider a unit vector $\bn\in\mathbb{S}^2$ and let $\xi_{\lambda,\bn}=(\lambda,\lambda\bn)$, $\lambda\in\bR$. Denote with $(u,\theta,\varphi)$ the coordinates on $\Im^+$. Then $$\Im^+ \ni \lim\limits_{\lambda\to +\infty} x+\xi_{\lambda,\bn}=(t-\bx\cdot\bn, \bn)\,.$$ 
\end{lemma}

\begin{proof}
Denote $u_{x,\bn}(\lambda)$ the first coordinate of $x+\xi_{\lambda,\bn}$ in the null coordinates $(u,v)$, see Equation $\eqref{eq:nullcoord}$. Then, 
\begin{eqnarray}
\nonumber
u_{x,\bn}(\lambda)&:=&(t+\lambda) - \|\bx-\lambda\bn\|=(t+\lambda) - \sqrt{\sum_{i=1}^{3}(x_i + \lambda n_i)^2}\\
\nonumber
& = & (t+\lambda)-\sqrt{\|\bx\|^2 + \|\lambda\bn\|^2 + 2\lambda\,\bx\cdot \bn}\\
\nonumber
&=& \left((t+\lambda)^2-\|\bx\|^2 - \|\lambda\bn\|^2 - 2\lambda\,\bx\cdot \bn\right)\cdot \left((t+\lambda)+\sqrt{\|\bx\|^2 + \|\lambda\bn\|^2 + 2\lambda\,\bx\cdot \bn}\right)^{-1}\\
\nonumber
&=& \left(\lambda^2+2\lambda t + t^2 - \|\bx\|^2 - \lambda^2 - 2\lambda \bx\cdot \bn\right)\cdot \lambda^{-1}\cdot \left(\frac{t}{\lambda} +1 + \sqrt{\frac{\|\bx\|^2}{\lambda^2} + 1 + \frac{2}{\lambda}\bx\cdot \bn}\right)^{-1}\\
&=&\frac{2(t-\bx\cdot\bn) +\frac{t^2-\|\bx\|^2}{\lambda}}{\frac{t}{\lambda} +1 + \sqrt{\frac{\|\bx\|^2}{\lambda^2} + 1 + \frac{2}{\lambda}\bx\cdot \bn}}
\end{eqnarray}

\noindent Therefore 

\begin{equation}
\nonumber
\lim\limits_{\lambda\to+\infty}u_{x,\bn}(\lambda)=t - \bx\cdot\bn\,.
\end{equation}

\noindent Similar manipulations yield that also the angular components of $x+\xi_{\lambda,\bn}$ converge to those of $\bn$, completing the proof. 
\end{proof}


