\begin{proof}[Proof of Theorem \ref{thm1}]
By Assumptions~\ref{a1}--\ref{a4}, the random variables $L_1(n), L_2(n), \dots$ are independent and identically distributed and independent of the counting process $N(t)$. Applying Wald's equation for expectation, we obtain
\begin{align*}
\E\big(S(n,t)\big) = \E\big(N(t)\big) \E(L_1(n)).
\end{align*}
Using the definition of $L_1(n)$ and linearity of expectation, it follows that
\begin{align*}
\E(L_1(n)) = \sum_{i,j=1}^n \E(G_{i,j}) = n\E(G_{1,1}) + n(n-1)\E(G_{1,2}),
\end{align*}
which establishes the formula for the expectation.

For the variance, we apply Wald’s equation for variance:
\begin{align*}
\Var\big(S(n,t)\big) = \Var\big(N(t)\big) \E(L_1(n))^2 + \E\big(N(t)\big) \Var(L_1(n)).
\end{align*}
To compute $\Var(L_1(n))$, we expand
\begin{align*}
\Var\big(L_1(n)\big) &= \sum_{i,j,i',j'=1}^n \Cov\big(G_{i,j,1},G_{i',j',1}\big) \\
&= n\Var(G_{1,1}) \\
&\quad + n(n-1) \big( 2\Cov(G_{1,1},G_{1,2}) + 2\Cov(G_{1,1},G_{2,1}) \\
&\quad\quad + \Var(G_{1,2}) + \Cov(G_{1,2},G_{2,1}) \big) \\
&\quad + n(n-1)(n-2) \big( \Cov(G_{1,2}, G_{1,3}) + \Cov(G_{1,2}, G_{3,1}) \\
&\quad\quad + \Cov(G_{2,1}, G_{1,3}) + \Cov(G_{2,1}, G_{3,1}) \big).
\end{align*}
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm2}.]
a) For arbitrary $m \in \mathbb{N}_0$ and $1 \leq i , j \leq n$, $i \neq j$,  define
\begin{align*}
\widetilde X_{i,j}(m) &= X_{i,j}'(m) + X_{j,i}'(m) - 2m\E(G_{1,2}), \\
\widetilde X_{i,i}(m) &= X_{i,i}'(m) - m\E(G_{1,1}).
\end{align*}
By Assumptions~\ref{a1}--\ref{a4}, the array $\widetilde X(m) = (\widetilde X_{i,j}(m))_{(i,j) \in \mathbb{N} \times \mathbb{N}}$ is centered, symmetric, jointly exchangeable, and dissociated. Moreover, we can decompose
\begin{align*}
S'(n,m) - m\mu_L(n) = U(n,m) + R(n,m),
\end{align*}
where
\begin{align*}
U(n,m) &= \sum_{1 \leq i < j \leq n} \widetilde X_{i,j}(m), \\
R(n,m) &= \sum_{i=1}^{n} \widetilde X_{i,i}(m).
\end{align*}
By Theorem A in \citet{sil}, the statistic $U(n,m)$ satisfies
\begin{align*}
\frac{U(n,m)}{n^{ 3/ 2 }}\overset{d}{\longrightarrow}N(0,m\tau^2)~\text{as}~n\to\infty,
\end{align*}
where 
\begin{align*}
\tau^2=\Cov(G_{1,2}, G_{1,3})+\Cov(G_{1,2},  G_{3,1})+\Cov(G_{2,1}, G_{1,3})+\Cov(G_{2,1},  G_{3,1}).
\end{align*}
Furthermore, we have
\begin{align*}
\frac{n^{ 3/ 2 }}{\sigma_L(n)}\longrightarrow\frac 1 \tau~\text{as}~n\to\infty,
\end{align*}
By the  strong law of large numbers,
\begin{align*}
\frac{R(n,m)}{n}\overset{a.s.}{\longrightarrow}0~\text{as}~n\to\infty.
\end{align*}
Finally, from 
\begin{align*}
\frac{S'(n,m)-m \mu_L(n)}{\sigma_L(n)}&= \frac{n^{ 3/ 2 }}{\sigma_L(n)} \frac{S'(n,m)-m \mu_L(n)}{n^{ 3/ 2 }}\\
&= \frac{n^{ 3/ 2 }}{\sigma_L(n)}\frac{U(n,m)}{n^{ 3/ 2 }}+\frac{n^{ 3/ 2 }}{\sigma_L(n)}\frac{R(n,m)}{n}
\end{align*}
Slutsky's theorem implies that for all $m\in\N_0$,
\begin{align*}
 \frac{S'(n,m)-m \mu_L(n)}{\sigma_L(n)}\overset{d}{\longrightarrow}N(0,m)~\text{as}~n\to\infty.
\end{align*}


b) For any fixed $x\in\R$, we define, for  $m\in\N_0$,
\begin{align*}
h_n(m)=P\Bigg( \frac{S'(n,N(t))-N(t) \mu_L(n)}{\sigma_L(n)}\le x\Bigg|N(t)=m\Bigg), \quad
h(m)=\Phi_{0,m}(x).
\end{align*}
Part a) combined with the Portmanteau theorem yields 
$h_n(m)\longrightarrow h(m)$ as  $n\to\infty$.
Observing
\begin{align*}
P\Bigg(\frac{S'(n,N(t))-N(t) \mu_L(n)}{\sigma_L(n)}\le x\Bigg)&=\E\Bigg(P\Bigg(\frac{S'(n,N(t))-N(t) \mu_L(n)}{\sigma_L(n)}\le x\Bigg|N(t)\Bigg)\Bigg)\\
&=\E\Big(h_n\big(N(t)\big)\Big),
\end{align*} 
it follows from the dominated convergence theorem, since $h_n\ge 0$ and $h_n$ is bounded by 1, that 
\begin{align*}
\E\Big(h_n\big(N(t)\big)\Big)\longrightarrow \E\big(h(N(t))\big)=\sum_{m=0}^\infty P(N(t)=m)\Phi_{0,m}(x)~\text{as}~n\to\infty.
\end{align*}
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm3}.]
a) We show the statement for an arbitrary sequence $m(n)\in(0,\infty)$, $n\in\N$, with $\lim_{n\to\infty}m(n)=\infty$. It is 
\begin{align*}
\frac{ S'(n,m(n))-m(n)\mu_L(n)}{\sqrt{m(n)}\sigma_L(n)}&=\frac{\sum_{k=1}^{m(n)}L_{k}(n)-m(n)\mu_L(n)}{\sqrt{m(n)}\sigma_L(n)}\\
&=\frac{1}{\sqrt{m(n)}}\sum_{k=1}^{m(n)}\frac{ L_k(n)-\mu_L(n)}{\sigma_L(n)}\\
&=\frac{S(n)}{s(n)},
\end{align*}
where 
\begin{align*}
S(n)=\sum_{k=1}^{m(n)}H_k(n),~s^2(n)=\Var(S(n))=m(n)
\end{align*}
with the triangular array of standardized (centered and normalized) independent and identically distributed random variables
\begin{align*}
H_k(n)=\frac{ L_k(n)-\mu_L(n)}{\sigma_L(n)},~k=1,\dots,m(n).
\end{align*}
We  will apply the central limit theorem of Lindeberg-Feller. For this purpose, we verify Lindeberg's condition. We have  for all $u\in(0,\infty)$ 
\begin{align*}
\frac{1}{s(n)^2}\sum_{k=1}^{m(n)}E\big(H_k(n)^2I(|H_k(n)|>s(n) u)\big)=E\big(H_1(n)^2I(|H_1(n)|>\sqrt{m(n)} u)\big).
\end{align*}
Applying again Theorem A in \cite{sil}, we obtain analogously to the proof of Theorem \ref{thm2}
\begin{align*}
H_1(n)\overset{d}{\longrightarrow}\eta~\text{as}~n\to\infty.
\end{align*}
where $\eta\sim N(0,1)$. By the Skorokhod representation theorem, we may replace $(H_1(n))_n$ and $\eta$ by new random variables (with notation unchanged) on a common probability space such that  $H_1(n)\overset{a.s.}{\to}\eta$ as $n\to\infty$. From 
\begin{align*}
H_1(n)^2I(|H_1(n)|>\sqrt{m(n)} u)\overset{a.s.}{\longrightarrow} 0~\text{as}~n\to\infty
\end{align*}
and $H_1(n)^2I(|H_1(n)|>\sqrt{m(n)} u)\le H_1(n)^2$ as well as $E(H_1(n)^2)=1$ it follows from the dominated convergence theorem that
\begin{align*}
E\big(H_1(n)^2I(|H_1(n)|>\sqrt{m(n)} u)\big)\longrightarrow 0~\text{as}~n\to\infty,
\end{align*}
i.e., Lindeberg's condition. The central limit theorem of Lindeberg-Feller implies
\begin{align*}
\frac{S(n)}{s(n)} \overset{d}{\longrightarrow}N(0,1)~\text{as}~n\to\infty.
\end{align*}


b)  It is sufficient to show the statement for an arbitrary sequence $t_n\in(0,\infty)$, $n\in\N$, with $\lim_{n\to\infty}t_n=\infty$. Due to Assumption~\ref{a4} we may assume without loss of generality that the random variables  $L_{1}(n),L_{2}(n),\dots$ on the one hand and the  process $N=(N(t))_{t\in[0,\infty)}$ on the other hand are defined on different probability spaces $(\Omega_1,\AA_1,P_1)$ and  $(\Omega_2,\AA_2,P_2)$, where  $(\Omega,\AA,P)= (\Omega_1\times\Omega_2,\AA_1\otimes\AA_2,P_1\otimes P_2)$ is endowed with the product measure. We fix an arbitrary $\omega\in\{\lim_{t\to\infty}N(t)=\infty\}\in\AA_2$ and set $m(n)=N(t_n)(\omega)$; $\lim_{n\to\infty}m(n)=\infty$ is satisfied. In addition, we fix arbitrary $x\in\R$. Setting
\begin{align*}
h_n(\omega)=P_1\Bigg(\frac{ S'(n,N(t_n)(\omega))-N(t_n)(\omega)\mu_L(n)}{\sqrt{N(t_n)(\omega)}\sigma_L(n)}\le x \Bigg) =P_1\Bigg(\frac{ S'(n,m(n))-m(n)\mu_L(n)}{\sqrt{m(n)}\sigma_L(n)}\le x \Bigg),
\end{align*}
and 
$
h(\omega)=\Phi_{0,1}(x)
$
constant in $\omega$, it follows from 
 part a) that $ h_n(\omega)\rightarrow h(\omega)~\text{as}~n\to\infty$. Because $h_n\ge 0$ and $h_n$ is bounded by 1, it follows from the dominated convergence theorem that 
\begin{align*}
&P\Bigg(\frac{ S'(n,N(t_n))-N(t_n)\mu_L(n)}{\sqrt{N(t_n)}\sigma_L(n)}\le x \Bigg)\\
&=\int h_n(\omega)dP_2(\omega)\\
&=\int h_n(\omega)I\Big(\omega\in\Big\{\lim_{t\to\infty}{N(t)}=\infty\Big\}\Big)dP_2(\omega)\\
&\longrightarrow \int h(\omega)I\Big(\omega\in\Big\{\lim_{t\to\infty}{N(t)}=\infty\Big\}\Big)dP_2(\omega)\\
&=\Phi_{0,1}(x)~\text{as}~n\to\infty,
\end{align*}
observing that our additional assumption  implies $P_2(\{\lim_{t\to\infty}{N(t)}=\infty\})=1$. This completes the proof of part b).
\end{proof}



\begin{proof} [Proof of Theorem \ref{thm4}.]

a)  From the expression
\begin{align*}
S'(n,m)=\sum_{k=1}^{N(t)}L_{k}(n),
\end{align*}
where $L_{1}(n),L_{2}(n),\dots$ are independent and identically distributed real-valued random variables with expectation $\mu_L(n)$ and variance $\sigma_L^2(n)$,
we have
\begin{align*}
\frac{ S'(n,m)-m\mu_L(n)}{\sqrt{m}\sigma_L(n)} =\frac{ \sum_{k=1}^{N(t)}L_{k}(n)-m\mu_L(n)}{\sqrt{m}\sigma_L(n)},
\end{align*}
so the statement in a) follows immediately by the application of the central limit theorem of Lindeberg-Levy.


b) 
This follows immediately from part a) and with analogous arguments as in the proof of Theorem \ref{thm3} b). 
\end{proof}



\begin{proof} [Proof of Theorem \ref{thm4b}.]

a) We recall the expression for the loss of the insurance company:
\begin{align*}
S(n,t)=\sum_{k=1}^{N(t)}L_{k}(n), \quad
L_{k}(n)=\sum_{i,j=1}^nG_{i,j,k}.
\end{align*}
The expectation and variance are
\begin{align*}
\mu_S(n,t) = & \; \E\big(S(n,t)\big)=\mu_N(t) \mu_L(n)=\lambda t \mu_L(n)\\
\sigma^2_S(n,t)  = & \; \Var\big(S(n,t)\big)=\sigma^2_N(t)\mu_L(n)^2+\mu_N(t)\sigma^2_L(n)=\lambda t \big(\mu_L(n)^2+\sigma^2_L(n)\big).
\end{align*}
We can write  
$
S(n,t)-\mu_S(n,t)=\widetilde S(n,t)+R(n,t)
$
with the telescopic sum 
$
\widetilde S(n,t)=\sum_{k=1}^{\lfloor t \rfloor}H_{k}(n)
$
of the increments
\begin{align*}
H_{k}(n)=\sum_{k'=1}^{N(k)}L_{k'}(n)-\sum_{k'=1}^{N(k-1)}L_{k'}(n)-\lambda\mu_L(n), \quad k=1,\dots,\lfloor t \rfloor, 
\end{align*}
and with the remainder term
\begin{align*}
R(n,t)=\sum_{k= N(\lfloor t \rfloor)+1 }^{N(t)}L_{k}(n)-\lambda( t-\lfloor t \rfloor)\mu_L(n).
\end{align*}
Due to Assumptions \ref{a1}--\ref{a4}, and in particular the fact that the counting process $N = (N(t))_{t\in[0,\infty)}$ is a homogeneous Poisson process with intensity $\lambda \in (0,\infty)$, we observe that the increments $H_{1}(n), \dots, H_{\lfloor t \rfloor}(n)$ form a sequence of independent and identically distributed centered random variables. Setting
$
\sigma^2_{H}(n)=\Var\big(H_{1}(n)\big),
$
it follows from the central limit theorem of Lindeberg-Levy that 
\begin{align*}
\frac{\widetilde S(n,t)}{\sqrt{\lfloor t \rfloor}\sigma_{H}(n)} \overset{d}{\longrightarrow}N(0,1)~\text{as}~t\to\infty.
\end{align*}
Moreover, it is
\begin{align*}
\sigma^2_{\widetilde S}(n,t)=\Var\big(\widetilde S(n,t)\big)={\lfloor t \rfloor}\Var\big(H_{1}(n)\big)={\lfloor t \rfloor}\sigma^2_{H}(n).
\end{align*}
Due to Assumptions \ref{a1}--\ref{a4}, and in particular the fact that the counting process $N = (N(t))_{t\in[0,\infty)}$ is a homogeneous Poisson process with intensity $\lambda \in (0,\infty)$, the random variables $\widetilde S(n,t)$ and $R(n,t)$ are independent.
For that reason, we have
\begin{align*}
\sigma^2_S(n,t)=\Var\big( S(n,t)-\mu_S(n,t)\big)=\sigma^2_{\widetilde S}(n,t)+\Var\big(R(n,t)\big),
\end{align*}
and, due to the fact that the distribution of $R(n,t)$ is periodic in $t$ with period $1$, it follows that
\begin{align*}
\sigma^2_{\widetilde S}(n,t)\sim\sigma^2_{ S}(n,t)~\text{as}~t\to\infty.
\end{align*}
This implies
\begin{align*}
{\lfloor t \rfloor}\sigma^2_{H}(n)\sim{\sigma^2_{ S}(n,t)}~\text{as}~t\to\infty.
\end{align*}
Furthermore, again due to the fact that the distribution of $R(n,t)$ is periodic in $t$ with period $1$, we have 
$
\frac{R(n,t)}{\sqrt{\lfloor t \rfloor}} \overset{P}{\longrightarrow}0$ as $t\to\infty$.
In summary, Slutsky's theorem implies
\begin{align*}
\frac{S(n,t)-\mu_S(n,t)}{\sigma_S(n,t)}=\frac{\sqrt{\lfloor t \rfloor}\sigma_{H}(n)}{{\sigma_{ S}(n,t)}}\bigg(\frac{\widetilde S(n,t)}{\sqrt{\lfloor t \rfloor}\sigma_{H}(n)}+\frac{1}{\sigma_{H}(n)}\frac{R(n,t)}{\sqrt{\lfloor t \rfloor}}\bigg)
\overset{d}{\longrightarrow}N(0,1)~\text{as}~t\to\infty.
\end{align*}
This completes the proof of a).


b)  The proof is similar to the proof of Theorem \ref{thm3} b). Due to our assumptions, we can assume without loss of generality that the random variables   $\widetilde N$, $G_{k}$, $k\in\N$, on the one hand and the  process $T$ on the other hand are defined on different probability spaces $(\Omega_1,\AA_1,P_1)$ and  $(\Omega_2,\AA_2,P_2)$, where  $(\Omega,\AA,P)= (\Omega_1\times\Omega_2,\AA_1\otimes\AA_2,P_1\otimes P_2)$ is endowed with the product measure. We fix an arbitrary $\omega\in\{\lim_{s\to\infty}T(s)=\infty\}\in\AA_2$ and set $t'(t)=T(t)(\omega)$ for $t\in[0,\infty)$; $\lim_{t\to\infty}t'(t)=\infty$ is satisfied. In addition, we fix arbitrary $x\in\R$. Setting
\begin{align*}
h_t(\omega)=P_1\Bigg(\frac{ S'(n,\widetilde N(T(t)(\omega)))-\lambda T(t) \mu_L(n)}{\sqrt{\lambda T(t) (\mu_L(n)^2+\sigma^2_L(n))}}\le x \Bigg)
\end{align*}
it is
\begin{align*}
h_t(\omega)=P_1\Bigg(\frac{ S'(n,\widetilde N(t'(t)))-\lambda t'(t) \mu_L(n)}{\sqrt{\lambda t'(t) (\mu_L(n)^2+\sigma^2_L(n))}}\le x \Bigg).
\end{align*}
Furthermore,  $S'(n,\widetilde N(t'(t)))$ is the total loss at time $t'(t)$ in the situation in part a) with  expectation
$
\E(S'(n,\widetilde N(t'(t))))=\lambda t'(t) \mu_L(n)
$
and  variance
$
\Var(S'(n,\widetilde N(t'(t))))=\lambda t'(t) \big(\mu_L(n)^2+\sigma^2_L(n)\big).
$
Setting $
h(\omega)=\Phi_{0,1}(x)$ (which is constant in $\omega$), part a) implies that $ h_t(\omega)\rightarrow h(\omega)~\text{as}~t\to\infty$. Because $h_t\ge 0$ and $h_t$ is bounded by 1, it follows from the dominated convergence theorem that 
\begin{align*}
&P\Bigg(\frac{ S(n,t)-\lambda T(t) \mu_L(n)}{\sqrt{\lambda T(t) (\mu_L(n)^2+\sigma^2_L(n))}}\le x \Bigg)\\
&=\int h_t(\omega)dP_2(\omega)\\
&=\int h_t(\omega)I\Big(\omega\in\Big\{\lim_{s\to\infty}{T(s)}=\infty\Big\}\Big)dP_2(\omega)\\
&\longrightarrow \int h(\omega)I\Big(\omega\in\Big\{\lim_{s\to\infty}{T(s)}=\infty\Big\}\Big)dP_2(\omega)\\
&=\Phi_{0,1}(x)~\text{as}~t\to\infty,
\end{align*}
observing that $P_2(\{\lim_{s\to\infty}{T(s)}=\infty\})=1$ is satisfied. This completes the proof of part b).
\end{proof}




\begin{proof}[Proof of Theorem \ref{thmrel}.]



For $t\in[0,\infty)$, we consider  the Laplace transform of $(S(n,t),M(n,t))$, i.e,  $\psi_{(S(n,t),M(n,t))}(u,v)=E(e^{-uS(n,t)-vM(n,t)})$ for $(u,v)\in[0,\infty)\times[0,\infty)$, which characterizes the distribution uniquely. With $\eta\in\N_0$, $\iota=(\iota_{i,j,k})_{(i,j,k) \in\N\times \N\times \N}\in\{0,1\}^{\N\times \N\times \N}$, and setting $m=\sum_{i=1}^n\sum_{j=1}^n\sum_{k=1}^{\eta}\iota_{i,j,k}$, we have for $t\in[0,\infty)$ and  $(u,v)\in[0,\infty)\times[0,\infty)$:
\begin{align*}
\E(e^{-uS(n,t)-vM(n,t)}|N(t)=\eta,I=\iota)=\psi_Z(u)^me^{-vm} ,
\end{align*}
thus
\begin{align*}
\psi_{(S(n,t),M(n,t))}(u,v)=\E(\E(e^{-uS(n,t)-vM(n,t)}|N(t),I))=\E(\psi_Z(u)^{M(n,t)}e^{-vM(n,t)})
\end{align*}
on the one hand; on the other hand, we obtain for $m\in\N_0$:
\begin{align*}
\E(e^{-u\sum_{i=1}^{M(n,t)}Z_i-vM(n,t)}|M(n,t)=m)=\psi_Z(u)^me^{-vm} ,
\end{align*}
thus
\begin{align*}
\psi_{\big(\sum_{i=1}^{M(n,t)}Z_i,M(n,t)\big)}(u,v)=\E(\E(e^{-u\sum_{i=1}^{M(n,t)}Z_i-vM(n,t)}|M(n,t)))=\E(\psi_Z(u)^{M(n,t)}e^{-vM(n,t)}).
\end{align*}
This proves the assertion. 
\end{proof}


