\subsection*{Conventions}
All rings are commutative with identity and all ring maps are unital.
We will sometimes use set-theoretic notation when talking about inclusions or
intersections of categories.

\section{Excellent rings and Lyubeznik functors}\label{sect:exclyu}
\subsection{Excellent rings}
\begin{citeddef}[{\citeleft\citen{EGAIV2}\citemid D\'efinition 7.8.2\citepunct
  \citen{Mat80}\citemid (32.B), (33.A), and (34.A)\citeright}]\label{def:excellent}
  Let \(R\) be a ring.
  We say that \(R\) is \textsl{excellent} if it is Noetherian and it satisfies
  the following conditions.
  \begin{enumerate}[label=\((\roman*)\)]
    \item \(R\) is universally catenary.
    \item \(R\) is a \textsl{G-ring}, that is, for every prime ideal \(\fp \subseteq R\),
      the \(\fp R_\fp\)-adic completion map
      \(R_\fp \to \hat{R}_\fp\)
      has geometrically regular fibers.
    \item \(R\) is \textsl{J-2}, that is, for every module-finite \(R\)-algebra
    \(S\), the regular locus \(\Reg(S)\) in \(\Spec(S)\) is open.
  \end{enumerate}
\end{citeddef}
\subsection{Lyubeznik functors}
The following class of functors was introduced by Lyubeznik \cite{Lyu93} and
named in \cite{NB13}.
\begin{citeddef}[{\citeleft\citen{Lyu93}\citemid \S1\citepunct
  \citen{NB13}\citemid Definition 4.1\citeright}]\label{def:lyubeznikfunctors}
  Let \(X\) be a scheme.
  A \textsl{Lyubeznik functor \(T\) on \(X\)} is a functor of the form
  \( T = T_t \circ \cdots \circ T_2 \circ T_1 \)
  where each \(T_j\) is one of the following functors.
  \begin{enumerate}[label=\((\roman*)\)]
    \item \(\sH^{i_j}_{Y_j}(\,\cdot\,)\) for a locally
      closed subset \(Y_j\) of \(X\).
    \item The kernel of a morphism in the long exact sequence
      \begin{equation}\label{eq:lyubeznikfunctorles}
        \cdots \longrightarrow \sH^i_{Y'}(\,\cdot\,) \longrightarrow
        \sH^i_{Y}(\,\cdot\,)
        \longrightarrow \sH^i_{Y-Y'}(\,\cdot\,) \longrightarrow \cdots
      \end{equation}
      of local cohomology functors from \cite[Expos\'e I, Th\'eor\`eme 2.8]{SGA2}
      where \(Y\) is a locally closed subset of \(X\) and \(Y'\) is a
      closed subset of \(Y\).
  \end{enumerate}
\end{citeddef}

\section{\texorpdfstring{{\normalfont\textit{t}}}{t}-structures and perverse
sheaves}\label{sect:perversesheaves}
We review preliminaries on perverse sheaves.
Perverse sheaves and the Riemann--Hilbert correspondence (see
\eqref{eq:riemannhilbert}) were previously applied
to commutative algebra, in particular to questions about local cohomology, in
\cite{BBLSZ}.
\subsection{Dimension and perversity functions}
\begin{citeddef}[{\citeleft\citen{ILO14}\citemid Expos\'e XIV, D\'efinition
  2.1.2\citeright}]
  Let \(X\) be a scheme.
  An \textsl{immediate Zariski specialization} \(x \rightsquigarrow y\) is a
  pair of points \(x,y\in X\) such that
  \(y \in \overline{\{x\}}\) and the closure of the image of \(x\) in
  \(\Spec(\cO_{X,y})\) is of dimension 1.
\end{citeddef}
\begin{citeddef}[{\cite[Expos\'e XIV, Proposition 2.1.6 and D\'efinition
  2.1.10]{ILO14}}]
  \label{def:dimfunction}
  Let \(X\) be a universally catenary Noetherian scheme.
  A \textsl{dimension function on \(X\)} is a function \(\delta\colon X \to
  \ZZ\) such that for every immediate Zariski specialization \(x \rightsquigarrow y\)
  of points in \(X\), we have \(\delta(y) = \delta(x) - 1\).
\end{citeddef}
\begin{example}\label{ex:codimdimfunction}
  Let \(X\) be an equidimensional universally catenary Noetherian scheme.
  \begin{enumerate}[label=\((\roman*)\),ref=\roman*]
    \item\label{ex:codimfunction}
      The function \(\delta(x) = -{\dim(\cO_{X,x})}\)
      is a dimension function on \(X\).
      If \(X\) is irreducible, this is proved in \cite[Expos\'e XIV, Proposition
      2.2.2]{ILO14}.
      In general, \(\delta(x) = -{\dim(\cO_{X,x})}\) restricts to a
      dimension function on each irreducible component of \(X\), and hence is a
      dimension function on all of \(X\).
      See also \cite[Proposition 5.5]{Hei17}.
    \item\label{ex:dimfunction}
      Suppose additionally that \(X\) is equicodimensional.
      The function \(\delta(x) = \dim(\overline{\{x\}})\)
      is a dimension function on \(X\) by \cite[Expos\'e XIV, Corollaire
      2.4.4]{ILO14} when \(X\) is irreducible and by \cite[Proposition 3.18]{BH22} in
      general.
  \end{enumerate}
\end{example}
\begin{citeddef}[{\cite[\S1]{Gab04}}]
  Let \(X\) be a Noetherian scheme.
  A \textsl{strong perversity function on \(X\)} is a function \(\fp\colon X \to
  \ZZ \cup \{+\infty\}\) such that for all \(x,y \in X\) with \(y \in
  \overline{\{x\}}\), we have \(\fp(y) \ge \fp(x)\).
\end{citeddef}
We recall the standard example of a strong perversity function.
\begin{example}[Middle perversity {\citeleft\citen{BBDG18}\citemid (2.1.16) and
  (2.2.11)\citeright}]\label{ex:middleperversity}
  Let \(X\) be an equidimensional universally catenary Noetherian scheme of finite Krull
  dimension.
  Setting
  \begin{align*}
    \fp_{1/2}(x) \coloneqq -\bigl(\dim(X)+\delta(x)\bigr) ={} &{\dim(\cO_{X,x})} -
    \dim(X)
  \intertext{for \(\delta\) as in Example
  \ref{ex:codimdimfunction}\((\ref{ex:codimfunction})\) yields a strong perversity
  function, which we call the \textsl{middle perversity}.
  If \(X\) is biequidimensional in the sense of \cite[Definition
  1.2\((ii)\)]{Hei17}, the function \(\fp_{1/2}\) satisfies}
    \fp_{1/2}(x) = -\delta(x) = -&{\dim\bigl(\overline{\{x\}}\bigr)}
  \end{align*}
  for \(\delta\) as in Example
  \ref{ex:codimdimfunction}\((\ref{ex:dimfunction})\) since
  the dimension formula
  holds on \(X\) \citeleft\citen{EGAIV1}\citemid Chapitre 0, Corollaire
  14.3.5\citepunct \citen{Hei17}\citemid Proposition 4.1\citeright.
\end{example}
\subsection{\emph{t}-structures}
We collect some preliminaries on \(t\)-structures following
\cite[\S\S1.2--1.3]{BBDG18} and the summary of the material in \cite{BBDG18}
from \cite[\S2.2]{Jut09}.
\begin{citeddef}[{\cite[D\'efinition 1.3.1]{BBDG18}}]
  A \textsl{\(t\)-category} is a triangulated category \(\cD\) equipped with a
  pair \((\cD^{\le0},\cD^{\ge0})\) of
  strictly full subcategories of \(\cD\) such that setting \(\cD^{\le n}
  \coloneqq \cD^{\le 0}[-n]\) and \(\cD^{\ge n} \coloneqq \cD^{\ge 0}[-n]\) for
  every integer \(n\), the following conditions hold.
  \begin{enumerate}[label=\((\roman*)\)]
    \item For every \(X\) in \(\cD^{\le 0}\) and every \(Y\) in \(\cD^{\ge 1}\),
      we have \(\Hom_\cD(X,Y) = 0\).
    \item We have \(\cD^{\le 0} \subseteq \cD^{\le 1}\) and \(\cD^{\ge 0}
      \supseteq \cD^{\ge 1}\).
    \item For every \(X\) in \(\cD\), there exists a distinguished triangle
      \begin{equation}\label{eq:bbdgdef131iii}
        A \longrightarrow X \longrightarrow B \xrightarrow{+1}
      \end{equation}
      where \(A\) is in \(\cD^{\le 0}\) and \(B\) is in \(\cD^{\ge 1}\).
  \end{enumerate}
  We say that \((\cD^{\le0},\cD^{\ge0})\) is a \textsl{\(t\)-structure} on
  \(\cD\).
  The \textsl{heart} of the \(t\)-structure \((\cD^{\le0},\cD^{\ge0})\) is the
  full subcategory
  \[
    \cD^\heartsuit \coloneqq \cD^{\le 0} \cap \cD^{\ge 0} \subseteq \cD.
  \]
\end{citeddef}
\begin{citedprop}[{\cite[Proposition 1.3.3 and Proposition 1.3.5]{BBDG18}}]
  Let \(\cD\) be a \(t\)-category.
  \begin{enumerate}[label=\((\roman*)\)]
    \item The inclusion of \(\cD^{\le n}\) (resp.\ \(\cD^{\ge n}\)) in \(\cD\)
      admits a right adjoint \(\tau_{\le n}\) (resp.\ a left adjoint \(\tau_{\ge
      n}\)).
    \item For all \(X\) in \(\cD\), there exists a unique morphism
      \[
        d \in \Hom_\cD\bigl(\tau_{\ge1}X,\tau_{\le0}X[1]\bigr)
      \]
      such that the triangle
      \[
        \tau_{\le 0} X \longrightarrow X \longrightarrow \tau_{\ge 1} X
        \xrightarrow[\raisebox{3pt}{\(\scriptstyle+1\)}]{d}
      \]
      is distinguished.
      Up to unique isomorphism, this is the unique distinguished triangle
      \eqref{eq:bbdgdef131iii} with \(A\) in \(\cD^{\le 0}\) and \(B\) in
      \(\cD^{\ge1}\).
    \item Let \(a \le b\).
      For every \(X\) in \(\cD\), there exists a unique morphism
      \begin{equation}\label{eq:tauabxtaubax}
        \tau_{\ge a}\tau_{\le b}X \longrightarrow \tau_{\le b}\tau_{\ge a}X
      \end{equation}
      making the diagram
      \[
        \begin{tikzcd}[column sep=small]
          \tau_{\le b}X \rar \dar & X \rar & \tau_{\ge a}X\\
          \tau_{\ge a}\tau_{\le b}X \arrow{rr}{\sim}[swap]{\eqref{eq:tauabxtaubax}}
          & & \tau_{\le b}\tau_{\ge a}X \uar
        \end{tikzcd}
      \]
      commute.
      Moreover, the morphism \eqref{eq:tauabxtaubax} is an isomorphism.
  \end{enumerate}
\end{citedprop}
\begin{citedprop}[{\cite[Proposition 1.2.2]{BBDG18}}]
  Let \(\cD\) be a triangulated category and let \(\cC\) be a full subcategory
  of \(\cD\) such that \(\Hom(X,Y[i]) = 0\) for all \(i < 0\) and \(X,Y\) in
  \(\cC\).
  Let \(f\colon X \to Y\) be a morphism of \(\cC\) and consider a distinguished
  triangle
  \[
    X \overset{f}{\longrightarrow} Y \longrightarrow S \xrightarrow{+1}
  \]
  containing \(f\).
  Suppose that \(S\) fits into a distinguished triangle
  \[
    N[1] \longrightarrow S \longrightarrow C \xrightarrow{+1}
  \]
  where \(N\) and \(C\) are in \(\cC\).
  We then obtain the diagram
  \begin{equation}\label{eq:bbdg1221}
    \begin{tikzcd}[column sep={between origins,4em},row
      sep=scriptsize,baseline=(S.base)]
      N[1]\arrow[dd,"\alpha"',""{name=leftcomm}] \arrow[dr] & & C
      \arrow[ll,"+1"'{pos=0.545},""{name=top1,pos=0.545}]\\
      &|[alias=S]| S \arrow[ur] \arrow[dl,"+1"'{sloped}]\\
      X \arrow[rr,"f"',""{name=bottom1}]
      & & Y \arrow[uu,"\beta"',""{name=rightcomm}] \arrow[ul]
      \arrow[phantom,from=S,to=top1,"\scriptstyle \star"{description,pos=0.6}]
      \arrow[phantom,from=S,to=bottom1,"\scriptstyle \star"{description,pos=0.6}]
      \arrow[phantom,from=S,to=leftcomm,"\scriptstyle \circlearrowright"{description,pos=0.6}]
      \arrow[phantom,from=S,to=rightcomm,"\scriptstyle \circlearrowright"{description,pos=0.6}]
    \end{tikzcd}
  \end{equation}
  where the triangles marked with \(\circlearrowright\) commute and the triangles
  marked with \(\star\) are distinguished.
  Then, \(\alpha[-1]\colon N \to X\) and \(\beta\colon Y \to C\) are
  respectively a kernel and a cokernel for \(f\) in \(\cC\).
\end{citedprop}
\begin{citeddef}[{\cite[(1.2.3)]{BBDG18}}]
  Let \(\cD\) be a triangulated category and let \(\cC\) be a full subcategory
  of \(\cD\) such that \(\Hom(X,Y[i]) = 0\) for all \(i < 0\) and \(X,Y\) in
  \(\cC\).
  A morphism \(f\colon X \to Y\) of \(\cC\) is \textsl{\(\cC\)-admissible} or
  simply \textsl{admissible} if it appears as the bottom horizontal morphism
  in a diagram of the form
  \eqref{eq:bbdg1221}.
  For every distinguished triangle
  \[
    X \overset{f}{\longrightarrow} Y \overset{g}{\longrightarrow} Z
    \xrightarrow[\raisebox{3pt}{\(\scriptstyle+1\)}]{d}
  \]
  such that \(X,Y,Z\) are in \(\cC\), the morphisms \(f,g\) are
  admissible, \(f\) is a kernel for \(g\), \(g\) is a cokernel for \(f\), and
  \(d\) is uniquely determined by \(f\) and \(g\).
  \par A sequence \(X \to Y \to Z\) in \(\cC\) is an \textsl{admissible short
  exact sequence} if it can be obtained from a distinguished triangle by
  suppressing the degree \(1\) morphism \(d\colon Z \to X[1]\).
\end{citeddef}
\begin{citedprop}[{\cite[Proposition 1.2.4]{BBDG18}}]\label{prop:bbdg124}
  Let \(\cD\) be a triangulated category and let \(\cC\) be a full subcategory
  of \(\cD\) such that \(\Hom(X,Y[i]) = 0\) for all \(i < 0\) and \(X,Y\) in
  \(\cC\).
  Suppose that \(\cC\) is stable under finite direct sums.
  Then, the following conditions are equivalent.
  \begin{enumerate}[label=\((\roman*)\)]
    \item \(\cC\) is Abelian and its short exact sequences are admissible.
    \item Every morphism of \(\cC\) is \(\cC\)-admissible.
  \end{enumerate}
\end{citedprop}
\begin{citeddef}[{\cite[D\'efinition 1.2.5]{BBDG18}}]
  Let \(\cD\) be a triangulated category and let \(\cC\) be a full subcategory
  of \(\cD\).
  We say that \(\cC\) is an \textsl{admissible Abelian subcategory} of \(\cD\)
  if the following conditions hold.
  \begin{enumerate}[label=\((\roman*)\)]
    \item \(\Hom(X,Y[i]) = 0\) for all \(i < 0\) and \(X,Y\) in \(\cC\).
    \item \(\cC\) is stable under finite direct sums.
    \item \(\cC\) satisfies one of the equivalent conditions in Proposition
      \ref{prop:bbdg124}.
  \end{enumerate}
\end{citeddef}
\begin{citedthm}[{\cite[Th\'eor\`eme 1.3.6]{BBDG18}}]\label{thm:bbdg136}
  Let \(\cD\) be a \(t\)-category.
  The heart \(\cD^\heartsuit\) of \(\cD\) is an admissible Abelian subcategory
  of \(\cD\) that is stable under extensions.
  The functor
  \[
    \cH^0 \coloneqq \tau_{\ge0}\tau_{\le0} \colon \cD \longrightarrow
    \cD^\heartsuit
  \]
  is a cohomological functor.
\end{citedthm}
We also define \(t\)-exact functors.
\begin{citeddef}[{\cite[(1.3.16)]{BBDG18}}]
  Let \(\cD_1,\cD_2\) be two \(t\)-categories.
  Let \(T\colon \cD_1 \to \cD_2\) be an exact functor of the underlying
  triangulated categories.
  \begin{enumerate}[label=\((\roman*)\)]
    \item We say that \(T\) is \textsl{right \(t\)-exact} if \(T(\cD_1^{\le0}) \subseteq
      \cD_2^{\le 0}\).
    \item We say that \(T\) is \textsl{left \(t\)-exact} if \(T(\cD_1^{\ge0}) \subseteq
      \cD_2^{\ge 0}\).
    \item We say that \(T\) is \textsl{\(t\)-exact} if \(T\) is both right
      \(t\)-exact and left \(t\)-exact.
  \end{enumerate}
\end{citeddef}
\begin{citedprop}[{\cite[Proposition 1.3.17\((i)\)]{BBDG18}}]
  Let \(\cD_1,\cD_2\) be two \(t\)-categories.
  Denote the inclusion functors by \(\varepsilon\colon \cD_i^\heartsuit
  \hookrightarrow \cD_i\).
  Let \(T\colon \cD_1 \to \cD_2\) be an exact functor of the underlying
  triangulated categories.
  If \(T\) is left (resp.\ right) \(t\)-exact, then the additive functor
  \[
    \prescript{\fp}{}{T} \coloneqq \cH^0 \circ T \circ \varepsilon\colon
    \cD_1^\heartsuit \longrightarrow \cD_2^\heartsuit
  \]
  is left (resp.\ right) exact.
\end{citedprop}

\subsection{Perverse sheaves}
We now define perverse sheaves with coefficients in rings such as \(\ZZ_\ell\)
or \(\QQ_\ell\) using the formalism of
\(\ell\)-adic complexes from \citeleft\citen{Eke90}\citepunct
\citen{Far09}\citemid \S5\citepunct \citen{ILO14}\citemid Expos\'e XIII,
\S4\citeright.
As noted in \cite[Remark 2.1.1]{Mor25}, this adic formalism extends to all
separated morphisms of finite type between excellent Noetherian schemes of
finite Krull dimension under coprimeness assumptions.
See \cite[p.\ 198]{Eke90} for the definition of essentially zero inverse
systems.
\begin{citeddef}[{\citeleft\citen{Gab04}\citemid \S2\citepunct
  \citen{Far09}\citemid \S5.11\citepunct
  \citen{ILO14}\citemid Expos\'e XIII, \S4.1\citepunct
  \citen{Mor25}\citemid \S2.2\citeright}]
  Let \(\ell > 0 \) be a prime number.
  Let \(E\) be a finite extension of \(\QQ_\ell\) and let
  \(\cO\) be its ring of integers with uniformizer \(\varpi\).
  Let \(X\) be a Noetherian scheme and consider a strong perversity function
  \(\fp\) on \(X\).
  For every integer \(n\),
  we define strictly full subcategories \(\Dp^{\le n}\) and \(\Dp^{\ge n}\)
  of \(\DD^b_c(X,\cO)\) (resp.\ \(\DD^b_c(X,E) \coloneqq
  \DD^b_c(X,\cO) \otimes_{\cO} E\)) as follows.
  \begin{enumerate}[label=\((\roman*)\)]
    \item \(\Dp^{\le n}\)
      consists of all objects \(F^\bullet\) of
      \(\DD^b_c(X,\cO)\) (resp.\ \(\DD^b_c(X,E)\))
      such that for every \(x \in X\), 
      \(\cH^i(i_{\bar{x}}^*F^\bullet)\) is essentially zero (resp.\ zero)
      for all \(i > \fp(x) + n\).
    \item \(\Dp^{\ge n}\)
      consists of all objects \(F^\bullet\) of \(\DD^b_c(X,\cO)\)
      (resp.\ \(\DD^b_c(X,E)\)) such
      that for every \(x \in X\), \(\cH^i(i_{\bar{x}}^!F^\bullet)\) is
      essentially zero (resp.\ zero)
      for all \(i < \fp(x) + n\).
  \end{enumerate}
\end{citeddef}
We state the following result which says that in many cases, \((\Dp^{\le
0},\Dp^{\ge 0})\) defines a \(t\)-structure.
The statement in \cite{Far09} assumes the existence of a dualizing complex
for \(\DD^b_c(X,\cO/\varpi)\) in the sense of
\citeleft\citen{SGA5}\citemid Expos\'e I, D\'efinition 1.7\citepunct
\citen{ILO14}\citemid Expos\'e XVII, D\'efinition 0.1\citeright.
This assumption on \(\DD^b_c(X,\cO/\varpi)\) holds automatically for \(X\) as in
the statement below by \cite[Expos\'e XVII, Th\'eor\`eme 0.2]{ILO14}.
\par Below, we denote \(\prescript{\fp}{}{\mathcal{H}}^i(\,\cdot\,) \coloneqq
\mathcal{H}^0(\,\cdot\,[i])\) where \(\mathcal{H}^0\) is computed in terms of
the \(t\)-structure defined by \(\fp\) (see Theorem \ref{thm:bbdg136}).
The superscript \(\fp\) on \(\prescript{\fp}{}{\mathcal{H}}^i\) is written to
differentiate this cohomology sheaf from the usual cohomology sheaf computed
using the ordinary \(t\)-structure.
\begin{citedthm}[{\citeleft\citen{Gab04}\citemid
  \S6 and Theorem 8.3\citepunct
  \citen{Far09}\citemid Th\'eor\`eme 5.29\citepunct
  \citen{Mor25}\citemid \S2.2 and Theorem 2.2.3\citeright\ (cf.\
  \citeleft\citen{BBDG18}\citemid \S2.2, Th\'eor\`eme 4.3.1\((i)\),
  and \((b)\) on p.\ 101\citeright)}]\label{thm:perv}
  Let \(\ell > 0 \) be a prime number.
  Let \(L\) be a finite extension of \(\QQ_\ell\) and let
  \(\cO\) be its ring of integers with uniformizer \(\varpi\).
  Let \(X\) be an equidimensional excellent Noetherian
  \(\ZZ[\frac{1}{\ell}]\)-scheme of
  finite Krull dimension and consider the middle perversity
  \(\fp \coloneqq \fp_{1/2}\) on \(X\).
  Then, \((\Dp^{\le 0},\Dp^{\ge 0})\) defines a t-structure on
  \(\DD^b_c(X,\cO)\) (resp.\ \(\DD^b_c(X,E)\)).
  The heart
  \begin{align*}
    \Perv(X,\cO) &\coloneqq \Dp^{\le 0} \cap \Dp^{\ge0}
    \intertext{of the \(t\)-structure on \(\DD^b_c(X,\cO)\) is
    Noetherian.
    The heart}
    \Perv(X,E) &\coloneqq \Dp^{\le 0} \cap \Dp^{\ge0}
  \end{align*}
  of the \(t\)-structure on \(\DD^b_c(X,E)\) is both Artinian and
  Noetherian with simple objects of the form
  \[
    j_{!*}L[d] \coloneqq \im\Bigl(\prescript{\fp}{}{\cH}^0j_!L[d] \longrightarrow
    \prescript{\fp}{}{\cH}^0j_*L[d]\Bigr)
  \]
  where
  \(j\colon Z \hookrightarrow X\) is a locally closed immersion of a connected
  regular subscheme \(Z\) of dimension \(d\) and \(L\) is a lisse sheaf on
  \(Z\) corresponding to an irreducible representation of \(\pi_1^\et(Z)\).
\end{citedthm}
We can now define perverse sheaves as the objects living in
the categories \(\Perv(X,\cO)\) and \(\Perv(X,E)\) appearing in
Theorem \ref{thm:perv}.
\begin{citeddef}[{\citeleft\citen{BBDG18}\citemid p.\ 102\citepunct
  \citen{Gab04}\citemid \S7\citepunct
  \citen{Mor25}\citemid \S2.2\citeright}]
  Let \(\ell > 0 \) be a prime number.
  Let \(E\) be a finite extension of \(\QQ_\ell\) and let
  \(\cO\) be its ring of integers.
  Let \(X\) be an equidimensional excellent Noetherian \(\ZZ[\frac{1}{\ell}]\)-scheme of
  finite Krull dimension and consider the middle perversity
  \(\fp \coloneqq \fp_{1/2}\) on \(X\).
  The hearts \(\Perv(X,\cO)\) and \(\Perv(X,E)\) of the
  \(t\)-structures \((\Dp^{\le 0},\Dp^{\ge 0})\) appearing in Theorem
  \ref{thm:perv} are called the categories of 
  \textsl{perverse sheaves} with coefficients in \(\cO\) and \(E\),
  respectively.
\end{citeddef}

\section{Lyubeznik functors of excellent regular
\texorpdfstring{\(\QQ\)}{Q}-algebras}\label{sect:equichar0}
Let \(X\) be a complex manifold.
The Riemann--Hilbert correspondence of Kashiwara
\cite{Kas75,Kas80,Kas84} and Mebkhout \cite{Meb80,Meb82,Meb84a,Meb84b} states that the
de Rham functor
\begin{equation}\label{eq:riemannhilbert}
  \begin{tikzcd}[row sep=0,column sep=1.475em]
    \DR_X\colon &[-2.35em] \DD^b_{\rh}(\sD_X) \rar & \DD^b_c(X,\CC)\\
    & M^\bullet \rar[mapsto] &
    \Omega_X \otimes^{\mathrm{L}}_{\sD_X} M^\bullet
  \end{tikzcd}
\end{equation}
is an equivalence of categories that is \(t\)-exact with respect to the ordinary
\(t\)-structure on the domain, the bounded derived category of \(\sD_X\)-modules
with regular holonomic cohomology sheaves, and the perverse \(t\)-structure on the
codomain, the bounded derived category of sheaves of \(\CC\)-vector spaces
with constructible cohomology sheaves on \(X\).
See \citeleft\citen{Ber83}\citemid Lecture 5\citepunct
\citen{BGKHME87}\citemid Chapter VIII\citeright\ for the algebraic version of the
Riemann--Hilbert correspondence due to Be\u{\i}linson and Bernstein, which can also
be deduced from the analytic version \cite[\S VII]{Bry86}.
This algebraic version of the correspondence is what we will use.\medskip
\par While there is no version of the Riemann--Hilbert correspondence available
in our generality, even for complete regular local \(\QQ\)-algebras, we show
that there exists a perverse sheaf \(F_T\) encoding the data of the associated
primes of \(T(\cO_X)\).
In fact, for smooth complex varieties, the perverse sheaf \(F_T\) we use is exactly the
image of \(T(\cO_X)\) under the Riemann--Hilbert correspondence, where we note
that \(T(\cO_X)\) is a regular holonomic
\(\sD_X\)-module by \cite[Theorem 5.4.1]{KK81}.
When \(X\) is a smooth complex variety, our main result below (Theorem
\ref{thm:assocaresimple}) says that the associated primes
of \(T(\cO_X)\) are contained in the set of simple components of
\(\DR_X(T(\cO_X))\).
\par Since we cannot apply the Riemann--Hilbert correspondence directly, we will
reduce to the local case and then approximate \(X\) by spectra of local rings
essentially smooth over \(\QQ\) using N\'eron--Popescu desingularization
\citeleft\citen{Pop86}\citemid Theorem 2.4\citepunct \citen{Pop90}\citemid p.\
45\citepunct\citen{Swa98}\citemid Theorem 1.1\citeright.
We can keep track of Lyubeznik functors, associated primes, and perverse sheaves
while performing this approximation procedure.
After this reduction, we can base change to \(\CC\) and apply the
Riemann--Hilbert correspondence to prove what we want.
\subsection{The perverse sheaf encoding the associated primes of a Lyubeznik
functor}
\par We first define the perverse sheaf whose simple components will encode the
data of the associated primes of a Lyubeznik functor.
\begin{citeddef}\label{def:perverselyu}
  Let \(\ell > 0\) be a prime number.
  Let \(X\) be a connected excellent regular Noetherian scheme of finite Krull
  dimension \(d\).
  Let \(T = T_t \circ \cdots \circ T_2 \circ T_1\) be a Lyubeznik functor on
  \(X\).
  The \textsl{perverse sheaf \(F_T\) associated to \(T(\cO_X)\) with
  coefficients in \(\QQ_\ell\)} is defined inductively as follows.
  \begin{itemize}
    \item If \(t = 0\), then \(F_T = F_\id \coloneqq \QQ_\ell[d]\).
    \item Suppose \(t > 0\) and set \(F' \coloneqq F_{T_{t-1} \circ \cdots \circ
      T_2 \circ T_1}\).
      \begin{enumerate}[label=\((\roman*)\),ref=\roman*]
        \item\label{item:perverselc}
          Suppose \(T_t = \sH^{i}_{Y}(\,\cdot\,)\) for a locally
          closed subset \(Y\) of \(X\).
          Decomposing the inclusion \(Y
          \hookrightarrow X\) as the composition
          \[
            Y \overset{i_Y}{\hooklongrightarrow} U
            \overset{j_U}{\hooklongrightarrow} X
          \]
          of a closed immersion followed by an open immersion, we set
          \[
            F_T \coloneqq \prescript{\fp}{}{\mathcal{H}}^i
            \bigl(j_{U*}i_{Y*}i_Y^!j_U^*\,F'\bigr).
          \]
        \item\label{item:perverselyu}
          Suppose \(T_t\) is the kernel of a morphism in the long exact sequence
          \[
            \cdots \longrightarrow \sH^i_{Y'}(\,\cdot\,) \longrightarrow
            \sH^i_{Y}(\,\cdot\,)
            \longrightarrow \sH^i_{Y-Y'}(\,\cdot\,) \longrightarrow \cdots
          \]
          from \cite[Expos\'e I, Th\'eor\`eme 2.8]{SGA2}
          where \(Y\) is a locally closed subset of \(X\) and \(Y'\) is a
          closed subset of \(Y\).
          With notation as in \((\ref{item:perverselc})\), we also denote by
          \(i\colon Y' \hookrightarrow Y\) the closed inclusion and \(j\colon Y
          - Y' \hookrightarrow Y\) the open inclusion of its complement.
          We then set \(F_T\) to be the kernel of
          the corresponding morphism in the long exact sequence
          \begin{equation}\label{eq:lyubeznikfunctorlesperverse}
            \cdots \longrightarrow
            \prescript{\fp}{}{\mathcal{H}}^i
            \bigl(j_{U*}i_{*}i^!j_U^*\,(\,\cdot\,)\bigr)
            \longrightarrow
            \prescript{\fp}{}{\mathcal{H}}^i
            \bigl(j_{U*}i_{Y*}i_Y^!j_U^*\,(\,\cdot\,)\bigr)
            \longrightarrow
            \prescript{\fp}{}{\mathcal{H}}^i
            \bigl(j_{U*} j_* j^{*} j_U^*(\,\cdot\,)\bigr)
            \longrightarrow \cdots
          \end{equation}
          of functors applied to \(F'\).
      \end{enumerate}
  \end{itemize}
\end{citeddef}
\par When \(X\) is a smooth complex variety, we have
\[
  F_T = \DR_X\bigl(T(\cO_X)\bigr)
\]
by the Riemann--Hilbert correspondence \cite[Chapter VII, Theorem 14.4\((i)\)
and (18.3)]{BGKHME87} and the description of local cohomology functors in
\cite[Chapter VI, Theorem 7.13\((ii)\)]{BGKHME87}.
\subsection{The main comparison theorem and the proof of Theorem
\ref{thm:lyubeznikfunctorsnew}}
\par We can now state our main theorem comparing associated points of Lyubeznik
functors \(T(\cO_X)\) to the simple components of their associated perverse
sheaves \(F_T\).
When \(X\) is a smooth complex variety,
this comparison follows from \citeleft\citen{BBLSZ14}\citemid p.\ 516\citepunct
\citen{NB14}\citemid Remark 2.3\citeright\ together with the Riemann--Hilbert
correspondence \cite[Chapter VII, Theorem 14.4\((i)\) and (18.3)]{BGKHME87} and
the comparison theorem for perverse sheaves in the analytic vs.\ \'etale
topologies \cite[(6.1.2)]{BBDG18}.
\begin{theorem}\label{thm:assocaresimple}
  Let \(\ell > 0\) be a prime number.
  Let \(X\) be a connected excellent regular Noetherian scheme of finite Krull
  dimension and of equal characteristic zero.
  Consider a Lyubeznik functor \(T(\,\cdot\,)\) on \(X\).
  Then, we have
  \begin{equation}\label{eq:associnsimple}
    \Ass_{\cO_X}\bigl(T(\cO_X)\bigr) \subseteq
    \Set*{\eta \in X \given
      \begin{tabular}{@{}c@{}}
        \(\eta\) is the generic point of a locally closed connected\\
        regular subscheme \(j\colon Z \hookrightarrow X\) such that
        \(j_{!*}L[{\dim(Z)}]\)\\
        is a simple component of \(F_T\) for some
        lisse sheaf \(L\) on \(Z\)
    \end{tabular}}.
  \end{equation}
\end{theorem}
Theorem \ref{thm:assocaresimple} immediately implies Theorem
\ref{thm:lyubeznikfunctorsnew}.
\begin{customthm}{B}
  \label{thm:lyubeznikfunctors}
  Let \(R\) be an excellent regular \(\QQ\)-algebra of finite Krull dimension.
  Let \(T(\,\cdot\,)\) be a Lyubeznik functor on \(R\).
  Then, the module \(T(R)\) has finitely many associated prime ideals.
\end{customthm}
\begin{proof}
  This follows from Theorem \ref{thm:assocaresimple} since the right-hand side
  of \eqref{eq:associnsimple} is finite by Theorem \ref{thm:perv}.
\end{proof}
We now prove Theorem \ref{thm:assocaresimple}.
\begin{proof}[Proof of Theorem \ref{thm:assocaresimple}]
  Let \(x \in \Ass_{\cO_X}(T(\cO_X))\).
  Since associated points \cite[Chapter IV, \S1, no.\ 4, Proposition 5]{Bou72}
  and composition series for perverse sheaves are
  compatible with localization
  (see \citeleft\citen{Far09}\citepunct Proof of Th\'eor\`eme 6.1\citepunct
  \citen{Mor25}\citemid Proposition 2.2.1\citeright),
  we may work with one associated point \(x\) at a
  time and replace \(X\) by the local scheme \(\Spec(\cO_{X,x})\).
  Set \(R = \cO_{X,x}\) with maximal ideal \(\fm = \fm_x\).
  We will denote the global sections of \(T(\cO_X)\) by \(T(R)\) since
  \(T(\cO_X)\) is quasi-coherent \cite[Expos\'e II, Proposition 1]{SGA2}.
  \begin{step}\label{step:approxr}
    Noetherian approximation.
  \end{step}
  Since \((R,\fm)\) is a regular local \(\QQ\)-algebra, we can apply
  N\'eron--Popescu desingularization \citeleft\citen{Pop86}\citemid Theorem
  2.4\citepunct \citen{Pop90}\citemid p.\ 45\citepunct\citen{Swa98}\citemid
  Theorem 1.1\citeright\ to write
  \[
    R = \varinjlim_{\lambda \in \Lambda} R_\lambda
  \]
  as a direct limit of smooth \(\QQ\)-algebras.
  Replacing the \(R_\lambda\) by their localizations at \(\fm \cap R_\lambda\),
  we can write \(R\) as a direct limit of essentially smooth local
  \(\QQ\)-algebras \((R_\lambda,\fm_\lambda)\)
  \citeleft\citen{Pop86}\citemid Corollary 2.7\citepunct \citen{Swa98}\citemid
  Corollary 1.3\citeright.
  Now choose a generating set \(f_1,f_2,\ldots,f_r\) for \(\fm\).
  After replacing \(\Lambda\) by a cofinal subset, we may assume that our
  generators \(f_i\) lie in \(R_\lambda\) for every \(\lambda \in \Lambda\).
  Since the maximal ideal \(\fm_\lambda = \fm \cap R_\lambda\) is generated by
  the \(f_i\), we see that \(\dim(R) \ge \dim(R_\lambda)\) for all \(\lambda \in
  \Lambda\) \cite[Theorem 14]{Coh46}.
  Choosing a maximal chain of prime ideals in \(R\), we may moreover assume that
  the generators for all these prime ideals lie in \(R_\lambda\), and hence
  \(\dim(R) \le \dim(R_\lambda)\) for all \(\lambda \in \Lambda\).
  We therefore have \(\dim(R) = \dim(R_\lambda)\) for all \(\lambda \in
  \Lambda\).
  \par Now let \(\varphi_{\lambda\mu}\colon R_\lambda \to R_\mu\) be the
  transition maps in the direct system and let \(\varphi_\lambda \colon
  R_\lambda \to R\) be the insertion maps.
  The maps \(\varphi_{\lambda\mu}\) and \(\varphi_\lambda\) are flat by miracle
  flatness \cite[Proposition 6.1.5]{EGAIV2} since \(R/\fm\) is a field.
  Moreover, these maps have geometrically regular fibers since the maps
  \[
    R_\lambda/\fm_\lambda \hooklongrightarrow R_\mu/\fm_\mu \hooklongrightarrow
    R/\fm
  \]
  are separable extensions of fields and
  then we can apply \cite[Proposition 7.9.8]{EGAIV2} (which uses Hironaka's
  resolutions of singularities \cite[Chapter I, \S3, Main Theorem
  I\((n)\)]{Hir64}).
  \par By \cite[Th\'eor\`eme 8.3.11]{EGAIV3}, there exists \(\lambda_0 \in \Lambda\)
  such that all closed subsets and complements of open sets
  appearing in the composition
  \[
    T = T_t \circ \cdots \circ T_2 \circ T_1
  \]
  are pullbacks of closed subsets \(Z_{j,\lambda_0} \subseteq \Spec(R_{\lambda_0})\).
  Let \(T_{\lambda_0}\) be the corresponding Lyubeznik functor obtained by
  computing local cohomology functors on \(R_{\lambda_0}\) using these
  \(Z_{j,\lambda_0}\).
  Suppose \(\xi \in T(R)\) is an element such that \(\Ann_R(\eta) = \fm\),
  which exists by our hypothesis that \(\fm \in \Ass_R(T(R))\).
  By Gabber's version of Grothendieck's limit theorem for local cohomology
  \cite[Proposition 5.2]{Gab04}, after possibly replacing \(\lambda_0\) by a
  larger element in \(\Lambda\), \(\xi\) is the image of an element
  \(\xi_{\lambda_0} \in T_{\lambda_0}(R_{\lambda_0})\).
  After possibly replacing \(\lambda_0\) again and using \cite[Proposition
  5.2]{Gab04}, we may assume that
  \(f_i \cdot \xi_{\lambda_0} = 0\) for all \(i\).
  Since \(R_{\lambda_0}\) is local, we see that
  \(\Ann_{R_{\lambda_0}}(\xi_{\lambda_0}) = \fm_{\lambda_0}\).
  We therefore have
  \[
    \fm_{\lambda_0} \in
    \Ass_{R_{\lambda_0}}\bigl(T_{\lambda_0}(R_{\lambda_0})\bigr).
  \]
  Since we will no longer need to replace \(\lambda_0\) by a larger element, we
  will denote \(\lambda_0\) simply by \(\lambda\).\smallskip
  \begin{step}\label{step:approxsheaf}
    Approximating \(F_T\).
  \end{step}
  \par We claim that all functors appearing in
  \eqref{eq:lyubeznikfunctorlesperverse} are
  compatible with pullback along the map
  \[
    \prescript{a}{}{\varphi}_\lambda\colon \Spec(R) \longrightarrow
    \Spec(R_\lambda).
  \]
  We proceed by induction on \(t\).
  The case \(t = 0\) holds since \(\QQ_\ell[d]\) pulls back to \(\QQ_\ell[d]\).
  For the case \(t \ge 1\), we work with each \(T_j\) at a time.
  First, we note that since \(R_\lambda \to
  R\) is flat with geometrically regular fibers and \(\dim(R_\lambda) =
  \dim(R)\), pulling back along \(\prescript{a}{}{\varphi}_\lambda\) is
  \(t\)-exact with respect to the perverse \(t\)-structure \cite[Proof of
  Th\'eor\`eme 6.1]{Far09}.
  We then consider the special case when \(Y = U\).
  With notation as in Definition \ref{def:perverselyu}\((\ref{item:perverselyu})\),
  the long exact sequence \eqref{eq:lyubeznikfunctorlesperverse} breaks up into
  the exact sequence
  \begin{equation}\label{eq:fourtermes}
    0 \longrightarrow
    \prescript{\fp}{}{\mathcal{H}}^0\bigl(i_*i^!(\,\cdot\,)\bigr)
    \longrightarrow (\,\cdot\,) \longrightarrow
    \prescript{\fp}{}{\mathcal{H}}^0\bigl(j_*j^*(\,\cdot\,)\bigr)
    \longrightarrow
    \prescript{\fp}{}{\mathcal{H}}^1\bigl(i_*i^!(\,\cdot\,)\bigr)
    \longrightarrow 0
  \end{equation}
  and the isomorphisms
  \begin{equation}\label{eq:fourtermisos}
    \prescript{\fp}{}{\mathcal{H}}^i\bigl(j_*j^*(\,\cdot\,)\bigr)
    \overset{\sim}{\longrightarrow}
    \prescript{\fp}{}{\mathcal{H}}^{i+1}\bigl(i_*i^!(\,\cdot\,)\bigr)
  \end{equation}
  for \(i \ge 1\).
  The terms not involving \(i_*i^!\) are compatible with pullback along
  \(\prescript{a}{}{\varphi}_\lambda\) since
  \(\prescript{a}{}{\varphi}_\lambda^*\) is \(t\)-exact and by the version of
  smooth base change in \citeleft\citen{ILO14}\citemid Expos\'e XIV, Lemme
  2.5.3\citeright.
  This implies the terms involving \(i_*i^!\) are also compatible with pullback
  along \(\prescript{a}{}{\varphi}_\lambda\) by the exactness of
  \eqref{eq:fourtermes} and \eqref{eq:fourtermisos}.
  We therefore see that the long exact sequence
  \eqref{eq:lyubeznikfunctorlesperverse} is compatible with pulling back along
  \(\prescript{a}{}{\varphi}_\lambda\).
  By composing different \(T_j\), we conclude that \(F_T\) is compatible with
  pulling back along \(\prescript{a}{}{\varphi}_\lambda\).
  \par We construct \(F_{T_\lambda}\) to be the perverse sheaf obtained by
  approximating each functor appearing in the definition of \(F_T\) (Definition
  \ref{def:perverselyu}) and applying
  it to \(\QQ_\ell[d]\).
  By the previous paragraph, \(\prescript{a}{}{\varphi}_\lambda^*F_{T_\lambda} =
  F_T\).
  Now take a composition series
  \[
    0 = F_{T_\lambda,0} \subsetneq F_{T_\lambda,1} \subsetneq \cdots \subsetneq
    F_{T_\lambda,\ell} = F_{T_\lambda}
  \]
  for \(F_{T_\lambda}\).
  Since perverse sheaves
  \cite[Proof of Th\'eor\`eme 6.1]{Far09} and \(j_{!*}\) \citeleft\citen{SGA43}\citemid
  Expos\'e XVII, Lemme 5.1.2\citepunct \citen{Eke90}\citemid
  Theorem 6.3\((iii)\)\citepunct \citen{ILO14}\citemid Expos\'e XIV, Lemme
  2.5.3\citeright\ are compatible with base change along
  faithfully flat maps with geometrically regular fibers between local rings of
  the same dimension, we see that this
  composition series pulls back to a filtration
  \begin{align*}
    0 = \prescript{a}{}{\varphi}_\lambda^*\,
    F_{T_\lambda,0} \subsetneq
    \prescript{a}{}{\varphi}_\lambda^*\,
    F_{T_\lambda,1} &\subsetneq \cdots \subsetneq
    \prescript{a}{}{\varphi}_\lambda^*\,
    F_{T_\lambda,\ell} =
    F_T
  \intertext{for \(F_T\) that can be refined
  into a composition series for \(F_T\) by taking a composition series}
    0 = F_{T,i,0}
    \subsetneq
    F_{T,i,1}
    \subsetneq \cdots
    &\subsetneq F_{T,i,\ell_i} = \frac{\prescript{a}{}{\varphi}_\lambda^*\,
    F_{T_\lambda,i}}{\prescript{a}{}{\varphi}_\lambda^*\,
    F_{T_\lambda,i-1}}
  \end{align*}
  for each \(i \in \{1,2,\ldots,\ell\}\) and then concatenating the composition
  series together to form a composition series for \(F_T\).\smallskip
  \setcounter{step}{2}
  \begin{step}
    Base change to \(\CC\) and applying the Riemann--Hilbert correspondence.
  \end{step}
  \par We now base change to \(\CC\) by considering the ring \(R_\lambda
  \otimes_\QQ \CC\), which is essentially smooth over \(\CC\).
  Denote the pullback of \(F_{T_\lambda}\) to \(\Spec(R_\lambda
  \otimes_\QQ \CC)\) as \(F_{T_\lambda,\CC}\).
  As in Step \ref{step:approxsheaf}, we can choose a composition series for
  \(F_{T_\lambda}\), pull it back to \(R_\lambda \otimes_\QQ \CC\), then refine
  it to yield a composition series for \(F_{T_\lambda,\CC}\).
  By flat base change for associated prime ideals \cite[Chapter IV, \S1, no.\ 4,
  Proposition 5]{Bou72} and local cohomology modules \cite[Theorem 4.3.2]{BS13},
  we see that every prime ideal in \(R_\lambda
  \otimes_\QQ \CC\) lying over \(\fm_\lambda\) is an associated prime ideal of
  \(T(R) \otimes_{\QQ} \CC\).
  By \citeleft\citen{BBLSZ14}\citemid p.\ 516\citepunct
  \citen{NB14}\citemid Remark 2.3\citeright, the Riemann--Hilbert
  correspondence \cite[Chapter VII, Theorem 14.4\((i)\) and (18.3)]{BGKHME87},
  the description of local cohomology functors in
  \cite[Chapter VI, Theorem 7.13\((ii)\)]{BGKHME87}, and
  the comparison theorem for perverse sheaves in the analytic vs.\ \'etale
  topologies \cite[(6.1.2)]{BBDG18},
  the associated prime ideals of \(T(R_\lambda) \otimes_{\QQ} \CC\) must
  be generic points of locally closed subschemes of \(\Spec(R_\lambda
  \otimes_\QQ \CC)\) associated to simple components of
  \(F_{T_\lambda,\CC}\).
  By construction of our composition series for \(F_{T_\lambda}\), we see that
  \(F_{T_\lambda}\) has a simple component supported on \(\{\fm_\lambda\}\).
  Finally, by the previous paragraph, this simple component pulls back to a
  subquotient of \(F_T\) that has a simple component supported on \(\{\fm\}\).
\end{proof}

\section{Local cohomology modules of\texorpdfstring{\except{toc}{\\}{}}{}
excellent locally unramified regular rings}\label{sect:mixedchar}
In this section, we prove Theorem \ref{thm:mainnew}.
Since Theorem \ref{thm:lyubeznikfunctors} says that \(H^i_I(R) \otimes_\ZZ \QQ\)
has finitely many associated prime ideals, what remains is to show that
\[
  \bigcup_{p\ \text{prime}}
  \Ass_R\Bigl(\ker\bigl(H^i_I(R) \overset{p}{\longrightarrow}
  H^i_I(R)\bigr)\Bigr)
\]
is finite.
To do so, we will use Lyubeznik's theory of \(F\)-modules \cite{Lyu97}, the fact
that local cohomology modules are \(F\)-finite \(F\)-modules \cite[Example
2.2\((b)\)]{Lyu97}, and the fact that \(F\)-finite \(F\)-modules have finite
length in the category of \(F\)-modules.
This last finite length property is where the hypothesis on the quotients
\(R/pR\) is used, and is due to
Blickle and B\"ockle
\cite[Theorem 5.13]{BB11}.
See Theorem \ref{thm:fmodfinlen}, where we also state an earlier finite length
result for rings of
finite type over regular local rings of prime characteristic \(p > 0\)
due to Lyubeznik \cite[Theorem
3.2]{Lyu97}.
\subsection{\emph{F}-modules}
We recall the definition of \(F\)-modules due to Lyubeznik \cite{Lyu97}.
This notion relies on the following functor introduced by Peskine and Szpiro
\cite{PS73}.
\begin{citeddef}[{\cite[Chapitre I, D\'efinition 1.2]{PS73}}]
  Let \(R\) be a ring of prime characteristic \(p > 0\).
  Denote by
  \[
    \begin{tikzcd}[row sep=0,column sep=1.475em]
      F\colon &[-2.35em]  R \rar & F_*R\\
      & r \rar[mapsto] & r^p
    \end{tikzcd}
  \]
  the Frobenius map.
  The \textsl{Frobenius functor of Peskine--Szpiro} is the extension of scalars functor
  \[
    \begin{tikzcd}[row sep=0,column sep=1.475em]
      \mathsf{F}\colon
      &[-3.5em]
      \mathsf{Mod}_R \rar
      & \mathsf{Mod}_R\\
      & M \rar[mapsto] & M \otimes_R F_*R\\
      & \Bigl(M \overset{h}{\longrightarrow} N\Bigr) \rar[mapsto]
      & \Bigl(M \otimes_R F_*R \xrightarrow{\,h \otimes \id\,} N \otimes_R
      F_*R\Bigr)
    \end{tikzcd}
  \]
  along the Frobenius map \(F\), where we consider \(M \otimes_R F_*R\) as an
  \(R\)-module using the \(F_*R\)-module structure coming from the right factor
  \(F_*R\).
\end{citeddef}
The Peskine--Szpiro functor \(\mathsf{F}\) is exact when \(R\) is regular, since
in this case, the Frobenius map \(F\colon R \to F_*R\) is flat \cite[Theorem
2.1]{Kun69}.
\begin{citeddef}[{\cite[Definition 1.1]{Lyu97}}]
  Let \(R\) be a regular ring of prime characteristic \(p > 0\).
  An \textsl{\(F\)-module} over \(R\) is a pair \((\sM,\theta_\sM)\) where \(\sM\) is an
  \(R\)-module and
  \[
    \theta_\sM\colon \sM \overset{\sim}{\longrightarrow} \mathsf{F}(\sM)
  \]
  is a right \(R\)-module isomorphism, which we call the \textsl{structure morphism}
  of \(\sM\).
  A \textsl{morphism} \(f\colon (\sM,\theta_\sM) \to (\sN,\theta_\sN)\) of \(F\)-modules is
  an \(R\)-module homomorphism \(f\colon \sM \to \sN\) for which the diagram
  \[
    \begin{tikzcd}
      \sM \rar{f}\dar[swap]{\theta_\sM} & \sN\dar{\theta_\sN}\\
      \mathsf{F}(\sM) \rar{\mathsf{F}(f)}
      & \mathsf{F}(\sN)
    \end{tikzcd}
  \]
  commutes in \(\mathsf{Mod}_R\).
\end{citeddef}
The following class of \(F\)-modules satisfies good finiteness properties.
\begin{citeddef}[{\cite[Definitions 1.9 and 2.1]{Lyu97}}]
  Let \(R\) be a regular ring of prime characteristic \(p > 0\).
  Let \((\sM,\theta)\) be an \(F\)-module over \(R\).
  A \textsl{generating morphism} for \(\sM\) is an \(R\)-module map
  \[
    \beta\colon M \longrightarrow \mathsf{F}(M)
  \]
  for an \(R\)-module \(M\) such that \(\sM\) is the direct limit of the direct
  system in the top row of the commutative diagram
  \[
    \begin{tikzcd}[column sep=large]
      M \rar{f} \dar[swap]{\beta}
      & \mathsf{F}(M) \dar{\mathsf{F}(\beta)}\rar{\mathsf{F}(\beta)}
      & \mathsf{F}^2(M) \dar{\mathsf{F}^2(\beta)}\rar{\mathsf{F}^2(\beta)}
      & \cdots\\
      \mathsf{F}(M) \rar{\mathsf{F}(\beta)}
      & \mathsf{F}^2(M) \rar{\mathsf{F}^2(\beta)}
      & \mathsf{F}^3(M) \rar{\mathsf{F}^3(\beta)}
      & \cdots
    \end{tikzcd}
  \]
  and such that the structure isomorphism \(\theta\colon \sM \to
  \mathsf{F}(\sM)\) is the direct limit of the vertical maps in this diagram.
  Any morphism \(\beta\colon M \to \mathsf{F}(M)\) induces an \(F\)-module in
  this way, which we call the \(F\)-module \textsl{generated by} \(\beta\).
  We say that \(\sM\) is \textsl{\(F\)-finite} if \(\sM\) has a generating
  morphism \(\beta\colon M \to \mathsf{F}(M)\) where \(M\) is a finitely
  generated \(R\)-module.
\end{citeddef}
We now state the finite length property of \(F\)-finite \(F\)-modules that we need.
For the statement below, recall
that a ring \(R\) of prime characteristic \(p > 0\) is \textsl{\(F\)-finite} if
the Frobenius map \(F\colon R \to F_*R\) is module-finite \cite[p.\ 464]{Fed83}.
\begin{citedthm}[{\citeleft\citen{Lyu97}\citemid Theorem 3.2\citepunct
  \citen{BB11}\citemid Theorem 5.13\citeright}]\label{thm:fmodfinlen}
  Let \(R\) be a regular ring of prime characteristic \(p > 0\).
  Suppose one of the following assumptions hold.
  \begin{enumerate}[label=\((\roman*)\)]
    \item \(R\) is finitely generated over a regular local ring of prime
      characteristic \(p > 0\).
    \item \(R\) is \(F\)-finite.
  \end{enumerate}
  Then, every \(F\)-finite \(F\)-module over \(R\) has finite length in the
  category of \(F\)-modules over \(R\).
\end{citedthm}

\subsection{The proof of Theorem \ref{thm:mainnew}}
We are now ready to prove Theorem \ref{thm:mainnew} using Theorem
\ref{thm:lyubeznikfunctors} and a modification of
the strategy in \cite{BBLSZ14}.
\begin{customthm}{A}\label{thm:mainnewtext}
  Let \(R\) be an excellent regular ring of finite Krull dimension that is flat
  over a regular domain \(A\) of dimension \(\le 1\).
  Suppose for every nonzero prime ideal \(\fp \subseteq A\) such that \(A/\fp\)
  is of prime characteristic, the quotient ring
  \(R/\fp R\) is regular and one of the following assumptions hold:
  \begin{enumerate}[label=\((\roman*)\),ref=\roman*]
    \item\label{thm:mainnewtextffin} \(R/\fp R\) is \(F\)-finite.
    \item\label{thm:mainnewtexteft} \(A_\fp\) is excellent and
      \(R \otimes_A A_\fp\) is essentially of finite type over \(A_\fp\).
  \end{enumerate} 
  Let \(I \subseteq R\) be an ideal.
  Then, for every \(i \ge 0\), the local cohomology module \(H^i_I(R)\) has
  finitely many associated prime ideals.
\end{customthm}
\begin{proof}
  Working one connected component of \(\Spec(R)\) at a time, we may assume that
  \(R\) is a domain.
  Fix a set of generators \(f_1,f_2,\ldots,f_r\) for \(I\) and consider the
  Koszul cohomology module \(H^i(\underline{f};R)\).
  Since \(H^i(\underline{f};R)\) is finitely generated, we can write
  \[
    \Ass_R\bigl(H^i(\underline{f};R)\bigr) = \{\fq_1,\fq_2,\ldots,\fq_m\}
  \]
  as a finite set of prime ideals \cite[Chapter IV, \S1, no.\ 4, Corollary to
  Theorem 2]{Bou72}.\smallskip
  \par For every \(j\), let \(\fp_j = \fq_j \cap A\).
  We set
  \[
    R_\fp \coloneqq R \otimes_A A_\fp
  \]
  for every prime ideal \(\fp
  \subseteq A\).
  \begin{step}\label{step:koszulassoc}
    For every prime ideal
    \[
      \fp \in \Spec(A) - \bigl\{(0),\fp_1,\fp_2,\ldots,\fp_m\bigr\},
    \]
    the uniformizer of \(A_\fp\)
    is a nonzerodivisor on \(H^i_I(R) \otimes_A A_\fp\).
  \end{step}
  Let \(u\) be the uniformizer of \(A_\fp\).
  It suffices to show that \(u\) is a nonzerodivisor after localizing and
  completing \(R\) at every maximal ideal \(\fm \subseteq R\) containing \(\fp\).
  Since \(R_\fp/uR_\fp \cong R/\fp R\)
  is regular, we may choose \(u\) to be part of a regular system
  of parameters for \((R_\fm)^\land\), in which case \((R_\fm)^\land\) is a
  formal power series ring over a DVR \(V\) with uniformizer \(u\) by Cohen's
  structure theorem \cite[Theorem 15]{Coh46}.
  We then see that \(u\) is a nonzerodivisor on \(H^i_I((R_\fm)^\land)\) by
  \cite[Theorem 4.1(1)]{BBLSZ14}.\smallskip
  \par Since
  \begin{equation}\label{eq:basechangefraca}
    H^i_I(R) \otimes_A \Frac(A) \cong H^i_I\bigl(R \otimes_A \Frac(A)\bigr)
  \end{equation}
  has
  finitely many associated prime ideals by \cite[Corollary 2.3]{HS93} (if
  \(\Frac(A)\) is of characteristic \(p > 0\)) and Theorem \ref{thm:lyubeznikfunctors}
  (if \(\Frac(A)\) is of characteristic zero),
  it remains to show that
  \[
    \bigcup_{\fp \in \Spec(A) - \{(0)\}}
    \Ass_{R_\fp}
    \Bigl(\ker\bigl(H^i_I(R_\fp) \overset{u}{\longrightarrow}
    H^i_I(R_\fp)\bigr)\Bigr)
  \]
  is finite.
  Here, the isomorphism
  \eqref{eq:basechangefraca}
  holds by flat base change for local cohomology modules \cite[Theorem 4.3.2]{BS13}.
  By Step \ref{step:koszulassoc}, this set is equal to
  \[
    \bigcup_{\fp \in \{\fp_1,\fp_2,\ldots,\fp_m\} - \{0\}}  
    \Ass_{R_\fp}
    \Bigl(\ker\bigl(H^i_I(R_\fp) \overset{u}{\longrightarrow}
    H^i_I(R_\fp)\bigr)\Bigr)
  \]
  and hence we may work one prime \(\fp \in \{\fp_1,\fp_2,\ldots,\fp_m\} - \{0\}\) at a time.
  We may therefore replace \(A\) by \(A_\fp\) and assume that \((A,\fp)\) is a
  DVR with uniformizer \(u\).
  \par If \(A\) is of equal characteristic zero, then we are done by Theorem
  \ref{thm:lyubeznikfunctors}.
  It therefore suffices to consider the case when \(A/\fp A\) is of prime
  characteristic.
  \begin{step}
    The set
    \[
      \Ass_{R}
      \Bigl(\ker\bigl(H^i_I(R) \overset{u}{\longrightarrow}
      H^i_I(R)\bigr)\Bigr)
    \]
    is finite.
  \end{step}
  \par We claim it suffices to show the case when \(R/\fp R\) is \(F\)-finite.
  In other words, we show that case \((\ref{thm:mainnewtexteft})\)
  can be reduced to case \((\ref{thm:mainnewtextffin})\).
  By the gamma construction of Hochster and Huneke \citeleft\citen{HH94}\citemid
  \S6\citepunct \citen{Has10}\citemid Lemma 3.23\citeright\ when \(A\) is of
  prime characteristic or by the mixed characteristic version of the gamma
  construction \cite[\S5.2]{HJ24} when \(A\) is of mixed characteristic \((0,p)\),
  there exists a
  faithfully flat extension
  \[
    A \longrightarrow \hat{A} \longrightarrow \hat{A}^\Gamma
  \]
  of \(A\) such
  that \(A/\fp\) is \(F\)-finite and \(R/\fp R \otimes_A \hat{A}^\Gamma\) is
  regular.
  Note that the assumption that \(A_\fp\) is excellent is used to ensure
  that \(A \to \hat{A}\) has geometrically regular fibers, and hence all base
  changes of \(A \to \hat{A}\) by maps essentially of finite type preserve
  regular loci \cite[Proposition 6.8.2 and 6.8.3]{EGAIV2}.
  Since associated prime ideals are compatible with faithfully flat base change
  \cite[Chapter IV, \S1, no.\ 4, Proposition 5]{Bou72}, we may replace \(R\) by
  \(R \otimes_A \hat{A}^\Gamma\)
  to assume that \(R/\fp R\) is
  \(F\)-finite.
  \par Consider the exact sequence
  \[
    0 \longrightarrow R \overset{u}{\longrightarrow} R
    \longrightarrow R/\fp R
    \longrightarrow 0.
  \]
  We then have the associated long exact sequence
  \begin{equation}\label{eq:bblsz14}
    \cdots \longrightarrow H^{i-1}_I(R) \longrightarrow
    H^{i-1}_I(R/\fp R) \overset{d}{\longrightarrow}
    H^i_I(R) \overset{u}{\longrightarrow}
    H^i_I(R) \longrightarrow \cdots.
  \end{equation}
  Then, \(H^{i-1}_I(R/\fp R)\) is an \(F\)-finite \(F\)-module by \cite[Example
  2.2\((b)\)]{Lyu97} and has finite length in the category of
  \(F\)-modules by Theorem \ref{thm:fmodfinlen}.
  Here, we use the assumption that \(R/\fp R\) is \(F\)-finite.
  We will show that
  \begin{equation}\label{eq:redmodpcont}
    \Ass_R\Bigl(\ker\bigl(H^i_I(R) \overset{u}{\longrightarrow}
    H^i_I(R)\bigr)\Bigr) \subseteq \Set*{\fq \subseteq R \given
      \begin{tabular}{@{}c@{}}
        \(\fq\) is an associated prime ideal\\
        of a simple \(F\)-module\\
        component
        of \(H^{i-1}_I(R/\fp R)\)
    \end{tabular}}.
  \end{equation}
  By the exactness of \eqref{eq:bblsz14}, we have the isomorphism
  \[
    \im(d) \cong \ker\bigl(H^i_I(R) \overset{u}{\longrightarrow}
    H^i_I(R)\bigr).
  \]
  Fix a composition series
  \begin{align}
    0 = \sM_0 \subsetneq \sM_1 \subsetneq \cdots &\subsetneq \sM_\ell =
    H^{i-1}_I(R/\fp R)\nonumber
  \intertext{for \(H^{i-1}_I(R/\fp R)\) as an \(F\)-module.
  By \cite[Theorem 2.12\((b)\)]{Lyu97}, each factor \(\sM_i/\sM_{i-1}\) has a
  unique associated prime ideal.
  Since Frobenius is compatible with localization and completion,
  we see that}
    0 = \sM_0 \otimes_R (R_\fq)^\wedge \subseteq \sM_1 \otimes_R (R_\fq)^\wedge
    \subseteq \cdots &\subseteq \sM_\ell \otimes_R (R_\fq)^\wedge \cong
    H^{i-1}_I\bigl((R_\fq)^\wedge/\fp(R_\fq)^\wedge\bigr)\label{eq:compserrphat}
  \intertext{is a filtration as \(F\)-modules.
  Since generating morphisms of \(F\)-modules on \(R\) pull back to
  generating morphisms of \(F\)-modules on \((R_\fq)^\wedge\), the module}
    H^{i-1}_I(R/\fp R) \otimes_R (R_\fq)^\wedge &\cong
    H^{i-1}_I\bigl((R_\fq)^\wedge/\fp(R_\fq)^\wedge\bigr)\nonumber
  \end{align}
  is an \(F\)-finite \(F\)-module over \((R_\fq)^\wedge/\fp(R_\fq)^\wedge\).
  We can therefore refine the
  filtration \eqref{eq:compserrphat} to become a composition series for
  \(H^{i-1}_I(R/\fp R) \otimes_R (R_\fq)^\wedge\).
  Moreover, if
  \[
    \bigl(\sM_i/\sM_{i-1}\bigr) \otimes_R (R_\fq)^\wedge
  \]
  is nonzero, its simple components each
  have a unique associated prime ideal by \cite[Theorem 2.12\((b)\)]{Lyu97}.
  The associated prime ideals of these simple components
  all contract to the unique associated prime ideal of \(\sM_i/\sM_{i-1}\) by
  the compatibility of associated prime ideals with flat base change
  \cite[Chapter IV, \S1, no.\ 4, Proposition 5]{Bou72}.
  \par Now consider \eqref{eq:bblsz14} after base change to
  \((R_\fq)^\wedge\).
  As in the proof of \cite[Theorem 4.1]{BBLSZ14}, we see that the map
  \[
    H^{i-1}_I\bigl((R_\fq)^\wedge/\fp(R_\fq)^\wedge\bigr) \xrightarrow{d \otimes_R
    (R_\fq)^\wedge}
    H^i_I\bigl((R_\fq)^\wedge\bigr)
  \]
  is a map of \(\sD_V((R_\fq)^\wedge)\)-modules where \(V\) is a coefficient ring for
  \((R_\fq)^\wedge\) in the sense of \cite[Definition on p.\ 84]{Coh46}.
  Since
  \begin{equation}\label{eq:redmodplc}
    H^{i-1}_I\bigl((R_\fq)^\wedge/\fp(R_\fq)^\wedge\bigr) \cong
    H^{i-1}_I(R/\fp R) \otimes_R (R_\fq)^\wedge
  \end{equation}
  is of finite length as a
  \(\sD_V((R_\fq)^\wedge)\)-module by \cite[Theorem 5.7]{Lyu97}, we see that
  \(\im(d) \otimes_R (R_\fq)^\wedge\) is also of finite length and that
  each simple \(\sD_V((R_\fq)^\wedge)\)-module component
  \(\im(d) \otimes_R (R_\fq)^\wedge\) is a simple
  \(\sD_V((R_\fq)^\wedge)\)-module component of
  \eqref{eq:redmodplc}.
  In particular, since \(\fq(R_\fq)^\wedge\) is an associated prime ideal of
  \(\im(d) \otimes_R (R_\fq)^\wedge\), we see that by
  \citeleft\citen{BBLSZ14}\citemid p.\ 516\citepunct
  \citen{NB14}\citemid Remark 2.3\citeright, there is a simple
  \(\sD_V((R_\fq)^\wedge)\)-module component
  \(\sN\) of \eqref{eq:redmodplc}
  whose unique maximal
  associated prime ideal is \(\fq (R_\fq)^\wedge\).
  By \cite[Theorem 5.6]{Lyu97}, this simple component \(\sN\) is a direct
  summand of a simple \(F\)-module component \(\bar{\sN}\) of
  \eqref{eq:redmodplc}
  and \(\bar{\sN}\) has 
  \(\fq (R_\fq)^\wedge\) as its unique associated
  prime ideal by \cite[Theorem 2.12\((b)\)]{Lyu97}.
  This simple component \(\bar{\sN}\) appears as a simple component of one of
  the factors
  \[
    \bigl(\sM_i/\sM_{i-1}\bigr) \otimes_R (R_\fq)^\wedge
  \]
  in \eqref{eq:compserrphat}.
  By the previous paragraph, we see that \(\fq\) is the unique associated prime
  ideal of \(\sM_i/\sM_{i-1}\).
  This completes the proof of \eqref{eq:redmodpcont} and therefore of
  Theorem \ref{thm:mainnewtext}.
\end{proof}

