\subsection{Computing Sobol' indices}
The main and total effect indices can be computed by MC or QMC approximation of D-dimensional integrals (\cite{Sob01}). Here we assume that function $g$ is defined in the m-dimensional unit hypercube $[0,1]^m$. Let $\mathbf{v} = \{u_{i_1}, ..., u_{i_d} \} \subseteq \mathbf{u}$ with $i_j \in \mathbf{D}$ for all $j$ and $\mathbf{w}$ such that $(\mathbf{v}, \mathbf{w}) = \mathbf{u}$. Samples $\mathbf{u}=(\mathbf{v}, \mathbf{w})$ and $\mathbf{u}^{\prime}=(\mathbf{v}^{\prime}, \mathbf{w}^{\prime})$ are assumed to be independent. We adopted total effect indices formulas from \cite{Sob01} and main effect indices with improved formulas introduced in \cite{Mau07}: 
\begin{equation}
    \label{sobol_indices}
    \begin{split}
    S_{\mathbf{u}}^{tot} &= \frac{1}{2 \sigma^2_g} \int_0^1 \big[g(\mathbf{u}) - g(\mathbf{v}^{\prime}, \mathbf{w})\big]^2 d\mathbf{u}d\mathbf{v}^{\prime} \simeq \frac{1}{2 \sigma^2_g} \bigg(\frac{1}{N} \sum\limits_{j=1}^{N} \big[ g(\mathbf{u}_j) - g(\mathbf{v}_j^{\prime}, \mathbf{w}) \big]^2\bigg),\\
        S_{\mathbf{u}} &= \frac{1}{\sigma^2_g} \int_0^1 g(\mathbf{u})\big[g(\mathbf{v}, \mathbf{w}^{\prime}) - g(\mathbf{u}^{\prime})\big] d\mathbf{u}^{\prime}d\mathbf{u} \simeq \frac{1}{\sigma^2_g} \bigg(\frac{1}{N} \sum\limits_{j=1}^{N} g(\mathbf{u}_j)\big[ g(\mathbf{v}_j, \mathbf{w}_j^{\prime}) - g(\mathbf{u}_j^{\prime}) \big]\bigg).
    \end{split} 
\end{equation}
Here $\sigma^2_g$ denotes the function variance. 

