\section{Immersions of $K_{2\lfloor n/5\rfloor}$}\label{sec:2/5}

In this section, we present a somewhat simpler proof of Theorem~\ref{thm:gauthier}.
A natural step taken by Gauthier, Le, and Wollan~\cite{gauthier2019forcing}
is to prove that a minimal graph with independence number~\(2\) contains 
an induced copy of \(C_5\).
We prove it here for completeness.

\begin{lemma}\label{lemma:induced-C5}
  If \(G\) is a minimal graph with independence number \(2\), 
  then $G$ has an induced copy of \(C_5\).
\end{lemma}
\begin{proof}
  First, we claim that \(G\) contains an induced path of length \(2\).
  Indeed, since \(G\) is not a complete graph, there is at least a pair of
  nonadjacent vertices \(u\) and \(v\).
  Let \(P\) be a shortest path joining \(u\) and \(v\).
  Note that \(P\) must be an induced path and, since \(u\) and \(v\) are nonadjacent,
  \(P\) contains an induced path of length \(2\) as desired.

  Let \(\langle v_1,v_2,v_3\rangle\) be an induced path of length \(2\) in \(G\).
  Observe that, by the minimality of~\(G\), for any edge $uv\in E(G)$, we have $\alpha(G - {uv})=3$.
  Hence, there is a vertex $v_4$ that is nonadjacent to both $v_1$ and $v_2$;
  and there is a vertex $v_5$ that is nonadjacent to both $v_2$ and $v_3$.
  Since \(v_1\) is nonadjacent to both \(v_3\) and \(v_4\), we have \(v_3v_4\in E(G)\). 
  Hence \(v_4 \neq v_5\).
  Analogously, \(v_1v_5, v_4v_5\in E(G)\), and hence
  \(\langle v_1,v_2,v_3,v_4,v_5,v_1\rangle\) is an induced copy of \(C_5\)
  in \(G\), as desired.
\end{proof}

Now we can present our proof of Theorem~\ref{thm:gauthier}.

\begin{proof}[Alternative proof of Theorem~\ref{thm:gauthier}]
  The proof follows by induction on \(n + |E(G)|\).
  One can easily check that the statement holds for \(n \leq 9\).
  Since we seek an immersion with $2\lfloor n/5\rfloor$ vertices, 
  we may also assume $n=5t$ for some $t\geq2$. So \(n\geq 10\),
  and now we look for an immersion of \(K_{2t}\) in \(G\).

  If \(\alpha(G-e) \leq 2\) for some edge \(e\in E(G)\),
  then, by the induction hypothesis, \(G-e\) (and consequently \(G\)) 
  contains an immersion of \(K_{2t}\), as desired.
  Therefore, we may assume that \(G\) is minimal with \(\alpha(G) \leq 2\).
  Moreover, the minimality of \(G\) implies \(\alpha(G) = 2\),
  and, in particular, \(G\) is not a complete graph.
  By Lemma~\ref{lemma:induced-C5}, there is an induced copy \(C\) of \(C_5\) in~\(G\).
  Let \(C = \langle v_1,v_2,v_3,v_4,v_5,v_1\rangle\), with \(v_i\in V(G)\) for \(i\in [5]\).

  \begin{claim}
    Every vertex in $V(G)\setminus V(C)$ is adjacent to three consecutive vertices in $C$.
  \end{claim}
  \begin{proof}
    Let \(u \in V(G)\setminus V(C)\).
    Assume, without loss of generality, that $u$ is nonadjacent to $v_1$. 
    Since $v_1v_3,v_1v_4\not\in E(G)$ and \(\alpha(G) = 2\),
    $u$ is adjacent to $v_3$ and $v_4$. 
    Again, since $v_2v_5\not\in E(G)$ and \(\alpha(G) =2\), 
    \(u\) is either adjacent to \(v_2\) or to \(v_5\),
    as desired.
    \renewcommand{\qedsymbol}{$\blacksquare$}%
  \end{proof}

  By the induction hypothesis, \(G - V(C)\) contains an immersion \(K'\) of \(K_{2t - 2}\).
  Let \(I \subseteq V(G)\setminus V(C)\) be the branch vertices of \(K'\).
  Partition $V(G)\setminus(I\cup V(C))$ into five sets $Z_1, \ldots, Z_5$ such that 
  if $u\in Z_i$ then $v_{i-1},v_i,v_{i+1}\in N(u)$, with \(v_0=v_5\) and \(v_6=v_1\).
  Observe that a vertex \(u \notin V(C)\) may fit in more than one such \(Z_i\).
  If this is the case, it is included in only one such \(Z_i\) chosen arbitrarily. 
  Thus \(|Z_1| + \cdots + |Z_5| = |V(G)\setminus(I\cup V(C))| = n - (2t - 2 + 5) = 3(t-1)\), 
  and hence there is an $i$ for which \(|Z_i|\leq\frac{3}{5}(t-1).\)
  Assume, without loss of generality, that
  \begin{equation}\label{eq:Zi}
    |Z_2|\leq\frac{3}{5}(t-1).
  \end{equation}

  Now, for \(i \in\{1,3\}\), let 
  \[X_i = I\setminus N(v_i) \qquad\text{and}\qquad Y^+_i=N(v_i)\setminus(I\cup V(C)).\]
  Since $v_1v_3\not\in E(G)$ and \(\alpha(G) = 2\), it follows that \(X_1\cap X_3 = \emptyset\) and
  \begin{equation}\label{eq:Y_1+UY_3+}
    Y^+_1\cup Y^+_3=V(G)\setminus(I\cup V(C)).
  \end{equation}

  Since $\alpha(G)= 2$, the set $\overline{N(u)} = V(G)\setminus (N(u)\cup\{u\})$ induces
  a clique for every $u\in V(G)$.
  Thus, if \(|\overline{N(u)}| \geq 2t\) for some vertex \(u\in V(G)\),
  then \(\overline{N(u)}\) induces the desired immersion.
  Therefore, we may assume that \(|\overline{N(u)}| \leq 2t-1\)
  for every \(u\in V(G)\).
  This implies that \(|N(u)| = n - 1 - |\overline{N(u)}| \geq 3t\) for every \(u\in V(G)\).
  The next claim is an important step in this proof.

  \begin{claim}\label{claim:good-subsets}
     There are disjoint sets $Y_1\subseteq Y^+_1\setminus Z_2$ and $Y_3\subseteq Y^+_3\setminus Z_2$ 
     such that \(|Y_1|=|X_1|\) and \(|Y_3|=|X_3|\).
  \end{claim}
  \begin{proof}
    Let \(i\in \{1,3\}\), and note that $|N(v_i)| = |Y^+_i|+|I\setminus X_i|+2$.
    Observe that \(|I\setminus X_i| = |I| - |X_i| = 2(t-1) - |X_i|\), and hence
    \begin{equation}\label{eq:lowerbound:Yi+}
      |Y^+_i|\geq |N(v_i)| - |I\setminus X_i| - 2 
      \geq 3t - 2(t-1) + |X_i| - 2 = 
      t+|X_i|.
    \end{equation}

    In particular, by~\eqref{eq:Zi}, we obtain that \(|Y^+_i| \geq |Z_2| + |X_i|\).
    Choose $Y_1\subseteq Y^+_1\setminus Z_2$ with $|Y_1|=|X_1|$, 
    giving priority to vertices not in $Y^+_1\cap Y^+_3$.
    This choice implies that either $Y_1\subseteq Y^+_1\setminus Y^+_3$
    or $Y^+_1\setminus Y^+_3 \subseteq Y_1$.
%   
    If $Y_1\subseteq Y^+_1\setminus Y^+_3$, then by~\eqref{eq:Zi} 
    and~\eqref{eq:lowerbound:Yi+}, since \(t\geq 2\),
    we have $|Y^+_3\setminus Z_2| \geq t + |X_3|-\frac{3}{5}(t-1)\geq |X_3|$, 
    and we can choose \(Y_3\) as desired.
%    
    On the other hand, if $Y^+_1\setminus Y^+_3\subseteq Y_1$, 
    then every element in \(Y_1^+\cup Y_3^+\) that is not in \(Y_1\) must be in~\(Y_3^+\).
    Hence, by~\eqref{eq:Y_1+UY_3+},
    we have \(V(G) \setminus \big(I \cup V(C)\big) = Y_1^+ \cup Y_3^+ = Y_1 \cup (Y_3^+\setminus Y_1)\)
    and, since~\(Y_1 \cap (Y_3^+\setminus Y_1) = \emptyset\), we have that
    \(|Y_3^+ \setminus Y_1| = |V(G) \setminus (I \cup V(C))| - |Y_1| = 3(t-1) - |Y_1|\).
    Note that \(|X_1|+|X_3|\leq |I| = 2(t-1)\) because \(X_1\) and \(X_3\) are disjoint sets in~\(I\). Thus
    \begin{align}
        |Y_3^+\setminus (Y_1\cup Z_2)| 
            & \geq |Y_3^+\setminus Y_1| - |Z_2| \nonumber \\
            & = 3(t-1) - |Y_1| - |Z_2|\nonumber \\
            &  \geq 3(t-1)-|X_1| -\frac{3}{5}(t-1) \nonumber \\ 
            &   >    3(t-1)-2(t-1)+|X_3|-(t-1) 
            \geq |X_3|.\label{eq:lower_bound_Y_3}
    \end{align}
    Therefore, we can choose \(Y_3\) as desired.
    \renewcommand{\qedsymbol}{$\blacksquare$}% 
  \end{proof}

  Finally, note that every vertex in $V(G)\setminus\big(I\cup V(C)\cup Z_2\big)$ has
  two neighbors in $\{v_2, v_4, v_5\}$.
  Moreover, every vertex in $X_1\cup X_3$ also has two neighbors in $\{v_2, v_4, v_5\}$.
  Therefore, every pair of vertices $u,w$ with $u\in X_1\cup X_3$ and $w\in Y_1\cup Y_3$ 
  has at least one common neighbor \(v_{uw}\) in \(\{v_2, v_4, v_5\}\).

  Now, let \(X_1 = \{x_1,\ldots,x_{\ell_1}\}\) and \(Y_1 = \{y_1,\ldots,y_{\ell_1}\}\),
  and for each \(i \in \{1,\ldots,\ell_1\}\), consider the path
  \(P_{v_1 x_i} = \langle v_1,y_i,v_{x_iy_i},x_i\rangle\) joining \(v_1\) to \(x_i\).
  Analogously, we define paths~\(P_{v_3 x'}\) joining \(v_3\) to each vertex \(x'\in X_3\).
  It is not hard to check that, since \(X_1 \cap X_3 = Y_1 \cap Y_3 = \emptyset\),
  these paths are edge-disjoint, and we can add \(v_1\) and \(v_3\) to \(K'\),
  while joining~\(v_1\) to \(v_3\) through a path in \(C\).
  This yields an immersion of \(K_{2t}\) in \(G\) whose set of branch vertices is \(I\cup \{v_1,v_3\}\),
  as desired (see Figure~\ref{fig:inductionfor2n/5}).
\end{proof}

