\title{Contextual Pattern Mining and Counting}
\author[1]{Ling Li}
\author[2]{Daniel Gibney}
\author[3]{Sharma V. Thankachan}
\author[4,5]{Solon P.\ Pissis}
\author[1]{\\Grigorios Loukides}
\affil[1]{King's College London, London, UK}
