\affil[4]{CWI, Amsterdam, The Netherlands}
\affil[5]{Vrije Universiteit, Amsterdam, The Netherlands}

\date{\vspace{-.5cm}}

\begin{document}

\maketitle

\thispagestyle{empty}

\begin{abstract}
Given a string $P$ of length $m$, a longer string $T$ of length $n>m$, and two integers $l\geq 0$ and $r\geq 0$, the \emph{context} of $P$ in $T$ is \emph{the set} of all string pairs $(L,R)$, with $|L|=l$ and $|R|=r$, such that the string $LPR$ occurs in $T$. We introduce two problems related to the notion of context: (1) the \emph{Contextual Pattern Mining} (\CPM) problem, which given $T$, $(m,l,r)$, and an integer $\tau>0$, asks for outputting the context of each substring $P$ of length $m$ of $T$, provided that the size of the context of $P$ is at least $\tau$; and (2) the \emph{Contextual Pattern Counting} (\CPC) problem, which asks for preprocessing $T$ so that the size of the context of a given query string $P$ of length $m$ can be found efficiently. Both problems have direct applications in text mining and bioinformatics and are challenging to solve for realistically long strings. 

For \CPM, we propose a linear-work algorithm that either uses only internal memory, or a bounded amount of internal memory and external memory, which allows much larger datasets to be handled. For \CPC, we propose an $\Ohtilde(n)$-space index that can be constructed in $\Ohtilde(n)$ time and answers queries in $\Oh(m)+\Ohtilde(1)$ time. We further improve the practical performance of the \CPC index by optimizations that exploit the LZ77 factorization of $T$ and an upper bound on the query length. Using billion-letter datasets from different domains, we show that the external memory version of our \CPM algorithm can deal with very large datasets using a small amount of internal memory while its runtime is comparable to that of the internal memory version. Interestingly, we also show that our optimized index for \CPC outperforms an approach based on the state of the art for the reporting version of \CPC [Navarro, SPIRE 2020] in terms of query time, index size, construction time, and construction space, often by more than an order of magnitude. 
\end{abstract}

\clearpage
\setcounter{page}{1}

\section{Introduction}\label{sec:intro}

Strings (sequences of letters over some alphabet) encode data arising from different sources such as DNA sequences~\cite{NGS}, natural language text~\cite{DBLP:books/lib/JurafskyM09}, and log files (e.g., sequences of visited webpages in a webserver log~\cite{DBLP:journals/pvldb/Boncz0L20} or visited locations in a location-based application~\cite{gis}). Analyzing such strings is key in applications including DNA sequence analysis~\cite{NGS}, document analytics~\cite{simonjea}, network analytics~\cite{ndsi16}, and location-based service provision~\cite{locis}. At the heart of these applications, there are two fundamental string-processing problems: (1) the frequent pattern mining problem~\cite{fisher}; and (2) the text indexing problem~\cite{DBLP:books/daglib/0020103}. 
Given a string $T$ and an integer $\tau>0$, frequent pattern mining asks for each string $P$ that occurs as a substring of $T$ at least $\tau$ times. Text indexing asks to preprocess a string $T$ into a compact data structure that supports efficient pattern matching queries; e.g., \emph{report} the set of starting positions of $P$ in $T$; or \emph{count} the size of the latter set. In what follows, we refer to $T$ as the \emph{text} and to $P$ as the \emph{pattern}. 

In this work, we shift the focus of these problems from $P$ to the string $L$  of length $l$ and the string $R$ of length $r$, which occurs immediately to the left and to the right of $P$ in $T$, respectively. The \emph{set} of such string pairs $(L, R)$ is referred to as the \emph{context} of $P$ in $T$ and denoted by $\mathcal{C}_{T}(P,l,r)$. 

We introduce the following two problems:

\begin{problem}[Contextual Pattern Mining (\CPM)]
    Given a text $T$ of length $n = |T|$ and a tuple of integers $(\tau, m, l, r)$, where $\tau, m > 0$ and $l, r \geq 0$, output 
    $\mathcal{C}_T(P,l,r)$, for each substring $P$ of $T$ with length $m$ such that $|\mathcal{C}_T(P,l,r)|\geq \tau$. 
\end{problem}

\begin{example} \label{EX:CPC}
For text $T$ below and $(\tau, m, l, r)=(3, 2, 2,1)$, the \CPM solution is 
$\mathcal{C}_T(\texttt{AA},2,1)=\{(\texttt{CT},\texttt{G}), (\texttt{AG}, \texttt{G}), (\texttt{AG},\texttt{T}), (\texttt{TG}, \texttt{C})\}$. Each occurrence of $P=\texttt{AA}$ and its context is highlighted by a different color. We have $|\mathcal{C}_T(\texttt{AA},2,1)|\geq \tau=3$, while $|\texttt{AA}|=m=2$, $|\texttt{CT}|=|\texttt{AG}|=|\texttt{TG}|=l=2$, and $|\texttt{G}|=|\texttt{T}|=|\texttt{C}|=r=1$.    
