\title{\red{Concurrent Skin-scale-free Localization} and Criticality under M\"obius Boundary Conditions in a Non-Hermitian Ladder}
\author{Shu Long}
\affiliation{Guangdong Provincial Key Laboratory of Quantum Metrology and Sensing $\&$ School of Physics and Astronomy, Sun Yat-sen University (Zhuhai Campus), Zhuhai 519082, China}\author{Linhu Li}\email{lilinhu@quantumsc.cn}
