{\section{\red{CRITICALITY ENHANCED BY MBCS}}\label{A4}
\red{Here we provide a perturbation treatment to explain how MBCs enhance criticality to a certain extent. Note that in the following we have taken a much simplified approximation of the unperturbed eigenstates, which does not give accurate results, but is enough for demonstrating the physical origin of our observations.}

\red{In our study, the criticality refers to the sensitivity of the system to a weak $t_0$. Thus, we may assume that $t_0$ is much weaker than the effect of MBCs. Therefore, we take MBCs as a perturbation to the system under OBCs, and $t_0$ as a higher-order perturbation to the overall system.
The explicit forms of these two terms are given by
\begin{align}
H_{t_0}=\sum_{x=1}^N t_0(\hat{a}_x^\dagger\hat{b}_x+\hat{b}_x^\dagger\hat{a}_x),
\end{align}
and
\begin{equation}
  \begin{aligned}  
   {{\hat H}_{\rm BC}} =&\,\  ({t_1} - {\delta _a})\hat b_1^\dag {{\hat a}_N} + ({t_1} - {\delta _b})\hat a_1^\dag {{\hat b}_N}\\
   &+ ({t_1} + {\delta _a}){{\hat a}^\dag }_N{{\hat b}_1} + ({t_1} + {\delta _b}){{\hat b}^\dag }_N{{\hat a}_1}.
   \end{aligned}  
\end{equation}
The strengths of these two terms are determined by $t_0$ and $t_1\pm\delta_s$, respectively.
In addition, we note that in the main text, the enhanced criticality is observed when the two chains are separated in energy by the on-site potential $V$. Thus, here we consider the scenario with $V\gg t_1\pm\delta_s \gg t_0$.}

\red{
First, the OBC system with $t_0=0$ is two separated Hatano-Nelson models. 
Expressing the eigenstates as
\begin{align}
\Psi=(\psi_{a,1},\psi_{a,2},...,\psi_{a,N},\psi_{b,1},\psi_{b,2},...,\psi_{b,N})^T,
\end{align}
The OBC eigenstates on chain $a$ and $b$ generally take the forms of~\cite{yao2018edge,okuma2020topological,lee2019anatomy}
\begin{align}
|\Psi_a^{\rm OBC}\rangle=C_a(r_a,r_a^2,...,r_a^N,0,0,...0)^T,\\
|\Psi_b^{\rm OBC}\rangle=C_b(0,0,...0,r_b,r_b^2,...,r_b^N)^T,
\end{align}
with $r_{s}=\sqrt{(t_1+\delta_{s})/(t_1-\delta_{s})}$ and $C_s$ the normalization factors.
Note that here we have taken approximate forms describing only the exponential decaying resultant from NHSE, and ignored the phase factor and oscillation from the Bloch wavefunction.
Without introducing MBCs, the first-order perturbation of $H_{t_0}$ is
\begin{align}
\langle \Psi_s^{\rm OBC}|H_{t_0}|\Psi_s^{\rm OBC}\rangle=0,
\end{align}
as each eigenstate distributes only on a single chain, and $H_{t_0}$ only contains coupling between the two chains.}

\red{
Next, we take MBCs as a perturbation to the OBC system.
The first-order perturbation to the eigenstates is given by
\begin{align}
|\Psi_a^{(1)}\rangle=&\sum_{\Phi_a^{\rm OBC}\neq\Psi_a^{\rm OBC}}\frac{\langle\Phi_a^{\rm OBC}|H_{\rm BC}|\Psi_a^{\rm OBC}\rangle}{E_{\Psi_a^{\rm OBC}}-E_{\Phi_a^{\rm OBC}}}|\Phi_a^{\rm OBC}\rangle\nonumber\\
&+\sum_{\Phi_b^{\rm OBC}}\frac{\langle\Phi_b^{\rm OBC}|H_{\rm BC}|\Psi_a^{\rm OBC}\rangle}{E_{\Psi_a^{\rm OBC}}-E_{\Phi_b^{\rm OBC}}}|\Phi_b^{\rm OBC}\rangle\nonumber\\
=&\frac{C_aC_bN}{V} \bigg[ (t_1-\delta_a)r_a^Nr_b+(t_1+\delta_b)r_ar_b^N \bigg] |\Psi_b^{\rm OBC}\rangle,
\end{align}
\begin{align}
|\Psi_b^{(1)}\rangle=&\sum_{\Phi_b^{\rm OBC}\neq\Psi_b^{\rm OBC}}\frac{\langle\Phi_b^{\rm OBC}|H_{\rm BC}|\Psi_b^{\rm OBC}\rangle}{E_{\Psi_b^{\rm OBC}}-E_{\Phi_b^{\rm OBC}}}|\Phi_b^{\rm OBC}\rangle\nonumber\\
&+\sum_{\Phi_a^{\rm OBC}}\frac{\langle\Phi_a^{\rm OBC}|H_{\rm BC}|\Psi_b^{\rm OBC}\rangle}{E_{\Psi_b^{\rm OBC}}-E_{\Phi_a^{\rm OBC}}}|\Phi_a^{\rm OBC}\rangle\nonumber\\
=&-\frac{C_aC_bN}{V} \bigg[ (t_1+\delta_a)r_a^Nr_b+(t_1-\delta_b)r_ar_b^N \bigg] |\Psi_a^{\rm OBC}\rangle.
\end{align}
The first term in each of these two equations vanishes, as $H_{\rm BC}$ also only contains coupling between the two chains.
In addition, we have further assumed  the $E_{\Psi_a^{\rm OBC}}=V$ and $E_{\Psi_b^{\rm OBC}}=-V$, as $V$ is the dominant energy scale in our consideration.
Note that despite the coefficient $1/V$, the amplitudes of these terms may not vanish for a large enough system size $N$.}

\red{
Thus, the eigenstates under MBCs, up to first-order approximation, are given by
\begin{align}
|\Psi_a^{\rm MBC}\rangle=|\Psi_a^{\rm OBC}\rangle+|\Psi_a^{(1)}\rangle,\\
|\Psi_b^{\rm MBC}\rangle=|\Psi_b^{\rm OBC}\rangle+|\Psi_b^{(1)}\rangle.
\end{align}
and we can already see the MBCs-induced mixture of the two chains for these eigenstates.
Thus, the first-order perturbation of $t_0$ to the eigenenergies under MBCs now takes non-vanishing value,
\begin{align}
\langle \Psi_s^{\rm MBC}|H_{t_0}|\Psi_s^{\rm MBC}\rangle\neq 0.
\end{align}
In other words, a system under MBCs is more sensitive to $t_0$ compared to that under OBCs, indicating an enhanced criticality.}

