\subsection{Algorithm for updating the MT front}
\label{subsec:TrackingMT} 
In \S~\ref{sec:CG1} we provided a general formulation of three-dimensional MT front dynamics inside a cell surface $\Gamma$. Here we provide details of evolving the front of leading MT plus-ends in terms of a coordinate system centered on the centrosome with polar angle $\varphi'(t)\in[0,\pi]$ and azimuthal angle $\theta'(t)\in[0,2 \pi)$. We focus on a convex cell surface $\Gamma$ so there is a unique pair of coordinates $(\varphi'(t),\theta'(t))$ that corresponds to coordinates of the force generators ${\bf Y}$ on $\Gamma$. We assume that the centrosomal array does not rotate, and represent the location of the MT plus-end (MT front) as ${\bf S}={\bf S}(\varphi'(t),\theta'(t)) = {\bf X}(t) + D_{\bf S}(\varphi'(t),\theta'(t))\hat{\boldsymbol{\xi}}(\varphi'(t),\theta'(t))$, where $D_{\bf S}$ is the distance from the centrosome to the MT front along the direction $\hat{\boldsymbol{\xi}}$, pointing from the centrosome to CFGs at ${\bf Y}(\varphi',\theta')$ at a distance $D = |{\bf Y}-{\bf X}|$. The relation between $D_{\bf S}$ and $D$ determines the state of the MT front; either

\noindent
{\bf(i)} the front reaches the cortex, i.e. $D_{\bf S}(\varphi'(t),\theta'(t))\ge D(\varphi'(t),\theta'(t))$. Centrosomal MTs are impinging on force generators in this direction, which implies $\Omega(\varphi'(t),\theta'(t))>0$; or

\noindent
{\bf(ii)} the front grows toward the cortex, i.e. $D_{\bf S}(\varphi'(t),\theta'(t))<D(\varphi'(t),\theta'(t))$ and $\partial_t D_{\bf S} = V_g$. Centrosomal MTs are not impinging on force generators, which implies $\Omega(\varphi'(t),\theta'(t))=0$.

In the following we summarize the numerical algorithm for evolving the three-dimensional centrosome motion with a MT front.  The superscripts denote the step in the time marching, starting from initial data of the occupancy probability $P(t^0)$, centrosome position ${\bf X}(t^0)$, and the unit vector $\hat{\boldsymbol{\xi}}(t^0)$ (from the initial centrosome position to a surface point ${\bf Y}$)  and the MT front position ${\bf S}(\varphi'(t^0),\theta'(t^0))$.


\begin{enumerate}
%[label=(\arabic*):]
\item Given a time-step $\triangle t$, and $({\bf X}(t^n)$, $P(t^n))$, at time $t^n = n \triangle t$ for $n\ge 0$, compute ${\bf X}(t^{n+1})$ as described in \S~\ref{subsec:simulation_methods}, and update the centrosome coordinates $(\varphi'(t^{n+1}),\theta'(t^{n+1}))$ and the distance $D(\varphi'(t^{n+1}),\theta'(t^{n+1}))$.


%\hat{\boldsymbol{\xi}}

\item Compute $\tilde D_{\bf S}(\varphi'(t^n),\theta'(t^n)) = D_{\bf S}^n(\varphi'(t^n),\theta'(t^n))+\Delta t V_g$; then compute $\tilde D_{\bf S}(\varphi'(t^{n+1}),\theta'(t^{n+1}))$ by interpolating $\tilde D_{\bf S}(\varphi'(t^n),\theta'(t^n))$ at the new coordinates (target points) $(\varphi'(t^{n+1}),\theta'(t^{n+1}))$. 

\item Update $D_{\bf S}$ and the impingement rate $R$ according to the following scheme: 
    \begin{itemize}
        \item 

        \noindent{If $\tilde D_{\bf S}(\varphi'(t^{n+1}),\theta'(t^{n+1})) \ge D(\varphi'(t^{n+1}),\theta'(t^{n+1}))$}

        \noindent{\hspace{0.4cm}$D_{\bf S}(\varphi'(t^{n+1}),\theta'(t^{n+1})) =D(\varphi'(t^{n+1}),\theta'(t^{n+1}))$}

        \noindent{\hspace{0.4cm}$\Omega(\varphi'(t^{n+1}),\theta'(t^{n+1})) = \left[{\bf V}_S\cdot\hat{\bf n} \right]_+ \chi\left(\frac{r_m}{D}\right)\left(\frac{\gamma}{V_g} e^{-D/l_c}\right)$}

        \item 

        \noindent{Otherwise ($\tilde D_{\bf S}(\varphi'(t^{n+1}),\theta'(t^{n+1})) < D(\varphi'(t^{n+1}),\theta'(t^{n+1}))$)}

        \noindent{\hspace{0.4cm}$D_{\bf S}(\varphi'(t^{n+1}),\theta'(t^{n+1})) = \tilde D_{\bf S}(\varphi'(t^{n+1}),\theta'(t^{n+1}))$}

        \noindent{\hspace{0.4cm}$\Omega(\varphi'(t^{n+1}),\theta'(t^{n+1}))=0$}  
    \end{itemize}
\end{enumerate}
We then update the MT front position to ${\bf S}(\varphi'(t^{n+1}),\theta'(t^{n+1}))$, and use the updated impingement rate $\Omega(\varphi'(t^{n+1}),\theta'(t^{n+1}))$ to compute $P^{n+1}$ as described in \S~\ref{subsec:simulation_methods}:
    \begin{align}
        \frac{P(t^{n+1})-P(t^{n})}{\Delta t} &= \Omega(\varphi'(t^{n+1}),\theta'(t^{n+1})) {\cal I}(P(t^{n})) - \kappa P(t^{n+1}),\nonumber\\
        \label{eq:Pnp1}
        P(t^{n+1}) &= P(t^{n}) + \frac{\Delta t}{1+\kappa\Delta t}\left(\Omega(\varphi'(t^{n+1}),\theta'(t^{n+1})) {\cal I}(P(t^{n})) - \kappa P(t^{n})\right).
    \end{align}
    This completes one time-step, and the iteration repeats until the end of the simulation.

\subsection{Spectral formulation for the axi-symmetric centrosome dynamics in sphere\label{subsec:spectral_method}}
Here we recast Eqs~(\ref{eq:Zdot_3d}-\ref{eq:impingement_rate_3d})  with axisymmetry ($z$-axis as the axis of symmetry) in Legendre polynomials.
  The centrosome moves along the $z$-axis with a position $z(t)$, and the occupancy probability is a function of the polar angle $\varphi\in[0,\pi]$.  We set the areal density $\rho\left({\bf Y}\right) = 1/|\Gamma|$.
The equations of motion for the axisymmetric system are
\begin{align}
\label{eq:Zdot0}
\eta \frac{dz}{dt} &= \frac{M f_0}{2}\int^{\pi}_0 d\varphi \sin\varphi \frac{W\cos\varphi-z}{D(\varphi,z)}P(\varphi,t),\\
\label{eq:Pdot0}
\frac{\partial P(\varphi,t)}{\partial t} &=  \Omega(\varphi,z)\left[\frac{1-e^{-\frac{M}{M_0}(1-P(\varphi,t))}}{\frac{M}{M_0}}\right]- \kappa P(\varphi,t),\\
%\frac{\partial P}{\partial t} &=  R(\phi,t)\left(1-P(\phi,t)\right)-kP(\phi,t),\\
%\label{eq:D0}
%D(\phi,z) &= \sqrt{1-2 z\cos\phi + z^2},\\
\label{eq:R0}
\Omega(\varphi,z) &= \left[\dot z \cos\varphi + \frac{V_g\left(W-z\cos\varphi\right)}{D(\varphi,z)}\right]_+e^{-\frac{D(\varphi,z)}{l_c}}\chi\left(\frac{r_m}{D(\varphi,z)}\right)\frac{\gamma}{V_g},
%\label{eq:chi0}
%\chi(\rho) &=\frac{1}{2}\left(1-\frac{1}{\sqrt{1+\rho^2}}\right),
\end{align}
where $D(\varphi,z) = \sqrt{W^2-2 W z\cos\varphi + z^2}$.
We expand the occupancy probability $P(\varphi,t)$ in Legendre polynomials $P_n(x)$ as $P(\varphi,t) = \sum^{\infty}_{i=0} c_i(t) P_i(\cos\varphi)$, where $P_i(x=\cos\varphi)$ is the $i$th order Legendre polynomial. To recast
equations~(\ref{eq:Zdot0})-(\ref{eq:Pdot0}) into a system of nonlinear equations in $z(t)$ and the coefficients $c_i(t)$, we first
expand the impingement rate in Legendre polynomials as
\[ \Omega(x,z)=\left(\frac{dz}{dt} f_1(x, z) + f_2(x, z)\right)\frac{\gamma}{V_g} = \sum^{\infty}_{i=0} \left(\frac{dz}{dt} f_{1i} + f_{2i}\right)  P_i(x)\frac{\gamma}{V_g},\]
where $P_i(x)$ is the $i$th order Legendre polynomial, and
\begin{align}
\label{eq:f1}
f_1 &\equiv x e^{-\frac{D}{l_c}}\chi\left(\frac{r_m}{D}\right) \equiv \sum^{\infty}_{i=0}f_{1i} P_i(x),\\
\label{eq:f2}
f_2 &\equiv \frac{V_g(W- z x)}{D}e^{-\frac{D}{l_c}}\chi\left(\frac{r_m}{D}\right) \equiv \sum^{\infty}_{i=0}f_{2i} P_i(x).
\end{align}
%
% As in the linear analysis we expand the occupancy probability $P$
% %~\ref{eq:dPdt_Rexpanded}
% in Legendre polynomials as $P(x,t)= \sum^{\infty}_{i=0} c_i(t) P_i(x)$. 
Here we  truncate at $c_1$ to obtain
a system of nonlinear equations for $z(t)$, $c_0(t)$ and $c_1(t)$:
\begin{align}
\label{eq:dZdt_fullR}
\eta\frac{dz}{dt} &= \frac{M f_0}{2}\left[-\frac{4}{3} c_0 \frac{z}{W} + \left(\frac{2}{3} - \frac{2}{5}\left(\frac{z}{W}\right)^2\right)c_1\right],\\
\label{eq:dc0dt_fullR}
\frac{dc_0}{dt} &= \Omega_0 - \kappa c_0 -\left(c_0 R_0 + \frac{1}{3} c_1 R_1\right),\\
\label{eq:dc1dt_fullR}
\frac{dc_1}{dt} &= \Omega_1 - \kappa c_1 - \left(c_0 R_1 + c_1 R_0 + \frac{2}{5} c_1 R_2\right),
\end{align}
with $\Omega_i \equiv \left(\frac{dz}{dt} f_{1i} + f_{2i}\right)\frac{\gamma}{V_g}$.
For $i=0$ and $i\ge 2$, the linearized equation of $c_i$ simply yields decaying dynamics:
\begin{align}
    \frac{d c_i}{dt} &= - \left(\kappa + I_0\left({\bar P}\right)\right) c_i,\\
    I_0\left({\bar P}\right) &= e^{-W/l_c}\chi\left(\frac{r_m}{W}\right)\gamma \frac{1-e^{-\frac{M}{M_0}(1-{\bar P})}}{\frac{M}{M_0}} >0,
\end{align}
where ${\bar P}$, the occupancy probability of the base state, satisfies the equation ${\bar P} = \frac{I_0\left({\bar P}\right)}{I_0\left({\bar P}\right) + \kappa}$.
 These results show that the linear instability of a centrosome in a sphere in \S~\ref{subsec:stability_in_sphere} involves only $c_1$ and $z$, and all the other modes are linearly stable and do not contribute to the instability.

\subsection{Centrosome orbiting around sphere center\label{subsec:OrbitingCentrosome}}
Here we focus on  a centrosome orbiting at a constant speed and a constant distance to the sphere center. In spherical coordinates, with the origin at the sphere center, the centrosome position 
${\bf X}_c = \varrho(t)(\sin\theta_c(t)\cos\phi_c(t)\hat{\bf e}_1 + \sin\theta_c(t)\sin\phi_c(t) \hat{\bf e}_2 + \cos\theta_c(t)\hat{\bf e}_3)$ and the surface of the sphere of radius $W$ has coordinates
${\bf Y} = W(\sin\theta\cos\phi\hat{\bf e}_1+\sin\theta\sin\phi\hat{\bf e}_2+\cos\theta\hat{\bf e}_3)$, where the polar angles 
$\theta_c, \theta \in [0, \pi]$, and the azimuthal angles $\phi_c, \phi \in [-\pi,\pi]$.
The governing equations for the centrosome dynamics in spherical coordinates (with areal density $\rho\left({\bf Y}\right) = 1/|\Gamma|$) are
\begin{align}
\eta\dot\varrho &= \frac{M f_0}{|\Gamma|}\int\frac{P(\theta,\phi,t)}{D}\left(-\varrho + W \cos\theta\cos\theta_c + W\sin\theta\sin\theta_c\cos(\phi-\phi_c)\right) W^2 \sin\theta d\theta d\phi,\\
\eta\varrho\dot\theta_c &= \frac{M f_0}{A}\int\frac{P(\theta,\phi,t)}{D} \left(\cos\theta_c\sin\theta\cos(\phi-\phi_c) - \cos\theta\sin\theta_c\right) W^3\sin\theta d\theta d\phi,\\
\eta\varrho\sin\theta_c \dot\phi_c &= \frac{M f_0}{A}\int\frac{P(\theta,\phi,t)}{D} \sin\theta\sin(\phi-\phi_c)W^3 \sin\theta d\theta d\phi,\\
\frac{\partial P}{\partial t} &= \left[ \dot\varrho\left(\cos\theta\cos\theta_c + \sin\theta\sin\theta_c\cos(\phi-\phi_c)\right) + \right. \\
& \left. \varrho\dot\theta_c (\cos\theta_c\sin\theta\cos(\phi-\phi_c)-\sin\theta_c\cos\theta)+ \varrho\sin\theta_c\dot\phi_c\sin\theta\sin(\phi-\phi_c)+\right. \nonumber \\
&\left. \frac{V_g}{D}(W-\varrho\cos\theta\cos\theta_c - \varrho\sin\theta\sin\theta_c\cos(\phi-\phi_c))\right]_+ \frac{\chi e^{-D/l_c}}{V_g}\gamma I(P) - \kappa P,  \nonumber  \\
D &=\sqrt{W^2+\varrho^2-2W\varrho\cos\theta\cos\theta_c-2 W \varrho\sin\theta\sin\theta_c\cos(\phi-\phi_c)},\\
\chi &= \frac{1}{2}\left(1-\frac{1}{\sqrt{1+\left(\frac{r_m}{D}\right)^2}}\right),\;\;\;
I(P) = \frac{1-e^{-\frac{M}{M_0}(1-P)}}{M/M_0}.
\end{align}
We focus on the orbiting motion of a centrosome in the $xy$-plane (where $\theta_c = \pi/2$) with a constant radius $\varrho$ from the sphere center and a constant angular frequency $\dot\phi_c = \omega$. With the change of variable $\bar\phi = \phi-\phi_c = \phi-\omega t$ and the assumption that $P(\theta,\phi,t)=P(\theta,\bar\phi)$, we obtain the following equations 


\begin{align}
\label{eq:drhodt=0}
0 &= \frac{M f_0}{A}\int\frac{P(\theta,\bar\phi)}{D}\left(-\varrho  + W\sin\theta\cos(\bar\phi)\right) W^2 \sin\theta d\theta d\bar\phi,\rightarrow \varrho  = W\frac{I_2}{I_1},\\
\label{eq:omega0}
\eta\varrho\omega &=  \frac{M f_0}{A}\int\frac{P(\theta,\bar\phi)}{D} \sin\theta\sin(\bar\phi)W^3 \sin\theta d\theta d\bar\phi,\rightarrow \eta \varrho \omega =\frac{M f_0}{A}I_3,\\
\label{eq:dPdphi}
-\omega\frac{\partial P\left(\theta,\bar\phi\right)}{\partial\bar\phi}&= \left[\varrho\omega\sin\theta\sin(\bar\phi) + \frac{V_g}{D}(W -\varrho\sin\theta\cos(\bar\phi))\right]_+ \frac{\chi e^{-D/l_c}}{V_g}\gamma I(P) - \kappa P,\\
D &=\sqrt{W^2+\varrho^2-2 W \varrho\sin\theta\cos(\bar\phi)},
\end{align}
where 
\begin{equation}
\label{eq:I1}
I_1 = \int \frac{P(\theta,\bar\phi)}{D}\sin\theta d\theta d\bar\phi,
\end{equation}
\begin{equation}
\label{eq:I2}
I_2 = \int \frac{P(\theta,\bar\phi)}{D} \sin^2\theta\cos(\bar\phi)d\theta d\bar\phi,
\end{equation}
\begin{equation}
\label{eq:I5}
I_3 = \int\frac{P(\theta,\bar\phi)}{D}W^3\sin^2\theta\sin(\bar\phi) d\theta d\bar\phi.
\end{equation}
Eq.~(\ref{eq:drhodt=0}) gives the radius of the orbit,  and Eq.~(\ref{eq:omega0}) gives the angular speed of the centrosome motion with the occupancy probability $P$ determined from Eq.~(\ref{eq:dPdphi}). 
Altogether the system consists of two integrals and one differential equation for the occupancy probability $P$.


This system of nonlinear integral-differential equations are solved as follows. For an initial guess of $(\varrho^i, \omega^i)$ we solve Eq.~(\ref{eq:dPdphi}) to find the occupancy probability $P$. We compute the integrals $I's$ to update the value $(\varrho^{i+1},  \omega^{i+1})$, and compute the loss function $E = \log(1+(\delta \varrho)^2+(\delta \omega)^2)$, with $\delta \varrho = \varrho^{i+1}-\varrho^i$, and $\delta\omega=\omega^{i+1}-\omega^{i}$. We update $(\varrho, \omega)$ using an iterative gradient method for nonlinear systems to minimize the loss function within a set tolerance. 

\subsection{Numerics for the linear stability of a centrosome in a spheroid \label{subsec:Methods_arbitrary_geometry}}
Here we present numerical details for the linear stability analysis of a centrosome in a general spheroid. To obtain high-order accuracy of the numerical linear stability analysis on this differential-integral system, we need to compute surface integral
%
\begin{align*}
\int_{\Gamma} f({\bf Y}) dA, 
\end{align*}
%
with high-order spatial accuracy. We generate quadrature for spheroidal surfaces via a differential function $\varphi$, which maps $\Gamma$ to the surface of the unit sphere ($S^2$). We then transform a surface integral on $\Gamma$ to one on the unit sphere as
\begin{align}
\int_{\Gamma} \mathcal{F}({\bf Y}) dA({\bf Y}) = \int_{S^2} \mathcal{F}(\varphi({\bf X}) )  \big \lvert  \det(J_\varphi ({\bf X}) )   J_\varphi^{-t}({\bf X}) \hat{n}({\bf X}) \big \rvert  dA({\bf X}),
\end{align}
where $J_\varphi$ is the Jacobian and $\hat{n}$ is the outward normal of the sphere. This transformation allows us to efficiently compute the force on the centrosome by spatially discretizing the surface using a quadrature rule for the sphere. In particular, we put three non-overlapping patches, two caps and a ring, described by
%
\begin{align}
\mathcal{A}_1 &= \left \{ {\bf X} \in S^2 \, | \, \cos^{-1}({\bf X} \cdot \hat{z}) \leq \frac{\pi}{4}   \right\}, \\
\mathcal{A}_2  &= \left\{ {\bf X} \in S^2   \, | \, \frac{\pi}{4}\leq \cos^{-1}({\bf X} \cdot \hat{z}) \leq \frac{3\pi}{4}    \right\}, \\
\mathcal{A}_3 &= \left\{ {\bf X} \in S^2 \, | \,  \cos^{-1}({\bf X} \cdot \hat{z}) \geq \frac{3 \pi}{4}    \right\}.
\end{align}
%
Patches $\mathcal{A}_1$ and $\mathcal{A}_3$ can be discretize as a Disk, noting that $\frac{\sin(\varphi)}{\varphi}$ is smooth, hence, for the integral $\int_0^{\varphi_0} f(\varphi) \frac{\sin{\varphi}}{\varphi} \varphi  d\varphi$ we can use the same quadrature rules used for the Disk \cite{SpectralDisk}, where $\varphi$ takes the role of the radius.

\begin{figure}[t]
\includegraphics[keepaspectratio=true,scale=0.5]{PatchedQ.png}
\caption{An illustration of patched quadrature. Yellow is for the ring patch ${\cal A}_{2}$, and blue (pink) is for the top (bottom) cap patch ${\cal A}_1$ (${\cal A}_3$). Note that there is an accumulation of quadrature points around the union of the patches.
}
\label{FigPatchedQ}
\end{figure}
