\subsection{Hyperbolic Space}
The hyperbolic space has a constant negative curvature and expands exponentially. Due to these properties, the hyperbolic space is appropriate for modeling tree-like or hierarchically structured graphs where the number of nodes grows exponentially. Unlike Euclidean space, the hyperbolic space is not a vector space, and thus vector operations cannot be applied. Therefore, Definitions 4-8 are required to perform graph convolution operations in the hyperbolic space.

\begin{definition}[\bf \Poincare ball model]
\label{def:4}
\Poincare ball model with curvature $-c\ (c>0)$ is defined by the Riemannian manifold $(\mathbb{D}^{n,c}, g_x^c)$, where
\begin{align*}
    & \mathbb{D}^{n,c}=\{x \in \mathbb{R}^n : c||x||^2 < 1\},\\
    & g_x^c = \left(\lambda^c_x\right)I_d.
\end{align*}
Here, $\mathbb{D}^{n,c}$ is the open $n$-dimensional unit ball with radius $\frac{1}{\sqrt{c}}$ and $g_x^c$ is the Riemannian metric tensor, where $\lambda_x^c=\frac{2}{1-c||x||^2}$ and $I_d$ is the identity matrix. We denote $\mathcal{T}_x\mathbb{D}^{n,c}$ as the tangent space centered at point $x$.
\end{definition}

\begin{definition}[\bf \Mobius addition]
\label{def:5}Given the point $x,y \in \mathbb{D}^{n,c}$, \Mobius addition which represents the equation for the addition operation in the \Poincare ball model with curvature $-c\;(c>0)$ is defined as follows:
\begin{align*}
    x\oplus_c y = \frac{\left(1+2c\langle x,y\rangle+c||y||^2\right)x+\left(1-c||x||^2\right)y}{1+2c\langle x,y \rangle+c^2||x||^2||y||^2},
\end{align*}
where $\langle\cdot\rangle$ is the Euclidean inner product and $||\cdot||$ is the Euclidean norm.
\end{definition}

\begin{definition}[\bf Exponential and logarithmic maps]\label{def:6}
In \Poincare ball model with curvature $-c\;\left(c>0\right)$, the exponential map $exp^c_x:\mathcal{T}_x\mathbb{D}^{n,c}\rightarrow\mathbb{D}^{n,c}$ and the logarithmic map $log^c_x:\mathbb{D}^{n,c}\rightarrow \mathcal{T}_x\mathbb{D}^{n,c}$ are defined as shown below:
\begin{align*}
    & exp_x^c\left(v\right) = x\oplus_c\left(\text{tanh}\left(\sqrt{c}\frac{\lambda_x^c||v||}{2}\right)\frac{v}{\sqrt{c}||v||}\right),\\
    &log_x^c\left(y\right)=\frac{2}{\sqrt{c}\lambda_x^c}\text{tanh}^{-1}\left(\sqrt{c}||-x\oplus_cv||\right)\frac{-x\oplus_c y}{||-x\oplus_c y||},
\end{align*}
where $x$ and $y$ are the points in 
the hyperbolic space $\mathbb{D}^{n,c}$ and $x\neq y$. Here, $v$ is a nonzero tangent vector in the tangent space $\mathcal{T}_x\mathbb{D}^{n,c}$.
\end{definition}

\begin{definition}[\bf Hyperbolic matrix-vector multiplication] \label{def:7}
Given a point $x\in\mathbb{D}^{n,c}$ and a matrix $M\in\mathbb{R}^{m\times n}$, the matrix-vector multiplication operation in hyperbolic space is defined as follows:
\begin{align*}
    & M\otimes_c x = exp_0^c\left(Mlog_0^c\left(x\right)\right),
\end{align*}
where $\mathbf{0}\in\mathbb{R}^{n}$ is a zero vector. 
\end{definition}


\begin{definition}[\bf Hyperbolic non-linear activation function]\label{def:8}
Given the point $x\in\mathbb{D}^{n,c}$, the hyperbolic non-linear activation function is defined as follows:
\begin{align*}
    & \sigma\otimes_c\left(x\right) = exp_0^c\left(\sigma\left(log_0^c\left(x\right)\right)\right),
\end{align*}
where $\sigma$ is the Euclidean non-linear activation function.
\end{definition}


