Following~\cite{Peretz_2023}, we first introduce the momentum balance on the left and right sides of the capsule, in which magnetic forces between magnets of the neighboring capsules and between the coils and the magnets were incorporated,
\begin{subequations}\label{E:Force_Balance}
\begin{equation}\label{E:Force_Balance A}
\begin{aligned}
 p_L(t)\pi r_p^2-f_c\left(l_{\text{cap}}(t),t\right)-f_{\mu,L}(t)-p_M(t)\pi (r_p^2-r_e^2) 
 +\sum_{j=1}^J f_{m_j}(x_L(t)+w/2-s_j,t)+f_{d_L}(d_L) =0,
 \end{aligned}
\end{equation}
\begin{equation}\label{E:Force_Balance B}
\begin{aligned}
 -p_R(t)\pi r_p^2+f_c\left(l_{\text{cap}}(t),t\right)-f_{\mu,R}(t)+p_M(t)\pi (r_p^2-r_e^2) 
 +\sum_{j=1}^J f_{m_j}(x_R(t)-w/2-s_j,t)-f_{d_R}(d_R)=0,
 \end{aligned}
\end{equation}
\end{subequations}
and a mass balance
\begin{equation}\label{E:diff Q_L Q_R}
q_L-q_R=2\pi r_t(r_t-r_e)\left(\frac{\partial x_R}{\partial t}-\frac{\partial x_L}{\partial t}\right),
\end{equation}
where $p_L$, $p_M$, and $p_R$ denote the pressures at the left end, at the middle, and at the right end of the capsule, respectively, $r_e$ is the maximal radius of the frustum, $d_L$ and $d_R$, are the distances between the magnets on the left and right sides and the neighboring (from the left and from the right) magnets, respectively. Moreover, $f_c(l_{\text{cap}}(t),t)$ appearing in~\eqref{E:Force_Balance} is the elastic force exerted by the capsule, which is given by the multistable relation as introduced in~\cite{Peretz_2022,Peretz_2023} and multiplied by the area of the capsule's bases, namely 
\begin{equation}\label{E:elast force}
    f_c(l_{\text{cap}}(t),t)=\pi r_e^2 \left[a(t)l_{\text{cap}}(t)+b(t)\right],
\end{equation}
where $l_{\text{cap}}(t)=x_R(t)-x_L(t)$ denotes the capsule's length and $a(t)$, $b(t)$ denote two coefficients of the piece-wise linear function, so that their values depend on the permutation. For additional details regarding the definition of $f_c$, see Section 3.1 in SI.
Moreover, $f_{\mu,L}$ (and $f_{\mu,R}$) the viscous resistance acting on the left (and on the right) plate, under the assumption of annular geometry, is given by
%\begin{subequations}\label{E:def F_mu_s}
\begin{equation}\label{E:def F_mu_s}
    f_{\mu,L}=\frac{2\pi r_p w \mu}{r_t-r_p}\left[ \frac{\partial x_L}{\partial t}+\frac{(r_t-r_p)^2}{2\mu w}\left(p_M(t)-p_L(t)\right)\right],
\end{equation}
% \begin{equation}
%     f_{\mu,R}=\frac{2\pi r_p w \mu}{r_t-r_p}\left[ \frac{\partial x_R}{\partial t}+\frac{(r_t-r_p)^2}{2\mu w}\left(p_R(t)-p_M(t)\right)\right],
% \end{equation}
%\end{subequations}
where $w$ is the width of the magnet. The mass flux $q_L$ is given by lubrication approximation as
\begin{equation}\label{E:Flux}
 q_L= 2\pi r_t \left(
 \frac{(r_t-r_p)^3}{12\mu}\frac{p_L(t)-p_M(t)}{w}-\frac{r_t-r_p}{2}\frac{\partial x_L}{\partial t}
 \right).
\end{equation}
For the expressions for $F_{\mu,R}$ and $q_R$, see SI, Section 2. Moreover, the expressions for the forces between two neighboring magnets or between a magnet and solenoid $j$, $j=1,\ldots,J$, as well as the operation regimes of the solenoids are found in SI, Section 1.
