and note that $G_s(t)$ is $\mathcal F_s$-measurable for each $t \geq s$.  We also denote by  $dU_{s,u}$, $dZ_{s,u}$  the differentials with respect to the second variable $u$, for $u\geq s\,$. 

\begin{proposition}  The dynamics of the increments of $U$ defined in \eqref{eq:UZ} are given by 
\begin{align}\label{eq:Ust}
    U_{s,t}=    G_s(t) 
+ \int_s^t K(t-r) \left( b U_{s,r} + c Z_{{s,r}}\right)  \,dr, \quad s\leq t,
\end{align}
where $G$ is defined by \eqref{eq:Gs}. 
\end{proposition}

\begin{proof} We define $\widetilde Z$ by 
\begin{align}\label{eq:tildeZ}
    \widetilde Z_{s,r} = b U_{s,r} + c Z_{s,r}, \quad s \leq r.
\end{align}
Fix $s\leq t$. The dynamics of $U_{0,\cdot}$ in \eqref{eq:U0} yield 
\[
   \begin{aligned}
   U_{s,t} &= U_{0,t} - U_{0,s} \\
   &= \int_s^t g_0(u) \,du  + \int_0^s (K(t-r)-K(s-r)) \widetilde Z_{0,r} dr + \int_s^t K(t-r) \widetilde Z_{0,r} \, dr\\
   &= \int_s^t g_0(u) \,du  + \int_0^s (K(t-r)-K(s-r)) \widetilde Z_{0,r} dr + \int_s^t K(t-r)  \, dr \widetilde Z_{0,s} +  \int_s^t K(t-r) \widetilde Z_{s,r} \, dr\,,
   \end{aligned}
\]
where we used that $\widetilde Z_{0,r} = \widetilde Z_{0,s} + \widetilde Z_{s,r}$, for $r\geq s$, for the last equality. Hence,  in order to obtain  \eqref{eq:Ust}, it suffices to prove that 
   \begin{align}\label{eq:tempfubini} 
     \int_0^s \int_s^t K(u-r) \,du \, d\widetilde Z_{0,r} =   \int_0^s (K(t-r)-K(s-r)) \widetilde Z_{0,r} dr + \int_s^t K(t-r)  \, dr \widetilde Z_{0,s}. 
   \end{align}
   This is done by 
successive applications of stochastic Fubini's theorem and a change of variables as follows
\begin{align*}
     \int_0^s \int_s^t K(u-r) \,du \, d\widetilde Z_{0,r} &= \int_0^s \int_{s-r}^{t-r} K(v) \,dv \, d\widetilde Z_{0,r} \\
   &=  \int_0^t  K(v) \int_{0}^{t} 1_{\{ 0\leq r \leq s \}} 1_{\{ s-v \leq r\leq t-v\}} \, d\widetilde Z_{0,r}  \,dv  \\
   &= \int_0^t K(v) \left(\widetilde Z_{0, s\wedge (t-v)} - \widetilde Z_{0, 0 \vee (s-v)}\right) \,dv \\
   &= \int_0^{t-s} K(v) \,dv \widetilde Z_{0,s} + \int_{t-s}^t K(v) \widetilde Z_{0,t-v} \,dv \\
   &\quad - \int_0^s K(v) \widetilde Z_{0,s-v}\,dv - \int_s^t K(v) \,dv \widetilde Z_{0,0}\\
   &= \int_s^t K(t-r) \,dr \widetilde Z_{0,s}  + \int_0^s K(t-r) \widetilde Z_{0,r}\, dr - \int_0^s K(s-r) \widetilde Z_{0,r}dr,  
\end{align*}
where we used that $\widetilde Z_{0,0}=0$. This yields \eqref{eq:tempfubini} and ends the proof. 
\end{proof}


The main idea behind our scheme is to simply discretize the equation \eqref{eq:Ust} for the increments of the process $U$ between $t_{i}$ and $t_{i+1}$ in an implicit way. 
First we discretize $G_{t_{i}}(t_{i+1})$. The second term in $G_t(s)$  is discretized as follows, recalling the definition of $\widetilde Z$ in \eqref{eq:tildeZ} and  using that $d\widetilde Z_{0,r}=d\widetilde Z_{t_j,r}$ for $r\geq t_j$,  
\begin{align}
    \int_0^{t_i} \int_{t_i}^{t_{i+1}} K(u-r) \,du \, d\widetilde Z_{0,r} &=  \sum_{j=0}^{i-1}  \int_{t_j}^{t_{j+1}} \int_{t_i}^{t_{i+1}} K(u-r) \,du \, d\widetilde Z_{t_j,r} \\
    &\approx  \sum_{j=0}^{i-1}    \int_{t_i}^{t_{i+1}} K(u-t_j) \,du \int_{t_j}^{t_{j+1}} \, d\widetilde Z_{t_j,r} \\
    &= \sum_{j=0}^{i-1}    \int_{t_i}^{t_{i+1}} K(u-t_j) \,du  \widetilde Z_{t_j,{t_{j+1}}},
\end{align}
which leads, with a uniform partition $t_i=iT/n$ for $i=0,\ldots, n$,  to
\begin{align}\label{eq:Gapprox}
    G_{t_i}(t_{i+1}) \approx  \int_{t_{i}}^{t_{i+1}} g_0(u) \, du + \sum_{j=0}^{i-1}    \int_{t_i}^{t_{i+1}} K(u-t_j) \,du  \,\widetilde Z_{t_j,{t_{j+1}}} = \alpha_i,
\end{align}
with $\alpha_i$ given by \eqref{eq:alphai}. 
As for the second term on the right hand side of \eqref{eq:Ust},  using the right endpoint rule on  $\widetilde Z_{t_i,\cdot}$, i.e.~approximating $\widetilde Z_{t_i,s} $ by the value $\widetilde Z_{t_i,t_{i+1}}$ for $s\in [t_i,t_{i+1})$, yields
\begin{align}
\int_{t_i}^{t_{i+1}} K(t_{i+1}-r)  \widetilde Z_{t_i,r} \, dr \approx \int_{t_i}^{t_{i+1}} K(t_{i+1}-r)    \, dr \widetilde Z_{{t_i,t_{i+1}}} = k_0 \widetilde Z_{{t_i,t_{i+1}}},
\end{align}
with $k_0$ as in \eqref{eq:kij}.
Plugging the two approximations above in \eqref{eq:Ust} and recalling \eqref{eq:tildeZ}, yields 
\begin{align}\label{eq:Uti}
     U_{{t_i},{t_{i+1}}}  \approx  \alpha_i + k_0 bU_{{t_i,t_{i+1}}} +  k_0 c Z_{{t_i,t_{i+1}}},
\end{align}
where the $\left(\alpha_i\right)_{i \leq n-1}$ are defined in \eqref{eq:alphai}.
Now the key point is to observe that having contructed $ U_{t_j,t_{j+1}},Z_{t_{j},t_{j+1}}$ for $j=0,\ldots, i-1$, this forms an implicit equation on $ U_{{t_i},{t_{i+1}}}$ by rewriting $Z$ using a time-changed Brownian motion. Indeed, recall from the definition of $(Z_{t_i,s})_{s\geq t_i}$ in \eqref{eq:UZ} that it is a  continuous local martingale with quadratic variation   $U_{t_{i},\cdot}$. Hence, an application of the celebrated Dambis, Dubins-Schwarz Theorem, see \cite[Theorem 1.1.6]{revuz2013continuous}, yields the representation of $(Z_{t_i,s})_{s\geq t_i}$ in terms of a time changed Brownian motion $Z_{t_i, s} = \widetilde W_{U_{t_i,s}}$ for all $s\geq t_{i}$ where $\widetilde W$ is a standard Brownian motion. 

Hence, plugging this in \eqref{eq:Uti}, approximating $U_{t_i, t_{i+1}}$  boils down to finding  a nonnegative random variable $\widehat U_{i,i+1}$ solving  
\begin{align}\label{eq:IGequation}
   (1-b k_0) \widehat U_{i,i+1} = \alpha_i + k_{0} c\widetilde W_{\widehat U_{i,i+1}}.
\end{align}  

Said differently,  $\widehat U_{i,i+1}$ is a passage  time of the level $\alpha_i$ for the drifted Brownian motion $ ((1-b k_0)s -  k_{0}c \widetilde W_{s})_{s\geq 0} $. In particular,  the first passage time 
$$ X = \inf \left\{ s\geq 0: (1-b k_0) s -  c k_{0}\widetilde W_{s}= \alpha_i \right\} $$
satisfies \eqref{eq:IGequation}. 
It is well known that $X$ follows an  Inverse Gaussian distribution $IG(\mu_i,\lambda_i)$ with mean parameter $\mu_i= \frac{\alpha_i}{1-b k_0}$  and shape parameter $\lambda_i = \frac{\alpha_i^2}{k_{0}^2 c^2}$. Inverse Gaussian distributions are recalled in Appendix~\ref{A:IG}.  

Hence, we sample $\widehat U_{i,i+1}$ using  the Inverse Gaussian distribution as in \eqref{eq:hatUsample}. Beyond its tractability and efficient  sampling, see Algorithm~\ref{alg:IG_sampling}, the choice of the Inverse Gaussian distribution is further justified in Section~\ref{S:whyIG} where it is shown to be intimately linked with the distributional properties of the integrated square-root process $U$. Then, using \eqref{eq:IGequation} we can define the   $\widehat Z_{i,i+1}$ (which plays the role of $\widetilde W_{\widehat U_{i,i+1}}$) using equation \eqref{eq:Zii}. 

Putting everything together, we arrive at the iVi scheme of Algorithm~\ref{alg:simulation}.  


\subsection{Well-definedness of the scheme}

To ensure the well-definedness of Algorithm~\ref{alg:simulation}, we need to verify that the mean parameter $\alpha_i$ in \eqref{eq:alphai} of the Inverse Gaussian distribution is nonnegative for each $i=0,\ldots,n$, with the convention that \( IG(0,0) = \delta_0 \) the dirac at $0$.

This is the objective of Theorem~\ref{T:nonnegative}. As a by-product, we will show that the discretized increments $\widehat{U}_{i,i+1}$ are nonnegative for all \( i = 0, \ldots, n-1 \).

The proof relies on a continuous time reformulation of the problem.~For this, we introduce the functions $\bar{g}_0$ and $\bar{K}$ defined by:
\begin{align}\label{eq:barGbarK}
    \bar{g}_0(t) = \int_0^{\frac{T}{n}} g_0(t+s) \, ds \quad \text{and} \quad \bar{K}(t) = \int_0^{\frac{T}{n}} K(t+s) \, ds,
\end{align}
and observe that $\bar{K}(t_i - t_j) = k_{i-j}$, so that $\alpha_i$ in \eqref{eq:alphai} can be rewritten as:
\[
\begin{aligned}\label{eq:alphai2}
    \alpha_i = \bar{g}_0(t_i) + \sum_{j=0}^{i-1} \frac{\bar{K}(t_i - t_j)}{\bar{K}(0)} \left( \widehat U_{j,j+1} - \alpha_j \right).
\end{aligned}
\]
One approach is to prove that $\alpha_i$ remains nonnegative recursively, but this would result in cumbersome recursive formulas involving the kernel \( K \) and the input function \( g_0 \). A more elegant solution simplifies these computations by leveraging an  idea introduced in \cite{alfonsi2025nonnegativity}. This approach reformulates the problem ``continuously in time"  and utilizes kernels that preserve nonnegativity, as described in \cite[Definition~2.1]{alfonsi2025nonnegativity}.

Intuitively, kernels that preserve nonnegativity ensure that if a  discrete convolution  by the kernel is nonnegative when evaluated at some  discretization points, then, the discrete convolution  remains nonnegative over all time.

\begin{definition}
    Let \( K \colon \mathbb{R}_+ \to \mathbb{R}_+ \) be a kernel such that \( K(0) > 0 \). We say that the kernel \( K \) preserves nonnegativity if, for any \( i \geq 1 \), any \( x_1, \ldots, x_i \in \mathbb{R} \), and \( 0 \leq t_1 < \cdots < t_i \) such that:
    $$
    \sum_{j=1}^\ell K(t_\ell - t_j) x_j \geq 0, \quad \ell = 1, \ldots, i,
    $$
    we have:
    $$
    \sum_{j : t_j \leq t} K(t - t_j) x_j \geq 0, \quad t \geq 0,
    $$
    with the convention \( \sum_{\emptyset} = 0 \).
\end{definition}

Unlike \cite{alfonsi2025nonnegativity}, where the nonnegative preserving property is required for the kernel \( K \), we impose this requirement on  the integrated kernel \( \bar{K} \), to be able to adapt the ideas to our context.

\begin{theorem}\label{T:nonnegative}
    Let $K, g_0 \in L^1_{\rm loc}(\R_+, \R)\,$, $b \leq 0$ and $c \geq 0\,$.  Assume that in \eqref{eq:barGbarK},  $\bar g_0:\R_+\to \R_+$ is non-decreasing and nonnegative  and that $\bar K:\R_+ \to \R_+$ is non-increasing and preserves nonnegativity.~Consider   \( ( \widehat U_{i, i+1})_{i=0, \ldots, n-1} \), and \( ( \widehat Z_{i, i+1})_{i=0, \ldots, n-1} \) satisfying the recursions of the {\normalfont iVi} scheme in  Algorithm~\ref{alg:simulation}. Then,  we have that 
    \begin{align}
         \alpha_i, \widehat U_{i,i+1} \geq 0, \quad i=0,\ldots, n-1,
    \end{align}
and the algorithm is well-defined.
\end{theorem}

\begin{proof}
    See Section~\ref{S:ProofMainWellDefined}.
\end{proof}



The following proposition provides examples of input curves $g_0$ and kernels $K$ that satisfy the assumptions of Theorem~\ref{T:nonnegative}.    

\begin{proposition}
Let $K, g_0 \in L^1_{\rm loc}(\mathbb{R}_+, \mathbb{R})$ such that $g_0$ is non-decreasing and nonnegative, and $K$ is non-increasing with the following representation 
\begin{align}\label{eq:laplacetranform}
    K(t) = \int_{\R} e^{- x t} \mu(dx), \quad t >0, 
\end{align}
where $\mu$ is  a 
measure of locally bounded variation.~Then, the function $\bar g_0: \mathbb{R}_+ \to \mathbb{R}_+$ is non-decreasing and nonnegative, while $\bar K: \mathbb{R}_+ \to \mathbb{R}_+$ is non-increasing and preserves nonnegativity.  
\end{proposition}


\begin{proof}
    The part for $\bar g_0$ is straightforward.~Note that since $K$  is non-increasing so is  $\bar K$.~It remains to  argue that $\bar K$ preserves nonnegativity. For this, it suffices to observe that, thanks to Fubini's theorem, $\bar K$ admits the representation 
    $ \bar K(t) = \int_{\R_+}e^{-xt} \nu(dx) $, for $t \geq 0$, with $\nu(dx) = ((1 - e^{xT/n})/x)\mu(dx)$. An application of \cite[Theorem 2.11]{alfonsi2025nonnegativity} yields that $\bar K$ preserves nonnegativity. 
\end{proof}


\begin{example}
\label{example:completely_monotone}
    Any completely monotone kernel $K$, i.e. a function that is infinitely differentiable on $(0, \infty)$ and satisfies  
    $(-1)^j K^{(j)}(t) \geq 0$ for all $t > 0$ and $j \geq 0$, satisfies \eqref{eq:laplacetranform} by Bernstein's theorem, with $\mu$ a nonnegative measure on $\mathbb{R}_+$.  

    Examples of such kernels include:  
    \begin{itemize}
        \item Weighted sum of exponentials: 
        $K(t) = \sum_{i=1}^N c_i e^{-x_i t}, \quad c_i \geq 0, \quad x_i \geq 0, \quad N \in \mathbb{N}.$
        \item Fractional kernel:  
        $K(t) = c t^{H - 1/2}, \quad c > 0, \quad H \in (-1/2, 1/2].$
        \item Shifted fractional kernel: 
        $K(t) = c (t+\epsilon)^{H - 1/2}, \quad c > 0, \quad \epsilon > 0, \quad H \leq 1/2.$
    \end{itemize}
    In addition, sums and products of completely monotone kernels are again completely monotone. 
    Hence, these kernels satisfy the assumptions of Theorem~\ref{T:nonnegative} and with $g_0$ non-decreasing, for instance with $g_0$ given by 
    $$g_0(t) = V_0 + a\int_0^t K(s)\,  ds, \quad t \geq 0,   $$ with $a, V_0 \geq 0$.\qed 
\end{example}


Figure~\ref{fig:samplepaths} presents sample paths of $\left(\widehat{U}, \widehat{Z}\right)$ generated using the iVi scheme in Algorithm~\ref{alg:simulation}, along with the discrete derivative  
$$\widehat{V}_i = \frac{\widehat U_{i, i+1}}{t_{i+1} - t_i}$$
for the fractional kernel $K(t) = t^{H-1/2} / \Gamma(H+1/2)$ with $H \in \{0.1,-0.1, -0.4\}$.

We can clearly observe the impact of the Hurst index $H$ on the sample paths of the process. If $H > 0$, the process $U$ is absolutely continuous with respect to the Lebesgue measure, and $\widehat{V}$ serves as an approximation of the density process $V$, which satisfies \eqref{eq:V}. In contrast, when $H < 0$, $U$ is no longer absolutely continuous with respect to the Lebesgue measure, and this transition is evident in the sample paths of both $\widehat{U}$ and $\widehat{V}$. As $H \to -0.5$, jump behavior emerges in $\widehat{U}$ and $\widehat{Z}$, illustrating their convergence toward a jump Inverse Gaussian process, as recently established in \cite*{jaber2025hyper}. 

Notably, in all cases, all sample paths of $\widehat{U}$ remain non-decreasing, as proved in Theorem~\ref{T:nonnegative}, and consequently $\widehat{V}$ stays nonnegative.

