\subsection{Estimates on the sequences of processes}
We now aim to characterize the processes $\left(U^n\,, Z^n\right)_{n \geq 1}$ defined in \eqref{eq:def_process_U}-\eqref{eq:def_process_Z}. Firstly, we prove the martingality of $\left(Z^n\right)_{t \leq T}$ for any $n \geq 1\,$, along with a control in $U^n$ over its quadratic variation, which is obtained using the estimates given by Lemma \ref{lemma:properties_sequence}. Additionally, we show that $\left(Z^n\right)^2 - U^n$ is a also martingale, which will play an important role in identifying the limit.
\begin{lemma}
    \label{lemma:martingality}
    For any $n \geq 1\,$, we have:
    \begin{enumerate}[label = (\roman*)]
        \item $\left(Z^n_t\right)_{t \leq T}$ is a square-integrable martingale, such that 
        $$
        \left[Z^n\right]_t = \sum_{i = 0}^{\lfloor nt/T\rfloor - 1}\,\left(\widehat{Z}^n_{i,i+1}\right)^2\,, \quad t \leq T\,,
        $$
        as well as
        \begin{equation}
        \label{eq:exp_quad_Z_equals_exp_U}
        \mathbb{E}\left[\left[Z^n\right]_t - \left[Z^n\right]_s \,|\, \mathcal{F}^n_s \right] = \mathbb{E}\left[U^n_t - U^n_s \,|\, \mathcal{F}^n_s\right] \,, \quad s \leq t \leq T\,,
        \end{equation}
        and 
        \begin{equation}
        \label{eq:control_quad_Z}
        \mathbb{E}\left[\left(\left[Z^n\right]_t - \left[Z^n\right]_s\right)^2\right] \leq 25\, \mathbb{E}\left[\left(U^n_t - U^n_s\right)^2\right]\,, \quad s \leq t \leq T\,.
        \end{equation}
        \item $\left(\left(Z^n_t\right)^2 - U^n_t\right)_{t \leq T}$ is a martingale.
    \end{enumerate}
\end{lemma}
\begin{proof}
    In this proof, we consider $s \leq t \leq T\,$, and define $i := \lfloor nt/T \rfloor$ and $j := \lfloor ns/T \rfloor$ for readability. We compute
    \begin{align*}
        \mathbb{E}\left[Z^n_t \,|\, \mathcal{F}^n_s\right] &= \mathbb{E}\left[Z^n_{t^n_i}\,|\,\mathcal{F}^n_{t^n_j}\right] \\
        &= Z^n_{t^n_j} + \sum_{l = j}^{i-1}\, \mathbb{E}\left[\widehat Z^n_{l,l+1}\,|\, \mathcal{F}^n_{t^n_j}\right] \\
        &= Z^n_{t^n_j} + \sum_{l = j}^{i-1}\, \mathbb{E}\left[\mathbb{E}\left[\widehat Z^n_{l,l+1}\,|\, \mathcal{F}^n_{t^n_l}\right]\,|\, \mathcal{F}^n_{t^n_j}\right]
    \end{align*}
    using the tower property of conditional expectation, since $\mathcal{F}^n_{t^n_j} \subset \mathcal{F}^n_{t^n_l}$ for $j \leq l\,$. Using (\textit{i}) of Lemma \ref{lemma:properties_sequence}, we obtain
    $$
    \mathbb{E}\left[Z^n_t\,|\, \mathcal{F}^n_s\right] = Z^n_{t^n_j} = Z^n_s\,,
    $$
    proving that $\left(Z^n_t\right)_{t \leq T}$ is a martingale. The fact that it is square-integrable is direct from Lemma \ref{lemma:properties_sequence}.
    Furthermore, notice that $Z^n$ can be rewritten as 
    $$
    Z^n_t = \sum_{i = 0}^{\lfloor nt/T\rfloor - 1}\, \left(\widehat Z^n_{i,i+1}\right)^+ - \sum_{i = 0}^{\lfloor nt/T\rfloor - 1}\, \left(\widehat Z^n_{i,i+1}\right)^-\,, \quad t \leq T\,,
    $$
    which is the difference of two non-decreasing processes. Therefore it has finite variation on $[0\,,T]$ and is a quadratic pure-jump martingale \citep[Theorem~II.26]{protter2005stochastic}. This proves that
    $$
    \left[Z^n\right]_{t} = \sum_{0 \leq s \leq t}\, \left(\Delta Z^n_s\right)^2 = \sum_{i = 0}^{\lfloor nt/T \rfloor -1}\, \left(\widehat Z^n_{i,i+1}\right)^2\,, \quad t \leq T\,,
    $$
    since $Z^n_0 = 0\,$.
    From (\textit{ii}) of Lemma \ref{lemma:properties_sequence},
    \begin{align*}
    \mathbb{E}\left[\left(\widehat{Z}^n_{l,l+1}\right)^2\,|\, \mathcal{F}^n_{t_j^n}\right] &= \mathbb{E}\left[\mathbb{E}\left[\left(\widehat{Z}^n_{l,l+1}\right)^2\,|\,\mathcal{F}^n_{t_l^n}\right]\,|\, \mathcal{F}^n_{t_j^n}\right] \\
    &= \mathbb{E}\left[\mathbb{E}\left[\widehat{U}^n_{l,l+1}\,|\,\mathcal{F}^n_{t_l^n}\right]\,|\, \mathcal{F}^n_{t_j^n}\right] \\
    &= \mathbb{E}\left[\widehat{U}^n_{l,l+1}\,|\, \mathcal{F}^n_{t^n_j}\right]\,, \quad j \leq l \leq n-1\,,
    \end{align*}
    and therefore taking any $s \leq t \leq T\,$, we obtain
    \begin{align*}
        \mathbb{E}\left[\left[Z^n\right]_t - \left[Z^n\right]_s\, |\, \mathcal{F}^n_s\right] &= \sum_{l = j}^{i-1} \, \mathbb{E}\left[ \left(\widehat{Z}^n_{l,l+1}\right)^2\,|\, \mathcal{F}^n_{t_j^n}\right] \\
        &= \sum_{l = j}^{i-1} \mathbb{E}\left[\widehat{U}^n_{l,l+1}\,|\, \mathcal{F}^n_{t_j^n}\right]\\
        &= \mathbb{E}\left[U^n_t - U^n_s \,|\, \mathcal{F}^n_s\right]\,,
    \end{align*}
    where $i = \lfloor nt/T \rfloor$ and $j = \lfloor ns/T \rfloor\,$,
    which proves \eqref{eq:exp_quad_Z_equals_exp_U}. Finally, we have 
    \begin{align*}
        \mathbb{E}\left[\left(\left[Z^n\right]_t - \left[Z^n\right]_s\right)^2\right] &= \mathbb{E}\left[\left(\sum_{l = j}^{i-1}\,\left(\widehat{Z}^n_{l,l+1}\right)^2 \right)^2 \right] \\
        &= \sum_{l = j}^{i-1}\, \mathbb{E}\left[\left(\widehat{Z}^n_{l,l+1}\right)^4\right] + 2\,\sum_{l = j}^{i-1}\,\sum_{k = l+1}^{i-1}\, \mathbb{E}\left[\left(\widehat{Z}^n_{l,l+1}\right)^2\, \left(\widehat{Z}^n_{k,k+1}\right)^2\right]\,.
    \end{align*}
    For $l < k \leq n-1\,$, (\textit{ii}) of Lemma \ref{lemma:properties_sequence} gives 
    $$
\mathbb{E}\left[\left(\widehat{Z}^n_{l,l+1} \right)^2\, \left(\widehat{Z}^n_{k,k+1} \right)^2\right] = \mathbb{E}\left[\left(\widehat{Z}^n_{l,l+1}\right)^2\, \mathbb{E}\left[ \left(\widehat{Z}^n_{k,k+1}\right)^2\,|\,\mathcal{F}^n_{t_k^n}\right] \right] = \mathbb{E}\left[\left(\widehat{Z}^n_{l,l+1}\right)^2\, \widehat{U}^n_{k,k+1}\right] \,.
    $$
 Combining this with (\textit{iii}) of the same lemma, we obtain 
\begin{align*}
    \mathbb{E}\left[\left(\left[Z^n\right]_t - \left[Z^n\right]_s\right)^2\right] &\leq \, \mathbb{E}\left[5\,\sum_{l = j}^{i-1}\, \left(\widehat{Z}^n_{l,l+1}\right)^2\, \widehat{U}^n_{l,l+1} + 2\,\sum_{l = j}^{i-1}\,\sum_{k = l+1}^{i-1}\, \left(\widehat{Z}^n_{l,l+1}\right)^2\, \widehat{U}^n_{k,k+1}  \right] \\
    &\leq 5\, \mathbb{E}\left[\sum_{l = j}^{i-1}\, \left(\widehat{Z}^n_{l,l+1}\right)^2\, \left(\widehat{U}^n_{0,i} - \widehat{U}^n_{0,l}\right) \right] \\
    &\leq 5\, \mathbb{E}\,\left[\left(\left[Z^n\right]_t - \left[Z^n\right]_s\right)\,\left(U^n_t - U^n_s\right) \right]\,,
\end{align*}
using the fact that $U^n$ is non-decreasing. Applying Cauchy-Schwarz's inequality, we get 
$$
\mathbb{E}\left[\left(\left[Z^n\right]_t - \left[Z^n\right]_s\right)^2\right] \leq 5\, \sqrt{\mathbb{E}\left[\left(\left[Z^n\right]_t - \left[Z^n\right]_s\right)^2 \right]\, \mathbb{E}\left[\left(U^n_t - U^n_s\right)^2\right]}\,,
$$
which proves \eqref{eq:control_quad_Z}.

In order to prove (\textit{ii}) of Lemma \ref{lemma:martingality}, we notice that \eqref{eq:exp_quad_Z_equals_exp_U} shows that $\left(\left[Z^n\right]_t - U^n_t\right)_{t \leq T}$ is a martingale. Thus, $\left(\left(Z^n_t\right)^2 - U^n_t\right)_{t \leq T}$ is a local martingale. Moreover,
$$
\mathbb{E}\left[\sup_{0 \leq t \leq T}\, \left|Z^n_t\right|^2\right] \leq C\, \mathbb{E}\left[\left[Z^n\right]_T\right] = C \, \mathbb{E}\left[U^n_T\right] < + \infty\,,
$$
for some constant $C \geq 0\,$, using the BDG inequality, along with \eqref{eq:exp_quad_Z_equals_exp_U} with $t = T$ and $s = 0\,$, and the fact that the $\left(\widehat U^n_{i,i+1}\right)_{i \leq n-1}$ all have finite expectation in virtue of Lemma \ref{lemma:properties_sequence}. Adding the fact that 
$$
\mathbb{E}\left[\sup_{0 \leq t \leq T}\, U^n_t\right] = \mathbb{E}\left[U^n_T\right] < + \infty\,,
$$
since $U^n$ is non-decreasing. We conclude that $\mathbb E \left[\sup\limits_{0 \leq t \leq T}\, \left|\left(Z^n_t\right)^2 - U^n_t \right| \right] < + \infty\,$, and $\left(Z^n\right)^2 - U^n$ is therefore a true martingale.
\end{proof}
Before deriving estimates on our processes, we show that they satisfy a Volterra equation with a measure-valued kernel, which will be pivotal for the proofs.
\begin{lemma}
    \label{lemma:convolution_equation}
    For any $n \geq 1\,$, define the nonnegative finite measure $K^n := \sum_{i = 0}^{n-1}\,k^n_i\, \delta_{t^n_i}$ on $\left([0\,,T]\,, \mathcal B_{[0\,,T]}\right)\,$, where the $\left(k^n_i\right)_{i \leq n-1}$ are defined in \eqref{eq:kij}. Then we have 
    $$
    U^n_t = G_0^n(t) + \int_{[0,t]}\,\widetilde{Z}^n_{t-s}\, K^n(ds)\,, \quad t \leq T\,, \quad n \geq 1\,,
    $$
    where $\widetilde{Z}^n := b\,U^n + c\,Z^n$ as in \eqref{eq:tildeZ} and $G_0^n(t) := \int_0^{\lfloor \frac{nt}{T} \rfloor \frac{T}{n}}\,g_0(s)\,ds\,$.
\end{lemma}
\begin{proof}
    Let $n \geq 1\,$, $t < T$ and define $i := \lfloor nt/T \rfloor\,$, then $t^n_i \leq t < t^n_{i+1}\,$. Then,
    \begin{equation}
        \int_{[0,t]}\,\widetilde{Z}^n_{t-s}\,K^n(ds) = \sum_{j = 0}^{i}\,k^n_j\, \tilde{Z}^n_{t-t^n_j} \,.
    \end{equation}
    Since the partition $\left(t^n_j\right)_{j \leq n}$ is uniform,
    $$
    t^n_{i-j} = t^n_i - t^n_j \leq t - t^n_j < t^n_{i+1} - t^n_j = t^n_{i-j +1}\,, \quad j \leq i\,,
    $$
    and we can rewrite the integral as 
    \begin{align*}
        \int_{[0,t]}\, \widetilde{Z}^n_s\,K^n(ds) = \sum_{j = 0}^i\,k^n_j\, \widetilde{Z}^n_{t^n_{i-j}} = \sum_{j = 1}^i\,k^n_{i-j}\, \widetilde{Z}^n_{t^n_j} \,,
    \end{align*}
    using $\widetilde{Z}^n_0 = 0\,$. In the case $t = T\,$, we have
    $$
    \int_{[0,T]}\, \widetilde{Z}^n_{T-s}\, K^n(ds) = \sum_{j = 0}^{n-1}\, k^n_j\, \widetilde{Z}^n_{T - t^n_j} = \sum_{j = 0}^{n-1}\, k^n_j\, \widetilde{Z}^n_{t^n_{n-j}} = \sum_{j = 1}^n\, k^n_{n-j}\, \widetilde{Z}^n_{t^n_j}\,.
    $$
    Therefore, we always have
    \begin{equation}
    \label{eq:convolution_equality_general}
    \int_{[0,t]}\, \widetilde{Z}^n_{t-s}\, K^n(ds) = \sum_{j = 1}^{i }\, k^n_{i-j}\,\widetilde{Z}^n_{t^n_j}\,, \quad t \leq T\,,
    \end{equation}
    with $i = \lfloor nt/T \rfloor \,$.

    Taking $t \leq T\,$, setting $i := \lfloor nt/T \rfloor\,$, and using \eqref{eq:alphai}-\eqref{eq:Zii}, we can compute
    \begin{align*}
        U^n_t &= \sum_{j = 0}^{i-1}\, \widehat U^n_{i,i+1} \\
        &= \sum_{j = 0}^{i-1}\, \left(\alpha^n_j + k_0^n\, \left(b\,\widehat U^n_{j,j+1} + c\, \widehat Z^n_{j,j+1}\right) \right) \\
        &= \int_0^{t^n_i}\, g_0(s)\,ds + \sum_{j  = 0}^{i-1}\, \sum_{l = 0}^{j}\, k^n_{j-l}\, \left(b\, \widehat{U}^n_{l,l+1} + c \,\widehat{Z}^n_{l,l+1}\right)\,.
    \end{align*}
    Using the fact that $\int_0^{t^n_i}\, g_0(s)\,ds = G_0^n(t)$ and $b\,\widehat U^n_{l,l+1} + c \,\widehat{Z}^n_{l,l+1} = \widetilde{Z}^n_{t^n_{l+1}} - \widetilde{Z}^n_{t^n_l}\,$, we get
    \begin{align*}
        U^n_t &= G_0^n(t) + \sum_{j = 0}^{i-1}\, \sum_{l = 0}^j\,k^n_{j -l}\, \left(\widetilde{Z}^n_{t^n_{l+1}} - \widetilde{Z}^n_{t^n_l}\right) \\
        &= G_0^n(t) + \sum_{l = 1}^i \, \widetilde{Z}^n_{t^n_l}\, \sum_{j = l}^i\, k^n_{j-l} - \sum_{l = 1}^{i-1}\, \widetilde{Z}^n_{t^n_l}\, \sum_{j = l}^{i-1}\,k^n_{j-l}\\
        &= G_0^n(t) + \sum_{l = 1}^i \, \widetilde{Z}^n_{t^n_l}\, k^n_{i-l}\,.
    \end{align*}
    Therefore, applying \eqref{eq:convolution_equality_general}, we finally obtain
    $$
    U^n_t = G_0^n(t) + \int_{[0,t]}\, \widetilde{Z}^n_{t-s}\,K^n(ds)\,.
    $$
\end{proof}
We are now ready to state our estimates on the processes $\left(U^n\,, Z^n\right)_{n \geq 1}\,$. We introduce the notation
\begin{equation}
    \label{eq:def_G_0}
    G_0(t) := \int_0^t\, g_0(s)\,ds\,, \quad t \leq T\,.
\end{equation}
\begin{lemma}
    We have the upperbound 
    \begin{equation}
        \label{eq:bound_exp_U}
        \mathbb{E}\left[U^n_t\right] \leq G_0(T)\,, \quad t \leq T\,, \quad n \geq 1\,,
    \end{equation}
    and there exists constants $C_1\,, C_2 \geq 0\,$, such that
    \begin{equation}
        \label{eq:bound_exp_U_2}
        \mathbb{E}\left[\left(U^n_t\right)^2\right] \leq C_1\,G_0(T) + C_2\, G_0(T)^2\,, \quad t \leq T\,, \quad n \geq 1\,.
    \end{equation}
    Moreover, 
    \begin{equation}
        \label{eq:bound_variation_U}
        U^n_{t^n_i} - U^n_{t^n_j} \leq G_0(t^n_i) - G_0(t^n_j) + 2 \, \left\|\widetilde{Z}^n\right\|_{\infty}\,\int_0^{t^n_i - t^n_j}\, K(s)\,ds\,, \quad j \leq i \leq n\,, \quad n \geq 1\,.
    \end{equation}
\end{lemma}
\begin{remark}
    Note that 
    \begin{equation}
    \label{eq:bound_exp_Z_2}
    \mathbb{E}\left[\sup_{0 \leq t \leq T}\,\left|Z^n_t\right|^2\right] \leq C_3\, \mathbb{E}\left[\left[Z^n\right]_T\right] = C_3 \, \mathbb{E}\left[U^n_T\right] \leq C_3\,G_0(T) \,, \quad n \geq 1\,,
    \end{equation}
    for a certain $C_3 \geq 0\,$, using the BDG inequality, along with \eqref{eq:exp_quad_Z_equals_exp_U} with $t = T$ and $s = 0\,$, and \eqref{eq:bound_exp_U}. Additionally, 
    \begin{equation}
    \label{eq:bound_exp_Z_tilde}
\mathbb{E}\left[\left\|\tilde{Z}^n\right\|_{\infty}\right] \leq |b|\, \mathbb{E}\left[U^n_T\right] + c \, \left(1 + \mathbb{E}\left[\sup_{0 \leq t \leq T}\, \left|Z^n_t\right|^2\right]\right) \leq C_4\, \left(1 + G_0(T)\right)\,, \quad n \geq 1\,,
    \end{equation}
    for a certain constant $C_4 \geq 0\,$, using \eqref{eq:bound_exp_Z_2} and \eqref{eq:bound_exp_U}.
\end{remark}
\begin{proof}
    We make use of the Volterra equation given by Lemma \ref{lemma:convolution_equation}. Since $b \leq 0$ and $U^n$ is a nonnegative process for any $n \geq 1\,$, we have 
    $$
    U^n_t \leq G_0^n(t) + c\,\int_{[0,t]}\,Z^n_{t-s}\,K^n(ds)\,, \quad t \leq T\,, \quad n \geq 1\,.
    $$
    Since $Z^n$ is a square-integrable martingale for any $n \geq 1\,$, taking the expectation in the previous relation proves \eqref{eq:bound_exp_U}, using the fact that
    $$
    G_0^n(t) \leq G_0^n(T) = G_0(T) \,, \quad t \leq T \,, \quad n \geq 1\,.
    $$
    Moreover, we have 
    $$
    U^n_t \leq G_0(T) + c\,\sup_{0 \leq s \leq T}\, \left|Z^n_s\right|\, \int_{[0,T]}\, K^n(ds)\, \quad t \leq T\,, \quad n \geq 1\,,
    $$
    so that
    $$   \mathbb{E}\left[\left(U^n_t\right)^2\right] \leq 2\,G_0(T)^2 + 2\,\left(c\,\int_0^T\,K(s)\,ds\right)^2 \, \mathbb{E}\left[\sup_{0 \leq s \leq T}\, \left|Z^n_s\right|^2\right]\,, \quad t \leq T\,, \quad n \geq 1\,,
    $$
    using the fact that $\int_{[0,T]}\,K^n(ds) = \int_0^T\,K(s)\,ds$ for any $n \geq 1\,$. Applying \eqref{eq:bound_exp_Z_2} (which only uses \eqref{eq:bound_exp_U}) leads to 
    $$
    \mathbb{E}\left[\left(U^n_t\right)^2\right] \leq 2\,G_0(T)^2 + 2\,C_3\,G_0(T)\, \left(c\,\int_0^T\, K(s)\,ds\right)^2\,, \quad t \leq T\,, \quad n \geq 1\,,
    $$
    and proves \eqref{eq:bound_exp_U_2}.

    In order to prove \eqref{eq:bound_variation_U}, we fix $n \geq 1$ and $j \leq i \leq n\,$. Lemma \ref{lemma:convolution_equation} gives
    \begin{align*}
        U^n_{t^n_i} - U^n_{t^n_j} &= G_0^n(t^n_i) - G_0^n(t^n_j) + \sum_{l = 1}^{i}\, k^n_{i-l}\, \widetilde{Z}^n_{t^n_l} - \sum_{l = 1}^j \,k^n_{j-l}\, \widetilde{Z}^n_{t^n_l} \\
        &= G_0^n(t^n_i) - G_0^n(t^n_j) + \sum_{l = 1}^j\, \widetilde{Z}^n_{t^n_l}\, \left(k^n_{i-l} - k^n_{j-l} \right) + \sum_{l = j+1}^i\, k^n_{i-l}\, \widetilde{Z}^n_{t^n_l}\,.
    \end{align*}
    In virtue of Assumption \ref{assumption:preserve_nonnegativity}, $\bar K^n$ is non-decreasing and therefore $\left(k^n_i\right)_{i \leq n-1}$ is a non-decreasing sequence. We deduce that 
    \begin{align*}
        U^n_{t^n_i} - U^n_{t^n_j} \leq G_0^n(t^n_i) - G_0^n(t^n_j) + \left\| \widetilde{Z}^n \right\|_{\infty}\, \left(\sum_{l = 1}^j\, k^n_{j-l} - k^n_{i-l} + \sum_{l = j+1}^{i}\,k^n_{i-l} \right) \,.
    \end{align*}
    We conclude by noticing that $G_0^n(t^n_l) = G_0(t^n_l)$ for any $l \leq n\,,$ and by upperbounding
    \begin{align*}
        \sum_{l = 1}^j\, k^n_{j-l} - k^n_{i-l} + \sum_{l = j+1}^{i}\,k^n_{i-l} &= \int_0^{t^n_j}\, K(s)\,ds - \int_{t^n_i - t^n_j}^{t^n_i}\,K(s)\,ds + \int_0^{t^n_i - t^n_j}\, K(s)\,ds \\
        &\leq \int_0^{t^n_i}\, K(s)\,ds - \int_{t^n_i - t^n_j}^{t^n_i}\,K(s)\,ds + \int_0^{t^n_i - t^n_j}\, K(s)\,ds \\
        &\leq 2\, \int_{0}^{t^n_i - t^n_j}\, K(s)\,ds\,.
    \end{align*}
\end{proof}

\subsection{Tightness}
We want to prove C-tightness of our sequences of processes, i.e.~tightness for the Skorokhod $J_1$ topology, with continuous limits. We use the following criterion.
\begin{proposition}[\cite{jacod2013limit}, Proposition~VI.3.26]
    \label{proposition:C_tight_criterion}
    A sequence of càdlàg stochastic processes $\left(X^n\right)_n$ defined on $[0\,,T]$ is C-tight if the following two conditions are satisfied:
    \begin{itemize}
        \item[$\bullet$] $\lim\limits_{R \to + \infty}\, \limsup\limits_n\, \mathbb{P}\left(\left\|X^n\right\|_{\infty} > R \right) = 0\,$.
        \item[$\bullet$] For any $\varepsilon > 0\,$,
        $$\lim\limits_{\delta \to 0^+}\, \limsup\limits_n \, \mathbb{P}\left(w\left(X^n\,,\delta\right) \geq \varepsilon\right) = 0\,,$$
        where $w$ is the modulus of continuity
        $$
        w(f, \delta) := \sup_{\substack{0 \leq s \leq t \leq T \\ |t - s| \leq \delta}}\, |f(t) - f(s)|\,, \quad f \in D([0\,,T])\,, \quad \delta > 0\,.
        $$
    \end{itemize}
\end{proposition}
We prove C-tightness of both sequences of processes.
\begin{lemma}
    \label{lemma:C_tightness}
    Both $\left(U^n\right)_{n \geq 1}$ and $\left(Z^n\right)_{n \geq 1}$ are C-tight.
\end{lemma}
\begin{proof}
    We first prove tightness of $\left(U^n\right)_{n \geq 1}\,$. \eqref{eq:bound_exp_U} gives us 
    $$
    \sup_n \, \mathbb{E}\left[\left\|U^n\right\|_{\infty}\right] = \sup_n \, \mathbb{E}\left[U^n_T\right] \leq G_0(T) < + \infty\,,
    $$
    so that the first condition of Proposition \ref{proposition:C_tight_criterion} is satisfied by Markov's inequality.

    Then, by definition, 
    $$
    w\left(U^n\,,\delta\right) = \max_{\substack{0 \leq j \leq i \leq n \\ |t^n_i - t^n_j| \leq \delta}} \, U^n_{t^n_i} - U^n_{t^n_j} \,, \quad n \geq 1\,,\quad \delta > 0\,.
    $$
    Thus, for any $\delta > 0$ and $n \geq 1\,$, \eqref{eq:bound_variation_U} gives 
    $$
    w\left(U^n\,, \delta\right) \leq w\left(G_0\,,\delta\right) + 2\,\left\|\tilde Z^n \right\|_{\infty}\, \int_0^{\delta}\,K(s)\,ds\,,
    $$
    so that
    $$
\mathbb{E}\left[w\left(U^n\,,\delta\right)\right] \leq w(G_0\,, \delta) + 2\,C_4\, \left(1 + G_0(T)\right)\, \int_0^{\delta}\,K(s)\,ds\,,
    $$
    using \eqref{eq:bound_exp_Z_tilde}. Since $g_0 \in L^1_{\rm loc}\left(\mathbb{R}_+, \mathbb R_+\right)\,$, $G_0$ defined in \eqref{eq:def_G_0} is continuous on $[0\,,T]\,$, by the dominated convergence theorem. With the same argument, $\int_0^{\delta}\,K(s)\,ds$ vanishes as $\delta$ goes to $0$. This proves C-tightness of $\left(U^n\right)_{n \geq 1}$ by Markov's inequality.


    For the sequence of martingales $\left(Z^n\right)_{n \geq 1}\,$, we first have
    $$
    \mathbb{E}\left[\sup_{0 \leq t \leq T}\, \left|Z^n_t\right|\right] \leq 1 + C_3\,G_0(T) < + \infty\,,
    $$
    from \eqref{eq:bound_exp_Z_2}, thus the first condition for C-tightness is satisfied. For the second criterion, let us fix $\delta > 0$ and $n > T / \delta\,$, we define $m := \lceil n\delta / T\rceil$ and $v := \lceil n / m \rceil\,$, as well as 
    $$
    s_i := i \, \frac{mT}{n} = t^n_{im}\,, \,\, 0 \leq i \leq v-1\,, \quad \text{and} \quad s_v := T \,.
    $$
    One can check that the two following inequalities are satisfied:
    \begin{equation}
        \label{eq:partition_above_delta}
        s_i - s_{i-1} \geq \delta \,, \quad 1 \leq i \leq v-1\,,
    \end{equation}
    \begin{equation}
        \label{eq:partition_upper_bound}
        s_i - s_{i-1} \leq \delta + T / n \leq 2\,\delta\,, \quad 1 \leq i \leq v\,.
    \end{equation}
Under the condition \eqref{eq:partition_above_delta}, \citet[Theorem~7.4]{billingsley2013convergence} gives 
$$
w\left(Z^n\,, \delta\right) \leq 3\, \max_{1 \leq i \leq v}\, \sup_{s_{i-1} \leq s \leq s_i}\, \left|Z^n_s - Z^n_{s_{i-1}}\right|\,.
$$
Therefore, for any $\varepsilon > 0\,$, recalling that our random variables admit finite moments of order $4$ thanks to Lemma \ref{lemma:properties_sequence},
\begin{align}
\label{eq:bdg_Z4}
    \mathbb{P}\left( w\left(Z^n\,, \delta\right) \geq 3\,\varepsilon\right) &\leq \sum_{i = 1}^v \, \mathbb{P}\left( \sup_{s_{i-1} \leq s \leq s_i}\, \left|Z^n_s - Z^n_{s_{i-1}}\right| \geq \varepsilon\right) \nonumber\\
    &\leq \frac{1}{\varepsilon^4}\, \sum_{i = 1}^v \, \mathbb{E}\left[\sup_{s_{i-1} \leq s \leq s_i}\, \left|Z^n_s - Z^n_{s_{i-1}}\right|^4 \right] \nonumber\\
    &\leq \frac{C_5}{\varepsilon^4}\, \sum_{i = 1}^v \, \mathbb{E}\left[\left(\left[Z^n\right]_s - \left[Z^n\right]_{s_{i-1}}\right)^2\right]\,,
\end{align}
for a certain constant $C_5 \geq 0\,$, thanks to the BDG inequality. We can apply \eqref{eq:control_quad_Z} to obtain
\begin{align*}
    \mathbb{P}\left( w\left(Z^n\,, \delta\right) \geq 3\,\varepsilon\right) &\leq \frac{25\,C_5}{\varepsilon^4}\, \sum_{i = 1}^v \, \mathbb{E}\left[\left(U^n_{s_i} - U^n_{s_{i-1}}\right)^2\right] \\
    &\leq \frac{25\, C_5}{\varepsilon^4}\, \mathbb{E}\left[U^n_T\, \max_{1 \leq i \leq v}\, U^n_{s_i} - U^n_{s_{i-1}}\right]\,.
\end{align*}
Finally, using \eqref{eq:bound_variation_U}, since $\left(s_i^n\right)_{i \leq v}$ is a sub-partition of $\left(t^n_i\right)_{i \leq n}$ with step less than $2\delta$ (see \eqref{eq:partition_upper_bound}), we obtain
\begin{align*}
    \mathbb{P}\left(w\left(Z^n\,, \delta\right) \geq 3\, \varepsilon \right) \leq \frac{25\, C_5}{\varepsilon^4}\, \left(w\left(G_0\,, 2\delta\right) + 2 \, \int_0^{2\delta}\, K(s)\,ds\, \mathbb{E}\left[U^n_T\, \left\| \tilde Z^n \right\|_{\infty}\right] \right)\,.
\end{align*}
We conclude by noticing that 
$$
\sup_n \, \mathbb{E}\left[U^n_T\, \left\| \tilde Z^n \right\|_{\infty}\right] \leq \sup_n \, \left(|b| \,\mathbb{E}\left[\left(U^n_T\right)^2\right] + c\, \sqrt{\mathbb{E}\left[\left(U^n_T\right)^2\right]\, \mathbb{E}\left[\sup_{0 \leq t \leq T}\, \left|Z^n_t\right|^2\right]}\right) < + \infty\,,
$$
combining \eqref{eq:bound_exp_U_2} and \eqref{eq:bound_exp_Z_2}. Thus, $\left(Z^n\right)_{n \geq 1}$ is C-tight.
\end{proof}
\begin{remark}
\label{remark:joint_tightness}
    In particular, the two sequences are $J_1(\mathbb{R})$-tight, which implies joint $J_1\left(\mathbb{R}^2\right)$-tightness of $\left(U^n\,, Z^n\right)_{n \geq 1}\,$, see \citet[Lemma~3.2]{whitt2007proofs}.
\end{remark}

\subsection{Characterization of the limiting processes}
Thanks to Prokhorov's theorem, joint tightness given by Lemma \ref{lemma:C_tightness} and Remark \ref{remark:joint_tightness} gives the existence of a weakly convergent subsequence of $\left(U^n\,,Z^n\right)_{n \geq 1}$ in $\left(D([0\,,T])^2\,, J_1\left(\mathbb{R}^2\right)\right)\,$. We therefore aim to characterize the law of those limits. This is achieved using the following stability lemma for convolutions.
\begin{lemma}
    \label{leamm:stability_convolution}
Consider a sequence $\left(f_n\right)_{n \geq 1}$ of càdlàg functions on $[0\,,T]\,$, converging in $L^1([0\,,T])$ to $f$ continuous. If the sequence $\left(F_n\right)_{n \geq 1}$ defined by 
$$
F_n(t) := \int_{[0,t]} \, f_n(t-s)\, K^n(ds)\,, \quad t \leq T\,, \quad n \geq 1\,,
$$
where $K^n$ is defined in Lemma \ref{lemma:convolution_equation}, converges in $L^1([0\,,T])$ to $F$ continuous, then 
$$
F(t) = \int_0^t \, f(t-s)\, K(s)\,ds \,, \quad t \leq T\,.
$$
\end{lemma}
\begin{proof}
    For any $n \geq 1\,$, we can write 
    \begin{align*}
        \int_0^T\, \left|F(t) - \int_0^t \, f(t-s)\, K(s)\, ds\right| \, dt &\leq \int_0^T \, \left|F(t) - F_n(t)\right| \, dt \\
        &\quad + \int_0^T\, \left| \int_{[0,t]} \, \left(f_n(t-s) - f(t-s)\right)\, K^n(ds) \right|\, dt \\
        &\quad + \int_0^T \, \left| \int_{[0,t]} \, f(t-s) \, K^n(ds) - \int_0^t \, f(t-s) \, K(s) \, ds\right| \, dt\,.
    \end{align*}
The first term on the right-hand side vanishes as $n$ goes to infinity by definition. The second is upper-bounded by 
$$
\int_0^T\, \int_s^T \, \left|f_n(t-s) - f(t-s)\right|\, dt \, K^n(ds) \leq \int_0^T \, K(s)\,ds \, \int_0^T \, \left|f_n(t) - f(t)\right|\, dt\,,
$$
which also vanishes by convergence in $L^1([0\,,T])\,$. Finally, we introduce the notations
$$
I^n_t := \int_{[0,t]}\,f(t-s)\,K^n(ds)\,, \quad I_t := \int_0^t\,f(t-s)\,K(s)\,ds\,, \quad t \leq T\,, \quad n \geq 1\,.
$$
For any $n \geq 1\,$, $0 < t < T\,$, setting $i := \lfloor nt/T \rfloor\,$, we have
$$
I^n_t = \sum_{j = 0}^{i} \,f(t- t^n_j)\,k^n_j = \sum_{j = 0}^{i}\,\int_{t^n_j}^{t^n_{j+1}}\,f(t - t^n_j)\, K(s)\,ds\,,
$$
and 
$$
I_t = \sum_{j = 0}^{i}\, \int_{t^n_j}^{t^n_{j+1}}\, f(t-s)\,K(s)\,ds - \int_t^{t^n_{i+1}}\,f(t-s)\,K(s)\,ds\,.
$$
Therefore, 
\begin{align*}
    \left|I^n_t - I_t\right| &\leq \sum_{j = 0}^i\, \int_{t^n_j}^{t^n_{j+1}}\, \left|f(t-t^n_j) - f(t-s)\right|\,K(s)\,ds + \int_{t}^{t^n_{i+1}}\, |f(t-s)|\,K(s)\,ds \\
    &\leq w\left(f\,,\frac{T}{n}\right)\, \sum_{j = 0}^i\, \int_{t^n_j}^{t^n_{j+1}}\, K(s)\,ds + \left\|f\right\|_{\infty}\, \int_t^{t^n_{i+1}}\,K(s)\,ds \\
    &\leq w\left(f\,,\frac{T}{n}\right)\, \int_0^T\,K(s)\,ds + \left\|f\right\|_{\infty}\, \int_t^{t^n_{i+1}}\,K(s)\,ds\,.
\end{align*}
Since $f$ is continuous, the modulus vanishes in the limit $n \to \infty\,$. Furthermore, $t^n_{i+1} = \frac{T}{n}\left(1 + \lfloor \frac{nt}{T}\rfloor \right)$ converges to $t\,$. By the dominated convergence theorem $\int_t^{t^n_{\lfloor nt/T\rfloor +1}}\,K(s)\,ds$ goes to $0\,$, as a consequence of $K$ being in $L^1([0\,,T])\,$. We deduce that for any $0 < t <T\,$, $I_t^n$ converges to $I_t$ as $n$ goes to infinity. Using the domination
$$
\left| I_t^n - I_t \right| \leq 2\, \|f\|_{\infty}\, \int_0^T \, K(s)\,ds < + \infty\,, \quad t \leq T\,, \quad n \geq 1\,,
$$
the dominated convergence theorem shows that the third integral on the right-hand side of our first inequality also vanishes in the limit. We conclude that 
$$
\int_0^T\, \left|F(t) - \int_0^t\, f(t-s)\,K(s)\,ds\right|\,dt = 0\,,
$$
and $F(t) = \int_0^{t}\,f(t - s)\,K(s)\,ds$ for $t \leq T$ in virtue of the continuity assumption on $F$ and $f\,$.
\end{proof}
We can now characterize the accumulation points of our sequence of processes.
\begin{lemma}
    \label{lemma:characterization_limit}
    Let $\left(U\,, Z\right)$ be a weak limit of a convergent subsequence $\left(U^{n_k}\,, Z^{n_k}\right)_{k \geq 1}\,$. Then:
    \begin{itemize}
        \item[$\bullet$] $U$ is a continuous, non-decreasing, nonnegative process, starting from 0.
        \item[$\bullet$] $Z$ is a continuous square-integrable martingale with respect to the filtration generated by $\left(U\,,Z\right)\,$, starting from 0, such that 
        $$
        \langle Z \rangle_t = U_t\,, \quad t \leq T. 
        $$
        \item[$\bullet$] The following Volterra equation is satisfied:
        $$
        U_t = \int_0^t\,g_0(s)\,ds + \int_0^t\, K(t-s)\, \left(b\,U_s + c\,Z_s\right)\,ds\,, \quad t \leq T\,, \quad \text{a.s.}
        $$
    \end{itemize}
\end{lemma}
\begin{proof}
    By Skorokhod's representation theorem \citep[Theorem~1.6.7]{billingsley2013convergence}, there exists càdlàg processes $\left(\mathfrak{U}^k\,, \mathfrak Z^k\right)_{k \geq 1}$ and $\left(\mathfrak U\,, \mathfrak Z\right)$ all defined on a common probability space $\left(\Omega'\,, \mathcal F'\,, \mathbb P'\right)\,$, such that:
    \begin{itemize}
        \item[$\bullet$] For any $k\geq 1\,$, $\left(U^{n_{k}}\,, Z^{n_{k}}\right) \sim \left( \mathfrak U^k \,, \mathfrak Z^k\right)\,$, and $\left(U\,, Z\right) \sim \left(\mathfrak U\,, \mathfrak Z\right)\,$.
        \item[$\bullet$] For any $\omega \in \Omega'\,$, $\left(\mathfrak U^k\,, \mathfrak Z^k\right)(\omega) \overset{J_1\left(\mathbb{R}^2\right)}{\longrightarrow} \left(\mathfrak U\,, \mathfrak Z\right)(\omega)\,$.
    \end{itemize}
    Since $\left(U^n\right)_{n \geq 1}$ and $\left(Z^n\right)_{n \geq 1}$ are both C-tight, $U$ and $Z$ are almost surely continuous, and therefore this is also the case for $\mathfrak U$ and $\mathfrak Z\,$.~Additionally, for any $n \geq 1\,$, $U^n$ is almost surely non-decreasing, nonnegative, and starts from $0\,$, so that these properties are also satisfied by $\mathfrak U^k$ for $k \geq 1\,$. Furthermore, $J_1$-convergence to a continuous function is equivalent to local uniform convergence, see \citet[Proposition~VI.1.17.b]{jacod2013limit}.~We deduce that $\mathfrak U$ is almost surely non-decreasing, nonnegative and starting from $0\,$. This is also the case for $U\,$, since $U \sim \mathfrak U\,$. The same reasoning shows that $Z$ almost surely starts from $0\,$. Additionally, we have,
    $$
    \mathfrak U^k_t(\omega) = G_0^k(t) + \int_{[0,t]}\, \left(b\, \mathfrak U^k_{t-s}(\omega) + c\, \mathfrak Z^k_{t-s}(\omega)\right)\, K^n(ds)\,, \quad t \leq T\,, \quad k \geq 1\,,
    $$
thanks to Lemma \ref{lemma:convolution_equation}, along with the càdlàg property for $\left(\mathfrak U^k(\omega)\,, \mathfrak Z^k(\omega)\right)_{k \geq 1}\,$, for any $\omega$ in $\mathcal A \in \mathcal F'$ of unit measure.~Therefore, taking $\left(F_k\right)_{k \geq 1} := \left(\mathfrak U^k(\omega) - G_0^k\right)_{k \geq 1}$\footnote{By the dominated convergence theorem, $G_0^k(t)$ converges to $G_0(t)$ for any $t \leq T\,$, and is dominated by $G_0(T)\,$. Thus, $G_0^k$ converges to $G_0$ in $L^1([0\,,T])\,$.} and $\left(f_k\right)_{k \geq 1} := \left(b\, \mathfrak U^k(\omega) + c\, \mathfrak Z^k(\omega)\right)_{k \geq 1}\,$, in Lemma \ref{leamm:stability_convolution}, since the $J_1$ topology is stronger than the $L^1$ topology \citep[Theorem~11.5.1]{whitt2002stochastic}, we obtain 
$$
\mathfrak U_t(\omega) = \int_0^t\, g_0(s)\,ds + \int_0^t\, K(t-s)\, \left(b\, \mathfrak U_s(\omega) + c\, \mathfrak Z_s(\omega) \right)\, ds\,, \quad t \leq T\,,
$$
for any $ \omega \in \mathcal A\,\cap\,\left\{\omega\,:\, \text{$\mathfrak U(\omega), \mathfrak Z(\omega)$ continuous} \right\}.$
Since $\left(U\,,Z\right) \sim \left(\mathfrak U\,, \mathfrak Z\right)\,$,
$$
U_t = \int_0^t \, g_0(s)\,ds + \int_{0}^t\, K(t-s)\, \left(b\,U_s + c\, Z_s\right)\, ds \,, \quad t \leq T\,,
$$
almost surely.


It remains to characterize the limiting process $Z\,$. For any $n \geq 1\,$, $Z^n$ is a martingale with respect to $\left(\mathcal F^n_t\right)_{t \leq T}\,$ generated by $U^n$ (see \eqref{eq:def_continuous_filtration}). Since for $i \leq n-1\,$, Algorithm \ref{alg:simulation} defines $\widehat Z^n_{i,i+1}$ as a linear combination of the $\left(\widehat U^n_{j,j+1}\right)_{j \leq i}\,$, in our case the filtration generated by $U^n$ coincides with the one generated by $\left(U^n\,, Z^n\right)\,$. Thus, $Z^n$ is also a martingale with respect to the latter filtration. According to \citet[Theorem~5.3]{whitt2007proofs}\footnote{The martingale property is proved for continuity points of the limit. Since our limits are almost surely continuous, it shows full martingality in our case.}, if we prove that $\left(Z^n_t\right)_{n \geq 1}$ is uniformly integrable for any $t \leq T\,$, then the weak limit $Z$ is a martingale with respect to the filtration generated by $\left(U,Z\right)\,$. Using \eqref{eq:bound_exp_Z_2}, we have
    $$
    \sup_n \,\sup_{0 \leq t \leq T}\, \mathbb{E}\left[ \left|Z^n_t\right|^2\right] \leq C_3\,G_0(T) < + \infty\,,
    $$
    which shows that $\left(Z^n_t\right)_{ t \leq T, n \geq 1}$ is uniformly integrable. Therefore $Z$ is a martingale with respect to the filtration generated by $\left(U\,, Z\right)\,$. Furthermore, 
    $$
    \mathbb{E}\left[\sup_{0 \leq t \leq T}\left|Z^n_t\right|^4\right] \leq C_5 \, \mathbb{E}\left[\left[Z^n\right]_T^2\right] \leq 25\, C_5\, \mathbb{E}\left[\left(U^n_T\right)^2\right]\,, \quad n \geq 1\,,
    $$
    using respectively the BDG inequality on $\left|Z^n\right|^4$ (see \eqref{eq:bdg_Z4})  and \eqref{eq:control_quad_Z}. Thus,
    $$
    \sup_n\, \sup_{0 \leq t \leq T}\,\mathbb{E}\left[ \left|\left(Z^n_t\right)^2 - U^n_t\right|^2\right] \leq 2\, \left(1 + 25\, C_5\right)\, \sup_n \,\mathbb{E}\left[\left(U^n_T\right)^2\right] < + \infty\,,
    $$
    thanks to \eqref{eq:bound_exp_U_2}. This proves that $\left(\left(Z^n_t\right)^2 - U^n_t\right)_{t \leq T, n \geq 1}$ is uniformly integrable, and since $\left(Z^n\right)^2 - U^n$ is a martingale for each $n \geq 1\,$, with respect to the filtration generated by $\left(U^n\,,Z^n\right)$ using the same reasoning, we deduce that $Z^2 - U$ is also a martingale with respect to the filtration generated by $\left(U\,,Z\right)$. This first proves that $Z$ is square-integrable, and by continuity and therefore predictablity of $U$, we deduce that 
    $$
    \langle Z \rangle_t = U_t \,, \quad t \leq T\,.
    $$
\end{proof}

We can now conclude with the proof of Theorem \ref{theorem:weak_convergence}.
\begin{proof}[Proof of Theorem \ref{theorem:weak_convergence}]
The result is direct from the joint tightness given by Remark \ref{remark:joint_tightness} and the characterization of the accumulation points of Lemma \ref{lemma:characterization_limit}.
\end{proof}

