\section{Inverse Gaussian and its sampling}\label{A:IG}

The Inverse Gaussian distribution, also known as the Wald distribution, is a continuous probability distribution on $\R_+$ with two parameters:    $ \mu > 0$ (mean parameter) and $\lambda > 0$ (shape parameter). The probability density function  of the Inverse Gaussian distribution is given by:
\[
f(x ; \mu, \lambda) = \sqrt{\frac{\lambda}{2\pi x^3}} \exp \left( -\frac{\lambda (x - \mu)^2}{2\mu^2 x} \right), \quad x > 0.
\]
We  denote  $X\sim IG(\mu, \lambda)$ to indicate that $X$ is a random variable with an inverse Gaussian distribution with mean parameter $\mu$ and shape parameter $\lambda$. Its characteristic function is given by 
\begin{align}\label{eq:IGchar}
\mathbb E \left [ \exp\left( wX\right) \right]= \exp\left(\frac{\lambda}{\mu} \left(1 - \sqrt{1 - \frac{2w\mu^2 }{\lambda}}\right)\right), 
\end{align}
for all $w\in \mathbb C$ such that  $\Re(w)\leq 0$.  In addition, it admits moments of any order, satisfying
\begin{equation}
\label{eq:IGmean}
    \mathbb{E}\left[X\right] = \mu\,, \quad \text{and} \quad \mathbb{E}\left[X^n\right] = (2n - 3)\, \frac{\mu^2}{\lambda}\,\mathbb{E}\left[X^{n-1}\right] + \mu^2\, \mathbb{E}\left[X^{n-2}\right]\,, \quad n \geq 2\,.
\end{equation}


Inverse Gaussian random variables can be simulated easily using one Gaussian random variable and one Uniform random variable using  an acceptance-rejection step as shown in \citet*{michael1976generating}, we recall the algorithm here.

\begin{algorithm}[H]
\caption{Sampling from the Inverse Gaussian Distribution}\label{alg:IG_sampling}
\begin{algorithmic}[1]
\State \textbf{Input:} Parameters \( \mu > 0 \), \( \lambda > 0 \).
\State \textbf{Output:} Sample \( IG \) from the Inverse Gaussian distribution.

\State   
Generate \( \xi \sim \mathcal{N}(0, 1) \) and compute \( Y = \xi^2 \).

\State Compute the candidate value \( X \):  
$$
X = \mu + \frac{\mu^2 Y}{2\lambda} - \frac{\mu}{2\lambda} \sqrt{4\mu\lambda Y + \mu^2 Y^2}.
$$

\State Generate a uniform random variable:  
Sample \( \eta \sim \text{Uniform}(0, 1) \).

\State Select the output:  
\If{$ \eta \leq \frac{\mu}{\mu + X} $}
    \State Set the output \( IG = X \).
\Else
    \State Set \( IG = \frac{\mu^2}{X} \).
\EndIf
\end{algorithmic}
\end{algorithm}





\section{Volterra Heston's characteristic function}\label{S:Heston}



We recall the expression of the joint characteristic function of the `integrated variance' $U$ and $\log S$ in the Volterra Heston model in \eqref{eq:HestonS} with $U$ given by \eqref{eq:U0}.  Let $v,w \in  \mathbb{C}$ be such that
\begin{equation}\label{eq:hestonchar}
    \Re w \leq 0 \quad \text{and}\quad  0 \leq \Re v\leq 1.
\end{equation}
The joint conditional characteristic function of $(\log S, U)$ is given by 
\begin{equation} \label{eq:hestonchar}
 \mathbb{E} \left[ \left. \exp\left(  v \log \frac{S_T}{ S_t} + w U_{t,T}\right) \right| \mathcal F_t \right] = \exp\left(  \int_t^T\!  \! F(\psi(T-s))dG_t(s) \right), \quad t \leq T,
\end{equation}
 where $G_t$ is given by \eqref{eq:Gs} and  $\psi$ is the solution of the following Riccati Volterra equation 
\begin{align}
	\psi(t)&=\int_0^t K(t-s)  F(\psi(s))ds, \quad t \geq 0, \label{eq:Ric1} \\
	F(u)&= w + \frac 12 (v^2 -v) +  (\rho c v  +b)u + \frac {c^2} 2 u^2,  \label{eq:Ric2}
	\end{align}
    and satisfies $      \Re \psi \leq 0. $  

We refer to \cite[Theorem 7.3]{abi2021weak} for the case of $L^1_{\rm loc}$ kernels, and \cite[Theorem 7.1]{abijaber2019affine}  for the equivalent formulations in the specific (and more standard) case of $L^2_{\rm loc}$ kernels. 




