\title{Structural Order Drives Diffusion in a Granular Packing}

\author{David Luce}
\affiliation{LEMTA, Université de Lorraine, CNRS, 2, Avenue de la Forêt de Haye, Vandœuvre-lès-Nancy, 54504, France} 
\affiliation{GRASP, Institute of Physics B5a, Université de Liège, 4000 Liège, Belgium}
