\begin{lemma} \label{i1i2i}
Let $g \in G$ be a semirational element of order $n$. Let 
$$\begin{array}{l}
I=\{m\ |\ 1 \leq m \leq n,\ (m,n)=1\}, \\
I_1=\{m \in I\ |\ g \sim g^m\}, \\
I_2=\{m \in I\ |\ g^{-1} \sim g^m\}.
\end{array}$$
We identify each integer with its reduction modulo $n$. Then $1 \in I_1$, $-1 \in I_2$ and $I_1 \cup I_2 = I$. If $h$ is a positive integer such that $e(g) > h+1$ then, for every $m_1,\ldots,m_h \in I_1$ such that $m_1+\ldots+m_h \in I$, we have $m_1+\ldots+m_h \in I_1$.
\end{lemma}
\begin{proof}
Assume $m_1,\ldots,m_h \in I_1$ satisfy $m_1+\ldots+m_h \in I \setminus I_1$. By assumption $m_1+\ldots+m_h \in I_2$ so $m=-m_1-\ldots-m_h \in I_1$ and $g^{m_1} \cdots g^{m_h} g^m = 1$. Since $m_1,\ldots,m_h,m \in I_1$, this implies $e(g) \leq h+1$, a contradiction.
\end{proof}

\begin{prop} \label{semir1}
Let $g \in G$ be a semirational element of order $n$. Write $n=\prod_{i=1}^k p_i^{a_i}$ with the $p_i$ pairwise distinct primes. If $p_i \geq k+2$ for all $i=1,\ldots,k$, then $e(g) \leq 3$.
\end{prop}

So for example if $n=5^a 7^b 11^c$ then $e(g) \leq 3$.
\begin{proof}
Assume by contradiction that $e(g) > 3$. We use the notation of Lemma \ref{i1i2i} and, in particular, we identify each integer in $I$ with its reduction modulo $n$. If $I_1=I$ then $e(g) \leq 2$, so we may assume that $I_1 \neq I$. Since $p_i \geq k+2$ for all $i$, we have $1,2,\ldots,k+1 \in I$. By Lemma \ref{i1i2i} we may assume that, whenever $a,b \in I_1$ are such that $a+b \in I$, we have $a+b \in I_1$. So, since $1 \in I_1$ and $1,2,\ldots,k+1 \in I$, we have $2=1+1 \in I_1$, $3=2+1 \in I_1$ and so on until $k+1$, so $1,\ldots,k+1 \in I_1$. If $m \in \mathbb{N}$ then $I \cap \{m+1,\ldots,m+k+1\} \neq \varnothing$. Indeed, if by contradiction this is false, then for all $i=1,\ldots,k+1$ there exists a prime $p_{j_i} \in \{p_1,\ldots,p_k\}$ which divides $m+i$. Clearly, there exist two distinct $i_1,i_2 \in \{1,\ldots,k+1\}$ such that $p_{j_1}=p_{j_2}$, in other words there exists a prime $p$ dividing $n$ and dividing $m+i_1$, $m+i_2$ for some $i_1,i_2$, so $p$ divides $i_1-i_2$. This is impossible because $|i_1-i_2| \leq k$ and $p > k$. Therefore there exists $f(m) \in \{1,\ldots,k+1\} \subseteq I_1$ such that $m+i \not \in I$ for all $i$ with $0 < i < f(m)$ and $m+f(m) \in I$. Define a sequence $(\ell_k)_{k \geq 1}$ by $\ell_1:=1$ and $\ell_{k+1} := \ell_k+f(\ell_k)$. Since $1 \in I_1$, we have $\ell_k \in I_1$ for all $k \geq 1$ by Lemma \ref{i1i2i}, on the other hand it is clear that $\{\ell_k\ |\ k \geq 1\} = I$ so $I_1=I$, a contradiction.
\end{proof}

For a positive integer $n$, set $j(n)$ to be $\max_{m \in \mathbb{N}} (a_{m+1}-a_m)$ where $(a_m)_m$ is the increasing sequence of positive integers coprime to $n$. In other words, $j(n)$ is the maximal distance between ``two consecutive numbers coprime to $n$'', where $a,b$ are called ``consecutive coprime (to $n$)'' if they are coprime to $n$ and no integer $m$ such that $a<m<b$ is coprime to $n$. Note that $j(n) \in \mathbb{N}$ because it can be calculated working modulo $n$. For example, if $n$ is a prime power, then $j(n)=2$. Observe that, if $n=\prod_{i=1}^k p_i^{a_i}$ where each $p_i$ is a prime number, then $j(n)=j(p_1 \ldots p_k)$.

Note that $j(n)$ equals the smallest positive integer $m$ such that every sequence of $m$ consecutive positive integers contains an integer coprime to $n$. The function $j$ is called the \textit{Jacobsthal function} and there is literature about it. The Jacobsthal function of primorial numbers $h(n)$ is defined as $j(p_1 \ldots p_n)$ where $p_1,p_2,\ldots$ are all the prime numbers in increasing order. Since $h(n) \geq p_n$, the Jacobsthal function is unbounded.
%The first few values of $h(n)$ are $h(1)=2$, $h(2)=4$, $h(3)=6$, $h(4)=10$, $h(5)=14$, $h(6)=22$.

\begin{prop} \label{semir2}
Let $g \in G$ be a semirational element of order $n$. Then $e(g) \leq j(n)+2$.
\end{prop}
For example, if $n=3^a 5^b$, then $e(g) \leq j(n)+2=5$.
\begin{proof}
We use Lemma \ref{i1i2i} and the notation therein. We may assume that $I_1 \neq I$ (otherwise $e(g) \leq 2$) and that the conclusion of the lemma holds for $h=j(n)+1$. Let $x,y \in I$, with $x \in I_1$, and assume that $x,y$ are ``consecutive'' in $I$, meaning that $x<y$ and no integer strictly between $x$ and $y$ belongs to $I$. If we show that $y \in I_1$ we are done, because iterating this argument (starting from $x=1$) leads to $I_1=I$, a contradiction. We have $y-x \leq j(n)$ by definition of $j(n)$. Since $1 \in I_1$, Lemma \ref{i1i2i} implies that $y=x+(y-x) = x+1+\ldots+1 \in I_1$ since the number of summands on the right-hand side is at most $j(n)+1$.
\end{proof}

\begin{corol} \label{cor881}
Let $g \in G$ be a semirational element of order $n$. If $n$ is an odd prime power, then $e(g) \leq 3$. If $n$ is a power of $2$, then $e(g) \leq 4$.
\end{corol}
\begin{proof}
If $n$ is an odd prime power, we apply Proposition \ref{semir1} with $k=1$. If $n$ is a power of $2$, then Proposition \ref{semir2} implies that $e(g) \leq j(n)+2 = 4$.
\end{proof}

\section{Sporadic groups}

For sporadic simple groups we use the notation of \cite{at}.

\begin{theor} \label{sporadicthm}
Let $G$ be a sporadic simple  group. If $G \in \{J_1,J_2\}$ then $e(G)=2$. Otherwise, $e(G)=3$.
\end{theor}

\begin{proof}
By \cite{TZ05}, the only simple sporadic groups in which all elements are real are $J_1$ and $J_2$. Therefore, it is enough to prove that $e(G) \leq 3$ for every sporadic simple  group $G$. %Let $G$ be a simple sporadic group. 
If $g \in G$ is a product of two elements $x,y$ of order $3$ then
$$g \cdot g^x \cdot g^{x^2} = xy \cdot yx \cdot x^{-1}yx^2 = xy^3x^2 = 1.$$
By a result by Malcolm \cite[Theorem 4.1]{Malcolm21}, every element of $G$ is a product of at most $2$ elements of order $3$ unless $G$ is in the list $HS,Co_2,Co_3,Fi_{22},Fi_{23},BM$. So we may assume that $G$ is in this list. The same theorem of Malcolm implies that, if $G \not \in \{HS,Co_2,Fi_{22}\}$, then the elements that are not products of two elements of order $3$ have order $2$, so they are real, hence we may assume that $G\in\{HS$, $Co_2$, $Fi_{22}\}$. By \cite{at}, the orders of the non-real elements of these groups are $11,20$ for $HS$,   $14$, $15$, $23$, $30$ for $Co_2$ and  $11$, $16$, $18$, $22$ for $Fi_{22}$. It follows that all the ``width-three classes'' in \cite[Table 1]{Malcolm21} are real, so the result follows.
\end{proof}

