\subsection{Groups $\PSU_4(q)$}

\begin{lemma}\label{rr2} Let $G=\PGL_2(q)$ or $\PU_2(q)$. Then every semisimple element of $G$ is real. \end{lemma}

\begin{proof} 
Note that the groups $\PGL_2(q)$ and $\PU_2(q)$ are isomorphic (see \cite[Lemma 4.9]{DZ8}). So it suffices to deal with $\PGL_2(q)$. Let $H=\GL_2(q)$ and let $g\in H$. Let $V$ be the underlying space for $H$. Suppose first that $g$ is reducible on $V$. Then, under some basis of $V$, we can express $g=\diag(a,b)$. 
Then  $g'=\diag(b,a)$ is conjugate to $g$  and $gg'$ is scalar. Whence the result in this case.

Suppose that $g$ is irreducible.  Then the centralizer of $g$ in ${\rm Mat}_2(q)$ is a field
by Schur's lemma,  which is isomorphic to $\mathbb{F}_{q^2}$. The nontrivial Galois automorphism $\gamma$ of $\mathbb{F}_{q^2}/\mathbb{F}_q$ sends $x\in \mathbb{F}_{q^2}$ to $x^q$. By the Skolem-Noether theorem, $\gamma$ is realized via an inner 
automorphism of $\GL_2(q)$, and hence $g^q = hgh^{-1}$ for some   $h \in \GL_2(q)$.
Then $gg^q\in \mathbb{F}_q$ is scalar in $\GL_2(q)$. So again $g$ is real in $\PGL_2(q)$.
\end{proof} 

Remark. For $H \in \{ \GL_2(q), \U_2(q)\}$   the matrix $h\in H$ such that $ghgh^{-1}$ is scalar can be chosen in 
$\SL_2(q)$, $\SU_2(q)$, respectively. This is because $h$ can be replaced by $ht$, where $t\in C_G(g)$ with $\det t=\det x^{-1}$.

\begin{obs} \label{centsem}
In general, the centralizer of a semisimple element $s\in X=\GL_n(q)=\GL(V)$ is described as follows. Let $V=\bigoplus_{i=1}^k V_i$, where the $V_i$'s are homogeneous $\mathbb{F}_q\langle s\rangle$-modules, and let $s_i$ be the projection of $s$ into $X_i = \GL(V_i)$. Then $C_X(s) V_i = V_i$ for all $i$ and $C_X(s)$ is the direct product $\prod_{i=1}^k C_{X_i}(s_i)$. Let $m_i$ be the common dimension of the irreducible constituents of $s$ on $V_i$. Then $C_{X_i}(s_i) \cong \GL_{n_i/m_i}(q^{m_i})$, where $n_i = \dim V_i$. See \cite[Lemma 3.2]{TZ04}.
\end{obs}

\begin{lemma}\label{6ps} Let $ G=\PSU_4(q)$, q odd,  and let $s\in G$ be a semisimple element. Then $e(s)\leq 4$. In addition, $e(G)\leq 6$ and $e(\PSU_4(2))=e(\PSU_4(3))= 3$.
\end{lemma}

\begin{proof} The result for $\PSU_4(3)$ and $\PSU_4(3)$ follows by \cite{gap}. Now we prove the first part. By Lemma \ref{un2},  $e(g)\leq 4$ if $g\in G$ is semisimple, and $e(g)\leq 3$ if $g$ is unipotent (Lemma  \ref{u26}).   
 Let $H=\SU_4(q)=\SU(V)$, let $h\in H$ be such that $g=hZ(H)$ and $h=su$,
where $s\neq 1$ is semisimple, $u\neq 1$ is unipotent and $su=us $. Let $C$ be the conjugacy class of $h$ in $H$.

  Let $J$ be the Jordan form of $u$ in $\GL_4(q^2)$. Then $J\in\{J_4,\diag(J_3,1),\diag(J_2,J_2)\}$. In the former case $su=us$ implies $s$ is scalar, so $e(g)\leq 3$. In the following discussion we use Observation \ref{centsem}.

If $J=\diag(J_3,1)$ then $h=\diag(\mu\cdot J_3,\mu^{-3})$.
In the notation of \cite{Si} (see also \cite{Ge, Or}), $J_3\in \PSU_3(q)$ belongs to one of  $d=(3,q+1)$ conjugacy classes 
$C_3^{(0,k)}$, where $0 \leq k < d$ (which glue in $\PU_3(q)$).
So, let $D$ be any of these classes,  and let $D'$ be the conjugacy
class of $C_8^{(1)}$. Then, $D'$ consists of elements of order
$(q^2-q+1)/d$. Using the character table of $\PSU_3(q)$, one concludes that $D'\subset D^2$. So there  exists $x \in \PSU_3(q)$ such that
the product $t:=J_3\cdot xJ_3x^{-1}$ has order $(q^2- q +1)/d$. It follows that $C^2$ 
contains an element $y=\diag(\mu^2t,\mu^{-6})$. As $t$ is irreducible in $\U_3(q)$, $t$ does not  have an eigenvalue in $\mathbb{F}_{q^2}$, and hence $y$ is regular semisimple.  
By Lemma \ref{Gow}, some product of $3$ conjugates of $y$ is scalar. So $e(g)\leq 6$. 


Assume now that $J=\diag(J_2,J_2)$. 
Then $W=(\Id-u)V$ is a totally isotropic space of dimension 2. Let $s_1\in \GL_2(q^2)$
be the restriction of $s$ on $W$. Then  the action of $s$ on $V/W$ is $s_2:={}^t\gamma(s^{-1}_1)$, where $\gamma$ is the nontrivial Galois automorphism 
of $\mathbb{F}_{q^2}/\mathbb{F}_{q}$ extended to $\GL_2(q^2)$  (see for instance \cite[Lemma 4.8]{ez1}).
 By Lemma \ref{rr2}, the product of two conjugates of $s_1$ by an element of $\SL_2(q^2)$ is scalar in $\GL_2(q^2)$. So the  product $h_1$, say, of  two conjugates of $h$ by some element of $H$ is a matrix product of a matrix $t:=\diag(\mu \cdot \Id_2,\mu^{-q} \cdot \Id_2)$ and  a unipotent matrix $u'$ of the form   $\begin{pmatrix} \Id_2&A\\ 0& \Id_2\end{pmatrix}$, where $A$ is a $(2\times 2)$-matrix over  $\mathbb{F}_{q^2}$. Moreover,
$t\in \langle h_1\rangle$ and hence $u':=t^{-1}h$ is unipotent and $u't=tu'$. Then either
 $u'=1$ or $t$ is scalar. In the latter case $e(g)\leq 3$. As $\diag(\mu^{-q} \cdot \Id_2,\mu \cdot \Id_2)$ is conjugate to $t$ by a matrix $\begin{pmatrix}0&\Id_2\\ \Id_2&0 \end{pmatrix}$, we have $e(g)\leq 4$.
\end{proof}


\subsection{Groups $\PSp_4(q)$, $q \equiv 3 \pmod 4$}

\begin{lemma} \label{s33}
Let $H=\SL_2(q)$ with $q$ odd. If $u \in H$ is a nontrivial unipotent element, there exist three conjugates of $u$ in $H$ whose product is $-1$.
\end{lemma}

\begin{proof}
Note that $H$ has two conjugacy classes of nontrivial unipotent elements which glue in $\GL_2(q)$, so that a suitable element of $\GL_2(q)$ swaps the two $H$-classes of unipotent elements (see \cite[Lemma 5.2]{TZ04} for a more general fact). So it is enough to prove the result for one of the two classes. Consider the following elements of $H$. 
$$g_1=\begin{pmatrix}0&1\\ -1&2\end{pmatrix}, \hspace{.1cm}
g_2=\begin{pmatrix}2&1\\ -1&0\end{pmatrix}, \hspace{.1cm}
g_3=\begin{pmatrix}1&0\\ -4&1\end{pmatrix}, \hspace{.1cm}
h=\begin{pmatrix} 0 & 1 \\ -1 & 0 \end{pmatrix}, \hspace{.1cm}
k=\begin{pmatrix} 2 & 1/2 \\ 0 & 1/2 \end{pmatrix}.$$
The characteristic polynomial of $g_1,g_2,g_3$ is $(x-1)^2$, so they are unipotent and $g_1 g_2 g_3=-1$. Moreover $h^{-1}g_1h=g_2$ and $k^{-1}g_1k=g_3$.
\end{proof}

\begin{prop}\label{s4q} Let $G=\PSp_4(q)$. % $q>3$, $q \equiv 3 \pmod 4$. 
Then $e(G)= 3$.\end{prop}

\begin{proof}  The case with $q=3$ follows by GAP \cite{gap}. Note that the semisimple elements of $G$ are real, and some unipotent elements of $G$ are not real, so $e(G)\geq 3$. 

Set  $H = \Sp(4,q) = \Sp(V)$,  $h\in H$ and $g$ the projection of $h$ in $G$. If $h$ is unipotent then $e(h)\leq 3$ by Corollary \ref{cor881}, as $\Phi(h)$ lies in two conjugacy classes of $H$ by \cite[Theorem 1.5]{TZ05}.
If $h$ is semisimple then $h$ is real so $e(h)=2$. Let $h=su$, $s,u\neq 1$, $su=us$, $s$ semisimple and $u$ unipotent. If $s\in Z(H)$ then $g$ is unipotent in $G$. So we assume that $s\notin Z(H)$, $u\neq 1$.

Suppose first that $s$  has an eigenvalue $\lambda\in\{ 1,-1\}$, and let $V_1$ be the $\lambda$-eigenspace of $s$ on $V$. It is well known that $V_1$ is non-degenerate, and hence $\dim V_1=2$ and $V=V_1\oplus V_1^\perp$. By replacing $s$ by $-s$ we can assume that $\lambda=1$. As $us=su$, we have $uV_i=V_i$ for $i=1,2$. Then we can write $u=\diag(u_1,u_2)$, where $u_i\in \Sp_2(q)$ is the restriction of $u$ to $V_i$. In addition, $s=\diag(\Id_2,s_2)$, where $s_i\in \Sp_2(q)$ is the restriction of $s$ to $V_2$, and $s_2\neq \Id_2$ (as $s\notin Z(G)$).

Let $X$ be the stabilizer of $V_1$ in $H$. Then $X=X_1X_2$, where $X_1=\diag(\SL_2(q), \Id_2)$ and $X_2=\diag(\Id_2, \SL_2(q))$.

(i) Suppose that $u_1=1$. Then $u_2\neq 1, s_2=-\Id_2$. By Lemma \ref{s33},
there are 3 conjugates of $u_2$ in $\Sp_2(q)$ whose product is $-\Id$. Then the  product of
respective conjugates of $s_2u_2$ is $s_2^3 \cdot (-\Id)=\Id$, so $e(g)=3$. 

(ii) Suppose $u_1\neq 1$, $u_2= 1$. If $s_2=-\Id$ then we  replace $h$ by $-h$
and argue as in (i) to get $e(g)=3$. So we assume $s_2\neq -\Id$, 
and then $s_2$ is regular semisimple in $\SL_2(q)$. As $q>3$, the group $\PSL_2(q)$ is simple; by Lemma \ref{Gow}, %if $q\neq 3$
 there are 3 conjugates of $s_2$ whose product equals $ \Id$ or $-\Id$.
In the latter case, as $u_1\neq 1$, there are 3 conjugates of $u_1$ in $\SL_2(q)$
whose product equals $-\Id$ (Lemma \ref{s33}). So $e(g)=3$ in this case.
%If $q=3$ then $|s_2|=4$
In the former case, as $q$ is odd, $\Phi(u_1)$ lies in at most two conjugacy classes of $\SL_2(q)$ (see \cite[Theorem 1.5]{TZ04}). Then the proof of Corollary \ref{cor881} shows that  $\langle u_1 \rangle$ contains 3 conjugates of $u_1$   whose product equals 1.  This again implies $e(g)\leq 3$. 

(iii) Suppose that  $u_1,u_2\neq 1$. Then $s_2=-\Id$. As $\SL_2(q)$ has two conjugacy classes of unipotent elements (and they are not real), we can assume that $u_2\in\{u_1,u_2^{-1}\}$, so
%$u_1,u_1^{-1}$ are not conjugate in  $\Sp_2(q)$, we conclude that $u_2$ is conjugate to $u_1$ or $u_1^{-1}$, so 
we can assume that  $h=\diag(u_1,-u_1)$ or $\diag(u_1,-u_1^{-1})$. Let 
$y=\begin{pmatrix}0&\Id\\
-\Id&0\end{pmatrix}$. 
Then $y\in H$ and $h_2:=yhy^{-1}=\diag(-u_1,u_1)$ or $\diag(-u_1^{-1}, u_1)$, respectively.  
%Then $g$ is conjugate to $g_2=(-u_1,u_1)$ and $(-u_1\up,u_1)$, resp. 
In the second case $hyhy^{-1}=-\Id$, so $e(g)=2$.

So $h=\diag(u_1,-u_1)\subset X_1X_2$. We have seen above that there are 3 conjugates of 
$u_1$ in $X_1\cong \SL_2(q)$ whose product is $\Id$, and there are three conjugates of 
$-u_1$ in $X_2\cong \SL_2(q)$ whose product is $\Id$. So $e(g)=3$. 



Next suppose that $s$ does not have eigenvalue 1 or $-1$. Let $S= \langle s \rangle$.  
If the irreducible  constituents of $V|_S$ are pairwise non-equivalent then $s$ is regular. It follows that either all these have dimension $1$ or they all have dimension $2$. Indeed, suppose the contrary; then one of them is of dimension $2$ and the others are of dimension $1$. So $s$ has eigenvalue $\lambda \in {\mathbb F}_q$. As $\lambda \neq \pm 1$ and $s$ is real,  $s$ has eigenvalue $\lambda^{-1}\neq \lambda$, and hence all three irreducible constituents of $V|_S$ are paiwise non-equivalent, a contradiction. 

So we have two cases:
(a) $V|_S$ is a sum of two equivalent irreducible constituents of dimension 2 and 
(b) $s$ has  two distinct eigenvalues $\lambda,\lambda^{-1}\in \mathbb{F}_q$, each of multiplicity $2$.

(a) In this case  $u\in C_{G}(s)\cong \U_2(q)$ (see for instance \cite[Lemma 6.6]{ez1}).  As the non-trivial unipotent elements in $\U_2(q)$ are conjugate \cite[Lemma 6.1]{TZ04}, and $s$ is real, we conclude that $g$ is real, hence $e(g)=2$ in this case. 

 (b) $V=W_1+W_2$, where $W_1,W_2$
is the  $\lambda$- and $\lambda^{-1}$-eigenspace of $s$ on $V$, respectively.   As $\lambda\neq \pm 1$, each of them is totally isotropic. 
Let $Y=\{x \in H: xW_i=W_i$ for $i=1,2\}$.
It is well known that $Y\cong \GL_2(q)$ (see, for instance, \cite[Lemma 4.8]{ez1} for a more general fact).  Since $us=su$, the eigenspaces of $s$ are $u$-stable, therefore $u\in Y$. As all  
non-trivial unipotent elements in $\GL_2(q)$ are conjugate,
and $s$ is real, we conclude that $g$ is real, hence $e(h)=2$ in this case.\end{proof}

\section{Classical groups}

\subsection{Symplectic groups} 



The following result follows from Theorem \ref{un4} and Lemma \ref{ee7}.


\begin{theor} \label{symplectic}
Let $G=\PSp(n,q)$ be a simple symplectic group, with $n$ even. If $q \equiv 3 \mod 4$ then $e(G) \leq 6$. If $q \not \equiv 3 \mod 4$, then $e(G)=2$.
\end{theor}

\subsection{Orthogonal groups}

\begin{lemma} \label{isomodules}
Let $G = \langle s \rangle$ be a finite cyclic group and let $\phi,\tau$ be two finite dimensional irreducible representations of $G$ over a finite field $F$. If the matrices $\phi(s)$, $\tau(s)$ have an eigenvalue in common, then $\phi$ and $\tau$ are equivalent, i.e. the corresponding $F[G]$-modules are isomorphic.
\end{lemma}

\begin{proof}
Let $F_1$ be the field $F(\zeta)$ where $\zeta$ is a primitive $|G|$-root of unity. Then, over $F_1$, $\phi$ is a direct sum of absolutely irreducible constituents that are obtained from each other by Galois conjugations by elements of $\mathcal{G}(F_1/F)$. We can say that they form a Galois group orbit. See \cite[Theorem 19.4(ii)]{Feit}. The same is true for $\tau$, so the orbits either coincide or are disjoint.

Note that two absolutely irreducible representations $\mu$, $\nu$ of a cyclic group $\langle s \rangle$ are the same if and only if $\mu(s)=\nu(s)$. Since $\phi(s)$, $\tau(s)$ have an eigenvalue in common, and this eigenvalue belongs to $F_1$, they share a $1$-dimensional component, so the orbits are the same. It follows that $\phi$ and $\tau$ have the same irreducible constituents over $F_1$, so $\phi(s)$, $\tau(s)$ have the same list of eigenvalues up to ordering.
So $\phi$ and $\tau$ are equivalent over $F_1$. So $\tau(s) = g \phi(s) g^{-1}$ for some $g \in \GL_m(F_1)$, where $m = \dim(W_1)$. In terms of matrix entries, the equation $g\phi(s) = \tau(s)g$ can be viewed as a homogeneous system of linear equations with indeterminates $g_{ij}$, $1 \leq i,j \leq m$ and coefficients in $F$. Then this system has a non-zero solution over $F$, so there is a matrix $h$ over $F$ such that $h\phi(s) = \tau(s)h$. Note that $\det(h) \neq 0$. Indeed, otherwise $hW_1=Y\neq W_1$ and hence $\tau(s)Y<\tau(s) h W_1 = h\phi(s)W_1 < hW_1=Y$, which is false as $\tau$ is irreducible.
\end{proof}


\begin{lemma}\label{au8} Let $u$ be a unipotent element in $H=O^\pm _{2d}(q)=O(V)$ with $q$ even, $d$ odd. Then $C_H(u)$ is not a subgroup of $\Omega^\pm _{2d}(q)$.
\end{lemma}

\begin{proof} By \cite[Lemma 4.9]{TZ04}, there exists an orthogonal decomposition $V=V_1 \oplus \ldots \oplus V_f$, such that each $V_i$ is nondegenerate, $uV_i=V_i$ for all $i$ and the Jordan block sizes of $u$ on $V_i$ are the same and distinct on $V_i,V_j$ for $i\neq j$, $i,j\in \{1,\ldots,f\}$. Let $u_i$ be the resriction of $u$ on $V_i$. It suffices to observe that $C_{O(V_i)}(u_i)$ is not contained in $\Omega (V_i)$ for some $i$. As $q$ is even, $\dim V_i$ is even for every $i$  by \cite[Proposition 2.5.1]{KL}, so  $\dim V_i\equiv 2\pmod 4$ for some $i  $. It suffices to show that $C_{O(V_i)}(u_i)$ is not contained in $\Omega (V_i)$. To this end,   Let $a,m$ be such that   the Jordan blocks of $u_i$ consists of $a$ blocks of the same size $m$.

If $a$ is odd then then $u_i\notin \Omega (V_i)$ by  \cite[p.182]{C}. Suppose that $a$ is even. Then $m$ is odd and $u_i\in \Omega (V_i)$.  

We use \cite{LiS}. As  $m$ is odd, $u$ is of type $W(m)^{a/2}$ in the notation of \cite[p.117, Theorem 7.3(iii)]{LiS}. In this case $\Omega(V_i)\cong \Omega^+_{am}(q)$ and there is a single conjugacy class of elements of type $W(m)^{a/2}$ in  $\Omega (V_i)$. Therefore, it suffices to observe the following. Let $M$ be a maximal totally singular
subspace of $V_i$; then $V_i = M \oplus M'$, where $M'$  is a maximal totally singular
subspace of $V_i$ too. There is a basis $B$, say, of $V_i$ such that $B\cap M$,
$B\cap M'$ are bases of $M,M'$, respectively, and the Gram matrix of $B$ is 
$\begin{pmatrix}0&\Id_k\\ \Id_k&0\end{pmatrix}$
with $k=\dim M$. Let $u_i'=\diag(A,{}^t A^{-1})$, where $A\in \GL(M)$ is such that the Jordan forms of $u_i,u_i'$ coincide. Then $u_i'\in \Omega(V_i)$ is of type  $W(m)^{a/2}$. As there is a single conjugacy class of elements of this type in $\Omega(V_i)$, we can assume that $u_i=u'_i$. To show that 
$C_{O(V_i)}(u_i)$ contains an element  in $ O(V_i)\setminus \Omega(V_i)$, observe that 
if  $y=\begin{pmatrix}0&\Id_{k}\\ \Id_{k}&0\end{pmatrix}$
then $yu_iy^{-1}=\diag({}^tA^{-1},A)$. As $A$ and ${}^tA^{-1}$ have the same Jordan form, we have $xAx^{-1}={}^tA^{-1}$ for some $x\in \GL_{ k}(q)$, and $zyu_iy^{-1}z^{-1}=u_i $ for $z=\diag(x,{}^tx^{-1})\in \Omega(V_i)$. Note that $y$ is the product of $k$ reflections. As the spinor norm of a reflection is not equal to 1, so is the spinor norm of $y$ as $k$ is odd.
\end{proof}

In the following proof we will use the fact that, if $g \in O(V)$ is semisimple and $W=\{v \in V\ |\ gv=v\}$, then $W$ is nondegenerate. To see this, set $X := W \cap W^{\perp}$. Then $X$, and hence $X^{\perp}$, is $g$-stable. Since $g$ is semisimple, $V=X^{\perp} \oplus Y$ for some $g$-stable subspace $Y$ of $V$. If $y \in Y$, $x \in X$ then $(gy-y,x) = (gy,x)-(y,x) = (gy,gx)-(y,x) = 0$, so $gy-y \in X^{\perp} \cap Y = \{0\}$. This means that $g$ acts trivially on $Y$, in other words $Y \leq W$. Since $W \leq X^{\perp}$, we deduce $Y=\{0\}$. This implies $X^{\perp}=V$, so $X=\{0\}$.

\begin{theor}\label{orth4}
Let $G=\Omega_n(q)$ for $n$ odd, or $\Omega^{\pm}_n(q)$ for $n>2$ even, and let 
$g\in G$. Then $e(g) \leq 4$, unless possibly $G=\Omega^{-}_n(q)$,  $n/2$ odd, $q$ even, $g$ is indecomposable and the composition factors of g on $V$ are isomorphic $\mathbb{F}_q\langle g\rangle$-modules of dimension $2$. In the exceptional case $e(G)\leq 8$. \end{theor}

\begin{proof} Assume $q$ is odd. Let $g \in G$. If $g=xy$ with $x,y$ involutions, then $g \cdot g^x = 1$, so $e(g) \leq 2$. If $g=xyz$ with $x,y,z$ involutions, then $g \cdot g^z \cdot g^x \cdot g^{zx} = 1$, so $e(g) \leq 4$. \cite[Theorem 8.5]{kt1} implies that every element of $G$ is a product of at most $3$ involutions, so $e(G) \leq 4$, unless possibly for $(n,q) \in \{(3,3),(4,3),(5,3)\}$. These three cases can be checked with \cite{gap}.

Assume that $q$ is even. Then $Z(G)=1$ and $G$ is a subgroup of index 2 in $O(V)$. If $n \geq 3$ is odd, then $\Omega_{n}(q) \cong \PSp_{n-1}(q)$ and the result follows from Theorem \ref{symplectic}. Now assume that $n$ is even. If $4|n$ then $e(G)=2$ by Theorem \ref{un4}, items (3),(4).

Assume that $q$ is even, $n \equiv 2 \mod 4$ (in particular $n\geq 6)$. Let  $G=\Omega^{\pm}_{n}(q)$ and let $V$ be the underlying orthogonal space for $G$.  Let $g=su\in G$,   where $u$ is unipotent, $s$ is semisimple and $su=us$. 

(i) Suppose that  $gW=W$, where $W$ is a non-degenerate subspace such that $g$ acts trivially on $W^\perp$. Then $g$ is real. 

Indeed, $W^\perp$ contains a non-degenerate subspace $W_1$, say, of dimension 2.
Then $4|\dim W_1^\perp$, and every element of $O(W_1^\perp)$ is real by  \cite{Gw}.
For every   $x\in O( W_1^\perp)$ there exists $x'\in G$ such that $x'$ stabilizes $W_1^\perp$ and acts on it as $x$.  Whence the claim.    

(ii) Suppose that $V=V_1\oplus    V_2$, where $V_1, V_2$ are non-zero
 non-degenerate subspaces of $V$ and $gV_i=V_i$ for $i=1,2$. (Sometimes one says that $g$ is orthogonally decomposable.) Then $e(g)\leq 4$.

By reordering $V_1, V_2$ we can assume that $4|\dim V_2$. 
Let $g_1,g_2$ be the restrictions of $g$ to $V_1, V_2$, respectively. By \cite{Gw}, $xg_2x^{-1}=g_2^{-1}$ for some $x\in O(V_2)$. Let $y\in G$ be such that $yV_i=V_i$ for $i=1,2$ and $y$ coincides with $x$ on $V_2$. Then $gygy^{-1}=\diag(g_1',\Id)$. By (i), this element is real, and hence $e(g)\leq 4$.

(iii) Suppose that $g$ is irreducible on $V$. Then $e(g)\leq 3$. In addition, there are 2  conjugates of $g$ whose product is a real and hence the product of some 4   conjugates of $g$  equals 1.

Note that $G$ is simple for $n>2$ even. So the former claim follows from Lemma \ref{Gow} as $g$ is regular semisimple in this case. Moreover, by \cite{Gow} every semisimple element $t\in G$ is a product of two conjugates of $g$. We can choose $t$ real. Indeed,
let $W$ be a non-degenerate subspace of $V$ of dimension 4.  
Then every element of $\Omega(W)$ is real (by the above), so we can choose 
for $t$ any semisimple element of $G$ acting  trivially on $W^\perp$. Whence the second claim.    

(iv) $e(g)\leq 4$ unless $s$ is homogeneous on $ V$. 

To prove this, suppose the contrary. Let $V_1,\ldots, V_k$ be the homogeneous components of $s$ on $V$, where $k>1$. Each homogeneous component is a largest direct sum of isomorphic $\mathbb{F}_q \langle s \rangle$-submodules. As $gs=sg$, we have $gV_i=V_i$ for $i=1,\ldots,k$.  By \cite[Lemma 3.3]{SZ02},  $V_1$ is either non-degenerate or totally singular. In the former case $e(g)\leq 4$ by (ii).

Suppose that $V_1$ is totally singular. Then there is $j\in\{1,\ldots,k\}$ such that $V_j$ is totally singular and  $V_1+V_j$ is non-degenerate.  By (i) we conclude that either $e(g)\leq 4$ or $k= 2$.  

We show that $e(g)\leq 4$ if $k=2$. In this case let $H$ be the stabilizer of $V_1,V_2$ in $G$, so $g\in H$. Then $H\cong \GL_{n/2}(q)$. In fact, there is a basis in $V$ such that 
the matrix   of $h$ on $V_2$ is the inverse-transpose of that on $V_1$ which yields 
an isomorphism  $\GL_{n/2}(q)\rightarrow H$. Note that the image is contained in $G$
as $|O(V):G|=2$ whereas the index  $|H:H'|$ is odd  for $n/2>2$. The latter holds as $n\geq 6$.

We show that $g$ is indecomposable as an element of $X:=\GL_{n/2}(q)$. Indeed, let $V_1=W_1+W_2$, where $gW_i=W_i\neq 0$ for $i=1,2$. It is well known that there exists a ``Witt basis'' $b_1,\ldots,b_n$ of $V$ with respect of $W_1$, which means that $b_1,\ldots,b_k$
is a basis of $W_1$ for $k=\dim W_1$, $b_{k+1},\ldots,b_{n-k} \in W_1^\perp$, and if 
$M$ is the matrix of the action of $g$ on $b_1,\ldots,b_k$ then $W_3 = \langle b_{n-k+1},\ldots,b_n \rangle$ is $g$-stable and the matrix of the action of $g$ on this basis of $W_3$ is  
${}^tM^{-1}$. Moreover, the subspace $W_1+W_3$ is non-degenerate (as so is $V$). 
So $V=W_1+W_3+(W_1+W_3)^\perp$ so $e(g)\leq 4$ by (ii).

So we assume that $g$ is indecomposable as an element of $\GL_{n/2}(q)$. Let $h,t,v\in X$ be the elements of $X$ that are images of $g,s,u$ under the isomorphism $X\rightarrow H$. Recall that $u\neq 1$. By Lemma \ref{in3}, $h$ is contained in a subgroup $X_1\circ X_2$,
 where $X_1\cong \GL_k(q)$, $X_2\cong \GL_l(q)$, $kl=n/2$, $[X_1,X_2]=1$ and $t\in X_1$ is irreducible as an element of $\GL_k(q)$, $v\in X_2$ is a Jordan block of size $l$ in $\GL_l(q)$. Here $X_1\circ X_2$ means the central product, and this is the image of the homomorphism  $X_1\times X_2\rightarrow X_1\otimes X_2$.
Let $y\in \GL_{n/2}(q)$ be  a non-scalar  diagonal element having eigenvalue 1 and  with $\det y=\det h^2$. For instance, we can choose $y=\diag(a,\Id)$ with $a=\det h^2$.
 By Lemma \ref{GuT1}, $y$ is the product of some 2 conjugates of $h$. As $u$ is real in $X_2$, we conclude that  the product of some 2 conjugates of $g$ in $X_1X_2$ is of the form $y':=\diag(y,y^{-1})$. Since $y$ is semisimple, the 1-eigenspace $W'$ of $y'$ on $V$ is non-zero and nondegenerate. By  (i) above,  $y'$ is real, so $e(g)\leq 4$.

Let $k=1$. Then $g$ stabilizes a singular line $\langle v\rangle $ on $V$.
Then $gv=av$ for some $a\in\mathbb{F}_q$. If $a= 1$ then the $1$-eigenspace of the semisimple part $s$ of $g$ on $V$ is non-zero and nondegenerate, and it is also $g$-invariant since $gs=sg$, so the result follows by (ii). If $a\neq 1$ then the $a$- and 
$a^{-1}$-eigenspaces $W,W'$, say, of $g$ on $V$ are totally singular (since $q$ is even, $-1=1$) and $W+W'$ is non-degenerate.
Then the result follows from (ii), unless $V=W+W'$. This means that $V$ is of type $+$,
which is a contradiction.  

(v) By (iv), we can assume that $s$ is homogeneous on $ V$. Let $l$ be the composition 
length of $s$ on  $V$, where $l>1$ as  $u\neq 1$. 
It follows from  Schur's lemma that $K$, the $\mathbb{F}_q$-span of $\langle s\rangle$,
is a field, so $V$ can be viewed as a vector space over $K$.  It is shown in \cite[Lemma 6.6(1)]{ez1} that $|K|=q^{2k}$, where $2k=n/l$ is the dimension of every composition factor, and $C_{O(V)}(s)\cong \U_l(q^k)$.  As $n/2$ is odd, both $k,l$ are odd. Let $V_K$ denote $V$ viewed as a $K$-module.  Then, by \cite[Lemma 6.6(2)]{ez1}, $V_K$ is a unitary $K$-space, and the unitary geometry 
on $V_K$ agrees with orthogonal geometry on $V$ in the sense that  
for a $K$-subspace $W$ the space $W^\perp$ is the same in each geometry. In addition, 
$W$ is totally singular if and only if $W$ is totally isotropic in the unitary geometry.
In addition, $g$ stabilizes no non-degenerate   subspace of $V$ if and only if
$g$ stabilizes no non-degenerate subspace of $V_K$  equivalently,
$u$  stabilizes no non-degenerate  subspace of $V_K$. By \cite[Lemma 6.1]{TZ04},  this is equivalent to saying that the Jordan form of $u'$ consists of a single block. 

It is well known that $V_K$ is a direct sum of non-degenerate one-dimensional subspaces.
It follows that $V$ decomposes as a direct sum of  non-degenerate $s$-stable subspaces, each  of dimension $2k$. Therefore, $s$ is contained in the stabilizer of such a decomposition 
and hence we can write $s=\diag(t,\ldots,t)$, where $t\in O(W)$ if $W$ denotes one of the summands. As $|s|$ is odd, $t\in \Omega(W)$. In addition, as $s$ is irreducible in $O(W)$,
we have $O(W)\cong O_{2k}^-(q)$ see \cite[Satz 3(b)]{Huppert}. This means that 
$G=\Omega^-_{2n}(V)$ (as $V$ is a direct sum of $l$  non-degenerate subspaces of $-$ type and $l$ is odd, see \cite[Proposition 2.5.11]{KL}).  This implies that $e(g)\leq 4$ if $G=\Omega^+_{n}(q)$, $n$ even.

Let $S=\{\diag(a,\ldots,a)\ |\ a\in \Omega(W)\}$. Then $S\subset G$, $s\in S$ (as $|s|$ is odd). Let $\eta:S\rightarrow \Omega(W)$ be an isomorphism. 

Let $M'$ be a maximal totally isotropic subspace of $V_K$ and let $M$ be the corresponding subspace of $V$. Then $M$ is totally singular, $\dim M'=(k-1)/2$ and $\dim M=l(k-1)/2$. Then there exist totally isotropic subspaces $M_1'<\ldots<M'_{(k-1)/2}$ with factors of dimension 1. Let $0=M_0<M_1<\ldots<M_{(k-1)/2}$ be the respective chain of $K$-stable subspaces of  $V$.
Then the stabilizer of all these subspaces is a parabolic subgroup $P$ of $G$, $O_2(P)$
consists of all $x\in P$ acting trivially on the subsequent factors of the chain as well as 
on $M_{(k-1)/2}^\perp/M_{(l-1)/2}$. Let $Q_i$ be any complement of $M_i$ in $M_{i+1}$
for $i=0,\ldots,(l-1)/2$ (which are totally singular), and $Q_{(l-1)/2}$ is a complement of  $M_{(l-1)/2}$ in $M^\perp_{(l-1)/2}$, which is non-degenerate.  Note that $Q_{(l-1)/2}$ is non-degenerate, and $Q_i$ is totally singular for $i=0,\ldots,(l-1)/2$.
In addition, $P=O_2(P).L$, where
 $L=\{y\in P: yQ_i=Q_i\}$ for $i=0,\ldots,(l-1)/2$. Then the restriction of 
$L$ on $Q_i$ is $\GL(Q_i)$ for $i=0,\ldots,(l-3)/2$ and $\Omega^-_{2k}(q)$ for $i=(l-1)/2$.
 More precisely,  $y_i$ can be arbitrary with these condition, so $L\cong \GL(Q_1)\times \ldots \times \GL(Q_{(q-1)/2}) \times \Omega^-(Q_{(l-1)/2})$. 

As $s\in C_G(s)$, we can assume  $s\in L$, and that $s_i\in O^-(Q_i)$ for $i=0,\ldots,(l-1)/2$. 
We denote by $S$ the subgroup of $L$ consisting of the elements with the same 
$y_i$, in other words, as an element of $\GL(Q_i)$ the matrix $y_i$ is the same.
Then using a Witt basis $B$ of $V$ such that $B\cap Q_i$ is a basis of $Q_i$ for $i=0,\ldots,(k-1)/2$, $S$ can be written as the set of matrices in $L$ of the form
$\diag(t,\ldots,t)$, $t\in \Omega^-_{2k}(q)$. (Note that for $y_i\in \Omega^-_{2k}(q)$
the matrix of $y$ on $M_i^\perp/M_{i+1}^\perp$ coincides with $y_i$.)  

Suppose that $k>1$. As $k$ is odd,  $k\geq 3$ and  $\Omega^-_{2k}(q)$ is simple. 
By \cite{Gow},
every semisimple element $t\in S\cong \Omega^-_{2k}(q)$ is a product of two conjugates of $s$.  We can choose $t$ such that $m(t)$, the eigenvalue 1 multiplicity  of $\eta(t)$,   be   not a multiple of 4 (indeed, as $2k\geq 6$, we can find $\eta(t)$ of order 3  with $m(\eta(t))=2k-4$). Then the  eigenvalue $1$ multiplicity of $t$  is $2d:=l \cdot m(\eta(t))$, which is not a multiple of $4$ too (since $l$ is odd). Let $x\in S$ be such that $sxsx^{-1}=t$.  Then $h:=gxgx^{-1}=us xsx^{-1} \cdot xux^{-1}=utxux^{-1}=tu'$, where $u'=t^{-1}ut.xux^{-1}\in O_2(P)$. Let $V_0$ is the $1$-eigenspace of $t$ on $V$; then $V_0$ is non-degenerate and  $hV_0=V_0$. 
By the above, $\dim V_0=2d$ with $d$  odd.    Then $4|\dim V_0^\perp$.  
Let $h=\diag(h_0,h_1)$ with $h_0,h_1$ the restriction of $h$ on $ V_0, V_0^\perp$, resp.
Then $h_0\in O^+(V_0)$ is unipotent and $h_1$ is real in  $O^+( V_0^\perp)$. 

As $h_0$ is real in $  O^- (V_0)$ and $h_1$ is real in $O^+ (V_0^\perp)$,
$h$ is real in $O(V)$. As $d$ is odd, $C_{O(V_0)}(h_0)$ contains an element  whose spinor norm is not $ 1$ (By Lemma \ref{au8}). It follows that $h$ is real in $G$, and hence $e(g)\leq 4$.

(vi)  By \cite[Theorem 1.8]{TZ04}, $u$ is real in $\SU_l(q^k)$, and $e(s)\leq 4$. So $e(g)\leq 8$.\end{proof}

Next we look at the lower bound for $e(G)$ with $G$ as above. 
We need the following lemma.

\begin{lemma}\label{qe1} Let $F$ be an algebraically closed field and let  $A,B\in \GL_n(F)=\GL(V)$ be diagonalizable elements with exactly two eigenvalues. Let $X=\langle A,B\rangle$. Then the composition factors of X on V are of dimension $1$ or $2$. \end{lemma}

\begin{proof} Suppose the contrary, and let $W$ be a composition factor of dimension $d>2$. Since $A$ and $B$ are diagonalizable, they both have exactly two eigenvalues on $W$. So we can assume that $W=V$, so $X$ is irreducible.  

Let $\lambda_1,\lambda_2$,  $\mu_1,\mu_2$ be the eigenvalues   of $A,B$, respectively, and we can assume  (by reordering them)  that 
the multiplicity of $\lambda_1$  and of $\mu_1$ is at least $n/2$.    Let $V_1,V_2$ be 
$\lambda_1,\mu_1$-eigenspaces of $A,B$, respectively. As $X$ is irreducible, we have $V_1\cap V_2=0$, and hence $\dim V_1=\dim V_2=n/2$ and $V_1+V_2=V$. Choose a basis $K$
of $V$ such that $K_i:=K\cap V_i$ is a basis of $V_i$, $i=1,2$, ordered so that the elements of $K_1$ are prior to those of $K_2$. Under such a basis the matrices of $A,B$ are of the form
$$\begin{pmatrix}\lambda_1 \cdot \Id&C\\ 0&\lambda_2 \cdot \Id\end{pmatrix}, \hspace{1cm}
\begin{pmatrix}\mu_2 \cdot \Id&0\\ D&\mu_1 \cdot \Id\end{pmatrix}$$ 
where $C,D$ are square matrices of size $n/2$, and $D\neq 0$ as $X$ is irreducible.
Let $\eta:V_1\rightarrow  V_2$ be the mapping defined by $\eta(v) := (B-\mu_2\Id)v\,$ 
for $v\in V_1$.
Since ${\rm ker}\, \eta$ is $X$-stable, $D$ is nonsingular, so $\eta(B_1)$ is a basis of $V_2$, hence we can choose $K_2=\eta(K_1)$ so that $D$ is replaced by the identity matrix.  
Now we can take $C$ to the upper triangular form  by
conjugating both $A,B$ by a suitable matrix $N=\diag(M,M)$ with $M\in \GL_{n/2}(F)$. Note that $NBN^{-1}=B$. Then the vectors $v_1=(1,0,\ldots, 0)$, $v_2=(0,\ldots, 0,1,0,\ldots ,0)\in F^{2n}$ span a 2-dimensional $X$-stable subspace of $V$ (here $1$ is located at the $(n+1)$-th position). \end{proof}



Consider the  matrix $J=\begin{pmatrix}0&\Id_n\\ \Id_n&0\end{pmatrix}$. The orthogonal group $O^+_{2n}(F)$ is contained in $H=\{ h\in \GL_{2n}(F): JxJ^{-1}={}^tx^{-1}\}$, where ${}^t$ denotes the transposition operation. This inclusion is an equality if $F$ is not of characteristic $2$. Then $J$ is the Gram matrix of the natural basis $B$ of $V=F^{(n)}$.
We use this notation in the proof of the following result.

\begin{theor}\label{th2} Let $F$ be a field of characteristic $p\geq 0$.  For $n$ odd let $G=\SO^+_{2n}(F)$ if $p\neq 2$, and $G=\Omega^+_{2n}(F)$ if $p=2$. 
Suppose that $F^\times $ has an element $\mu$ such that $\mu^6\neq 1$.
Let $g = \diag(\mu\cdot \Id_n,\mu^{-1}\cdot \Id_n) \in G$. Then $e(g)>3$. In addition, if $\mu^{6}\neq \pm 1$ and $g'$ is the image of $g$ in $G/Z(G)$ then $e_{G/Z(G)}(g')>3$.
\end{theor}

\begin{proof} Let $V=F^{n}$ be the underlying space of $G$. Let $W,W'$ be the $\mu$-, $\mu^{-1}$-eigenspaces of $g$, respectively. Observe that $W,W'$ are totally singular (as a $\mu$-eigenvector is singular unless $\mu=\pm  1$) and $JW=W'$. 

We claim that $J\in O^+_{2n}(F)$. This is clear for $p\neq 2$.  Suppose  that $p=2$, and let $Q$ be the quadratic form on $V$ defining $O^+_{2n}(F)$. We need to show that $Q(Jv)=Q(v)$ for every $v\in V$. Recall that $Q(v+v')=Q(v)+Q(v')+(v,v')$, where
$(v,v')$ is a bilinear form defining $\Sp_{2n}(q)$. As $J\in \Sp_{2n}(q)$, it suffices to show that $Q(Jv)=Q(v)$ for  $v$ running on a basis of $V$. Note that  $B\cap W$, $B\cap W'$ are bases of $W,W'$, respectively. Then $Q(v)=0$ for every $v\in B$ as both $W,W'$ are totally singular.  Since $Jv\in W\cup W'$ for $v\in B$, the claim follows.  

In addition, $J\notin G$. This is obvious for $p\neq 2$ as $\det J=-1$. If $p=2$ then $J$ is a product of $n$ reflections and $n$ is odd, so the claim follows from the definition of the spinor norm, see \cite[p. 29]{KL}. 

We claim that $g$ is not real in $G$ for $p\neq 2$.   Indeed, if $xgx^{-1}=g^{-1}$ for $x\in G$ then $Jxgx^{-1} J^{-1}={^t}g=g$, so $Jx\in C_{\GL_{2n}(F)}(g)$, hence $Jx=\diag(y,y')$ for some $y,y'\in \GL_n(F)$. Since $Jx \in O_{2n}^{+}(F)$, we have $y'={^t}y^{-1}$ hence $\det Jx = 1$. This is a contradiction, as $\det J=-1$ (since $n$ is odd) and $\det x = 1$. (This argument is valid if $\mu^2\neq 1$.) 
Therefore,  $e(g)>2$. 

Observe that $g' = gZ(G)$ is not real in $G/Z(G)$ if $\mu^{4}\neq 1$. Indeed, if $xgx^{-1}= z g^{-1}$ for $1\neq z\in Z(G)$ and $x \in G$ then $z^2=1$ and $xg^2x^{-1} = g^{-2} = \diag(\mu^{-2}\cdot\Id,\mu^2\cdot\Id)$. This is false unless $\mu^4=1$ as we have just seen. So $e_{G/Z(G)}(g')>2$.


If $p=2$ then $g$ is not real in $O(V)$. Indeed,    if $xgx^{-1}=g^{-1}$ for $x\in G$ then 
the spinor norm of $x$ and of $Jx=\diag(y,{}^ty^{-1})$
is 1, and hence so is that of  $J$, which is false. So  $x\notin \Omega^+_{2n}(F)$. 


Thus $g$ is not real in $G$.
Assume by contradiction that $e(g) \leq 3$. Then $e(g)=3$, so there exists $h \in G$ such that $g,h$ are conjugate in $G$ and $gh$ is conjugate to $g^{-1}$. Set $X := \langle g,h \rangle$. Then 

(*)  $g,h$ have no common eigenvector on every composition factor $M$ of $X$ on $V$.

Indeed, if $0\neq v\in M$ and $gv=\mu v$, $hv=\mu^{\pm 1}v$ then $gh v=
\mu \cdot \mu^{\pm 1} v \in\{v, \mu^2 v\}$. As $\mu^{\pm 1}$ are the only eigenvalues of $g^{-1}$ we have $\mu^2=\mu^{-1}$, whence $\mu^3=1$. 

This implies, by Lemma \ref{qe1}, that all composition factors of $X $ on $V$ are of dimension 2.

(**) Observe that $O_2^\pm  (F)$ has an abelian normal subgroup  
of index 2 (see for instance \cite[Proposition  2.9.1(iii)]{KL}). If $p\neq 2$ then $\SO_2(F)$
is abelian,  see \cite[\S 6, item (3) on p. 49]{Di}. 


Let $W$ be a minimal non-trivial $FX$-submodule of $V$. Then  $W$ is degenerate and hence totally singular.  
Indeed, otherwise the restriction $X_W$ of $X$ to $W$ is a subgroup of $O(W) $. 
If $p=2$ then all semisimple elements of $O(W)$ commute and hence $g,h$ have a common eigenvector on $W$.   Let $p\neq 2$. As both $\mu,\mu^{-1}$ are eigenvalues of 
$g$ (and of $h$), we observe that $X_W\subset \SO(W)$. So $X_W$ is abelian and hence cannot be irreducible. 

Let $L$ be a maximal totally singular $X$-stable subspace of $V$.
Then $L^\perp/L$ is a non-degenerate orthogonal space and, by the maximality of $L$,
this has no totally singular  $X$-stable subspace.
However, if $W_1$ is a minimal $FX$-submodule of $L^\perp/L$ then, by (*) as above,  we conclude that $W_1$ is totally singular. This is a contradiction unless $L=L^\perp$, and then $\dim V=2\dim L$. Then $\dim L$ is even as all composition factors of $X$ on $L$ are of dimension 2. Therefore, $4|\dim V$, a contradiction.

 If $p=2$  then $Z(G)=1$ and the additional statement is trivial. 
If $p\neq 2$ then $|Z(G)|=2$. We have seen above that $g'$ is not real if $\mu^6 \neq \pm 1$, so   $e(g')\geq 3$. Suppose that $e(g')= 3$. Then (*) remains true if $\mu^6\neq 1$, and all further considerations are valid with no changes, leading to a contradiction.
\end{proof}


\begin{lemma}\label{dd2} Let V be an orthogonal space over ${\mathbb F}_q$ of dimension $2n$. 

$(1)$ If $V$ is of type $+$ then $V$ is an orthogonal sum of $n$ dimension $2$ non-degenerate subspaces of type $+$, and if n is even then $V$ also is an orthogonal sum of $n$ dimension $2$ non-degenerate subspaces of type $-$. 

$(2)$ If $V$ is of type $-$ and $n$ is odd then $V$ is an orthogonal sum of $n$ dimension $2$ non-degenerate subspaces of type $-$.

$(3)$ Suppose that n,q are odd. Then $Z(\Omega(V))\neq 1$ 
if and only if $V$ is of type $+$ and   $4|(q-1)$ %$|\mathbb{F}^\times _q|\equiv 0\pmod 4$  
or $V$ is of type $-$ and $4|(q+1)$. %, so$ \mathbb{F}^\times _q$ has no element  of order 4.  
\end{lemma}

\begin{proof}
This follows from \cite[Propositions 2.5.11(ii) and 2.5.13]{KL}.\end{proof}

Note that for elements $g\in \SO^\pm_{2n}(q)$ the spinor norm of $g$ is $\eta(g)$ under the natural homomorphism  $\eta:\SO^\pm_{2n}(q)\rightarrow \SO^\pm_{2n}(q)/\Omega^\pm_{2n}(q)$, see \cite[p.29]{KL}  for $q$ odd,  \cite[p.65]{Di}  for $q$ even.  
We say that $g$ has spinor norm $-1$ if  $|\eta(g)|=2$ and 1 otherwise. 
Recall that 
$\Omega_2^\pm (q)$ is a cyclic group of order $(q\pm 1)/(2,q-1)$ \cite[Proposition  2.9.1(iii)]{KL}. 
It follows that the elements of order $q-(\pm 1) $ in $\SO_2^\pm (q)$ have spinor norm  $-1$ if $q$ is odd and 1 if $q$ is even.

\begin{corol}\label{oo7} 
$(1)$ Let $G=\Omega^-_{2n}(q) $, n odd.  
If $q\neq 2,3,5,11$ then $e(G)>3$; if $q\neq 2,3,5,7,11,23$ then $e(G/Z(G))>3$. %for some $g\in G$.

$(2)$ Let $G=\Omega^+_{2n}(q)$, n odd. If $q\neq 2,3,4,5,7,13$. 
%Let $g\in G;$ suppose that $g$   has two eigenvalues $\mu,\mu^{-1}\in \mathbb{F}_q$, $\mu^6\neq 1$, each of multiplicity  n. 
Then $e(G)>3$;  if $q\neq 2,3,4,5,7,9,13,25$ then $e(G/Z(G))>3$.
\end{corol} 

\begin{proof} Let $V$ be the underlying orthogonal space for $G$. Set $H=\SO(V)$.

(1) By Lemma \ref{dd2}(1), $V$ is a direct  sum of 2-dimensional non-degenerate subspaces of type $-$ orthogonal to each other. Therefore, the stabilizer of this decomposition in $ H$ contains the direct product of  $n$ copies of $\SO_2^-(q)$. As  $\SO_2^-(q)$ has an element $x$, say, of order $q+1$ with eigenvalues $\nu,\nu^{-1}$ over $\overline{{\mathbb F}}_q$, where $\nu$ is a primitive $(q+1)$-root of unity, we can construct $h\in H$ as $\diag(x,\ldots, x)$. Note that $h$ is diagonalizable over an algebraic closure of $\mathbb{F}_q$ with eigenvalues $\nu,\nu^{-1}$ of multiplicity $n$. Recall that the spinor norm of an element of $O(V)$ is  an element of the group $O(V)/\Omega(V)$. 
 The spinor norm  of $h$ is $a^n$, where $a$ is the spinor norm of $x\in \SO^-_2(q)$. If $q$ is odd, then $a\neq 1$, and since $n$ is odd $a^n\neq 1$. So $h\notin G$, but $g=h^2\in G$. We wish to use 
  Theorem \ref{th2}; note that if $e(g)>3$ over an algebraic closure of $\mathbb{F}_q$, then $e(g)>3$ in $G$ as well. If $q\neq 2,3,5,11$
then $(\nu^2)^6\neq 1$, so $e(g)\geq 3$ by  Theorem \ref{th2}. 
  If $Z(G)=1$ then this holds for $P\Omega^-_{2n}(q)$.  Suppose that $Z(G)\neq 1$. Then $4|(q+1)$ by Lemma \ref{dd2}. To use Theorem \ref{th2}, we now need  $(\nu^2)^6\neq -1$, or $\nu^{24}\neq 1$, equivalently $q \not\in \{3,5,7,11,23\}$. So $e(G/Z(G)) > 3$ in this case. If  $q$ is even then $|x|$ is odd and hence $a=1$, $h\in G$, and we set $g=h$. Then $\nu^{12} \neq 1$ if and only if  $q\neq 2$.

(2) In this case $V$ is a direct sum of 2-dimensional non-degenerate spaces of type $+$
orthogonal to each other.
Therefore, the stabilizer of this decomposition in $\SO^+_{2n}(q)$ contains the direct product of  $n$ copies of $\SO_2^+(q)$. Now $\SO_2^+(q)$ has an element $x$ of order  $q-1$.    As above, if $a$ is the spinor norm of $x$ in $\SO_2^+(q)$ then  the spinor norm of 
$h=\diag(x,\ldots, x)\in H $ is $a^{n}$ which is 1 for $q$ even. If $q$ is odd,  then $h\notin G$, and we set $g=h^2$. If $\nu^{12} \neq 1$, equivalently $q \notin \{3,5,7,13\}$, then, as above, $e(G)\geq 3$ by  Theorem \ref{th2}.  If $Z(G)\neq 1$ then $4|(q-1)$ and we need 
$\nu^{24}\neq 1$,  equivalently $q \not\in \{3,5,7,9,13,25\}$. So $e(G/Z(G)) > 3$ in this case. If $q$ is even then $|x|$ is odd and hence $a=1$, $h\in G$, and we set $g=h$. Now $\nu^{12} \neq 1$ if and only if $q\notin\{2,4\}$. So again the result follows from Theorem \ref{th2}.
\end{proof}


\subsection{Groups $\PSL_n(q)$ }  

\begin{lemma} \label{lemmaPSL}
Let $n \geq 2$ be an integer, $F$ a field, $H=\SL_n(F)$, $G=\PSL_n(F)$. Let $\mu \in F^{\times}$ and let $g=\diag(\mu^{1-n},\mu,\ldots,\mu) \in H$. Let $l \in \{1,\ldots,n-1\}$ be such that $g^{x_1} \ldots g^{x_l} = \lambda \cdot I \in H$ for some $x_1,\ldots,x_l \in \GL_n(F)$, $\lambda \in F$. Then $\mu^{ln}=1$. In particular, if $F$ is finite of size $q$ and $d=(n,q-1)$, if $e(G) < n$ then $e(G) \geq (q-1)/d$.
\end{lemma}

\begin{proof}
The last claim follows by choosing $\mu$ of multiplicative order $q-1$, since then $\mu^{ln}=1$ implies that $q-1$ divides $ln$, so $(q-1)/d$ divides $l$. Now we prove the first claim, i.e. that $\mu^{ln}=1$. If $\mu^n=1$ the claim is trivial. Now assume that $\mu^n \neq 1$. Then $\mu^{1-n} \neq \mu$ so the matrix $g$ is not scalar. In particular, the $g$-eigenspace of $\mu$ has dimension $n-1$. Assume $g^{x_1} \ldots g^{x_l} = \lambda \cdot \Id \in H$ where each $x_i \in H$. Let $W_i=\{v \in V\ |\ g^{x_i}(v)=\mu v\}$ be the $g^{x_i}$-eigenspace of $\mu$ and let $U$ be the $g$-eigenspace of $\mu$, then we have an isomorphism $U \to W_i$ defined by $u \mapsto x_i^{-1}(u)$. Therefore $\dim(W_i)=n-1$ for all $i=1,\ldots,l$. Set $W:=\bigcap_{i=1}^l W_i$. Then $\dim(W) \geq n-l > 0$. Moreover $g^{x_1} \ldots g^{x_l}$ acts as the multiplication by $\mu^l$ on $W$, so $\mu^l=\lambda$ and hence $\mu^{ln} = \lambda^n=\det(\lambda\cdot \Id)=1$.
\end{proof}

If $d=q-1$, that is, $n$ is a multiple of $q-1$, then Lemma \ref{lemmaPSL}
reduces to the trivial claim that $e(G)>1$. So we can try to improve the result for this and related cases. For $q=2$ we have:


\begin{theor}\label{gg6}
Let $G=\GL_n(2)$, $n>1$.  Then $e(G)\leq 6$ and $e(s)\leq 3$ for $s\in G$ semisimple.  
\end{theor}

\begin{proof} 
Write $G=\GL(V)$. Suppose that $s\in G$ is semisimple. Then $V=\bigoplus_{i=1}^k V_i$, where $V_1,\ldots, V_k$
are irreducible $\mathbb{F}_2\langle s\rangle $-modules. Therefore, $s$ belongs to 
$$S = \{x \in G\ |\ xV_i=V_i\ \mbox{for}\ i=1,\ldots,k\} \cong \GL(V_1)\times \cdots\times \GL(V_k).$$ 
Let $s_i$ be the projection of $s$ into $\GL(V_i)$ for $i=1,\ldots,k$. Suppose that $s_i\neq 1$ (equivalently, $\dim V_i>1$). Then $|C_{\GL(V_i)}(s_i)|$ is odd (by Schur's lemma), and hence $s_i$ is regular in $\GL(V_i)$. 
 If $\dim V_i>2$  then the group  $\GL(V_i)$ is simple, and then,  by  Lemma \ref{Gow}, there are $x_i,y_i\in \GL(V_i)$ such that $s_i x_is_ix_i^{-1} y_is_iy_i^{-1}=\Id$. This is also true if 
 $\dim V_i \leq 2$.  The case with $\dim V_i=1$ is trivial. Let $\dim V_i=2$. Then $\GL(V_i)\cong S_3$, so $|s_i|\in 1,3$, and hence $s_i^3=1$.   
It follows that   $sxsx^{-1} ysy^{-1} =\Id$ for some $x,y\in S$. 

It is well known that $C_G(s)$ is a direct product of groups $\GL_{n_j}(2^{k_j})$ for various
$n_j,k_j$, see \cite[Lemma 3.2]{TZ04}. Let $g=su$, where $s\in G$ is semisimple,  $u\in G$ is unipotent and $us=su$. Then $u=\Pi_ju_j$, where  $  u_j$ is a unipotent element in $ \GL_{n_j}(2^{k_j})$. By \cite[Theorem 1.8(ii)]{TZ04}, $u_j$ is real in $\GL_{n_i}(2^j)$. Therefore,  $u$ is real in  $C_G(s)$. 
Now we use Lemma  \ref{xy8} with $x=s$, $y=u$ and $m=e_{C_G(s)}(u)=2$. As $s^2$ is semisimple, we have $e_G(s^2)\leq 3$, and hence $e_G(su)\leq 6$.
\end{proof}

\begin{lemma}\label{s25} $e(\GL_n(2))=3$ for $n=3,4,5$. 
\end{lemma}

\begin{proof} Observe that $e(\GL_n(2))=3$ for $n=3,4$ as $\GL_3(2)\cong \PSL_2(7)$ and $\GL_4(2)=A_8$. Let $n=5$.

Let $g\in G$ and let $g=su$, where $s\in \langle g\rangle$  is of odd order, $u$ is a 2-power.   If %$u=1$ then $e(s)\leq 3$ (by Schur's lemma ), if 
$s=1$ then $e(u)=2$. Suppose that $s\neq 1 $. In view of Lemma \ref{Gow} we can assume that $s$ is not regular. Then $s$ is reducible by Schur's lemma. Let $V_1,\ldots,V_k$ be the homogeneous components of $s$ on $V$, and we can assume that $\dim V_1\geq \dim V_2\geq \ldots \geq \dim V_k$. If $\dim V_k=1$ then $g\in \diag(\GL_4(2),1)$ and the result follows since we know that $e(\GL_4(2))=3$. So we  assume that $\dim V_k\geq 2$, and hence $k=2$, $\dim V_1=3$, $\dim V_2=2 $. Note that the homogeneous components of $s$ are $g$-stable. So $gV_i=V_i$ for $i=1,2$. 
Then $g\in  X_1,X_2$, $X_1\cong  \GL_3(2)$, $X_2\cong \GL_2(2)$. We can write  $g=\diag(g_1,g_2)$, and let $g_i=s_iu_i$ for $i=1,2$. Then $s_i$ is either irreducible on $V_i$ or $s_i=\Id$. If both $s_1,s_2$ are irreducible then $s$ is regular by \cite{at}.
So $s\neq 1,u\neq 1$, and either $g_1=s_1$, $g_2=u_2$ or  $g_1=u_1$, $g_2=s_2$.
In the latter case each $u_1$, $s_2$ is real, so $g$ is real. In the former case $|s_1|=7$, $|u_2|=2$, so $|g|=14$.

For this $g$ we can use the character table \cite[Page 70]{at}. Note that the 4 characters 
of degrees 496 take value $b_7,\overline{b_7},-b_7,-\overline{b_7}$ so their cubes sum to 0.  We have
$$\sum_{\chi\in{\rm Irr}(G)}\frac{\chi(g)^3}{\chi(1)}=1+\frac{-1}{155}+ \frac{1}{930}+\frac{1}{960} + \frac{-1}{1240}>0.$$
This proves the claim.
