%=(-1+3\sqrt{-7}+21-7\sqrt{-7})/2
%=10-2\sqrt{-7}$, $c_7^3=10+2\sqrt{-7}$,
%$b_7^3+c_7^3=20$ and hence the above sum is positive.
%equals $1-\frac{1}{155}-\frac{40}{465}-\frac{-1}{496}+\frac{1}{930}+ +\frac{1}{960} +\frac{1}{1240}>0$.
\end{proof}

\begin{lemma}\label{id4}
If  $g \in \GL_n(3)$ is indecomposable, then there exist $x,y \in \SL_n(3)$ such that $g \cdot g^x \cdot g^y$ is scalar.
\end{lemma}

\begin{proof} Let $g=su$ with $s$ semisimple and $u$ unipotent. In the notation of Lemma \ref{in3}, $s\in M_1$, $u\in M_2$, and $s$ is irreducible in $M_1\cong \GL_k(3)$.  Let $M_3\subset M_1$, $M_4\subset M_2$ be subgroups isomorphic to $\SL_k(3), \SL_l(3)$, respectively. Since the ground field has $3$ elements, $ \langle s,M_3 \rangle$ is either $M_1$ or $M_3$. 
By Corollary \ref{GuT}, a product of $3$ conjugates of $s$ in $\langle s,M_3\rangle$ is scalar and the conjugation elements can be chosen in $M_3$. In addition, if $u$ is not real then a product of 3 conjugates of $u$ in $M_2$ equals 1 by Lemma \ref{u26}. If $u$ is real 
then  $u$ is rational in $M_4$  by \cite[Lemma 2.2(ii)]{TZ05}. 
 Then $u$ is conjugate to $u^{-2}$,  so some product of $3$ conjugates of $u$ in $M_2$ equals 1. It follows that a product of $3$ conjugates of $g$ is scalar and the conjugation elements can be taken in $\SL_n(3)$.
\end{proof}

\begin{lemma}\label{33s}
$e(\SL_n(3)) \leq 6$.
\end{lemma}

\begin{proof} Let $h\in H=\SL_n(3)=\SL(V)$, and $V=\bigoplus_{i=1}^t V_i$, where $V_i$ are indecomposable ${\mathbb F}_3\langle h\rangle$-modules, and let $h_i$ be the projection of $h$ in $\GL(V_i)$ for all $i$. By Lemma \ref{id4}, the product of some three $\SL(V_i)$-conjugates of $h_i$ is of order $\leq 2$ in $\SL(V_i)$ for $i=1,\ldots,k$;  hence a product of $3$ conjugates of $h$ in $H$ is of order 2. Then $e(h)\leq 6$.
\end{proof}


\begin{lemma}\label{44s} Let $G=\SL_n(4)$. Then $e(G)\leq 18$. If $h\in G$
is semisimple then $e(h)\leq 9$.
\end{lemma} 

\begin{proof} 
Suppose that $h \in G$ is semisimple. Let $V=\bigoplus_{i=1}^k V_i$ be a decomposition of $V$ as a direct sum of minimal $\langle h \rangle$-stable subspaces of $V$. Let $h_i$ be the projection of $h$ on $V_i$ for $i=1,\ldots ,k$.  Then $h_i$ is irreducible on $V_i$. Note that $|\GL(V_i) : \SL(V_i) Z(\GL(V_i))| \in\{1,3\}$. By Corollary  \ref{GuT},
there are $x_i,y_i\in \SL(V_i)$ such that $h_ix_ih_ix_i^{-1}y_ih_iy_i^{-1}\in Z(\GL(V_i))$.
This is also true for  $i$ with $\dim V_i= 1$.
It follows that the product of some 3 conjugates of $h$ in $H$ acts scalarly on each $V_i$. 
Since $q=4$, we have  $e(h)\leq 9$.

In general, let $h=su$, where $1\neq s\in H$ is semisimple, $1\neq u\in H$ is unipotent and $us=su$. Then $e_{C_G(s)}(u)\leq 2$. Indeed, $C_{\GL(V)}(s)$ is a direct product of groups isomorphic to $\GL_{m}(q^k)$ for various $m,k$, see \cite[Lemma 3.2]{TZ04}. Therefore, $u$ is contained in a subgroup of $C_{\GL(V)}(s)\cap H$ isomorphic to a direct product of groups $\SL_{m}(q^k)$, since $|u|$ is a $p$-element for $p|q$ and $|GL_{m}(q^k)/\SL_{m}(q^k)|$ is a $p'$-group. By \cite[Theorem 1.7]{TZ04}, $u$ is real in $C_G(s)$. Therefore, $s^2$ is a product of 2 conjugates of $h$; as $e(s^2)\leq 9$, we have $e(h)\leq 18$.     \end{proof}


\begin{lemma}\label{s53} Let $G=\PSL_5(3)$. Then $e(G)\leq 5$. In addition, $e(\PSL_3(3))=e(\PSL_4(3))=3$.\end{lemma}

\begin{proof}
The second claim follows from \cite{gap}, so we will now prove that $e(G) \leq 5$. Let $g=su \in G$, where $s$ is semisimple, $u$ is unipotent and $su=us$. If $g$ is semisimple then $e(g)\leq 5$
by Lemma \ref{un2}. If $g$ is unipotent then $e(g)\leq 2$ by \cite[Theorem 1.8(ii)]{TZ04}. 

Suppose that  $g$ is neither semisimple nor unipotent.   Let $h\in H=\SL_5(3)$ be such that $g=hZ(H)$, and $h=su$, where $s,u\in  \langle h\rangle$, $s$ is is semisimple, $u$ is unipotent. Then $s$ is not scalar. Recall that an $(n \times n)$-matrix $A$ over a field $F$ is called cyclic if there exists $x \in F^n$ such that $\{x,Ax,\ldots,A^{n-1}x\}$ is a basis of $F^n$. The matrix $A$ is cyclic if and only if its Jordan canonical form contains only one Jordan block for every eigenvalue.

We   use Observation \ref{centsem} and the notation therein in the following discussion, in which we list the possibilities for $u$ (up to conjugation). In particular, $n_1,\ldots ,n_k$ are the dimensions of the homogeneous components of $s$.
%We may assume that $n_1 \geq \ldots \geq n_k$. 
We denote by $J_m$ the canonical Jordan block of size $m$. If $x$ is a $p$-element in $\GL_n(q)$, where $p$ is the prime dividing $q$, then $(x-1)^n=0$, therefore if $\GL_n(q)$ contains a unipotent element whose Jordan form is $J_m$, then $n \geq m$. Since $s$ is not scalar, $k \geq 2$.

(a) $u=\diag(J_4,1)$. The fact that $u \in C_G(s)$ implies that $k=2$ and $n_1/m_1 \geq 4$, so $m_1=m_2=1$, $n_1=4$, $n_2=1$. Therefore $h$ is a cyclic matrix whose all eigenvalues are in $\mathbb{F}_3$. By \cite[Theorem 3]{Lev94}, $g^{-1}$ is the product of two conjugates of $h$, whence $e(g)\leq 3$.

(b) $u=\diag(J_3,J_2)$. In this case $n_1=3$, $m_1=1$, $n_2=2$, $m_2=1$, $s=\diag(s_1,s_2)$,   $s_i=\mu_i \cdot \Id$ for $i=1,2$, $\mu_i\in \mathbb{F}_3$ and $\mu_1^3\mu_2^2=1$. As $s_1\neq s_2$, $h$ is a cyclic matrix. So again $e(g)\leq 3$ by \cite[Theorem 3]{Lev94}.


(c) $u=\diag(J_3,1,1)$. In this case $k \in \{2,3\}$, $n_1=3$, $m_1=1$, $s=\diag(\pm  \Id_3,s_2)$, $s_2\in \GL_2(3)$. 
Then $J_3$ is real in $\SL_3(3)$ and $s_2$ is real in $\PGL_2(3)$. Using $-\Id_3$, if necessary, to adjust the determinant, we deduce that the product of some two conjugates of $g$ in $G$ is $\diag( \Id_3,\nu \cdot \Id_2)$, where  $\nu=\pm 1$. Then  $e(g)\leq 4$.

(d) $u=\diag(J_2,1,1,1)$. In this case $k \in \{2,3,4\}$, $n_1=2$, $m_1=1$, $s=\diag(\mu \cdot \Id_2,s_2)$, $\mu=\pm 1$, $s_2\in \SL_3(3)$.
 If $s_2$ is regular, then the product of  3 conjugates of $s_2$ in $\SL_3(3)$ equals $ \Id_3$ by Lemma \ref{Gow}, as $\det (-\Id_3)=-1$. If $\mu=-1$ then, by Lemma \ref{s33}, the product of 3 conjugates of $J_2$ in $\SL_2(3)$ equals $-\Id$, so the product of some $3$ conjugates of $-J_2$ in  $\SL_2(3)$ equals 1. Then  $e(g)\leq 3$.  If $\mu=1$ then, since
$J_2^3=1$, again $e(g)\leq 3$. If $s_2$ is not regular in $\SL_3(3)$ then $s_2$ centralizes some unipotent element in $\SL_3(3)$, and hence it is diagonalizable with at least two equal eigenvalues which belong to $\mathbb{F}_3$. So we can assume that $s_2=\diag(1,\pm \Id_2)$. Then $g = \diag(\mu.J_1,1,\pm \Id_2)$ is contained in the group $X= \left\{ \diag(A,\det A^{-1},\pm\Id_2)\ |\ A \in \GL_2(3) \right\}$. It follows that $g$ is real in $X$, so $e(g)=2$.

(e) $u=\diag(J_2,J_2,1)$. Then $n_1/m_1 \geq 2$. If $m_1 \geq 2$, then $m_1=2$ and $n_1=4$, while if $m_1=1$ then $n_1 \geq 2$. This implies that 
there are two isomorphic irreducible components, and their dimension is $1$ or $2$.
Suppose first that these are of dimension $2$. Then, replacing $g$ by some conjugate, we can assume that $s=\diag(s_1,s_1,t)$, where $s_1\in \GL_2(3)$ is irreducible, $t\in \mathbb{F}_3$. 
Then $t=1$ as $ \det s_1^2=1$. So $s=\diag(s_1,s_1,1)$. We deduce that $h=\diag(A,1)$, where $A=s_2\otimes J_2 \in \GL_2(3)\otimes \GL_2(3)$. Note that $\GL_2(3)\otimes \GL_2(3)\subset \SL_4(3)$.  
Since $J_2$ is real in $\GL_2(3)$, and semisimple elements are real in  $\GL_2(3)$ too, the result follows. Suppose now that $s$ has at least $2$ isomorphic components of dimension $1$. Then some eigenvalue $\mu$ of $h$ is of multiplicity at least 2. Let $W$ be the $\mu$-eigenspace of $h$. If $\dim W=2$ or $3$ then $h=\diag(-J_2,J_2,1)$ 
and  $e(h)=2$ as $J_2$ is real in $\GL_2(3)$. If $\dim W=4 $ then  $h=\diag(-J_2,-J_2,1)$, and again  $e(h)=2$.
\end{proof} 

\begin{corol} \label{boundsPSL}
Let $n \geq 2$ be an integer, let $F$ be a field and let $G:=\PSL_n(F)$.
\begin{enumerate}[$(1)$]
\item If $F$ is finite of size $q$ and $d=(n,q-1)$, then $e(G) \geq \min \{n,(q-1)/d\}$.
\item If $F$ is finite of size $q$, $n \geq 3$, $q \geq 4$ and $n \leq (q-1)/d$ then $e(G)=n$.
\item If $n=3$ and $F$ is algebraically closed, then $e(G)=n$.
\item If $n \geq 4$ and $F$ is infinite, then $e(G)=n$.
\item $e(\PSU_n(q)) \geq \min\{n,(q+1)/(n,q+1)\}$.
\end{enumerate}
\end{corol}

So for example if $q \geq 5$ is an odd prime power then $e(\PSL_{q-2}(q))=q-2$.
Moreover, if $q \geq 4$ is a prime power then $e(\PSL_q(q)) \in \{q-1,q\}$.

\begin{proof} Item (1) follows from Lemma \ref{lemmaPSL}. Item (2) follows from (1) and Lev's theorem \cite[Theorem 1]{Lev1996}. Item (5) follows from Lemma \ref{lemmaPSL} by choosing $\mu$ of order $q+1$, so that $\mu \cdot \overline{\mu} = \mu^{q+1} = 1$ and hence the element $g$ belongs to $\SU_n(q)$. Now we prove (3) and (4). Lev's theorem \cite[Theorem 1]{Lev1996} implies that $e(G) \leq n$ (in both items), assume now by contradiction that $e(G) < n$. Let $\mu,l,g$ be as in the lemma. Then $l \leq e(G) < n$ so $\mu^{ln}=1$. Since $l<n$, this implies that $\mu^{n!}=1$. Since this holds for all $\mu \in F^{\ast}$, every nonzero element of $F$ is a root of the polynomial $X^{n!}-1$, contradicting the fact that $F$ is infinite.
\end{proof}


\begin{prop} \label{geqn}
Let $F$ be an algebraically closed field. Then $e(\PSL_n(F)) = n$.
\end{prop}

\begin{proof}
As  $\GL_n(F)=\SL_n(F)\cdot Z(\GL_n(F))$, elements conjugate   in $\GL_n(F)$   are conjugate in $\SL_n(F)$. 
%Indeed, if we have an equality of the form $S^{-1}AS=B$, where $A \in \SL_n(F)$ and $S \in \GL_n(F)$, then choosing $\alpha \in F$ with the property that $\alpha^n=\det(S)^{-1}$ (which exists because $F$ is algebraically closed) we have $(\alpha S)^{-1} A (\alpha S) = B$ and $\alpha S \in \SL_n(F)$. 
Assume $n=2$. For $\alpha \in F^{\times}$, set
$$M_{\alpha} = \left( \begin{array}{cc} \alpha & 0 \\ 0 & \alpha^{-1} \end{array} \right), \hspace{.2cm} 
A = \left( \begin{array}{cc} 1 & 1 \\ 0 & 1 \end{array} \right), \hspace{.2cm}
S = \left( \begin{array}{cc} 0 & 1 \\ 1 & 0 \end{array} \right), \hspace{.2cm}
T = \left( \begin{array}{cc} 1 & 0 \\ 0 & -1 \end{array} \right).
$$
By basic linear algebra, every matrix in $\SL_2(F)$ is conjugate to one of the matrices $A$, $-A$ or $M_{\alpha}$ for some $\alpha \in F^{\times}$. We have $S^{-1}M_{\alpha}S = M_{\alpha^{-1}} = M_{\alpha}^{-1}$, $T^{-1}AT=A^{-1}$. So $e(\PSL_2(F))=e(\SL_2(F))=2$.

Assume now that $n \geq 3$. The covering number $\cn(G)$ of a group $G$ is the smallest positive integer $k$ such that $C^k=G$ for every nontrivial conjugacy class $C$ of $G$. Lev \cite{Lev1996} proved that the covering number of $\PSL_n(F)$ is equal to $n$ if $n \geq 3$. Let $l:=e(\PSL_n(F))$.
%Note that $e(G) \leq \cn(G)$, so $e(\PSL_n(q)) \leq n$ for all $n \geq 3$, $q \geq 4$. 
Since $l \leq \cn(\PSL_n(F))$, we only need to prove that $l \geq n$. Assuming this is false, Lemma \ref{lemmaPSL} implies that $\mu^{l! \cdot n}=1$ for every $\mu \in F^{\ast}$. This contradicts the fact that $F$ is algebraically closed.
\end{proof}



\subsection{Unitary groups   ${\rm PSU}_n(q)$}\hfill\\

We first recall a few well known facts on maximal parabolic subgroups of $H=\SU_n(q)=\SU(V)$.
By \cite[Proposition  2.3.2]{KL}, $V=W+X+W'$, where $W,W'$ are totally isotropic subspaces of $V$ of dimension $r=[n/2]$ and $(W+W')^\perp=X$. This is equivalent to saying that  $V$
has a basis with Gram matrix $\begin{pmatrix}0&0&\Id_r\\ 0&1&0\\ \Id_r&0&0\end{pmatrix}$ if $n$ is odd and 
 $\begin{pmatrix}0&\Id_r\\  \Id_r&0\end{pmatrix}$ if $n$ is even. Let $P$ be the stabilizer of $W$ in $H$. Then $P=LU$, where $U$ is the unipotent radical of $P$, and $L$
is a complement of $U$ in $P$.  Let $\sigma$ be the automorphism of $H$ arising from the Galois automorphism of $\mathbb{F}_{q^2}/\mathbb{F}_q$, sending $x \in \mathbb{F}_{q^2}$ to $x^q$, so $\sigma$ rises every matrix entry of $h\in H$ to the $q$-th power. Under the basis with above Gram matrix, $L$ consists of  all matrices of determinant $1$ of the form $\mbox{diag}(M,d,{}^t\sigma(M)^{-1})$ if $n$ is odd, and $\mbox{diag}(M,{}^t\sigma(M)^{-1})$ if $n$ is even, where $M\in \GL_r(q^2)$ is such that $\det (M) \cdot \sigma(\det (M^{-1})) \cdot d=1$. (Here $t$ means the transpose.) 
In particular,  if  $M$ is diagonal then $\sigma(M)=M^q$. It follows that the derived subgroup of $L$ is
$L' \cong \SL_r(q^2)$. 


\begin{lemma} \label{pu3} Let $H=\SU_n(2)$, $n>1$ and let $s\in H$ be a semisimple element.   Then  $e(s)\leq 9$ and $e(H)\leq 18 $.\end{lemma}

\begin{proof} Let $V$ be the underlying space for $H$. By \cite[Satz 2]{Huppert}, $V=\bigoplus_i V_i$, where $V_i$'s are minimal $\langle s \rangle$-stable non-degenerate subspaces of $V$. Let $s_i$ be the restriction of $s$ to $V_i$. Then either $s_i$ is irreducible, or $V_i=W_i \oplus W_i'$,
where $W_i,W_i'$ are totally isotropic minimal $\langle s_i \rangle$-stable subspaces. In addition, there exists a basis of $V_i$ such that if $M_i$ is the matrix of $s_i$ on $W_i$ then 
the matrix $M_i'$ of $s_i$ on $W_i'$ is ${}^t\gamma(M_i)^{-1}$, where $\gamma$ is a non-trivial Galois automorphism of ${\mathbb F}_4$ (\cite[Satz 2]{Huppert}). 
As $W_i$ is irreducible, $s_i$ is a regular element of $\GL(W_i)$. Moreover, by Schur's lemma $s_i$ is regular in $\GL(V_i)$ unless $W_i,W_i'$ are isomorphic $\mathbb{F}_{q^2}\langle s_i\rangle $-modules, equivalently, $M_i$ and $M'_i$ are similar as matrices of $\GL_d(q^2)$, $d=\dim W_i$. Then $M_i$ is contained in a subgroup $X_i$ of  $\GL_d(q^2)$ isomorphic to $\U_d(q)$. It follows that $V_i$ is a direct sum of  two $\langle s_i \rangle$-stable non-degenerate subspaces. Therefore, if we choose the decomposition $V=\bigoplus_i V_i$ with maximal number of non-degenerate terms $V_i$ then $s_i$ is a regular element in $\GL(V_i)$ and $\U(V_i)$.

Since $|\U(V_i)/Z(\U(V_i)) \SU(V_i)|\in\{1,3\}$, by Corollary \ref{GuT} there are $x_i,y_i\in \SU(V_i)$ such that $s_i x_i s_i x_i^{-1} y_i s_i y_i^{-1} \in Z(\U(V_i))$. Therefore, the product of some 3 conjugates of $s$ is of order 3 or 1.  This implies $e(s)\leq 9$. 

Let $h\in H$ and 
$h=su$, $s,u\in \langle h\rangle$ with $s$ semisimple, $u$ unipotent. 
Note that $C_{\U(V)}(s)$ is a direct product of groups
isomorphic to $\GL_{m}(q^{2k})$ and $\U_m(q^k)$ for various $m,k$, see \cite[Lemma 3.3]{TZ04}. Therefore, $u$ is contained in a subgroup of $C_{\GL(V)}(s)\cap H$ isomorphic to a direct product of groups  $\SL_{m}(q^k)$ and  $\SU_m(q^k)$. By \cite[Theorem 1.7(ii)]{TZ04}, applied to every multiple, $u$ is real in $C_G(s)$. Therefore, $s^2$ is a product of 2 conjugates of $h$; as $e(s^2)\leq 9$, we have $e(h)\leq 18$. 
\end{proof}


\begin{lemma} \label{pu2} Let $G=\PSU_n(q),n>1$, q odd.  
Then $e(G)\leq 3n+3$. If $(n,q)=1$ then $e(G)\leq 3n$.\end{lemma}

\begin{proof} 
Let $g\in G$ and let $h\in H = \SU_n(q)$ be such that $g=hZ$ where $Z=Z(H)$. Let $h=su$ with $s,u\in \langle h\rangle$, $s$ semisimple, $u$ unipotent.  
By Lemma \ref{u26}, $e_{C_H(s)}(u)\leq 3$. Therefore, $s^3$ is a product of $3$ conjugates of $h$ in $C_H(s)$. By Lemmas \ref{un2} and \ref{u42}, $e_G(s^3Z) \leq n$ if $(n,q)=1$ and  $e_G(s^3Z) \leq n+1$ otherwise. So the result follows by Lemma \ref{gr1}.\end {proof}


\begin{theor}\label{u36} Let $G = \PSU_n(q), n>2$, $q$ even. Then  $e(G) \leq 2n-2$.
\end{theor} 

\begin{proof} Note that the exponent of a Sylow $2$-subgroup of $G$ equals $2^m$, where $n\leq 2^m<2n-1$. The result follows from Lemma \ref{5eg}.
\end{proof}


