\begin{lemma} \label{g24}
Let $G=G_2(q)$, q even.  Then $e(G)\leq 4$. %If $q$ is a square then $e(G)= 3$.
\end{lemma}

\begin{proof} The character table of $G$ is available in \cite{EY}. By inspection of this  one observes that the irreducible character values are not real only at two conjugacy classes, denoted by  $B_2(1)$ and $ B_2(2)$. So $e(g)=2$ unless 
$g\in B_2(1)\cup B_2(2)$.  

Representatives of  $B_i(1)$, $i=1,2,
$ are written in \cite[Table IV-1]{EY} and in \cite{Enomoto} as
$h(\omega,\omega,\omega)y_i$, where $y_i$ are unipotent,   $h:=h(\omega,\omega,\omega)^3=1$ and $hy_i=y_ih$, see \cite[p.327]{EY}.  So $|g|$ is even and hence $g,g^2$ are not conjugate. Therefore, $g^2$ is real, and hence $e(g)\leq 4$. 
\end{proof}

\begin{theor} \label{sf4} Let $G=F_4(q)$ or $G={}^2F_4(q)$, with $q$ even. Then $e(G)\leq 4,6$, respectively. 
\end{theor}

\begin{proof}
By \cite[Proposition  10.11]{TZ04}, $G$ has property $\frac{1}{2}\mathcal{SR}^*$. This means (see \cite[p. 333]{TZ04}) that the unipotent elements $u \in C_G(s)$ are semirational. Indeed, the property $\mathcal{SR}^*$ means that  $u,u^m$ are conjugate in $C_G(s)$ whenever $(m,|u|)=1$ and $4|(m-1)$. This is equivalent to saying that $u^m$ is conjugate to $u$ or to $u^{-1}$ in $C_G(s)$. In particular, every unipotent element $u$ of $G$ is semirational in $G$. So, by Corollary \ref{cor881}, $e(u)\leq 4$. 

Suppose that $g\in G$ is not unipotent, and write $g=su$, where $s$ is semisimple, $u$ is unipotent and $su=us$. Since $s$ is real (Lemma \ref{sn2}), if $u=1$ then $e(g)=e(s)=2$.

Suppose that $s\neq 1,u\neq 1$. As observed in \cite[pp. 381-382]{TZ04}, either $u$ is real in $C_G(s)$ and then $e(g) \leq 4$ by Lemma \ref{xy8} or $G={}^2F_4(q)$ and $C_G(s)\cong H\times C$, where $H\cong \Sz(q)$ and $C$ is a cyclic group of order $q^2-1$. Then $e_H(u)\leq 3$, hence $e(g)\leq 6$ by Lemma \ref{xy8}.
\end{proof}

We now discuss the groups of type $E_6$, $E_7$, $E_8$. 


For every quasisimple group of Lie type $G$ in defining characteristic $p > 0$ let $U$ be a Sylow $p$-subgroup of $G$ and $B = N_G(U)$. Then $B = HU$, where $H \cap U = \{1\}$. By \cite[Proposition 2.5.5]{C}, there  exists a conjugate $U^-$ of $U$ such that $N_G(U) \cap N_G(U^-) = H$. By \cite[Theorem H, p. 344]{egh}, 
for every non-central conjugacy class $C$ of $G$ and every $h\in H$ there exists 
$u_1\in U^-$, $u_2\in U$ such that $u_1 h u_2 \in C$. In particular, $C \cap  U^-U$ is not empty. 

\begin{lemma} \label{e62}
Let $G\in \{E_6(q), {^2}E_6(q)\}$ be a simple group, and $p|q$ a prime. Then $e(G)\leq d$, where $d=p$ for $p>11$, and $16,27,25,49,121$ for  $p=2,3,5,7,11$, respectively. 
\end{lemma}

\begin{proof}
Note that the exponent of a Sylow $p$-subgroup of $G$ equals $p$
for $p>11$, $p^2$ for $3<p\leq 11$, and $16,27$ for $p=2,3$  \cite{Lw}. So the result follows from  Lemma \ref{5eg}.
\end{proof}

