\begin{lemma} \label{613} 
Let $G \in \{E_6(q), {^2}E_6(q)\}$. Then $G$ contains a regular semisimple element of order $13$; if $(q,6)=1$ then G contains a regular semisimple element of order $12$.
\end{lemma}

\begin{theor} \label{666} 
Let $G\in \{E_6(q), {^2}E_6(q)\}$. Then $e(G)\leq 36$ if $(q,30)=1$ and $e(G) \leq 16,27,25$ if $q=2^k,3^k,5^k$, respectively. If $s\in G$ is a semisimple element, then $e(s)\leq 12$ if $(q,6)=1$ and $e(s) \leq 13$ otherwise.  \end{theor}

\begin{proof}
By Lemmas \ref{Gow} and \ref{613}, $s$ is a product of two elements of order $13$, and even $12$ if $(q,6)=1$. Then $e(s)\leq 13,12$, respectively.  

In general, let $g=su$ with $s$ semisimple, $u$ unipotent, and let $C$ be the conjugacy class of $G$ containing $g$. By \cite[Theorem 1.5]{TZ04}, the generators of $\langle u\rangle$
 lie in at most two conjugacy classes of $C_G(s)$. Therefore, $u$ is either real or semirational in $C_G(s)$. By Corollary \ref{cor881},  $s^m\in C^m$ for $m=2,3$, respectively. If  $(q,6)=1$ then $e(s)=12$, so $e(g) \leq 36$. If $(q,6) \neq 1$ then the claim follows from Lemma \ref{e62}.
\end{proof}

