\begin{theorem}
\label{thm:c_preferred_results}
    \JJ{C-preferred argumentative ensembling is equivalent to s-preferred argumentative ensembling.}
\end{theorem}

\begin{proof}
    \JJ{By definition, each c-admissible set is also d-admissible (see Section \ref{sec:preliminaries}). S-admissible sets are d-admissible, and we show in Theorem \ref{thm:stable_results} that d-preferred sets are equivalent to stable sets, therefore, by Property 2 of \cite{Cayrol_05}, our s-admissible sets are closed for support relations $\Supps$, therefore are c-admissible.}
\end{proof}

