\begin{proposition}
\label{prop:dominant_model}
    If $\exists \model_i \in \Models$ such that $\forall \model_j \in \Models$, $\model_i \msucc \model_j$, then $\forall \JJ{P^{s}_i} \in P^s$, $\model_i \in \JJ{P^{s}_i}$.
\end{proposition}

\begin{proof}
    If $\forall \model_j \in \Models$, $\model_i \msucc \model_j$ then, by Definition \ref{def:BAF}, $\Atts(\model_i) = \Atts(\cfx_i) =\emptyset$ and $\forall \model_j \in \Models$ where $\model_j(\inn) \neq \model_i(\inn)$, $\model_i \in \Atts(\model_j)$. Similarly, $\forall \cfx_k \in \CFXs$  %\delete{of $\model_k \in \Models$} 
    where $\model_i(\cfx_k)=\model_i(\inn)$, $\model_i \in \Atts(\cfx_k)$, and so $\model_i$ indirectly attacks $\model_k$. Then, $\nexists \JJ{P^{s}_i} \in P^s$ such that $\model_j \in \JJ{P^{s}_i}$ or $\model_k \in \JJ{P^{s}_i}$ and thus, $\forall \JJ{P^{s}_i} \in P^s$, $\model_i \in \JJ{P^{s}_i}$.
\end{proof}

