\begin{proposition}
\label{prop:the_best_model_is_in_m_preferred_set}
    If $\exists \model_i \in \Models$ such that $\forall \model_j \in \Models$, $\model_i \msucceq \model_j$, then $\exists \JJ{P^{s}_i} \in P^s$ such that $\model_i \in \JJ{P^{s}_i}$. 
\end{proposition}

\begin{proof}
    If $\forall \model_j \in \Models$, $\model_i \msucceq \model_j$ then, by Definition \ref{def:BAF}, $\nexists \arg_k \in \Atts(\model_i) \cup \Atts(\cfx_i)$ such that $\model_i \nin \Atts(\arg_k)$ and $\cfx_i \nin \Atts(\arg_k)$. Thus, it must be the case that $\exists \JJ{P^{s}_i} \in P^s$ such that $\model_i \in \JJ{P^{s}_i}$.
\end{proof}

We now show that if a model is outperformed wrt the preferences by all other models, then the outperformed model cannot exist in an s-preferred set unless it is defended by a more preferred model.

\begin{proposition}
\label{prop:worst_model_must_be_defended}
    For any $\model_i \in \Models$, if $\model_j \msucc \model_i$ {for all} $%\forall 
    \model_j \in \Models \setminus \{ \model_i \}$ and $\exists \JJ{P^{s}_i} \in P^s$ such that $\model_i \in \JJ{P^{s}_i}$, then, $\forall \model_k \in \Models$ where $\model_k(\inn) \neq \model_i(\inn)$,  %\todo{JJ: Mk is attacking Mi because of disagreement on prediction, or Mk is attacking Mi through cfx? {disagreement on prediction}}, 
    $\exists \model_l \in \JJ{P^{s}_i}$ such that $\model_l \msucceq \model_k$.
\end{proposition}

\begin{proof}
    By Definition \ref{def:BAF}, $\model_k \in \Atts(\model_i)$ and $\{ \model_m \in \Models | \model_i \in \Atts (\model_m) \vee \cfx_i \in \Atts (\model_m) \} = \emptyset$. 
    Then, given that $\exists \JJ{P^{s}_i} \!\in\! P^s$ such that $\model_i \!\in\! \JJ{P^{s}_i}$, we know that, $\forall \model_k \!\in\! \Atts(\model_i)$ $\exists \model_l \!\in\! X$ where $\model_l(\inn) \!=\! \model_i(\inn)$ and $\model_l \!\in\! \Atts(\model_k)$. Thus, by Definition \ref{def:BAF}, $\model_l \msucceq \model_k \msucc \model_i$.
\end{proof}


\JJ{Propositions \ref{prop:the_best_model_is_in_m_preferred_set} and \ref{prop:worst_model_must_be_defended} also apply to d-preferred \AR{argumentative ensembling} with the same proof.}

