\section{Technical details of loop calculations}
\label{app:loops}

This appendix provides comprehensive technical details supporting the main calculations in the manuscript, including explicit derivations of coefficient functions, numerical methods for bubble solutions, and parameter space constraints.

\subsection{Complete heat kernel expansion}

The heat kernel expansion for the functional determinant requires careful treatment of the $\tau$-dependent operator $\mathcal{O}_k(\tau)$. We expand the logarithm of the operator about a reference point $\tau_0$:

\begin{align}
\ln[\mathcal{O}_k(\tau)] &= \ln[\mathcal{O}_k(\tau_0)] + \sum_{n=1}^{\infty} \frac{(-1)^{n+1}}{n} \left(\frac{\delta\mathcal{O}_k(\tau)}{\mathcal{O}_k(\tau_0)}\right)^n
\end{align}

where $\delta\mathcal{O}_k(\tau) = \mathcal{O}_k(\tau) - \mathcal{O}_k(\tau_0)$.

For small fluctuations, we can expand:
\begin{equation}
\delta\mathcal{O}_k(\tau) = \mathcal{O}_k'(\tau_0)(\tau-\tau_0) + \frac{1}{2}\mathcal{O}_k''(\tau_0)(\tau-\tau_0)^2 + \ldots
\end{equation}

The first-order term integrates to zero over a symmetric interval, while the second-order term gives:
\begin{equation}
\int d\tau \left(\frac{\mathcal{O}_k'(\tau)}{\mathcal{O}_k(\tau)}\right)^2 = \frac{1}{\mathcal{O}_k(\tau_0)^2} \int d\tau [\mathcal{O}_k'(\tau)]^2
\end{equation}

Substituting the explicit form of $\mathcal{O}_k'(\tau)$:
\begin{equation}
\mathcal{O}_k'(\tau) = \frac{d}{d\tau}[k^2 + V''(\phi_0(\tau)) + g\lambda_0(\tau) - \frac{g^2\phi_0^2(\tau)}{\mu^2}]
\end{equation}

This yields:
\begin{equation}
\mathcal{O}_k'(\tau) = V'''(\phi_0)\frac{d\phi_0}{d\tau} + g\frac{d\lambda_0}{d\tau} - \frac{2g^2\phi_0}{\mu^2}\frac{d\phi_0}{d\tau}
\end{equation}

\subsection{Detailed derivation of coefficient functions}

The A-coefficient represents the kinetic term for the $\phi$ field. Starting from:
\begin{equation}
A(\phi_0,\lambda_0) = \frac{1}{2}\int \frac{d^dk}{(2\pi)^d} \frac{[V'''(\phi_0) - 2g^2\phi_0/\mu^2]^2}{[k^2 + V''(\phi_0) + g\lambda_0 - g^2\phi_0^2/\mu^2]^2}
\end{equation}

We perform the momentum integral using dimensional regularization. In $d = 4-2\varepsilon$ dimensions:
\begin{equation}
\int \frac{d^dk}{(2\pi)^d} = \frac{\mu_0^{2\varepsilon}}{(4\pi)^{d/2}\Gamma(d/2)}
\end{equation}

where $\mu_0$ is the dimensional regularization scale.

The momentum integral becomes:
\begin{equation}
A(\phi_0,\lambda_0) = \frac{[V'''(\phi_0) - 2g^2\phi_0/\mu^2]^2 \mu_0^{2\varepsilon}}{2(4\pi)^{2-\varepsilon}\Gamma(2-\varepsilon)} \int_0^{\infty} \frac{k^{3-2\varepsilon} \, dk}{[k^2 + M_{eff}^2]^2}
\end{equation}

where $M_{eff}^2 = V''(\phi_0) + g\lambda_0 - g^2\phi_0^2/\mu^2$.

The momentum integral can be evaluated using:
\begin{equation}
\int_0^{\infty} \frac{k^{3-2\varepsilon} \, dk}{[k^2 + M^2]^2} = \frac{1}{2}\frac{\Gamma(2-\varepsilon)\Gamma(\varepsilon)}{\Gamma(2)} (M^2)^{\varepsilon-1}
\end{equation}

This gives:
\begin{equation}
A(\phi_0,\lambda_0) = \frac{[V'''(\phi_0) - 2g^2\phi_0/\mu^2]^2 \mu_0^{2\varepsilon}}{(4\pi)^{2-\varepsilon}} \frac{\Gamma(\varepsilon)}{2\Gamma(2)} (M_{eff}^2)^{\varepsilon-1}
\end{equation}

Using $\Gamma(\varepsilon) = 1/\varepsilon - \gamma + O(\varepsilon)$ and $\mu_0 = \mu e^{\gamma/2}/(4\pi)^{1/2}$:
\begin{equation}
A(\phi_0,\lambda_0) = \frac{[V'''(\phi_0) - 2g^2\phi_0/\mu^2]^2}{32\pi^2} \left[\frac{1}{\varepsilon} + \ln\left(\frac{M_{eff}^2}{\mu^2}\right) + \text{finite}\right]
\end{equation}

Similarly, the B-coefficient for the $\lambda$ kinetic term is:
\begin{equation}
B(\phi_0,\lambda_0) = \frac{g^2}{32\pi^2} \left[\frac{1}{\varepsilon} + \ln\left(\frac{M_{eff}^2}{\mu^2}\right) + \text{finite}\right]
\end{equation}

The C-coefficient for the mixing term is:
\begin{equation}
C(\phi_0,\lambda_0) = \frac{g[V'''(\phi_0) - 2g^2\phi_0/\mu^2]}{16\pi^2} \left[\frac{1}{\varepsilon} + \ln\left(\frac{M_{eff}^2}{\mu^2}\right) + \text{finite}\right]
\end{equation}

\subsection{Renormalization and physical interpretation}

The divergent parts of the coefficient functions are removed by renormalization. We add counterterms to the original action:
\begin{equation}
S_{total} = S_{original} + S_{counterterms}
\end{equation}

The counterterm action is:
\begin{equation}
S_{counterterms} = \int d\tau \int d^3x \left[\frac{Z_A - 1}{2}(\partial_\tau\phi)^2 + \frac{Z_B - 1}{2}(\partial_\tau\lambda)^2 + (Z_C - 1)\partial_\tau\phi\partial_\tau\lambda\right]
\end{equation}

where the Z-factors are chosen to cancel the $1/\varepsilon$ poles:
\begin{align}
Z_A - 1 &= -\frac{[V'''(\phi_0)]^2}{32\pi^2\varepsilon} \\
Z_B - 1 &= -\frac{g^2}{32\pi^2\varepsilon} \\
Z_C - 1 &= -\frac{g V'''(\phi_0)}{16\pi^2\varepsilon}
\end{align}

After renormalization, the finite parts of the coefficient functions become:
\begin{align}
A_{ren}(\phi_0) &= \frac{[V'''(\phi_0)]^2}{32\pi^2} \ln\left(\frac{M_{eff}^2}{\mu^2}\right) \\
B_{ren}(\phi_0) &= \frac{g^2}{32\pi^2} \ln\left(\frac{M_{eff}^2}{\mu^2}\right) \\
