\draw[scale=1, domain=-1:1.5, smooth, variable=\x, blue, thick] plot ({\x}, {ln(\x+1.12)});
\node[black!60!green] at (-1,-0.5) [left] {$T(Y_{i})=X_{i}'\beta+\eps_{i} $};
