\label{fig:intui}
\end{figure}

Concavity of $T(\cdot)$ implies that $Y_{k}-Y_{j}>Y_{j}-Y_{i}$. Note that $T(Y_{k})-T(Y_{j})=T(Y_{j})-T(Y_{i})$ is equivalent to $(X_{k}-X_{j})'\beta +\eps_{k}-\eps_{j}= (X_{j}-X_{i})'\beta +\eps_{j}-\eps_{i}$. Hence, ``on average'' equally spaced $T(Y)$'s mean equally spaced index values $X'\beta$. Therefore, we can detect deviations from concavity by considering the following criterion:
\begin{gather*} 
-\frac{1}{n(n-1)(n-2)}\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} \mathbbm{1}\{Y_{k}-Y_{j}<Y_{j}-Y_{i} \}\mathbbm{1}\{X_{kj}'\beta = X_{ji}'\beta\}
\end{gather*}
where $X_{ji} \equiv X_{j}-X_{i}$.

In order to make this criterion operational with continuous distribution of $X'\beta$ (which is required for identification) we need to replace the last indicator function with a smooth kernel $K_{h}(\cdot) = h^{-1}K(\cdot/h)$ and $\beta$ with its estimator $\hat{\beta}$:
\begin{gather*} 
-\frac{1}{n(n-1)(n-2)}\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} \mathbbm{1}\{Y_{k}-Y_{j}<Y_{j}-Y_{i} \}K_{h}\left(X_{kj}'\hat{\beta} - X_{ji}'\hat{\beta}\right)
\end{gather*}
Deviations from convexity can be detected in a similar fashion. Finally, we can combine both criterion functions to detect deviations from linearity:
\begin{gather} 
U_{n}=\frac{1}{n(n-1)(n-2)}\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}\left(X_{kj}'\hat{\beta} - X_{ji}'\hat{\beta}\right)
\end{gather}
Here, very negative values of the objective function signify convexity and large positive values mark concavity. Outside testing, one may use the above measure itself to characterise an ``average'' curvature of function $T$, e.g. large positive values suggest that the function is predominantly concave.

Note that our test requires only one-dimensional kernel smoothing, thus it does not suffer from the curse of dimensionality. Also, unlike the specification test in \cite{szydlowski20} it does not require estimation of the transformation function, a computationally intense task itself.

\section{Formal definition and asymptotic theory}\label{formal}

\subsection{Global test}

As the probability limit of the criterion functions introduced in the previous section depends on the extent of concavity, but these functions are asymptotically centred at known values under linearity, we form our procedure as a test of:
\begin{align*}
H_0:
\begin{cases}
\text{$T(\cdot)$ is concave} \\
\text{$T(\cdot)$ is linear} \\
\text{$T(\cdot)$ is convex} \\
\end{cases}
 \qquad vs \qquad
H_{A}: 
\begin{cases}  
\text{$T(\cdot)$ is non-concave} \\
\text{$T(\cdot)$ is non-linear} \\
\text{$T(\cdot)$ is non-convex} \\
\end{cases}
\end{align*}
depending on the question of interest.  We will use the test statistic 
\begin{gather*}
S_{n}=\sqrt{n} U_{n} 
\end{gather*}
and reject the null hypothesis at level $\alpha$ if $S_{n}<c_{\alpha}, |S_{n}|>c_{1-\alpha/2}$ or $S_{n}>c_{1-\alpha}$ depending on $H_{0}$, respectively, where $c_{\alpha}$ denotes an $\alpha$ quantile from an appropriate asymptotic distribution. 

Define $\eps_{ji}=\eps_j - \eps_i$. Proposition \ref{prop:plim} justifies our testing strategy.

\begin{proposition} \label{prop:plim}
Define $f_{\Delta \eps}(\cdot,\cdot)$ to be the joint distribution of $(\eps_{ji}, \eps_{kj})$. Assume that $\{(X_{i},Y_{i})\}_{i=1}^n$ are i.i.d and that $f_{\Delta \eps}(\eps^{\Delta}_1,\eps^{\Delta}_2)= f_{\Delta \eps}(\eps^{\Delta}_2,\eps^{\Delta}_1)$ for all $(\eps^{\Delta}_1,\eps^{\Delta}_2)$. Then, as $n\to \infty$, $U_{n} \to^{p} \theta$ where:
%\begin{enumerate}[(i)]
%\item 
(i) $\theta\geq 0$ if $T(\cdot)$ is globally concave, 
%\item 
(ii) $\theta = 0$ if $T(\cdot)$ is globally linear, 
%\item 
(iii) $\theta\leq 0$ if $T(\cdot)$ is globally convex.
%\end{enumerate}
\end{proposition}

\begin{proof}
Let $f_{\xi\xi}(\cdot,\cdot)$ denote the joint distribution of $(X_{ji}'\beta, X_{kj}'\beta)$.  By 
standard arguments:
\begin{gather*}
U_{n} \to^{p}  \quad \int_{-\infty}^{+\infty} E[\mathbbm{1}\{Y_{i}<Y_{j}<Y_{k}\}sgn(Y_{k}-2Y_{j}+Y_{i})|X_{kj}'\beta=X_{ji}'\beta=\xi] f_{\xi\xi}(\xi,\xi)d\xi 
\end{gather*}
and we can write:
\begin{align*}
E[\mathbbm{1} & \{Y_{i}<Y_{j}<Y_{k}\}  sgn(Y_{k}-2Y_{j}+Y_{i})|X_{kj}'\beta = X_{ji}'\beta=\xi] = \\
&=  E[sgn(Y_{k}-2Y_{j}+Y_{i})|Y_{i}<Y_{j}<Y_{k}, X_{kj}'\beta=X_{ji}'\beta =\xi]P(Y_{i}<Y_{j}<Y_{k}, X_{kj}'\beta=X_{ji}'\beta=\xi) \\
& \equiv \tilde{\theta} P(Y_{i}<Y_{j}<Y_{k}, X_{kj}'\beta=X_{ji}'\beta=\xi)
\end{align*}
Further: 
\begin{align*}
\tilde{\theta} &= P(Y_{k}-2Y_{j}+Y_{i}>0|Y_{i}<Y_{j}<Y_{k}, X_{kj}'\beta =X_{ji}'\beta=\xi) \\
& \qquad \qquad \qquad \qquad  - P(Y_{k}-2Y_{j}+Y_{i}<0|Y_{i}<Y_{j}<Y_{k}, X_{kj}'\beta=X_{ji}'\beta=\xi) \\
& \equiv (1) - (2) 
\end{align*}
and the sign of the probability limit of $U_{n}$ is determined by the sign of $\tilde{\theta}$ (for all $\xi$). For simplicity let $\Xi$ denote the conditioning event in the probabilities above and note that this event is equivalent to $\{\eps_{ji}>-\xi, \eps_{kj}>-\xi, X_{kj}'\beta=X_{ji}'\beta=\xi\}$.  

(i) We will show that $(1)\geq (2)$ under concavity of $T$ (i.e. convexity of $T^{-1}$). 
Denote $a=X_{j}'\beta+\eps_{j}$, $b=X_{i}'\beta+\eps_{i}$ and $\Delta = \xi + \eps_{kj}$. Note that the conditioning event $Y_{i}<Y_{j}<Y_{k}$ implies that $\Delta>0, a-b>0$ by monotonicity of $T$. We can rewrite the event $Y_{k}-2Y_{j}+Y_{i}>0$ as:
\begin{gather*}
T^{-1}(a+\Delta)-T^{-1}(a)>T^{-1}(a)-T^{-1}(b)
\end{gather*}
Conditional on $\Xi(\xi)$ this event is implied by $\eps_{kj}>\eps_{ji}$. To see that observe that the latter event is implied by $\Delta>a-b$, which under convexity of $T^{-1}$ (i.e. concavity of $T$)  gives the desired result. 
Thus, we have:
\begin{gather*}
P(Y_{k}-2Y_{j}+Y_{i}>0|\Xi) \geq P(\eps_{kj}>\eps_{ji}|\Xi).
\end{gather*}
On the other hand, $Y_{k}-2Y_{j}+Y_{i}<0 \iff T^{-1}(a+\Delta)-T^{-1}(a)<T^{-1}(a)-T^{-1}(b)$, which under concavity implies $\eps_{kj}< \eps_{ji}$ as we need $\Delta<a-b$ for this event to occur and by definition $\Delta = a-b +\eps_{kj}-\eps_{ji}$. Hence:
\begin{gather*}
P(Y_{k}-2Y_{j}+Y_{i}<0|\Xi) \leq P(\eps_{kj}<\eps_{ji}|\Xi).
\end{gather*}
which implies $\tilde{\theta} \geq 2 P(\eps_{kj}>\eps_{ji}|\Xi) - 1$ and in order to show that $\tilde{\theta} \geq 0$ we need $P(\eps_{kj}<\eps_{ji}|\Xi)=0.5$ but that follows from symmetry of $f_{\Delta \eps}(\cdot,\cdot)$ along the 45$^{\circ}$ line.

(ii) It is enough to note that if $T$ is linear $P(Y_{k}-2Y_{j}+Y_{i}<0|\Xi) = P(\eps_{kj}<\eps_{ji}|\Xi)$, which implies $\tilde{\theta}=0$.

(iii) This part follows from an argument mirroring the one in (i).
\end{proof}

\begin{remark}
By direct calculation $f_{\Delta \eps}(\eps^{\Delta}_1,\eps^{\Delta}_2) = \int f(\eps - \eps^{\Delta}_1)f(\eps)f(\eps + \eps^{\Delta}_2) d\eps$. Therefore, $f_{\Delta \eps}(\eps^{\Delta}_1,\eps^{\Delta}_2)$ is symmetric along the 45$^{\circ}$ line if the probability density function of $\eps$, $f$, is symmetric around zero. Note that symmetry of the error term distribution is assumed in \cite{abrevaya_jiang05}.
\end{remark}

\begin{remark}
If we defined our test statistic using two independent pairs of observations, namely:
\small
\begin{gather*}
\tilde{S}_{n}=\frac{\sqrt{n} }{n(n-1)(n-2)(n-3)}\sum_{i\neq j \neq k \neq l} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k}<Y_{m} \} sgn(Y_{m}-Y_{k}-Y_{j}+Y_{i})K_{h}\left((X_{mk}-X_{ji})'\hat{\beta}\right)
\end{gather*}
\normalsize 
the requirement for symmetry of $f_{\Delta \eps}(\eps^{\Delta}_1,\eps^{\Delta}_2)$ could potentially be dropped. This would, however, come at the increased computational cost as we have a 4-th order U statistic now. Also as we require four observations on $Y$ with approximately equally spaced index values $X'\beta$ instead of triples in our original statistic, the test based on $\tilde{S}_{n}$ is likely to have lower finite sample power than our baseline test.
\end{remark}

In order to obtain critical value for our tests we will assume that the model under the null hypothesis is linear. This is the worst-case $H_{0}$ for testing concavity/convexity as any small local deviation from linearity violates the hypothesis. This can also be seen from the proof of Proposition \ref{prop:plim}. In order to derive the asymptotic distribution of our statistic we make the following assumptions.

\begin{assumption}
\label{A1}
%\textbf{\emph{(DGP)}}
\begin{enumerate}[(a)]
\item The kernel $K(\cdot)$ is a bounded, nonnegative, symmetric, twice continuously differentiable function with support on $[-1,1]$ and uniformly bounded derivatives satisfying: \label{A1a}
\begin{enumerate}[(i)]
\item $\int K(s) ds = 1$,
\item $\int s^{2} K(s) ds < \infty$.
\item  \label{A1aiii} Let $\mathcal{K}$ be the antiderivative of $K$. We have: 
\begin{gather*}
\int \int K(s_1)K(s_2) [\mathcal{K} (2s_1-s_2) + 2 \mathcal{K} (2s_2-s_1)] s_1 d s_1 d s_2 > 0
\end{gather*}
\end{enumerate}
\item $h (\log n)^5 \to 0$ and 
$n h^3 \to \infty$ as $n\to \infty$. \label{A1b} 
\item Conditional on the remaining regressors, the distribution of the first element of $X$ is absolutely continuous with respect to the Lebesgue measure, with bounded and twice continuously differentiable density and uniformly bounded second derivatives. Each element of $X$ has a finite fourth moment. \label{A1c}
\item The density of $\eps$ is bounded and twice continuously differentiable, the derivatives are uniformly bounded. 
\item The estimator of $\beta$ satisfies:
$\hat{\beta}-\beta = \frac{1}{n} \sum_{i=1}^{n}\Omega(X_{i}, Y_i) + o_{p}(n^{-1/2})$,
where 
$\beta$ is the \emph{plim} of $\hat{\beta}$, $E[\Omega(X_{i}, Y_i)]=0$ and each element of $\Omega$ has a finite fourth moment and is continuous in the second argument. \label{A1d}
\end{enumerate}  
\end{assumption}   

Assumption \ref{A1}\eqref{A1a}(iii) is nonstandard. It is not used for our global test, $S_n$, in this section but is needed for our local test in the next section to have power. It is satisfied by frequently used kernels like standard normal or Epanechnikov (with integral taking values 0.0072 and 0.0177, respectively). The bandwidth rate condition in Assumption \ref{A1}\eqref{A1b} is rather weak and allows standard ``rule-of-thumb'' bandwidth choice $h \sim n^{-1/5}$. Assumption \ref{A1}\eqref{A1d} is satisfied by a wide range of estimators including the OLS estimator in the linear model, Han's MRC or Ichimura's semiparametric least squares (see e.g. appendix in \cite{szydlowski20} for discussion). 

Let $\xi_{ji}$ denote the index $X_{ji}'\beta$ and $f_{\xi|\xi}$ denote the density of $\xi_{kj}$ given $\xi_{ji}$. Define:
\begin{align*}
H(Y_{i},X_{i},\xi_{ji},\xi_{kj}) &= 2E[\mathbbm{1}\{Y_{i}<Y_{j}<Y_{k}\}sgn(Y_{k}-2Y_{j}+Y_{i})|Y_{i},X_{i},\xi_{ji},\xi_{kj}]\\
& \quad+2E[\mathbbm{1}\{Y_{j}<Y_{i}<Y_{k}\}sgn(Y_{k}-2Y_{i}+Y_{j})|Y_{i},X_{i},\xi_{ji},\xi_{kj}]\\
& \quad +2E[\mathbbm{1}\{Y_{j}<Y_{k}<Y_{i}\}sgn(Y_{i}-2Y_{k}+Y_{j})|Y_{i},X_{i},\xi_{ji},\xi_{kj}]\\
\delta(Y_{i},X_{i},\xi_{ji},\xi_{kj}) &= 3 H(Y_{i},X_{i},\xi_{ji},\xi_{kj})f_{\xi|\xi}(\xi_{kj}|\xi_{ji}=(X_{j}-X_{i})'\beta) \\
G(\xi_{ji},\xi_{kj}) &= 6E[\mathbbm{1}\{Y_{i}<Y_{j}<Y_{k}\}sgn(Y_{k}-2Y_{j}+Y_{i})(X_{kj}-X_{ji})'|\xi_{ji},\xi_{kj}]\\
\mu(\xi_{ji},\xi_{kj}) &=  4G(\xi_{ji},\xi_{kj})f_{\xi|\xi}(\xi_{kj}|\xi_{ji})
\end{align*}
and let $\mu_{2}$ denote the derivative of $\mu$ with respect to the second argument.

\begin{theorem}\label{thm:global}
If Assumption \ref{A1} holds,
we have:
\begin{gather*}
\sqrt{n}(U_{n}-\theta) \to^{d} N(0,E[\psi_{i}^{2}])
\end{gather*}
where $\psi_{i}= E[\delta(Y_{i},X_{i},\xi_{ji},\xi_{ji})|Y_{i},X_{i}]- E[\mu_{2}(\xi_{ji},\xi_{ji})]\Omega(X_{i}, Y_i)$.
\end{theorem}

As linearity is the boundary case for testing $H_{0}$: $T(\cdot)$ is concave, or $H_{0}$: $T(\cdot)$ is convex, we will reject concavity if $S_{n}<c_{\alpha}$ and reject convexity if $S_{n}>c_{1-\alpha}$, where $c_{\alpha}$ denotes the $\alpha$ quantile from the normal asymptotic distribution. As typical with U-statistics, estimating the variance of the asymptotic distribution of $S_{n}$ is difficult. On the one hand, the plug-in estimator will involve estimating derivatives of conditional moments and distributions, which requires delicate choices of bandwidths and, essentially, calculation of higher order U-statistics. On the other hand, using the standardisation approach in \cite{ghosal_et_al00} will lead to a 5-th order U-statistic, which would be difficult to calculate with sample sizes typically encountered in applications.\footnote{Proceeding as there would involve calculating:
\scriptsize
\begin{align*}
\hat{\sigma}^{2} = \frac{1}{n(n-1)(n-2)(n-3)(n-4)}\sum_{i\neq j \neq k \neq l \neq m} &(\mathbbm{1}\{Y_{i}<Y_{j}<Y_{k}\}sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}\left(X_{kj}'\hat{\beta} - X_{ji}'\hat{\beta}\right)+\tilde{\mu}_{2}\Omega_{i})\\
&\times (\mathbbm{1}\{Y_{i}<Y_{l}<Y_{m}\}sgn(Y_{m}-2Y_{l}+Y_{i})K_{h}\left(X_{ml}'\hat{\beta} - X_{li}'\hat{\beta}\right)+\tilde{\mu}_{2}\Omega_{i})\\
& + \text{symmetric terms},
\end{align*}
\footnotesize
where $\tilde{\mu}_{2}$ is an estimator of $-E[\mu_{2}(\xi_{ji},\xi_{ji})]$ (which itself is a 3-rd order U statistic).
}
Thus, in Section \ref{sec:boot} we resort to bootstrap for calculating the critical value as bootstrapping involves only repeated calculation of a 3-rd order U-statistic, $U_{n}$, which we find computationally easier than the aforementioned methods. 

The global test introduced in this section only has power against global deviations from concavity/linearity/convexity and does not have power if the function is both convex and concave on different parts of the domain. Thus, it can be used as a first check -- for example, if the test rejects concavity the researcher concludes that the function cannot be globally concave. Failure to reject would, then, mean that one has to consider our local test described in the next section, in order to verify if indeed the function is globally concave.

\subsection{Local test}
The main idea of the local test is to consider only triples of the kind portrayed in Figure \ref{fig:intui} local to a point $y$ in the domain of the transformation function. In other words, we will check if the transformation function is concave/linear/convex locally around $y$. Local concavity may be of interest by itself. However, usually we are interested in verifying if the treatment effect is concave on the whole domain, thus we will take the minimum of the local statistics at different points $y$ to run the test. 

Formally, define:
\begin{align*}
U_{n}(y) = \frac{1}{n(n-1)(n-2)}\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} & sgn(Y_{k}-2Y_{j}+Y_{i})  K_{h}(Y_{i}-y)K_{h}(Y_{j}-y)\\
& \quad \quad \quad \quad \times K_{h}(Y_{k}-y)K_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right)
\end{align*}
where in practice the bandwidth used for $(Y_{i}-y)$ can be different than for $(X_{kj} - X_{ji})'\hat{\beta}$ but, in order to simplify exposition and mathematical arguments, we assume that both bandwidths are of the same order and denote both by $h$. Now our local test statistic for testing concavity is defined as:
\begin{gather*}
S_{n}^{conc} = \inf_{y \in \mathcal{Y}} \sqrt{nh} U_{n}(y) 
\end{gather*}  
where $\mathcal{Y}$ is a compact set, and the statistic for testing convexity is defined with $\sup$ replacing $\inf$ above. Linearity can be tested by replacing $U_{n}(y)$ with its absolute value. For the rest of the article we concentrate on $S_{n}^{conc}$ as results for testing convexity and linearity follow by very similar arguments.

Intuitively, low values of $S_{n}^{conc}$ show that there is a large deviation from concavity at some point $y$ and, hence, the treatment effects are not accelerating on the whole domain of the outcome.\footnote{Note that by the formulas in Example 1 concavity of $T$ is equivalent to convexity of the outcome in the treatment.} Therefore, the null hypothesis of concavity would be rejected if $S_{n}^{conc} < c_{\alpha}^{conc}$ where $c_{\alpha}^{conc}$ is an appropriate quantile from the asymptotic approximation to the distribution of our statistic. 

In order to obtain $c_{\alpha}^{conc}$ one could imagine proceeding as in \cite{ghosal_et_al00}: approximate the standardised U-statistic process $\sqrt{n} U_{n}(y)/\sigma_{n}(y)$, where $\sigma_{n}(y)$ is the estimator of the asymptotic variance, by a Gaussian process and then apply the extreme value theory in order to derive the distribution of the infimum. However, pursuing that approach is difficult in our setup for two reasons: 1) under $H_0$ we still have $E[U_n(y)]=O(h)$ rather than $o(h)$ therein, 2) as discussed above, estimating $\sigma_{n}(y)$ is computationally expensive. Instead we propose to use bootstrap to approximate $c_{\alpha}^{conc}$. 

Define:
\footnotesize
\begin{align*}
\phi_{i,n}(y) =& 6(E[ \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}(Y_{i}-y)K_{h}(Y_{j}-y)K_{h}(Y_{k}-y)K_{h}\left((X_{kj} - X_{ji})'\beta\right)|Y_{i},X_{i}]\\
&+E[ \mathbbm{1}\{Y_{j}<Y_{i}<Y_{k} \} sgn(Y_{k}-2Y_{i}+Y_{j})K_{h}(Y_{i}-y)K_{h}(Y_{j}-y)K_{h}(Y_{k}-y)K_{h}\left((X_{ki} - X_{ij})'\beta\right)|Y_{i},X_{i}]\\
&+E[ \mathbbm{1}\{Y_{j}<Y_{k}<Y_{i} \} sgn(Y_{i}-2Y_{k}+Y_{j})K_{h}(Y_{i}-y)K_{h}(Y_{j}-y)K_{h}(Y_{k}-y)K_{h}\left((X_{ik} - X_{kj})'\beta\right)|Y_{i},X_{i}]).
\end{align*}
\normalsize
The following asymptotic approximation will be useful in justifying our bootstrap procedure.

\begin{theorem}\label{thm:local}
If Assumption \ref{A1} holds, then:
\begin{gather*}
\sup_{y \in \mathcal{Y}}\left|U_{n}(y)  - E[U_n(y)] - \frac{1}{n} \sum_{i=1}^{n} \phi_{i,n}(y)\right| = o_{p}((nh)^{-1/2})
\end{gather*}
\end{theorem}  

An interesting consequence of this result is that the first-order term in the asymptotic approximation of the (centred) localised statistic does not depend on estimation of $\beta$, unlike the global test (cf. Theorem \ref{thm:global}).

\section{Bootstrap critical values}\label{sec:boot}

Our bootstrap procedure for obtaining the critical value for the global or local test is as follows:
\begin{enumerate}
\item Estimate $\beta$ (e.g. by OLS) and calculate the residuals $\hat{\eps}_{i} = Y_{i} - X_{i}'\hat{\beta}$.
\item For the global test: draw a random sample $\{v_i\}_{i=1}^{n}$ from a two point distribution with $P(v_{i}=-1)=P(v_{i}=1)=1/2$ and define $\eps_{i}^{*} =v_{i} \hat{\eps}_{i}$. For the local test: (a) draw $\{\eps_i^*\}_{i=1}^n$ with replacement from $\{\hat{\eps}_i\}_{i=1}^n$ or (b) follow the same procedure as for the global test. Then, generate $Y_{i}^*$ by: \label{boot2}
\begin{gather*}
Y_{i}^{*} = X_{i}'\hat{\beta} + \eps_i^*.
\end{gather*}
 \item Estimate $\beta$ (e.g. by OLS) using the bootstrap sample. Let the resulting estimate be denoted by $\beta^*$.
 \item Calculate the statistic $S_{n}$ or $S_{n}^{conc}$ on the bootstrap sample using $\beta^*$ instead of $\hat{\beta}$. Denote the resulting bootstrap statistics by $S_{n}^{*}$ and $S_{n}^{conc,*}$.
 \item Obtain the empirical distribution of $S_{n}^*$ and $S_{n}^{conc,*}$ by repeating steps 1-4 many times. Calculate the $\alpha$ quantiles of the empirical distribution of $S_{n}^*$ and $S_{n}^{conc,*}$ and denote them by $c_{\alpha}^{*}$ and $c_{\alpha}^{conc,*}$, respectively.  
\end{enumerate} 

Step two imposes the null hypothesis of linearity on the bootstrap sample so it ``recentres'' the bootstrap statistic on the linear case. Furthermore, sampling from a symmetric two point distribution in the wild bootstrap imposes symmetry of the error distribution in the bootstrap sample, thus implying that the assumption in Proposition \ref{prop:plim} is satisfied. 
Note that the jacknife multiplier bootstrap (JMB) of \cite{chen_kato20} will not work for the local test here (without modifications) as we have $E[U_n(y)]=O(h)$ even under the null so the JMB statistic will not be centred correctly.  
We assume an equivalent of Assumption \ref{A1}\eqref{A1d} for the bootstrap estimator $\beta^{*}$:
\begin{assumption}
\item The estimator of $\beta^*$ satisfies:
$\beta^* - \hat{\beta} = \frac{1}{n} \sum_{i=1}^{n}\Omega(X_{i}, Y_i^*) + o_{p}(n^{-1/2})$,
where 
$E[\Omega(X_{i}, Y_i^*)]=0$ has zero mean and each element of $\Omega$ has a finite fourth moment and is continuous in the second argument. 
\label{BA1d}
\end{assumption}
This assumption is satisfied in our leading case, when $\beta^*$ is estimated by OLS.


\begin{theorem}\label{thm:boot}
If Assumptions \ref{A1}-\ref{BA1d} hold,
then, if $T(\cdot)$ is linear:
\begin{gather*}
\lim_{n\to \infty} P\left(\sqrt{n}U_n \leq c_{\alpha}^{*}\right) = \alpha .
\end{gather*}
Moreover, we have:
\begin{gather*}
\lim_{n\to \infty} P(S_{n}^{conc} \leq c_{\alpha}^{conc,*}) = \alpha
\end{gather*}
(and equivalent result holds for a test of linearity or convexity). 
\end{theorem}

Theorem \ref{thm:boot} implies, for example, that we can reject global concavity of $T$, i.e. increasing treatment effect, when $S_{n}^{conc}<c_{\alpha}^{conc,*}$, and reject global linearity when $|S_{n}^{conc}|>c_{1-\alpha/2}^{conc,*}$. We prove validity of bootstrap in unconditional probability, which is a weaker result than the standard result conditional on the sample (see e.g. \cite{cavaliere_georgiev20} for discussion), as the fact that $E[U_n(y)] = O(h)$ under $H_0$ and the need to use parametric bootstrap complicates the analysis. The next theorem characterises alternatives for which our tests are consistent. 

Assume that $c^{conc,*}_{\alpha}$ is generated using method (a) in step 2 above (see Appendix \ref{app:wildboot} for the analysis with the wild bootstrap in (b)). Let $f_{xb}$ denote the pdf of $X_i'\beta$, where $\beta$ is the probability limit of our estimator $\hat{\beta}$, and $\mathbf{1} = [1 \quad  1 \quad  1]'$. Further, let $f_{\boldsymbol{\eps}}$ denote the joint distribution of $(\eps_i,\eps_j,\eps_k)$ and $\nabla f_{\boldsymbol{\eps}}$ denote its gradient and define $f_{\boldsymbol{\tilde{\eps}}}$,  $\nabla f_{\boldsymbol{\tilde{\eps}}}$, similarly for $\tilde{\eps} = Y -X'\beta$.

\begin{theorem}\label{thm:bootpwr}
If Assumptions \ref{A1}-\ref{BA1d} hold,
then, if $T(\cdot)$ is globally convex:
\begin{gather*}
\lim_{n\to \infty} P\left(\sqrt{n}U_n \leq c_{\alpha}^{*}\right) = 1.
\end{gather*}
Moreover, if $T(\cdot)$ is locally convex at some $y$, and the following condition holds: 
\scriptsize
\begin{align}
 \sup_{y\in \mathcal{Y}} \int \int& \nabla f_{\boldsymbol{\tilde{\eps}}} \begin{pmatrix} y -\zeta +\xi \\ y -\zeta  \\ y -\zeta -\xi \end{pmatrix}' \mathbf{1}  f_{xb}(\zeta-\xi)f_{xb}(\zeta)f_{xb}(\zeta+\xi) d \zeta d\xi -
 \sup_{y \in \mathcal{Y}} \int \int   \left\{ T'(y)^4 E_{|\zeta \xi}\left[\nabla f_{\boldsymbol{\eps}}   \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}  \right] ' \mathbf{1} \right. \nonumber \\
&\left. \qquad \qquad \qquad \qquad + 3T''(y)T'(y)^2 E_{|\zeta \xi}\left[f_{\boldsymbol{\eps}} \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix} \right]\right\} 
 f_{xb}(\zeta-\xi)f_{xb}(\zeta)f_{xb}(\zeta+\xi) d \zeta d\xi 
< 0  \label{eq:pwrcond}
\end{align}
\normalsize
where $E_{|\zeta \xi}[\cdot]$ denotes $E[\cdot| X_j'\beta = \zeta, X_{ji}'\beta = X_{kj}'\beta = \xi]$, then we have:
\begin{gather*}
\lim_{n\to \infty} P(S_{n}^{conc} \leq c_{\alpha}^{conc,*}) = 1
\end{gather*}
(and equivalent result holds for a test of linearity or convexity). 
\end{theorem}

The condition in \eqref{eq:pwrcond} is technical and it is not straightforward to find general sufficient conditions for it to hold as it depends not only on the shape of $T$ and the value of $(\beta - \beta_0)$ but also the distributions of $\epsilon$ and $X$. 
However, we can make the following observations. 

\begin{remark}
For testing linearity (\emph{vel} testing treatment effect heterogeneity), the condition would only require the expression in \eqref{eq:pwrcond} to be nonzero and, thus, should be satisfied generically for non-linear $T(y)$'s, and the test should be consistent against (almost) all nonlinear alternatives. 
\end{remark}

\begin{remark}
Theorem \ref{thm:bootpwr} shows the cost of using a simple bootstrap test that avoids estimation of the transformation function, in particular the fact that our bootstrap does not correctly approximate the error distribution $f$ but rather distribution of OLS residuals, $\tilde{\eps}$. The latter distribution depends on the distribution of $X$ and on $T$, complicating the power properties of the test. In principle, one could try to estimate $T'$ and $\nabla f_{\boldsymbol{\eps}}$ and approximate the term:

\scriptsize
\begin{gather*}
 \sup_{y \in \mathcal{Y}} \int \int  T'(y)^4 E_{\zeta \xi}\left[\nabla f_{\boldsymbol{\eps}}   \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}  ' \mathbf{1} \right]f_{xb}(\zeta-\xi)f_{xb}(\zeta)f_{xb}(\zeta+\xi) d \zeta d\xi 
\end{gather*}
\normalsize
by a bootstrap procedure, making sure that condition \eqref{eq:pwrcond} would be satisfied.  However, this approach would substantially complicate the calculation of the critical value as estimators of $T$ and $f$ in the transformation model often involve non-smooth criterion functions and do not readily offer estimates of the derivatives (e.g. \cite{chen02}).
Thus, for practical reasons we prefer our current approach, even though it carries a cost in terms of power of the tests for concavity and convexity. 
\end{remark}

\begin{remark}
One can remove the terms $X'(\beta-\beta_0)$ and the associated expectation from \eqref{eq:pwrcond} by replacing the OLS estimator of $\beta$ in Step 1 of our bootstrap by the estimator in \cite{cavanagh_sherman98}. Further, at an additional computational cost one could also estimate $T$ and use semiparametric residuals: $\hat{\eps}_i = \hat{T}(Y_i) - X_i'\hat{\beta}$ in our bootstrap. We look at the latter case in Appendix \ref{app:MCnpar} where we show that the finite sample performance of such test does not dominate our local test. 
\end{remark} 

Finally, let us note that the computation of the local statistic involves evaluating a third order U-statistic at different points $y$ and, hence, takes significantly longer to compute than the global statistic. In practice, we recommend running the global test first and then proceed with the local test if the null hypothesis cannot be rejected in the first step.

\section{Monte Carlo simulations}\label{MC}
The data is generated from the following five models: 
\begin{align*}
Y &= X + \eps & \text{(D0)}\\
\log(Y + 2.12) - \log(2.12) &= X + \eps & \text{(D1)}\\
\frac{1}{13}\sinh(2Y) &= X + \eps & \text{(D2)}\\
\log(2.12) - \log(2.12-Y) &= X + \eps & \text{(D3)} \\
5 \tanh(0.5Y)& =  X + \eps & \text{(D4)} 
\end{align*}
where 
we draw $X$ and $\eps$ from the standard normal distribution. Note that D0 is the worst-case model in the null hypothesis, D1 imposes concavity of the transformation, D3 convexity and D2 and D4 are neither concave or convex. 

