\section{Proofs} \label{proofs}
Let
%\begin{gather*}
$\mathcal{G} = \{g_{y}(w_1,w_2,\ldots,w_m):  y \in \mathcal{Y} \subset \mathbb{R}\}$
%\end{gather*}
be a family of symmetric, real-valued functions defined on $\mathcal{W}^m$. We will use the operator notation common in the U-statistics literature. 
For example, for the case of $m=2$ we will have $P^0h = h$, $P^2h = \int \int g(w_1,w_2) dP(w_1) dP(w_2)$, $P_n g (w_1)=1/n \sum_{i=1}^n g(w_1,W_i)$  etc. We say that a symmetric function $g$ is $P$-canonical if $Pg(w_1,\ldots,w_{m-1},\cdot)=0$ for almost all $w_1,\ldots, w_{m-1}$.

Let $\|\cdot\|_{\mathcal{G}} \equiv \sup_{g \in \mathcal{G}}\|\cdot\|$ where $\|\cdot\|$ is the Euclidean norm and $\|\cdot\|_{\infty}, \|\cdot\|_{P,q}$ denote the sup and the $L_{q}(P)$ norm, respectively. Define a $U$-process:
\begin{gather*}
U_n^{(m)} g = \frac{(n-m)!}{n!} \sum_{\text{$i_1, i_2,\ldots,i_m$ distinct}} g(W_{i_1},W_{i_2},\ldots,W_{i_m})
\end{gather*}
Furthermore, define
\begin{gather*}
\pi_{k,m}^{P}g(w_1,\ldots,w_k) = (\delta_{w_1} - P)\ldots(\delta_{w_k}-P)P^{m-k} g 
\end{gather*}
where $\delta_{w_1}g =  g(w_1,\cdot)$.

Let us draw $\eps^*_i$ independently of $X_i$ and across observations. Thus, using $w=(x,\eps)$ we define $P_n^* g (w_1)=1/n \sum_{i=1}^n g(w_1,(X_i,\eps_i^*))$ and
\begin{gather*}
U_n^{*(m)} g = \frac{(n-m)!}{n!} \sum_{\text{$i_1, i_2,\ldots,i_m$ distinct}} g((X_{i_1}, \eps_{i_1}^*), (X_{i_2}, \eps_{i_2}^*), \ldots, (X_{i_m}, \eps_{i_m}^*))
\end{gather*}

We will sometimes use the following stochastic order arithmetic, for a sequence $a_n$:
\begin{gather*}
o^*_p(a_n) + o_p(a_n) = o_p(a_n), \quad  O^*_p(a_n) + O_p(a_n) = O_p(a_n)
\end{gather*}
which follows from the Law of Iterated Expectations. See \cite{szydlowski20} for more discussion. We will also write $\lesssim$ for inequality up to a multiplicative constant where the constant does not depend on the sample size $n$ or the sample data (but may depend on $m$ and characteristics of $\mathcal{G}$).

Throughout the proofs $\beta$ denotes the probability limit of $\hat{\beta}$ both under the null hypothesis or under the alternative. 

\subsection{Useful lemmas}
\begin{lemma} \label{lem:SZ}
\begin{enumerate}[(a)]
\item \label{lem:SZa} Let $\mathcal{G}$ be a class of P-canonical, Euclidean functions with envelope $G$. Then:
\begin{align*}
P&\|U_n^{(m)} g\|_{\mathcal{G}} \lesssim n^{-m/2}\sqrt{P^{m}G^{2}},\\
P&\|U_n^{*(m)} g\|_{\mathcal{G}} \lesssim n^{-m/2}\sqrt{P^{m}G^{2}}.
\end{align*}
\item \label{lem:SZb} Let $\mathcal{G}_n$ be a sequence of subclasses of $\mathcal{G}$ such that $\sup_{g \in \mathcal{G}_n} P^m g^2 \to 0$ as $n\to \infty$. Then:
\begin{gather*}
P\|U_n^{(m)} g\|_{\mathcal{G}_n} = o(n^{-m/2}).
\end{gather*}
\end{enumerate}
\end{lemma}

\begin{proof}

First part of (a) and (b) follow from Lemma 2 (a)-(b) in \cite{szydlowski20} with $p=1$, taking $h(\cdot)=g(\cdot)/\sqrt{P^{m}G^{2}}$ for the first result. 

The second part of (a) extends Lemma 2 (c) in \cite{szydlowski20} to parametric bootstrap. We give a short proof below for general $p$, putting emphasis on parts that do not follow \emph{verbatim} from the proof therein.

We have:
\begin{gather}
U_n^{*(m)}g = \sum_{k=0}^m {{m}\choose{k}} U_n^{*(k)}\left( \pi_{k,m}^{P_n}g\right) \label{bootU}
\end{gather}
Let $W_i = (X_i,\eps_i)$ and $W_i^* = (X_i,\eps_i^*)$. Since $\eps_i^*$'s are i.i.d., $\{W_i^*\}_{i=1}^n$ constitutes and i.i.d. sample, decoupling an repeated application of Jensen's inequality gives:
 \begin{gather*}
 P\left\| U_n^{*(k)}\left( \pi_{k,m}^{P_n}g \right) \right\|^p_{\mathcal{G}}  \lesssim P \left\| \frac{(n-k)!}{n!} \sum_{\text{$i_1,\ldots,i_{k}$ distinct}} \epsilon_{i_1}^{(1)}\ldots \epsilon_{i_k}^{(k)} P_n^{m-k} g(W^{*(1)}_{i_1},\ldots,W^{*(k)}_{i_k}) \right\|^p_{\mathcal{G}} \equiv (\star)
 \end{gather*}
where $\{W^{*(k)}_i: i=1,\ldots,n\}_{k=1}^m$ are i.i.d. copies of $\{W^{*}_i: i=1,\ldots,n\}$, $\{\epsilon_i:i=1,\ldots,n\}$ denote a sequence of Rademacher random variables independent of $W_i^*$'s and $\{\epsilon_i^{(k)}:i=1,\ldots,n\}_{k=1}^m$ are independent copies of $\{\epsilon_i:i=1,\ldots,n\}$.

Introduce 
$Z^*_{i_1} = \sum_{\text{$i_2,\ldots,i_{k} \neq i_1$ distinct}} \epsilon_{i_2}^{(2)}\ldots \epsilon_{i_k}^{(k)} P_n^{m-k} g(W^{*(1)}_{i_1},\ldots,W^{*(k)}_{i_k})$
and let $P_X$ and $P_{|X}$ denote expectation operators w.r.t. and conditional on $\{X_i\}_{i=1}^{\infty}$. Note that conditional on $X$  and
$\{\epsilon_{i_2}^{(2)},\ldots ,\epsilon_{i_k}^{(k)}, W^{*(2)}_{i_2},\ldots,W^{*(k)}_{i_k}\}$, $Z^*_{i_1}$'s are bootstrap draws from the sample $\{Z_i:i=1,\ldots,n\}$ where
$Z_{i_1} =  \sum_{\text{$i_2,\ldots,i_{k} \neq i_1$ distinct}} \epsilon_{i_2}^{(2)}\ldots \epsilon_{i_k}^{(k)} P_n^{m-k} g(W_{i_1},W^{*(2)}_{i_2},\ldots,W^{*(k)}_{i_k})$. Now using repeatedly Proposition 2.2 in \cite{gine_zinn90} (note that $Z^*_{i}$'s follow the empirical law of $Z_i$, cond. on $X$), Jensen's inequality and finally the result in Lemma 2(a) of \cite{szydlowski20} we obtain:
\small
\begin{align*}
(\star) &= P_X P_{|X} \left\| \frac{(n-k)!}{n!} \sum_{i_1} \epsilon_{i_1}^{(1)} Z^*_{i_1} \right\|^p_{\mathcal{G}} \lesssim  P_X P_{|X} \left\| \frac{(n-m)!}{n!} \sum_{\text{$i_1,\ldots,i_{m}$ distinct}} N_{i_1}^{(1)}\ldots N_{i_m}^{(m)} g(W_{i_1},\ldots,W_{i_m}) \right\|^p_{\mathcal{G}} \\
&\equiv P \left\| \frac{(n-m)!}{n!} \sum_{\text{$i_1,\ldots,i_{m}$ distinct}} \tilde{g}((W_{i_1}, N_{i_1}^{(1)}),\ldots, (W_{i_m}, N_{i_m}^{(1)})) \right\|^p_{\mathcal{G}} = O(n^{-pm/2})(P^{m}\tilde{G})^{p/2} \lesssim O(n^{-pm/2})(P^{m}G)^{p/2}
\end{align*}
\normalsize
where $N_i$'s are independent Poisson random variables with parameter 1/2. This and \eqref{bootU} imply the final result:
\begin{gather*}
\left(P\|U_n^{*(m)} g\|_{\mathcal{G}}^p\right)^{1/p} = O(n^{-m/2})\sqrt{P^{m}G^{2}}.
\end{gather*}
Now the result in the Lemma follows from setting $p=1$.

\end{proof}

\begin{lemma} \label{lem:Gh}
Let $\mathcal{G}$ be a Euclidean class of functions with envelope $G$. We have for $r\leq m$:
\begin{align*}
P\left(\left\|U_n^{(m)}g - \sum_{k=0}^{r-1} {{m}\choose{k}} U_n^{(k)}\pi_{k,m}^{P}g\right\|_{\mathcal{G}}\right) &\lesssim n^{-r/2} \sqrt{P^{m}G^{2}}
\end{align*}
\end{lemma}
\begin{proof}
From Theorem A.1 in \cite{ghosal_et_al00} and the discussion that follows we have:
\begin{gather*}
P\left(\left\|U_n^{(m)}g - \sum_{k=0}^{r-1} {{m}\choose{k}} U_n^{(k)}\pi_{k,m}^{P}g\right\|_{\mathcal{G}}\right) \lesssim n^{-r/2} \sqrt{P^{m}G^{2}} \int_{0}^{1} \sup_{Q: \text{$Q$ discrete}} \log N(\varepsilon \|G\|_{Q,2},\mathcal{G},L_{2}(Q))^{r/2}d\varepsilon
\end{gather*}
where $N(\cdot)$ denotes a covering number as in the Definition 2.1.5 in \cite{van_der_vaart_wellner96}. The integral on the right-hand side is bounded as $\mathcal{G}$ is Euclidean (ibid., Ch.2).
\end{proof}


\begin{lemma} \label{lem:Ch}
Assume that:
\begin{enumerate}[(a)]
\item The functional $B: \mathcal{G} \to \mathbb{R}$ satisfies: there exists a countable subset $\mathcal{\bar{G}}$ of $\mathcal{G}$ such that for any $g\in \mathcal{G}$, there exists a sequence $\bar{g}_{m} \in \mathcal{\bar{G}}$  with $\bar{g}_{m} \to g$ pointwise and $B(\bar{g}_{m})\to B(g)$. \label{lem:ChA}
\item The class of functions $\mathcal{G}$ is Euclidean with a measurable envelope $G$ and constants $A>0$ and $v \geq 1$. \label{lem:ChB}
\item There exist constants $b\geq \sigma >0$ and $q \in [4,\infty)$ such that $\sup_{g \in \mathcal{G}} P|g|^{k} \leq \sigma^{2}b^{k-2}$ for $k=2,3,4$ and $\|G\|_{P,q} \leq b$. \label{lem:ChC}
\end{enumerate}
Let $\mathbb{G}_{n}=\sqrt{n}P_{n}$
and $\mathbb{G}_{P}$ denote a centred Gaussian process indexed by $\mathcal{G}$ with covariance function $E[\mathbb{G}_{P}f \times \mathbb{G}_{P}g]=Cov(f(W),g(W))$. Let $N_{B}(\varepsilon)$ denote the bracketing number of the class of functions $\mathcal{BG}=\{B(g): g \in \mathcal{G}\}$. 

Then for every $\gamma \in (0,1)$ there exists a random variable $Z$ 
that follows  the same distribution as $\|B(g) +\mathbb{G}_{P}g\|_{\mathcal{G}}$ 
, such that:
\begin{align*}
|\|B(g) + \mathbb{G}_{n}g\|_{\mathcal{G}} - Z| &= O_{p}\left(\frac{bK_{n}}{\gamma^{1/q}n^{1/2-1/q}} + \frac{(b\sigma^{2}K_{n}^{2})^{1/3}}{\gamma^{1/3}n^{1/6}}\right) 
\end{align*}
where $K_{n}$ is of order $\log N_{B}(\varepsilon) + \log n \vee \log(Ab/\sigma)$ and $K_{n}^{3} \leq n$.
\end{lemma}

\begin{proof}
This result follows directly from Theorem 2.1 in \cite{chernozhukov_et_al16} with one caveat. \cite{chernozhukov_et_al16} require $\mathcal{G}$ to be VC-type, i.e. 
\begin{gather*}
\sup_Q N(\varepsilon \|G\|_{Q,2},\mathcal{G},L_{2}(Q)) \leq (A/\varepsilon)^v \quad \forall 0< \varepsilon \leq 1
\end{gather*}
where $Q$ belongs to the set of finitely discrete probability measures (see their Definition 2.1), with constants $A, v$ such that $A\geq e$ and $v\geq 1$. But we assume a Euclidean property, which following p. 789 in \cite{nolan_pollard87}, implies:
\begin{gather*}
\sup_Q N(\varepsilon \|G\|_{Q,2},\mathcal{G},L_{2}(Q)) \leq \tilde{A} \varepsilon^{-v} \quad \forall 0< \varepsilon \leq 1
\end{gather*}  
Thus, Euclidean property implies the VC-type property, taking $A=\tilde{A}^{1/v}$ and $\tilde{A}$ large enough..
\end{proof}

\begin{lemma}\label{lem:int}
Let $K$ be a symmetric kernel function supported on $[-1,1]$ and $\mathcal{K}$ be its antiderivative. We have:
\small
\begin{align*}
\int \int \int &\mathbbm{1}\{s_{1}<s_{2}<s_{3}\} sgn(s_{3}-2s_{2}+s_{1})K(s_{1})K(s_{2})K(s_{3}) d s_{1} d s_{2} d s_{3} =0\\
b_K \equiv \int \int \int &\Bigg\{(\mathbbm{1}\{s_{1}<s_{2}<s_{3}\} + \mathbbm{1}\{s_{3}<s_{2}<s_{1}\}) sgn(s_{3}-2s_{2}+s_{1}) + \\
&(\mathbbm{1}\{s_{1}<s_{3}<s_{2}\} + \mathbbm{1}\{s_{2}<s_{3}<s_{1}\}) sgn(s_{2}-2s_{3}+s_{1}) + \\
&(\mathbbm{1}\{s_{2}<s_{1}<s_{3}\} + \mathbbm{1}\{s_{3}<s_{1}<s_{2}\}) sgn(s_{3}-2s_{1}+s_{2})\Bigg\}
s_1 K(s_{1})K(s_{2})K(s_{3}) d s_{1} d s_{2} d s_{3}\\
&=  -2 \left[\int \int K(s_1)K(s_2) [\mathcal{K} (2s_1-s_2) + 2 \mathcal{K} (2s_2-s_1)] s_1 d s_1 d s_2 \right] \\
\int \int \int & (\mathbbm{1}\{s_{1}<s_{2}<s_{3}\} + \mathbbm{1}\{s_{3}<s_{2}<s_{1}\}) sgn(s_{3}-2s_{2}+s_{1}) 
s_k s_l K(s_{1})K(s_{2})K(s_{3}) d s_{1} d s_{2} d s_{3} \\
&= 0
\end{align*}
for any $k, l \in \{1,2,3\}$. 
\normalsize
\end{lemma}

\begin{proof}
For simplicity we write $\int_{-1}^{1}\int_{-1}^{1}\int_{-1}^{1}$ as $\int_{-1}^{1}$. We have:
\small
\begin{align*}
\int_{-1}^{1} \mathbbm{1}\{s_{1}<s_{2}<s_{3}\} & sgn(s_{3}-2s_{2}+s_{1})K(s_{1})K(s_{2})K(s_{3}) d s_{1} d s_{2} d s_{3} \\
 &= \int_{-1}^{1} \mathbbm{1}\{s_{1}<s_{2}<s_{3}\}  sgn(s_{3}-2s_{2}+s_{1})K(-s_{1})K(-s_{2})K(-s_{3}) d s_{1} d s_{2} d s_{3} \\
 &= \int_{-1}^{1}\mathbbm{1}\{\tilde{s}_{1}>\tilde{s}_{2}>\tilde{s}_{3}\}  sgn(-\tilde{s}_{3}+2\tilde{s}_{2}-\tilde{s}_{1})K(\tilde{s}_{1})K(\tilde{s}_{2})K(\tilde{s}_{3}) d \tilde{s}_{1} d \tilde{s}_{2} d \tilde{s}_{3}\\
 &= -\int_{-1}^{1}\mathbbm{1}\{\tilde{s}_{3}<\tilde{s}_{2}<\tilde{s}_{1}\}  sgn(\tilde{s}_{1}-2\tilde{s}_{2}+\tilde{s}_{3})K(\tilde{s}_{1})K(\tilde{s}_{2})K(\tilde{s}_{3}) d \tilde{s}_{1} d \tilde{s}_{2} d \tilde{s}_{3}
\end{align*}
\normalsize
where the first equality follows from symmetry of $K$, second from change of variables and the third from $sgn(-x)=-sgn(x)$. Finally note that the last integral is equal to the initial one after renaming the variables, so the result follows.

For the second equation in the lemma, note that the first part of the integral is the same as the second one if we rename $s_2$ to $s_3$. We have:
\small
\begin{align*}
\int &\int (\mathbbm{1}\{s_{1}<s_{2}<s_{3}\} + \mathbbm{1}\{s_{3}<s_{2}<s_{1}\}) sgn(s_{3}-2s_{2}+s_{1})
K(s_{2})K(s_{3}) d s_{2} d s_{3}\\
&= \int_{s_1}^1 \int_{s_2}^1 \mathbbm{1}\{s_3 - 2 s_2 +s_1>0\} K(s_{2})K(s_{3}) d s_{3} d s_{2} - \int_{s_1}^1 \int_{s_2}^1 \mathbbm{1}\{s_3 - 2 s_2 +s_1 < 0\} K(s_{2})K(s_{3}) d s_{3} d s_{2}  \\
& \quad +  \int_{-1}^{s_1} \int_{-1}^{s_2} \mathbbm{1}\{s_3 - 2 s_2 +s_1>0\} K(s_{2})K(s_{3}) d s_{3} d s_{2} - \int_{-1}^{s_1} \int_{-1}^{s_2} \mathbbm{1}\{s_3 - 2 s_2 +s_1 < 0\} K(s_{2})K(s_{3}) d s_{3} d s_{2}  \\
& = \int_{s_1}^1 \int_{2 s_2 - s_1}^1 K(s_{2})K(s_{3}) d s_{3} d s_{2} - \int_{s_1}^1 \int_{s_2}^{2 s_2 - s_1} K(s_{2})K(s_{3}) d s_{3} d s_{2} 
+  \int_{-1}^{s_1} \int_{2 s_2 - s_1}^{s_2} K(s_{2})K(s_{3}) d s_{3} d s_{2} \\
& \quad - \int_{-1}^{s_1} \int_{-1}^{2 s_2 - s_1}  K(s_{2})K(s_{3}) d s_{3} d s_{2} = \frac{3}{2} - \mathcal{K}(s_1) - 2 \int_{-1}^{1} K(s_2) \mathcal{K}(2 s_2-s_1) d s_2  
\end{align*}
\normalsize
and, similarly,  
\small
\begin{align*}
\int &\int (\mathbbm{1}\{s_{2}<s_{1}<s_{3}\} + \mathbbm{1}\{s_{3}<s_{1}<s_{2}\}) sgn(s_{3}-2s_{1}+s_{2})
K(s_{2})K(s_{3}) d s_{2} d s_{3}\\
& = \int_{-1}^{s_1} \int_{2 s_2 - s_1}^1 K(s_{2})K(s_{3}) d s_{3} d s_{2} - \int_{-1}^{s_1} \int_{s_1}^{2 s_1 - s_2} K(s_{2})K(s_{3}) d s_{3} d s_{2} 
+  \int_{s_1}^1 \int_{2 s_1 - s_2}^{s_1} K(s_{2})K(s_{3}) d s_{3} d s_{2} \\
& \quad - \int_{s_1}^1 \int_{-1}^{2 s_1 - s_2}  K(s_{2})K(s_{3}) d s_{3} d s_{2} = 2 \mathcal{K}(s_1) - 2 \int_{-1}^{1} K(s_2) \mathcal{K}(2 s_1-s_2) d s_2  
\end{align*}
\normalsize
which, using $\int K(s) s ds = 0$, gives the expression for the second integral in the lemma:
\small
\begin{align*}
\int & \int -\left[ 3 + 2  \int_{-1}^{1} K(s_2) \mathcal{K}(2 s_1-s_2) d s_2 + 4 \int_{-1}^{1} K(s_2) \mathcal{K}(2 s_2-s_1) d s_2  \right]
s_1 K(s_{1})K(s_{2})K(s_{3}) d s_{1} d s_{2} d s_{3} \\
& = -2 \int \int K(s_1)K(s_2) [\mathcal{K} (2s_1-s_2) + 2 \mathcal{K} (2s_2-s_1)] s_1 d s_1 d s_2.
\end{align*} 
The last equality in the lemma follows from symmetry of $K$ by similar argument as the one above, using change of variables.

\end{proof}

