\end{lemma}

\begin{proof}
Note that $\mathcal{F}_{1}$, $\mathcal{F}_{2}$ and $\mathcal{F}_{3}$ are products of functions $\mathbbm{1}\{\boldsymbol{\cdot}'\beta +\boldsymbol{\cdot}>y\}$ and classes of functions of the form $ K\left(\frac{\boldsymbol{\cdot}'\beta+\boldsymbol{\cdot}-y}{h}\right)$, $ K'\left(\frac{\boldsymbol{\cdot}'\beta+\boldsymbol{\cdot}-y}{h}\right)$ or $ K''\left(\frac{\boldsymbol{\cdot}'\beta+\boldsymbol{\cdot}-y}{h}\right)$. The former class is Euclidean by Lemma 2.4 in \cite{pakes_pollard89} and the latter by Lemma 22 in \cite{nolan_pollard87}. As the product of Euclidean classes is Euclidean, the result follows. The form of the envelope follows from the fact that $K$ is supported on $[-1,1]$. 
\end{proof}

\section{Proof of Theorem \ref{thm:global}}
To simplify notation set $\theta=0$. The argument for $\theta \neq 0$ follows \emph{verbatim} by recentering the test statistic appropriately. Write $U_{n}$ as:
\footnotesize
\begin{align*}
U_{n} =& \frac{1}{n(n-1)(n-2)}\bigg\{\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}\left((X_{kj} - X_{ji})'\beta\right) &\text{(I)}\\
& + \sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K'_{h}\left((X_{kj} - X_{ji})'\beta\right)(X_{kj} - X_{ji})'(\hat{\beta}-\beta) &\text{(II)} \\
& + \sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K''_{h}\left((X_{kj} - X_{ji})'\tilde{\beta}\right)(\hat{\beta}-\beta)'(X_{kj} - X_{ji})(X_{kj} - X_{ji})'(\hat{\beta}-\beta)\bigg\} &\text{(III)} 
\end{align*}
\normalsize
where $\tilde{\beta}$ is between $\beta$ and $\hat{\beta}$.

Note that by Cauchy-Schwartz inequality the third term in this decomposition can be bounded as follows:
\footnotesize
\begin{gather*}
|(III)| \leq h^{-3}\|K''\|_{\infty} \|\hat{\beta}-\beta\|^{2} \left\| \frac{1}{n(n-1)(n-2)}\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})(X_{kj} - X_{ji})(X_{kj} - X_{ji})'\right\|
\end{gather*} 
\normalsize
Now $\|\hat{\beta}-\beta\|^{2} = O_{p}(n^{-1})$ by Assumption \ref{A1}\eqref{A1d} and the U-statistic on the right-hand side is $O_{p}(n^{-1/2})$ by Theorem 5.5.1A in \cite{serfling80}, which gives:
\begin{gather*}
(III) = O_{p}(n^{-3/2}h^{-3}) = o_{p}(n^{-1/2})
\end{gather*}
under our bandwidth conditions.

Further, using Assumption \ref{A1}\eqref{A1d} I can rewrite $(II)$ as:
\small
\begin{align*}
\frac{1}{n(n-1)(n-2)} &\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K'_{h}\left((X_{kj} - X_{ji})'\beta\right)(X_{kj} - X_{ji})'P_{n}\Omega = \\
&= \frac{1}{n(n-1)(n-2)(n-3)} \sum_{i\neq j \neq k \neq l} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K'_{h}\left((X_{kj} - X_{ji})'\beta\right)\\
& \quad \times (X_{kj} - X_{ji})'\Omega(X_l,Y_l) + o_{p}(n^{-1/2}).
\end{align*}
\normalsize

It remains to apply Lemma \ref{lem:Gh} to (I) and (II) with $r=2$ and $\mathcal{G}$ containing a single function. In order to do that, let $g^{I}$ and $g^{II}$ be symmetrised kernels of the U-statistics in $(I)$ and $(II)$. Note that $(I) = U_{n}^{(3)}g^{I}$ and $(II) = U_{n}^{4}g^{II} + o_p(n^{-1/2})$ and the envelopes satisfy:
\small
\begin{align*}
E(G^{I})^{2} &\lesssim h^{-2}E[K^2((X_{32}-X_{21})'\beta)/h)] = O(h^{-1})\\
E(G^{II})^2 &\lesssim h^{-4}E[(K'((X_{32}-X_{21})'\beta)/h))^2(X_{32}-X_{21})'\Omega_4] \\
& \leq  h^{-4}E[(K'((X_{32}-X_{21})'\beta)/h))^2(X_{32}-X_{21})'(X_{32}-X_{21})]E[\Omega_4'\Omega_4]   = O(h^{-3})
\end{align*}
\normalsize
which, using Lemma \ref{lem:Gh} gives:
\begin{gather*}
P\left(\left\|U_n^{(m)}(g^{I}+g^{II}) - 3P_n\pi_{1,3}^{P}g^{I} - 4P_n\pi_{1,4}^{P} g^{II}\right\|\right) = O(n^{-1}h^{-1/2} + n^{-1}h^{-3/2}) = o_{p}(n^{-1/2})
\end{gather*}
under our bandwidth conditions in Assumption \ref{A1}\eqref{A1b}.

Now by direct calculation, using change of variables, Taylor expansion and $\int K'(u) du = 0$, $\int K'(u) u du =-1$ we get $3\pi_{1,3}^{P}g^{I} = E[\delta(Y_{i},X_{i},\xi_{ji},\xi_{ji})|Y_{i},X_{i}]$, $4\pi_{1,4}^{P} g^{II} = - E[\mu_{2}(\xi_{ji},\xi_{ji})]\Omega(X_{i}, Y_i)$ and the result follows from the CLT.

\section{Proof of Theorem \ref{thm:local}}

Let $K_{h}(\mathbf{Y}-y)\equiv K_{h}(Y_{i}-y)K_{h}(Y_{j}-y)K_{h}(Y_{k}-y)$. Write $U_{n}(y)$ as:
\footnotesize
\begin{align}
& \frac{1}{n(n-1)(n-2)}\bigg\{\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}(\mathbf{Y}-y)K_{h}\left((X_{kj} - X_{ji})'\beta\right) &\text{(I)} \nonumber\\ 
& + \sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}(\mathbf{Y}-y)K'_{h}\left((X_{kj} - X_{ji})'\beta\right)(X_{kj} - X_{ji})'(\hat{\beta}-\beta) &\text{(II)} \nonumber\\ 
& + (\hat{\beta}-\beta)'\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}(\mathbf{Y}-y)K''_{h}\left((X_{kj} - X_{ji})'\tilde{\beta}\right)(X_{kj} - X_{ji})(X_{kj} - X_{ji})'(\hat{\beta}-\beta)\bigg\} &\text{(III)} \label{decomp}
\end{align}
\normalsize
where $\tilde{\beta}$ is between $\beta$ and $\hat{\beta}$.

First, we will show that $(III) = o_{p}(n^{-1/2})$ using Lemmas \ref{lem:SZ}-\ref{lem:Gh}. Define $g_{y}^{III}((X_i,Y_i),(X_j,Y_j),(X_k,Y_k))$ to be the symmetrised version of $\mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}(\mathbf{Y}-y)K''_{h}\left((X_{kj} - X_{ji})'\tilde{\beta}\right)(X_{kj} - X_{ji})(X_{kj} - X_{ji})'$. Its envelope is given by:
\small
\begin{align*}
G^{III} &= h^{-6} \|K\|^3_{\infty}\mathbbm{1}\{|y_1-y_2|<2h\} \mathbbm{1}\{|y_1-y_3|<2h\} \mathbbm{1}\{|y_2-y_3|<2h\}K''((x_{32}-x_{21})'\tilde{\beta}/h) \\
& \quad \qquad \qquad \hspace{10cm} \times (x_{32}-x_{21}) (x_{32}-x_{21})'   
\end{align*}
\normalsize

Let $f_{Y|X}$ denote the joint distribution of $(Y_1,Y_2,Y_3)$ given $(X_1,X_2,X_3)$. By standard calculation and Lemma \ref{lem:int}:
\small
\begin{align}
P^3 g_{y}^{III} & = hE\bigg[\left(\int \mathbbm{1}\{s_{1}<s_{2}<s_{3}\} sgn(s_{3}-2s_{2}+s_{1})K(\mathbf{s})\mathbf{s}' 
\nabla f_{Y|X}(\mathbf{y}|X) d\mathbf{s} \right) K''_{h}\left((X_{kj} - X_{ji})'\tilde{\beta}\right) \nonumber \\ 
& \quad \times (X_{kj} - X_{ji})(X_{kj} - X_{ji})' \bigg] + o(h) = O(h) \label{eq:EIII}
\end{align}
\normalsize

 Note that Lemma \ref{lem:Eucl} applies to the class of functions $\{g_{y}^{III}: y \in \mathcal{Y}\}$, thus this class is Euclidean. Further note that expectation of the square of the envelope of the $(l,m)$-th element of  $g_{y}^{III}$ is:
 \small
 \begin{align*}
 P^3 (G^{III}_{lm})^2 &\cong h^{-12} E[P(|Y_1-Y_2|<2h, |Y_1-Y_3|<2h, |Y_2-Y_3|<2h|X)K''((x_{32}-x_{21})'\tilde{\beta}/h)(X_{l,32}-X_{l,21})^2 \\
 & \quad \times (X_{m,32}-X_{m,21})^2] = O(h^{-9})  
 \end{align*}
 \normalsize
 using dominated convergence theorem, as $P(|Y_1-Y_2|<2h, |Y_1-Y_3|<2h, |Y_2-Y_3|<2h|X) = O(h^2)$ 
 and each element of $X$ has a finite fourth moment. Now Lemma \ref{lem:Gh} gives:
 \begin{gather}
 U_{n}^{(3)}g_{y}^{III} = P^3 g_{y}^{III} + 3 P_n \pi_{1,3}^P g_{y}^{III} +  O_p(n^{-1}h^{-9/2}). \label{eq:IIIdcmp}
 \end{gather}
 and by Lemma \ref{lem:SZ}:
 \begin{gather}
 P_n \pi_{1,3}^P g_{y}^{III} = O_p(n^{-1/2} h^{-7/2}) \label{eq:IIIfoterm}
  \end{gather}
  using the fact that the envelope of $\pi_{1,3}^P g_{y}^{III}$ satisfies: $P(\pi_{1,3}^P G^{III})^2 \cong h^{-8} P(|Y_2-Y_3|<2h) \cong h^{-7}$.

Now using \eqref{eq:EIII}, \eqref{eq:IIIdcmp}, \eqref{eq:IIIfoterm} and Assumption \ref{A1}\eqref{A1d} we can bound $(III)$ uniformly over $y$:
\begin{gather}
(III) \lesssim \| \hat{\beta}-\beta\|^2 ( O_{p}(h) + O_{p}(n^{-1/2}h^{-7/2}) + O_p(n^{-1}h^{-9/2})) = O_{p}(n^{-1}h + n^{-3/2}h^{-7/2} + n^{-2}h^{-9/2}) \label{eq:IIIfinal}
\end{gather} 
and this is $o_{p}((nh)^{-1/2})$ under our rate conditions. 

Further, let $g_{y}^{II}$ denote the symmetrised version of $\mathbbm{1}\{Y_{i}<Y_{j}<Y_{k} \} sgn(Y_{k}-2Y_{j}+Y_{i})K_{h}(\mathbf{Y}-y)K'_{h}\left((X_{kj} - X_{ji})'\beta\right)(X_{kj} - X_{ji})'\Omega(X_{l}, Y_l)$. Note that we have $(II) = U_{n}^{(4)}g_{y}^{II} + o_{p}(n^{-1/2})$. The envelope satisfies:
\begin{align*}
P^4(G^{II})^2 &\cong h^{-10} E[P(|Y_1-Y_2|<2h, |Y_1-Y_3|<2h, |Y_2-Y_3|<2h|X) K'((X_{32}-X_{21})'\beta /h) \\
 & \quad \hspace{4cm} \times ((X_{32}-X_{21})'\Omega_4)^2] = O(h^{-7}),
\end{align*}
where we have used the fact that $X$ and $\Omega$ have finite fourth moments, which by Lemma \ref{lem:Gh} 
implies:
 \begin{gather*}
 U_{n}^{(4)}g_{y}^{II} = P^4 g_{y}^{II} + 4P_n \pi_{1,4}^P g_{y}^{II} + {{4} \choose {2}} U_n^{(2)} \pi_{2,4}^P g_{y}^{II} + {{4} \choose {3}} U_n^{(3)} \pi_{3,4}^P g_{y}^{II} +  O_p(n^{-2}h^{-7/2}). \label{eq:IIdcmp}
 \end{gather*}
Now $P^4 g_{y}^{II}=0$ since $P\Omega=0$. Further, the envelopes of the second, the third and the fourth term above satisfy: $P(\pi_{1,4}G^{II})^2 = O(h^{2})$, $P(\pi_{2,4}G^{II})^2 = O(h^{-2})$ and $P(\pi_{3,4}G^{II})^2 = O(h^{-3})$  (where we used $\int K'(u) du =0$ and boundedness of the moments of $\Omega$ and $X$), which by Lemma \ref{lem:SZ} implies:
\begin{gather}
 U_{n}^{(4)}g_{y}^{II} = O_p(n^{-1/2}h + n^{-1}h^{-1} + n^{-3/2} h^{-3/2} +n^{-2}h^{-7/2})  = o_p((nh)^{-1/2}) \label{eq:IIfinal}
\end{gather}
 where the last equality follows from Assumption \ref{A1}\eqref{A1b}.

Additionally, if $g^{I}_{y}$ denotes the symmetrised version of the expression under the sum in (I), by similar reasoning as above we can show that its envelope satisfies:
\begin{align*}
P^3(G^{I})^2 &\cong h^{-8} E[P(|Y_1-Y_2|<2h, |Y_1-Y_3|<2h, |Y_2-Y_3|<2h|X) K((X_{32}-X_{21})'\beta/h)]  = O(h^{-5}),
\end{align*}
and we also have: $P(\pi_{2,3}^P G^{I})^2 = O(h^{-2})$, which by Lemmas  \ref{lem:SZ}-\ref{lem:Gh} and our rate conditions implies:
\begin{gather}
|U_{n}^{(3)}g_{y}^{I} - P^3 g_{y}^{I} - 3 P_n \pi_{1,3} g_{y}^{I}| =  O_p(n^{-1}h^{-3/2} + n^{-3/2}h^{-5/2}) = o_p((nh)^{-1/2}). \label{eq:Idcmp}
\end{gather}
uniformly over $y$.

Finally, \eqref{eq:IIIfinal}, \eqref{eq:IIfinal} and \eqref{eq:Idcmp} give the result of the theorem and the expression for $\phi_i$ follows by direct calculation.

\section{Proof of Theorem \ref{thm:boot}}

For the global statistic, showing that $\sqrt{n}(S_{n}^{*}-\theta)$ converges weakly to a normal random variable involves standard arguments so we skip it. Then, using this result and Theorem \ref{thm:global}, 
we obtain the first result in Theorem \ref{thm:boot}. 

For the local test we have the decomposition:
\scriptsize
\begin{align}
U&_n^*(y) = \frac{1}{n(n-1)(n-2)}\bigg\{\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}^*<Y_{j}^*<Y_{k}^* \} sgn(Y_{k}^*-2Y_{j}^*+Y_{i}^*)K_{h}(\mathbf{Y}^*-y)K_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right) &\text{(I)} \nonumber\\ 
& + \sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}^*<Y_{j}^*<Y_{k}^* \} sgn(Y_{k}^*-2Y_{j}^*+Y_{i}^*)K_{h}(\mathbf{Y}^*-y)K'_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right)(X_{kj} - X_{ji})'(\beta^*-\hat{\beta}) &\text{(II)} \nonumber\\ 
& + (\beta^*-\hat{\beta})'\sum_{i\neq j \neq k} \mathbbm{1}\{Y_{i}^*<Y_{j}^*<Y_{k}^* \} sgn(Y_{k}^*-2Y_{j}^*+Y_{i}^*)K_{h}(\mathbf{Y}^*-y)K''_{h}\left((X_{kj} - X_{ji})'\tilde{\beta}\right)(X_{kj} - X_{ji})(X_{kj} - X_{ji})'(\beta^* - \hat{\beta})\bigg\} &\text{(III)} \label{Bdecomp}
\end{align}
\normalsize
where $Y_i^* = X_i'\hat{\beta} + \eps^*_i$ and $\tilde{\beta}$ is between $\hat{\beta}$ and $\beta^*$.

We assume that $\eps^*_i$'s are drawn using the parametric bootstrap. The proof for wild bootstrap follows similar lines. The proof consists of three steps:
\begin{enumerate}
\item[Step 1.] Approximate $U_n^*(y)$ by $U_n^{\#}(y)$, where the latter statistic uses $Y_i^{\#} = X_i'\beta + \eps^{\#}_i$ and $\eps^{\#}_i$ is a bootstrap draw from $\tilde{\boldsymbol{\eps}} = \{\tilde{\eps}_i\}_{i=1}^n$ with $\tilde{\eps}_i = Y_i -X_i'\beta$.
\item[Step 2.] Show that a linear representation equivalent to the one in Theorem \ref{thm:local} holds for $U_n^{\#}(y)$ and approximate the test statistic $\sup_y  \sqrt{nh} U_n^{\#}(y)$, conditional on  $\{\tilde{\eps}_i\}_{i=1}^n$, by a Gaussian process.
\item[Step 3.] Approximate the sample statistic by a Gaussian process and show that, unconditionally, the difference between this process and the process in Step 2 is negligible. 
\end{enumerate}


\textbf{Step 1.} We will use Lemma \ref{lem:SZ} \eqref{lem:SZb} for
$U_n^{(3)} g^{I, diff}_{y, \hat{\beta}}, U_n^{(4)} g^{II, diff}_{y, \hat{\beta}}$ and $U_n^{(3)} g^{III, diff}_{y, \hat{\beta}}$ where:
\scriptsize
\begin{align*}
g^{I, diff}_{y, \hat{\beta}} =& \mathbbm{1}\{X_i'\hat{\beta} + \eps_i^*<X_j'\hat{\beta} + \eps_j^*<X_k'\hat{\beta} + \eps_k^* \} sgn(X_k'\hat{\beta} + \eps_k^*-2(X_j'\hat{\beta} + \eps_j^*)+X_i'\hat{\beta} + \eps_i^*)K_{h}(\mathbf{Y}^*-y)K_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right) \\
&- \mathbbm{1}\{X_i'\beta + \eps_i^{\#}<X_j'\beta + \eps_j^{\#}<X_k'\beta + \eps_k^{\#} \} sgn(X_k'\beta + \eps_k^{\#}-2(X_j'\beta + \eps_j^{\#})+X_i'\beta + \eps_i^{\#})K_{h}(\mathbf{Y}^{\#}-y)K_{h}\left((X_{kj} - X_{ji})'\beta\right)\\
g^{II, diff}_{y, \hat{\beta}} = & \mathbbm{1}\{X_i'\hat{\beta} + \eps_i^*<X_j'\hat{\beta} + \eps_j^*<X_k'\hat{\beta} + \eps_k^* \} sgn(X_k'\hat{\beta} + \eps_k^*-2(X_j'\hat{\beta} + \eps_j^*)+X_i'\hat{\beta} + \eps_i^*)K_{h}(\mathbf{Y}^*-y)K'_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right) \\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times (X_{kj} - X_{ji})' \Omega(X_l, X_l'\hat{\beta}+  \eps_l^*) \\
&- \mathbbm{1}\{X_i'\beta + \eps_i^{\#}<X_j'\beta + \eps_j^{\#}<X_k'\beta + \eps_k^{\#} \} sgn(X_k'\beta + \eps_k^{\#}-2(X_j'\beta + \eps_j^{\#})+X_i'\beta + \eps_i^{\#})K_{h}(\mathbf{Y}^{\#}-y)K'_{h}\left((X_{kj} - X_{ji})'\beta\right) \\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times (X_{kj} - X_{ji})' \Omega(X_l, X_l'\beta+  \eps_l^{\#})\\
g^{III, diff}_{y, \hat{\beta}} = & \mathbbm{1}\{X_i'\hat{\beta} + \eps_i^*<X_j'\hat{\beta} + \eps_j^*<X_k'\hat{\beta} + \eps_k^* \} sgn(X_k'\hat{\beta} + \eps_k^*-2(X_j'\hat{\beta} + \eps_j^*)+X_i'\hat{\beta} + \eps_i^*)K_{h}(\mathbf{Y}^*-y)K''_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right) \\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times (X_{kj} - X_{ji})(X_{kj} - X_{ji})' \\
&- \mathbbm{1}\{X_i'\beta + \eps_i^{\#}<X_j'\beta + \eps_j^{\#}<X_k'\beta + \eps_k^{\#} \} sgn(X_k'\beta + \eps_k^{\#}-2(X_j'\beta + \eps_j^{\#})+X_i'\beta + \eps_i^{\#})K_{h}(\mathbf{Y}^{\#}-y)K''_{h}\left((X_{kj} - X_{ji})'\beta\right) \\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times(X_{kj} - X_{ji})(X_{kj} - X_{ji})'
\end{align*}
\normalsize
Note that the functions above are indexed both by $y$ and $\beta$. In order to apply the lemma we will show that as $\|\hat{\beta} - \beta\|/h \to 0$ the variance of these functions converges to zero, uniformly over $y\in \mathcal{Y}$. 

Let $m_i \sim Multinomial(1; \frac{1}{n},\ldots,\frac{1}{n})$.  We can write $\eps_i^* = \hat{\eps}'m_i = (\tilde{\eps} -\mathbf{X}(\hat{\beta}-\beta))'m_i $ and $\eps^{\#}_i = \tilde{\eps}'m_i$. Firstly, we have:
\scriptsize
\begin{align*}
E&[\mathbbm{1}\{X_i'\hat{\beta} + \eps_i^*<X_j'\hat{\beta} + \eps_j^*<X_k'\hat{\beta} + \eps_k^* \} sgn(X_k'\hat{\beta} + \eps_k^*-2(X_j'\hat{\beta} + \eps_j^*)+X_i'\hat{\beta} + \eps_i^*)K_{h}(\mathbf{Y}^*-y)|\hat{\beta},\mathcal{X},m_i,m_j, m_k]
= \\
&\int E[\mathbbm{1}\{X_i'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_i<X_j'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_j<X_k'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_k \} sgn(X_k'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_k\\
&-2(X_j'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_j)+X_i'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_i)K_{h}\left(\begin{pmatrix} X_i'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_i \\ X_j'\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_j \\ X_k\hat{\beta} + (\tilde{\boldsymbol{\eps}} -\mathbf{X}(\hat{\beta}-\beta))'m_k \end{pmatrix}-y\right) f_{\tilde{\eps}'m}\left(\begin{pmatrix} \tilde{\boldsymbol{\eps}}'m_i \\ \tilde{\boldsymbol{\eps}}'m_j \\ \tilde{\boldsymbol{\eps}}'m_k  \end{pmatrix}{\Bigg |} \mathcal{X}\right) d\tilde{\eps} \\
&= \int \mathbbm{1}\{s_1<s_2<s_3\}sgn\{s_3-2s_2+s_1\}K(s_1)K(s_2)K(s_3)  f_{\tilde{\eps}'m}\left(\begin{pmatrix} s_1h +y - X_i'\hat{\beta} + (\mathbf{X}(\hat{\beta}-\beta))'m_i\ \\ s_2h +y - X_j'\hat{\beta} + (\mathbf{X}(\hat{\beta}-\beta))'m_j \\ s_3h +y - X_k'\hat{\beta} + (\mathbf{X}(\hat{\beta}-\beta))'m_k \end{pmatrix}{\Bigg |} \mathcal{X}\right) ds 
\end{align*}
\normalsize
and $h K_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right) = K\left( (X_{kj} - X_{ji})'\beta /h \right) + O(\|\hat{\beta}-\beta\|/h)$. Similarly:
\scriptsize
\begin{align*}
E&[\mathbbm{1}\{X_i'\beta + \eps_i^{\#}<X_j'\beta + \eps_j^{\#}<X_k'\beta + \eps_k^{\#} \} sgn(X_k'\beta + \eps_k^{\#}-2(X_j'\beta + \eps_j^{\#})+X_i'\beta + \eps_i^{\#})K_{h}(\mathbf{Y}^{\#}-y)|\mathcal{X},m_i,m_j, m_k]
= \\
& = \int \mathbbm{1}\{s_1<s_2<s_3\}sgn\{s_3-2s_2+s_1\}K(s_1)K(s_2 )K(s_3)  f_{\tilde{\eps}'m}\left(\begin{pmatrix} s_1h +y - X_i'\beta \\ s_2h +y - X_j'\beta \\ s_3h +y - X_k'\hat{\beta} \end{pmatrix}{\Bigg |} \mathcal{X}\right) ds 
\end{align*}
\normalsize
Thus, using  
$f(y+sh) = f(y) + O(sh)$, Lemma \ref{lem:int} and:
\footnotesize
\begin{align*}
 f_{\tilde{\eps}'m}&\left(\begin{pmatrix} s_1h +y - X_i'\hat{\beta} + (\mathbf{X}(\hat{\beta}-\beta))'m_i\ \\ s_2h +y - X_j'\hat{\beta} + (\mathbf{X}(\hat{\beta}-\beta))'m_j \\ s_3h +y - X_k'\hat{\beta} + (\mathbf{X}(\hat{\beta}-\beta))'m_k \end{pmatrix}  {\Bigg |} \mathcal{X}\right) = \\
 &=  f_{\tilde{\eps}'m}\left(\begin{pmatrix} s_1h +y - X_i'\beta \\ s_2h +y - X_j'\beta \\ s_3h +y - X_k'\beta \end{pmatrix}  {\Bigg |} \mathcal{X}\right) + \nabla  f_{\tilde{\eps}'m}\left(\begin{pmatrix} s_1h +y - X_i'\beta \\ s_2h +y - X_j'\beta \\ s_3h +y - X_k'\beta \end{pmatrix}  {\Bigg |} \mathcal{X}\right)'\begin{pmatrix} m_i'\mathbf{X} -X_i' \\ m_j'\mathbf{X} - X_j' \\ m_k'\mathbf{X} - X_k' \end{pmatrix} (\hat{\beta}-\beta) + O(\|(\hat{\beta}-\beta)\|^2)
\end{align*}
\normalsize
we obtain:
\begin{gather*}
\sup_y E\left[g^{I, diff}_{y, \hat{\beta}}\right]  = O(\|\hat{\beta}-\beta\| + h \|\hat{\beta}-\beta\| + \|(\hat{\beta}-\beta)\|^2) = o((nh)^{-1/2}) 
 \end{gather*}
 This allows us to define a P-canonical function $\tilde{g}^{I,diff}_{y, \hat{\beta}} =  g^{I, diff}_{y, \hat{\beta}} -  E\left[g^{I, diff}_{y, \hat{\beta}}\right]$ and write $U_n^{(3)} g^{I, diff}_{y, \hat{\beta}} = U_n^{(3)} \tilde{g}^{I, diff}_{y, \hat{\beta}} + o_p((nh)^{-1/2})$. 

 Furthermore, by similar calculation:
 \scriptsize
 \begin{align*}
 E&[\mathbbm{1}\{X_i'\hat{\beta} + \eps_i^*<X_j'\hat{\beta} + \eps_j^*<X_k'\hat{\beta} + \eps_k^* \} sgn^2(X_k'\hat{\beta} + \eps_k^*-2(X_j'\hat{\beta} + \eps_j^*)+X_i'\hat{\beta} + \eps_i^*)K^2_{h}(\mathbf{Y}^*-y)|\hat{\beta},\mathcal{X},m_i,m_j, m_k]
= \\
&= h^{-3} \int \mathbbm{1}\{s_1<s_2<s_3\}sgn^2\{s_3-2s_2+s_1\}K^2(s_1)K^2(s_2)K^2(s_3)  f_{\tilde{\eps}'m}\left(\begin{pmatrix} s_1h +y - X_i'\hat{\beta} - \mathbf{X}(\hat{\beta}-\beta)'m_i\ \\ s_2h +y - X_j'\hat{\beta} - \mathbf{X}(\hat{\beta}-\beta)'m_j \\ s_3h +y - X_k'\hat{\beta} - \mathbf{X}(\hat{\beta}-\beta)'m_k \end{pmatrix}{\Bigg |} \mathcal{X}\right) ds 
 \end{align*}
\normalsize
and 
\scriptsize
 \begin{align*}
 E&[\mathbbm{1}\{X_i'\hat{\beta} + \eps_i^*<X_j'\hat{\beta} + \eps_j^*<X_k'\hat{\beta} + \eps_k^* \} sgn(X_k'\hat{\beta} + \eps_k^*-2(X_j'\hat{\beta} + \eps_j^*)+X_i'\hat{\beta} + \eps_i^*)K_{h}(\mathbf{Y}^*-y) \\
 & \quad \times \mathbbm{1}\{X_i'\beta + \eps_i^{\#}<X_j'\beta + \eps_j^{\#}<X_k'\beta + \eps_k^{\#} \} sgn(X_k'\beta + \eps_k^{\#}-2(X_j'\beta + \eps_j^{\#})+X_i'\beta + \eps_i^{\#})K_{h}(\mathbf{Y}^{\#}-y)|\hat{\beta}, \mathcal{X},m_i,m_j, m_k]
= \\
&= h^{-3} \int \mathbbm{1}\{s_1<s_2<s_3\} \mathbbm{1}\{s_1 + X_i'(\hat{\beta}-\beta)/h +  (\mathbf{X}(\hat{\beta}-\beta))'m_i/h < s_2 + X_j'(\hat{\beta}-\beta)/h + (\mathbf{X}(\hat{\beta}-\beta))'m_j/h \\
&\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  < s_3 + X_k'(\hat{\beta}-\beta)/h + (\mathbf{X}(\hat{\beta}-\beta))'m_k/h\} \\
& \quad \times sgn\{s_3-2s_2+s_1\}  sgn\{s_3  + X_k'(\hat{\beta}-\beta)/h + (\mathbf{X}(\hat{\beta}-\beta))'m_k/h -2s_2  -2X_j'(\hat{\beta}-\beta)/h-2(\mathbf{X}(\hat{\beta}-\beta))'m_j/h\\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad + s_1 +X_i'(\hat{\beta}-\beta)/h +  (\mathbf{X}(\hat{\beta}-\beta))'m_i/h\} \\
& \quad \times K^2(s_1)K^2(s_2)K^2(s_3)  f_{\tilde{\eps}'m}\left(\begin{pmatrix} s_1h +y - X_i'\beta \ \\ s_2h +y - X_j'\beta  \\ s_3h +y - X_k'\beta \end{pmatrix}{\Bigg |} \mathcal{X}\right) ds + O(h^{-4} \|\hat{\beta} -\beta\|) \
 \end{align*}
\normalsize
which again implies that:
\begin{gather*}
 \sup_y E\left[h^4 \left(\tilde{g}^{I, diff}_{y, \hat{\beta}}\right)^2\right] \to 0 
\end{gather*}
 as $\|\hat{\beta} - \beta\|/h \to 0$. Finally, by Lemma \ref{lem:Eucl} the function class $\{\tilde{g}^{I, diff}_{y, \beta}: y \in \mathcal{Y}, \beta \in \Theta_{\beta}\}$ is Euclidean and we can apply Lemma \ref{lem:SZ}\eqref{lem:SZb} to show that:
\begin{gather*}
\sup_y \sup_{\|\hat{\beta} - \beta\|/h<\delta_n} | U_n^{(3)} g^{I, diff}_{y, \hat{\beta}} | = o_p(n^{-3/2} h^{-2})  +  o_p((nh)^{-1/2})= o_p((nh)^{-1/2})
\end{gather*}
for any $\delta_n \to 0$. 

Further, we have $E[g^{II, diff}_{y, \hat{\beta}}]=0$, $h^2 K'_{h}\left((X_{kj} - X_{ji})'\hat{\beta}\right) = K'\left( (X_{kj} - X_{ji})'\beta /h \right) + O(\|\hat{\beta}-\beta\|/h)$ and $E[((X_{kj}-X_{ji})'\Omega(X_l,X_l'\beta+\eps_l^{\#}))^2]<\infty$ using our assumption on the moments of $X$ and $\Omega$.  Thus, using continuity of $\Omega$ (see Assumption \ref{BA1d}), dominated convergence theorem and similar reasoning as above, we obtain $\sup_y E\left[h^7 \left(g^{II, diff}_{y, \hat{\beta}}\right)^2\right] \to 0$ as $\|\hat{\beta} - \beta\|/h \to 0$, which by Lemma \ref{lem:SZ}\eqref{lem:SZb} implies: 
\begin{align*}
\sup_y \sup_{\|\hat{\beta} - \beta\|/h<\delta_n} | U_n^{(4)} \tilde{g}^{II, diff}_{y, \hat{\beta}} | = o_p(n^{-2} h^{-7/2}) = o_p((nh)^{-1/2})
\end{align*}   

By similar reasoning as for $g^{I,diff}_{y,\hat{\beta}}$, we have $\sup_y E[g^{III, diff}_{y, \hat{\beta}}] = o((nh)^{-1/2})$ and $E\left[h^9 \left(\tilde{g}^{III, diff}_{y, \hat{\beta}}\right)^2\right] \to 0$ uniformly over $y$, where $\tilde{g}^{III, diff}_{y, \hat{\beta}}$ is a recentred version of $g^{III, diff}_{y, \hat{\beta}}$, which by Lemma  \ref{lem:SZ}\eqref{lem:SZb} implies:
\begin{align*}
\sup_y \sup_{\|\hat{\beta} - \beta\|/h<\delta_n} | U_n^{(3)} g^{III, diff}_{y, \hat{\beta}}| = o_p(n^{-3/2} h^{-9/2}) + o_p((nh)^{-1/2}).
\end{align*} 
Together with $\beta^*-\hat{\beta} = O_p^*(n^{-1/2}) =  O_p(n^{-1/2})$ this implies:
\begin{gather*}
\sup_y \sup_{\|\hat{\beta} - \beta\|/h<\delta_n} |(\beta^*-\hat{\beta})'U_n^{(3)} g^{III, diff}_{y, \hat{\beta}}(\beta^*-\hat{\beta})| = o_p(n^{-5/2} h^{-9/2}) = o_p((nh)^{-1/2}).
\end{gather*}

Finally, using Assumption \ref{BA1d} and putting all the results above together we obtain:
\begin{gather}
U_n^*(y) = U_n^{\#} g_y^{I} + U_n^{\#} g_y^{II} + (\beta^*-\hat{\beta})' U_n^{\#} g_y^{III} (\beta^*-\hat{\beta}) + o_p((nh)^{-1/2}). \label{eq:hashboot}
\end{gather}

\textbf{Step 2.} We will apply the second part of Lemma \ref{lem:SZ}\eqref{lem:SZa} and Lemma \ref{lem:Gh} in the same fashion as in the proof of Theorem \ref{thm:local}, the only difference being that now the error terms are drawn from the distribution of $\tilde{\eps}$ where $\tilde{\eps} = Y - X'\beta$, but still independently of $X$. 
Also note that:
\scriptsize
\begin{align*}
E& \mathbbm{1}\{X_i'\beta + \eps_i^{\#}<X_j'\beta + \eps_j^{\#}<X_k'\beta + \eps_k^{\#} \} sgn(X_k'\beta + \eps_k^{\#}-2(X_j'\beta + \eps_j^{\#})+X_i'\beta + \eps_i^{\#})K_{h}(\mathbf{Y}^{\#}-y)|X_i'\beta, X_j'\beta, X_k'\beta]= \\
&= E \left[ \mathbbm{1}\{X_i'\beta + \tilde{\boldsymbol{\eps}}'m_i<X_j'\beta + \tilde{\boldsymbol{\eps}}' m_j<X_k'\beta + \tilde{\boldsymbol{\eps}}' m_k \} sgn(X_k'\beta + \tilde{\boldsymbol{\eps}}'m_k-2(X_j'\beta + \tilde{\boldsymbol{\eps}}' m_j)+X_i'\beta + \tilde{\boldsymbol{\eps}}' m_i)  \vphantom{\begin{pmatrix} X_i'\beta + \tilde{\boldsymbol{\eps}}'m_i \\ X_j'\beta + \tilde{\boldsymbol{\eps}}'m_j \\ X_k'\beta + \tilde{\boldsymbol{\eps}}'m_k  \end{pmatrix}} \right. \\
& \left. \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times K_{h}\left(\begin{pmatrix} X_i'\beta + \tilde{\boldsymbol{\eps}}'m_i \\ X_j'\beta + \tilde{\boldsymbol{\eps}}'m_j \\ X_k'\beta + \tilde{\boldsymbol{\eps}}'m_k  \end{pmatrix} -y\right)\Bigg|X_i'\beta, X_j'\beta, X_k'\beta \right]=\\
& = E\left[\frac{1}{n^3} \sum_{l,p,q} \mathbbm{1}\{X_i'\beta + \tilde{\eps}_l<X_j'\beta + \tilde{\eps}_p<X_k'\beta + \tilde{\eps}_q \} sgn(X_k'\beta + \tilde{\eps}_q - 2(X_j'\beta + \tilde{\eps}_p)+X_i'\beta + \tilde{\eps}_l)  \vphantom{\begin{pmatrix} X_i'\beta + \tilde{\boldsymbol{\eps}}'m_i \\ X_j'\beta + \tilde{\boldsymbol{\eps}}'m_j \\ X_k'\beta + \tilde{\boldsymbol{\eps}}'m_k  \end{pmatrix}} \right. \\
& \left. \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times K_{h}\left(\begin{pmatrix} X_i'\beta + \tilde{\eps}_l \\ X_j'\beta + \tilde{\eps}_p \\ X_k'\beta + \tilde{\eps}_q  \end{pmatrix} -y\right)\Bigg|X_i'\beta, X_j'\beta, X_k'\beta \right]= \\
& = E\left[ \mathbbm{1}\{X_i'\beta + \tilde{\eps}_l<X_j'\beta + \tilde{\eps}_p<X_k'\beta + \tilde{\eps}_q \} sgn(X_k'\beta + \tilde{\eps}_q - 2(X_j'\beta + \tilde{\eps}_p)+X_i'\beta + \tilde{\eps}_l)  \vphantom{\begin{pmatrix} X_i'\beta + \tilde{\boldsymbol{\eps}}'m_i \\ X_j'\beta + \tilde{\boldsymbol{\eps}}'m_j \\ X_k'\beta + \tilde{\boldsymbol{\eps}}'m_k  \end{pmatrix}} \right. \\
& \left.  \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times K_{h}\left(\begin{pmatrix} X_i'\beta + \tilde{\eps}_l \\ X_j'\beta + \tilde{\eps}_p \\ X_k'\beta + \tilde{\eps}_q  \end{pmatrix} -y\right)\Bigg|X_i'\beta, X_j'\beta, X_k'\beta \right] + O(n^{-1})
\end{align*}
\normalsize
which gives $E[U_n^{\#} g_y^{I}] = \tilde{P}^3  g_y^{I} + O(n^{-1})$, where $\tilde{P}$ is the probability measure under which $Y_i = X_i\beta + \tilde{\eps}_i$ and $\tilde{\eps}_i$ is drawn independently of $X_i$ from $f_{\tilde{\eps}}$. 

This gives, uniformly over $y$:
\begin{align*}
(\beta^*-\hat{\beta})' U_n^{\#} g_y^{III} (\beta^*-\hat{\beta}) &= O_{p}(n^{-1}h + n^{-3/2}h^{-7/2} + n^{-2}h^{-9/2}) \\
U_n^{\#} g_y^{II} & = O_p(n^{-1/2}h + n^{-1}h^{-1} + n^{-3/2} h^{-3/2} +n^{-2}h^{-7/2}) \\
U_n^{\#} g_y^{I} &= \tilde{P}^3 g_{y}^{I} + 3 P_n^{\#} \pi_{1,3}^{\tilde{P}} g_{y}^{I} +  O_p(n^{-1}h^{-3/2} + n^{-3/2}h^{-5/2})
\end{align*}
and therefore:
\begin{gather}
U_n^*(y) = \tilde{P}^3 g_{y}^{I} + 3 P_n^{\#} \pi_{1,3}^{\tilde{P}}  g_{y}^{I} + o_p((nh)^{-1/2}). \label{eq:bootlin}
\end{gather}

Let $E_{|\boldsymbol{\tilde{\eps}}}$ denote the expectation conditional on $\boldsymbol{\tilde{\eps}}$. We will apply Lemma \ref{lem:Ch} conditionally on $\boldsymbol{\tilde{\eps}}$ with $\tilde{B}(y) = \sqrt{nh} \tilde{P}^3 g_{y}^{I}$ and $ \mathbbm{G}_P \phi_n^{\boldsymbol{\tilde{\eps}}}(y)$ where:\footnote{Note that the results in \cite{chernozhukov_et_al16} do not apply directly to our parametric bootstrap.}   
\footnotesize
\begin{align*}
\phi_n^{\boldsymbol{\tilde{\eps}}}(y) =& 3\sqrt{h} E_{|\boldsymbol{\tilde{\eps}}}[\mathbbm{1}\{X_i'\beta + \boldsymbol{\tilde{\eps}}'m_i <X_j'\beta + \boldsymbol{\tilde{\eps}}'m_j <X_k'\beta + \boldsymbol{\tilde{\eps}}' m_k \} sgn(X_k'\beta + \boldsymbol{\tilde{\eps}}' m_k-2(X_j'\beta + \boldsymbol{\tilde{\eps}}' m_j)+X_i'\beta + \boldsymbol{\tilde{\eps}}' m_i)\\
&  \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times K_{h}(\mathbf{Y}^{\#}-y) K_h((X_{kj}-X_{ji})'\beta)|X_i, m_i] + \textit{symmetric terms}.
\end{align*}
\normalsize
Let us first verify conditions of Lemma \ref{lem:Ch}. Condition \eqref{lem:ChA} is satisfied because $\tilde{P}^3 g_{y}^{I}$ is a continuous function of $y \in \mathcal{Y}$  where $\mathcal{Y}$ is a compact set. Condition \eqref{lem:ChB} is satisfied because  $\{\phi_n^{\boldsymbol{\tilde{\eps}}}(y): y\in \mathcal{Y}\}$ as a class of functions of $(X_i, m_i)$ is Euclidean by the same arguments as those leading to Lemma \ref{lem:Eucl} (note that this class depends on $n$ both through $h$ and $\boldsymbol{\tilde{\eps}}$).   

Next, in order to show that condition \eqref{lem:ChC}  of Lemma \ref{lem:Ch} is satisfied, it is enough to verify it for $\sqrt{h}\phi_n^{\boldsymbol{\tilde{\eps}}}(y)$. Define:  
\footnotesize
\begin{align*}
G_{h,y}^{\boldsymbol{\tilde{\eps}}}(X_{i}'\beta, \boldsymbol{\tilde{\eps}}'m_i) \equiv & 3 E_{|\boldsymbol{\tilde{\eps}}}[\mathbbm{1}\{X_{i}'\beta +  \boldsymbol{\tilde{\eps}}'m_i< X_{j}'\beta +  \boldsymbol{\tilde{\eps}}'m_j < X_{k}'\beta +  \boldsymbol{\tilde{\eps}}'m_k \} sgn(X_{k}'\beta +  \boldsymbol{\tilde{\eps}}'m_k - 2(X_{j}'\beta +  \boldsymbol{\tilde{\eps}}'m_j)+X_{i}'\beta +  \boldsymbol{\tilde{\eps}}'m_i) \\ 
& \times K_{h}(X_{j}'\beta +  \boldsymbol{\tilde{\eps}}'m_j-y)K_{h}(X_{k}'\beta +  \boldsymbol{\tilde{\eps}}'m_k-y)K_{h}\left((X_{kj} - X_{ji})'\beta\right)| X_{i}'\beta, m_i] + \textit{symmetric terms}
\end{align*}
\normalsize
and note that $\sqrt{h} \phi_n^{\boldsymbol{\tilde{\eps}}}(y) = G_{h,y}^{\boldsymbol{\tilde{\eps}}}(X_{i}'\beta, \boldsymbol{\tilde{\eps}}'m_i)K((X_{i}'\beta +  \boldsymbol{\tilde{\eps}}'m_i - y)/h)$. Furthermore, using smoothness and boundedness of the distribution of $X_j'\beta, $ (see Assumption \ref{A1}\eqref{A1c}), by change of variables and dominated convergence theorem:
\scriptsize
\begin{align*}
E_{|\boldsymbol{\tilde{\eps}}}&[\mathbbm{1}\{X_{i}'\beta +  \boldsymbol{\tilde{\eps}}'m_i< X_{j}'\beta +  \boldsymbol{\tilde{\eps}}'m_j < X_{k}'\beta +  \boldsymbol{\tilde{\eps}}'m_k \} sgn(X_{k}'\beta +  \boldsymbol{\tilde{\eps}}'m_k - 2(X_{j}'\beta +  \boldsymbol{\tilde{\eps}}'m_j)+X_{i}'\beta +  \boldsymbol{\tilde{\eps}}'m_i)  K_{h}(X_{j}'\beta +  \boldsymbol{\tilde{\eps}}'m_j-y) \\
&  \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \times K_{h}(X_{k}'\beta +  \boldsymbol{\tilde{\eps}}'m_k-y)|(X_{kj}-X_{ji})'\beta, X_i'\beta, m_i]  \\
& =\frac{1}{n^2} \sum_{p,q} \int_{-1}^1 \mathbbm{1}\{X_i'\beta + \boldsymbol{\tilde{\eps}}'m_i < s_2 h +y  < s_3 h + y  \} sgn(s_3 h + y  -2 (s_2 h + y ) + X_i'\beta + \boldsymbol{\tilde{\eps}}'m_i\}   K(s_2)K(s_3)  \\
&  \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \qquad \times f_{xb,xb}(s_2 h + y -\tilde{\eps}_p, s_3 h + y - \tilde{\eps}_q  |(X_{kj}-X_{ji})'\beta, X_i'\beta, \boldsymbol{\tilde{\eps}}) ds = O(1)
\end{align*}
\normalsize
where $f_{xb,xb}(\cdot|(X_{kj}-X_{ji})'\beta, X_i'\beta, \boldsymbol{\tilde{\eps}})$ denotes conditional distribution of $(X_j'\beta, X_k'\beta)$. This implies $G_{h,y}^{\boldsymbol{\tilde{\eps}}}(X_{i}'\beta, \boldsymbol{\tilde{\eps}}'m_i) = O(1)$. 
Now we have:
\footnotesize
\begin{align*}
E_{|\boldsymbol{\tilde{\eps}}}\left[(G_{h,y}^{\boldsymbol{\tilde{\eps}}}(X_{i}'\beta, \boldsymbol{\tilde{\eps}}'m_i))^{2} K^2\left(\frac{X_{i}'\beta +  \boldsymbol{\tilde{\eps}}'m_i -y}{h}\right)\right] 
= h  \frac{1}{n} \sum_{l} \int (G_{h,y}^{\boldsymbol{\tilde{\eps}}}(uh+y - \tilde{\eps}_l,\tilde{\eps}_{l}))^{2}K^{2}\left(u\right) f_{xb}(uh+y-\tilde{\eps}_l)du =O(h)
\end{align*} 
\normalsize
uniformly over $y$ and by similar reasoning $\sup_y E_{|\boldsymbol{\tilde{\eps}}} [h^{3/2} \phi_n^{\boldsymbol{\tilde{\eps}}}(y)^3] = O(h)$ and  $\sup_y E_{|\boldsymbol{\tilde{\eps}}} [h^2 \phi_n^{\boldsymbol{\tilde{\eps}}}(y)^4] = O(h)$. The envelope of $\phi_n^{\boldsymbol{\tilde{\eps}}}(y)$ is given by:
\footnotesize
\begin{align}
 G^{\boldsymbol{\tilde{\eps}}} =& h^{-7/2} \frac{1}{n^2} \sum_{p,q} E_{|\boldsymbol{\tilde{\eps}}}[\mathbbm{1}\{|X_{21}'\beta + \tilde{\eps}_p - \boldsymbol{\tilde{\eps}}'m_1|<2h\} \mathbbm{1}\{|X_{31}'\beta + \tilde{\eps}_q - \boldsymbol{\tilde{\eps}}'m_1|<2h\}  \mathbbm{1}\{|X_{32}'\beta + \tilde{\eps}_q - \tilde{\eps}_p|<2h\} \nonumber \\ 
 & \times K((X_{32}-X_{21})'\beta/h)|X_1'\beta, m_1 ] = O(h^{-1/2}) \label{eq:condenvlp}
\end{align}
\normalsize
where the last equality follows from $P(|X_{21}'\beta + \tilde{\eps}_p - \boldsymbol{\tilde{\eps}}'m_1|<2h, |X_{31}'\beta + \tilde{\eps}_q - \boldsymbol{\tilde{\eps}}'m_1|<2h, |X_{32}'\beta + \tilde{\eps}_q - \tilde{\eps}_p|<2h| X, \boldsymbol{\tilde{\eps}}) = O(h^2)$ and the standard change of variables argument. This further implies that $\| \sqrt{h}   G^{\boldsymbol{\tilde{\eps}}}\|_{P,q} = O(1)$ for $q=2,3,4$.

Thus, we can apply Lemma \ref{lem:Ch} with $q=4, K_n=\log n,\gamma = (\log n)^{-1}, \sigma^2=O(h)$ and $b=O(1)$  to obtain that there exists a random variable $Z^{\boldsymbol{\tilde{\eps}}}$ such that $\sqrt{h}|\sup_{y} \{\tilde{B}(y) + \sqrt{nh}P_{n}^{\#}\phi_n^{\boldsymbol{\tilde{\eps}}}(y)\} -Z^{\boldsymbol{\tilde{\eps}}}| = O_{p}(n^{-1/6}h^{1/3} \log n + n^{-1/4}\log^{5/4} n)$ and $Z^{\boldsymbol{\tilde{\eps}}}$ follows the same distribution as $\sup_{y} \{\tilde{B}(y) + \mathbbm{G}_P \phi_n^{\boldsymbol{\tilde{\eps}}}(y)\}$, which implies:
\begin{align}
|\sup_{y} \{\tilde{B}(y) + \sqrt{nh}P_{n}^{\#}\phi_n^{\boldsymbol{\tilde{\eps}}}(y)\} -Z^{\boldsymbol{\tilde{\eps}}}| &= O_{p}(n^{-1/6}h^{-1/6} \log n + n^{-1/4}h^{-1/2}\log^{5/4} n) \nonumber \\
&= o_{p}(1) \label{eq:final1}
\end{align}
where the last equality follows from $nh^2/(\log n)^5 \to \infty$, which is implied by the rate condition in Assumption \ref{A1}\eqref{A1b}. 

\textbf{Step 3.} For the sample statistic, we have from Theorem \ref{thm:local}:
\begin{gather*}
U_{n}(y)  = P^3 g_{y}^{I} + 3 P_n \pi_{1,3}^P g_{y}^{I} + o_p((nh)^{-1/2}).
\end{gather*} 
uniformly over $y$. Denote $\phi_n(y) = 3 \sqrt{h}  \pi_{1,3}^P g_{y}^{I}$. Following similar, and in fact simpler, reasoning as above in Step 2 (e.g. now $\eps_i$'s are not fixed so we can integrate them out) under the null hypothesis Lemma \ref{lem:Ch} implies:
\begin{gather}
|\sup_{y} \{B(y) + \sqrt{n}P_{n}\phi_n(y)\} -Z| = o_p(1) \label{eq:final2}
\end{gather}
where $Z$ follows the same distribution as $\sup_{y} \{B(y) + \mathbbm{G}_P \phi_n(y)\}$.

Now $\mathbbm{G}_P \phi_n(y)$ and $\mathbbm{G}_P \phi_n^{\boldsymbol{\eps}}(y)$ are processes defined on the joint probability space $(\mathcal{W}^{\infty} \times \{0,1\}^{\infty}, \mathcal{A} \times \mathcal{C}, P \times P_M)$, where $P_M$ is the multinomial distribution. We have:
\small
\begin{align}
|\sup_y \sqrt{nh} U_n^*(y) -  \sup_y \{B(y) + \mathbbm{G}_P \phi_n(y) \} | \leq & |\sup_y \sqrt{nh} U_n^*(y) -  \sup_y \{B(y) +  \mathbbm{G}_P \phi_n^{\boldsymbol{\eps}}(y) \} | \nonumber \\
& \qquad \qquad \qquad \qquad  +  \sup_y | \mathbbm{G}_P \phi_n^{\boldsymbol{\eps}}(y) -  \mathbbm{G}_P \phi_n(y)| \label{eq:final3}
\end{align}
\normalsize
Define $\gamma_n(y) = \phi_n^{\boldsymbol{\eps}}(y) - \phi_n(y)$ and the corresponding class of functions by $\Gamma$. Corollary 2.2.8. in \cite{van_der_vaart_wellner96} implies that, if $ \mathbbm{G}_P \gamma_n(y)$ is a separable sub-Gaussian process:
\begin{gather*}
E  \left[\sup_y | \mathbbm{G}_P \phi_n^{\boldsymbol{\eps}}(y) -  \mathbbm{G}_P \phi_n(y)| \right] \lesssim \int_0^{diam/2} \sqrt{\log N(\varepsilon, \Gamma, L_2(P \times P_M)) } d \varepsilon
\end{gather*}
where $diam$ is the $L_2(P \times P_M)$ diameter of $\Gamma$. Firstly, note that $\mathbbm{G}_P \gamma_n(y)$ is a Gaussian process with $L_2(P \times P_M)$-continuous sample paths (see Lemma \ref{lem:Ch}) indexed by a compact set $\mathcal{Y}$ so it is a separable sub-Gaussian process for the $L_2(P \times P_M)$ semi-metric. 

We have:
\small
\begin{gather*}
E[ \gamma_n^2(y)]  = 9 h E\left[\frac{1}{n} \sum_j (\pi_{1,3}^P g_y^{I}(X_i'\beta, \eps_j) - \pi_{1,3}^P g_y^{I}(X_i'\beta, \eps_i))^2\right] = 9 h \frac{n-1}{n} E\left[(\pi_{1,3}^P g_y^{I}(X_i'\beta, \eps_j) - \pi_{1,3}^P g_y^{I}(X_i'\beta, \eps_i))^2\right]        
\end{gather*} 
\normalsize
and, by direct calculation using dominated convergence theorem, change of variables and smoothness and boundedness of $f$:
\scriptsize
\begin{align*}
\pi_{1,3}^P(X_i'\beta,\eps_i) =& E\Big[E[\mathbbm{1}\{X_i'\beta + \eps_i<X_j'\beta + \eps_j <X_k'\beta + \eps_k\}   sgn(X_k'\beta + \eps_k - 2(X_j'\beta + \eps_j) + X_i'\beta + \eps_i)  K_h(X_j'\beta + \eps_j -y) \\
& \times K_h(X_k'\beta + \eps_k -y)|X_i'\beta, X_j'\beta, X_k'\beta, \eps_i]  K_h((X_{kj}-X_{ji})'\beta)|X_i'\beta, \eps_i\Big]K_h(X_i'\beta + \eps_i - y) + \text{symmetric terms}  \\
=&  - \frac{1}{2} \mathbbm{1}\{X_i'\beta + \eps_i <y\}  E\left[f(y -X_j'\beta) f(y-X_k'\beta)K_h((X_{kj}-X_{ji})'\beta)|X_i'\beta, \eps_i\right]K_h(X_i'\beta + \eps_i - y) + \text{symmetric terms}\\
=&  sgn(X_i'\beta + \eps_i -y) E\left[f(y -X_j'\beta) f(y-X_k'\beta)K_h((X_{kj}-X_{ji})'\beta)|X_i'\beta, \eps_i\right]K_h(X_i'\beta + \eps_i - y) + o(1)\\
\equiv & sgn(X_i'\beta + \eps_i -y) a_y(X_i'\beta, \eps_i) K_h(X_i'\beta + \eps_i - y) + o(1)
\end{align*}
\normalsize
where we have also used $\int \mathbbm{1}\{s_1<s_2\} K(s_1)K(s_2) ds_1 ds_2=\frac{1}{2}$ (by symmetry of $K$) and the fact that the leading term in the sum above has an equivalent term in the sum where indices $(j,k)$ are switched.

Thus, we obtain:
\scriptsize
\begin{align*}
E[(\pi_{1,3}^P(X_i'\beta,\eps_j) - \pi_{1,3}^P(X_i'\beta,\eps_i))^2] &=  E[a_y^2(X_i'\beta, \eps_i) (sgn(X_i'\beta + \eps_j -y) K_h(X_i'\beta + \eps_j - y) - sgn(X_i'\beta + \eps_i -y)  K_h(X_i'\beta + \eps_i - y) )^2] \\
&=E[a_y^2(X_i'\beta, \eps_i) \int_{-1}^1\int_{-1}^1(sgn(s_1) K(s_1) - sgn(s_2)  K(s_2) )^2 ds_1 ds_2 f^2(y-X_i'\beta)] + o(1)\\
&=O(1)
\end{align*}
\normalsize
which implies $diam = \sup_y \sqrt{E[ \gamma_n^2(y)]} = O(\sqrt{h})$.

Let $G^{\Gamma}$ denote the envelope of $\Gamma$. We have $\|G^{\Gamma}\|_{L_2(P \times P_M)}= O(h^{-1/2})$ by the same reasoning as in \eqref{eq:condenvlp}. Now by Lemma \ref{lem:Eucl} the class $\Gamma$ is Euclidean (note that now we treat the class of functions $\{\phi_n^{\boldsymbol{\eps}}(y): y \in \mathcal{Y}\}$ unconditionally, unlike in Step 2, which implies $N(\varepsilon \|G^{\Gamma}\|_{L_2(P \times P_M)}, \Gamma, L_2(P \times P_M)) \lesssim \varepsilon^{-v}$ with $v\geq 1$ and, consequently, 
$N(\varepsilon, \Gamma, L_2(P \times P_M)) \lesssim (\sqrt{h}\varepsilon)^{-v}$. Thus, we have by Corollary 2.2.8. in \cite{van_der_vaart_wellner96}:
\begin{gather}
E  \left[\sup_y | \mathbbm{G}_P \phi_n^{\boldsymbol{\eps}}(y) -  \mathbbm{G}_P \phi_n(y)| \right] \lesssim \int_0^{O(\sqrt{h})} \sqrt{\log (\sqrt{h}\varepsilon)^{-1}} d \varepsilon = O(\sqrt{h \log h^{-1}})=o(1) \label{eq:coupling}
\end{gather}

Finally, the latter result, \eqref{eq:final1} applied under $H_0$ (i.e. with $\tilde{\boldsymbol{\eps}} = \boldsymbol{\eps}$, $f_{\tilde{\eps}} (\cdot)= f (\cdot)$ and $\tilde{P} = P$), \eqref{eq:final2} and \eqref{eq:final3} imply $|S_n^{conc} - Z|=o_p(1)$ and $|S_n^{*,conc} - Z|=o_p(1)$ which gives the final result:
\begin{gather*}
|P(S_{n}^{conc} \leq c^{conc,*}_{\alpha}) - P(Z\leq c^{conc,*}_{\alpha})|= |P(S_{n}^{conc} \leq c^{conc,*}_{\alpha}) - \alpha|+o(1)=o(1) 
\end{gather*}
(see e.g. Lemma 2.1 in \cite{chernozhukov_et_al16}).

\section{Proof of Theorem \ref{thm:bootpwr}}

Again, we focus on the local test as the argument for the global test is standard.

Note that $\inf_y U_n(y) = - \sup_y \{-U_n(y)\}$ and by applying the same argument as above we can show $\sup_y \{-U_n(y)\} = \sup_y \{-B(y)- \mathbbm{G}_P \phi_n(y) \} + o_p(1)$, which implies $\inf_y U_n(y) = \inf_y \{B(y) + \mathbbm{G}_P \phi_n(y) \} + o_p(1)$. Further, using \eqref{eq:final1} and \eqref{eq:final2} we have:
\begin{align}
\inf_y & \sqrt{nh} U_n(y) - \inf_y \sqrt{nh} U_n^*(y) \leq  \inf_y \{ \sqrt{nh} P^3 g_y^I +  \mathbbm{G}_P \phi_n(y) \} - \inf_y \{ \sqrt{nh} \tilde{P}^3 g_y^I + \mathbbm{G}_P \phi_n^{\boldsymbol{\tilde{\eps}}}(y) \} + o_p(1) \nonumber \\  
& \leq \inf_y \{ \sqrt{nh} P^3 g_y^I +  \mathbbm{G}_P \phi_n(y) \}  - \inf_y \{ \sqrt{nh} \tilde{P}^3 g_y^I + \mathbbm{G}_P \phi_n(y) \}  + o_p(1) \label{eq:pwrdiff}
\end{align}  
where the last equality follows from \eqref{eq:coupling}.

Now by Corollary 2.2.8 in \cite{van_der_vaart_wellner96} and similar reasoning to the one leading to \eqref{eq:coupling}:
\begin{gather}
E \sup_y |\mathbbm{G}_P \phi_n(y) | \lesssim E|\mathbbm{G}_P \phi_n(0)| + K   \int_0^{O(\sqrt{h})} \sqrt{\log N(\varepsilon, \mathcal{F}^{\phi}, L_2(P)) } d \varepsilon = O(\sqrt{h \log h^{-1}}) \label{eq:Gpdiff}
\end{gather} 
where $\mathcal{F}^{\phi}=\{\phi_n(y):y \in\mathcal{Y}\}$  and by change of variables $E|\mathbbm{G}_P \phi_n(0)|  = \sqrt{h} E[|a_0(X_i'\beta,\eps_i)K_h(X_i'\beta + \eps_i)|]=O(\sqrt{h})$.

By direct calculation, using Lemma \ref{lem:int}, $T(Y) = X'\beta_0 + \eps$ (where $\beta_0 \neq plim(\hat{\beta})$):
\footnotesize
\begin{align*}
E[g_{y}^{I}|X_j'\beta = \zeta,  X_{ji}'\beta = \xi, X_{kj}'\beta = \xi] &= h b_K  E_{|\zeta \xi}\Bigg[ T'(y)^4 \nabla f_{\boldsymbol{\eps}}  \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix} \\
& \qquad \qquad +  T''(y)T'(y)^2 f_{\boldsymbol{\eps}} \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}\Bigg]'\mathbf{1}\\
E_{\tilde{P}}[g_{y}^{I}|X_j'\beta = \zeta,  X_{ji}'\beta = \xi, X_{kj}'\beta = \xi] &= h b_K  \nabla f_{\boldsymbol{\tilde{\eps}}}  \begin{pmatrix} y -\zeta +\xi \\ y -\zeta  \\ y -\zeta -\xi \end{pmatrix} '\mathbf{1}
\end{align*}
\normalsize
where $\mathbf{1}$ is a $[1 \quad  1 \quad  1]'$ vector, $b_K$ is defined as in Lemma \ref{lem:int}, $\nabla$ denotes the gradient
and $f_{\boldsymbol{\eps}}$ denotes the joint distribution of $(\eps_i, \eps_j, \eps_k)$. Let $g(\xi)$ be the expectation of any of the expressions above conditional on $X_{ji}'\beta = X_{kj}'\beta = \xi$. We have by change of variables that $P^3 g_{y}^{I}  = E[g(\xi) f_{\xi|\xi}(\xi|\xi)] + O(h^3)$, and similarly for $\tilde{P}^3 g_{y}^{I}$, which implies:
\scriptsize
\begin{align*}
P^3 g_{y}^{I}  =&   
h b_K \int \int  \left\{ T'(y)^4 E_{|\zeta\xi}\left[\nabla f_{\boldsymbol{\eps}}   \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}\right]' \mathbf{1}
+ T''(y)T'(y)^2 E_{|\zeta\xi}\left[f_{\boldsymbol{\eps}} \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix} \right] \right\} \\
& \times f_{xb}(\zeta-\xi)f_{xb}(\zeta)f_{xb}(\zeta+\xi) d \zeta d\xi + O(h^3)\\
\tilde{P}^3 g_{y}^{I} = & h b_K \nabla f_{\boldsymbol{\tilde{\eps}}} \begin{pmatrix} y -\zeta +\xi \\ y -\zeta  \\ y -\zeta -\xi \end{pmatrix}  \mathbf{1}  f_{xb}(\zeta-\xi)f_{xb}(\zeta)f_{xb}(\zeta+\xi) d \zeta d\xi + O(h^3)
\end{align*}
\normalsize
where $f_{xb}$ denotes the distribution of $X_i'\beta$ and we used the fact that the joint distribution of $(X_j'\beta, X_{ji}'\beta, X_{kj}'\beta)$ at $(\zeta, \xi_1, \xi_2)$ can be written as $f_{xb}(\zeta - \xi_1)f_{xb}(\zeta)f_{xb}(\zeta+\xi_2)$. 

Note that this and \eqref{eq:Gpdiff} mean that the terms $\sqrt{nh} P^3 g_y^I$ and $\sqrt{nh} \tilde{P}^3 g_y^I$ dominate the infima in \eqref{eq:pwrdiff} and thus:
\begin{gather}
\inf_y  \sqrt{nh} U_n(y) - \inf_y \sqrt{nh} U_n^*(y) \leq \inf_y \{ \sqrt{nh} P^3 g_y^I  \}  - \inf_y \{ \sqrt{nh} \tilde{P}^3 g_y^I  \}  + o_p(1)  \label{eq:pwrfinal}
\end{gather}
Now Assumption \ref{A1}\eqref{A1a}(iii) and Lemma \ref{lem:int} give $b_K<0$. This,  $nh^3 \to \infty$ and the condition \eqref{eq:pwrcond} in Theorem \ref{thm:bootpwr} imply that the right-hand side of \eqref{eq:pwrfinal} diverges to $-\infty$, which implies the final result: 
 \begin{gather*}
P(S_n^{conc}<c^*_{\alpha})  \to 1. 
\end{gather*}

\section{Power condition for wild bootstrap}\label{app:wildboot}

Consider using wild bootstrap in Step 2 of the bootstrap procedure for the local test. Namely, we draw a random sample $\{v_i\}_{i=1}^{n}$ from a two point distribution on \{-1,1\} with $P(v_{i}=-1)=P(v_{i}=1)=1/2$ and define $\eps_{i}^{*} =v_{i} \hat{\eps}_{i}$. 

With wild bootstrap we can apply the same argument as in the proof of Theorem \ref{thm:bootpwr} but now  $\tilde{P}$  corresponds to the DGP where the dependent variable, $Y^{\#}_i$, is generated as $Y^{\#}_i = X_i'\beta+ \tilde{\tilde{\eps}}_i$ where $\tilde{\tilde{\eps}}_i$ equals $\tilde{\eps}_i$ or $-\tilde{\eps}_i$ with equal probability. Noting that $\tilde{\eps}_i = Y_i - X_i'\beta$, this means that the outcome $Y^{\#}_i = Y_i$ or $Y^{\#}_i = 2X_i'\beta - Y_i$ with equal probability, thus $f_{Y^{\#}}(y|X_i) = 0.5 f_{Y}(y|X_i) + 0.5f_{2X\beta-Y}(y|X_i)$. Thus, writing these densities in terms of the density of $\eps$ we obtain:
\scriptsize
\begin{align*}
E_{\tilde{P}}  [g_{y}^{I} | & X_j'\beta = \zeta,   X_{ji}'\beta - \xi, X_{kj}'\beta = \xi] =\\
& =  \frac{1}{2} h a_K E_{\zeta\xi}\Bigg[ T'(y)^4 \nabla f_{\boldsymbol{\eps}}  \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}'\mathbf{1} - 
 \nabla f_{\boldsymbol{\eps}}  \begin{pmatrix} T(2(\zeta - \xi) - y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(2\zeta  - y) -\zeta + X_j'(\beta-\beta_0)  \\ T(2(\zeta + \xi) - y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}'  \begin{pmatrix} T'(2(\zeta - \xi) - y) \\ T'(2\zeta  - y) \\  T'(2(\zeta + \xi) - y) \end{pmatrix} \\
 & \times T'(2(\zeta - \xi) - y) T'(2\zeta  - y) T'(2(\zeta + \xi) - y) 
 +  3T''(y)T'(y)^2 f_{\boldsymbol{\eps}} \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix} \\
 & -  f_{\boldsymbol{\eps}} \begin{pmatrix} T(2(\zeta - \xi) - y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(2\zeta  - y) -\zeta + X_j'(\beta-\beta_0)  \\ T(2(\zeta + \xi) - y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}  \begin{pmatrix} T''(2(\zeta - \xi) - y) T'(2\zeta  - y) T'(2(\zeta + \xi) - y)  \\ T'(2(\zeta - \xi) - y) T''(2\zeta  - y) T'(2(\zeta + \xi) - y)  \\
  T'(2(\zeta - \xi) - y) T'(2\zeta  - y) T''(2(\zeta + \xi) - y) \end{pmatrix}' \mathbf{1} \Bigg]
\end{align*}  
\normalsize
which finally gives the equivalent of condition \eqref{eq:pwrcond} for wild bootstrap:
\scriptsize
\begin{align}
\sup_y \int & \int E_{\tilde{P}}  [g_{y}^{I} |  X_j'\beta = \zeta,   X_{ji}'\beta - \xi, X_{kj}'\beta = \xi] f_{xb}(\zeta-\xi)f_{xb}(\zeta)f_{xb}(\zeta+\xi) d \zeta d\xi \nonumber \\
&- \sup_y \int  \int  E_{\zeta \xi}\left[ T'(y)^4  \nabla f_{\boldsymbol{\eps}}   \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix}'\mathbf{1} 
  + 3T''(y)T'(y)^2 f_{\boldsymbol{\eps}} \begin{pmatrix} T(y) -\zeta +\xi + X_i'(\beta-\beta_0)\\ T(y) -\zeta + X_j'(\beta-\beta_0)  \\ T(y) -\zeta -\xi + X_k'(\beta-\beta_0) \end{pmatrix} \right]
 \nonumber \\
