\section{Transport coefficients}
\label{sec:A}
In a three-dimensional magnon gas, the magnetization current (${\bm { \mathcal J}}^z_ M=\gamma {\bm {\mathcal J}}^z_{s}$, where $\gamma=g\mu_B/\hbar$) and thermal current are defined by \cite{aoya2019,aoya2022,rez}
\begin{equation}
{\bm { \mathcal  J}^z_M}=g\mu_B\sum_{\bm q}\sum_{\alpha=\pm}{ {\bm v^\alpha_{\bm q}}} b^\dagger_{\bm q\alpha}b_{\bm q\alpha}, \;\;\; \bm {\mathcal J}_{th}=\sum_{\bm q}\sum_{\alpha=\pm}\omega_{\bm q\alpha} \bm v^\alpha_{\bm q}b^\dagger_{\bm q\alpha}b_{\bm q\alpha},
\label{eq:A1}
\end{equation}
where 
\begin{equation}
\omega_{\bm q\pm}=\Delta^\pm_{gp}+D^\pm|\bm q|^2, \;\;\; \Delta^\pm_{gp}=|J|\Delta^\pm+g\mu_B H,
\label{eq:A2}
\end{equation}
\begin{equation}
v^\pm_{\bm q\mu}=2D^{\pm}q_{\mu},
\label{eq:A3}
\end{equation} 
and
\begin{equation}\Delta^\pm= \frac{11\Delta-3}{2}\pm\frac{1}{8}\sqrt{C_1},\;\;\;D^{\pm}=\frac{|J|}{4}(1\pm\frac{C_2}{4\sqrt{C_1}}),\;\;\;C_1=784\Delta^2-672\Delta+912, \;\;\; C_2=112\Delta-176 .
\label{eq:A4}	
\end{equation}

In what follows, all transport quantities refer to their longitudinal components (e.g., $\sigma^{xx}=\sigma^{yy}=\sigma^{zz}$ while $\sigma^{\alpha \beta}=0$ for $\alpha \neq \beta$, with $\alpha, \beta =x,y,z$). The only distinction arises from the two dispersive magnon branches.


We present the general expressions for the spin and thermal conductivity in terms of the transport coefficients as follows:
\begin{equation}
\sigma^\pm(T)=L^\pm_{11},\;\;\; \kappa^\pm(T)=\frac{1}{T}\left(L^\pm_{22}-\frac{(L^\pm_{12})^2}{L^\pm_{11}} \right),
\label{eq:A5}
\end{equation}
where the transport coefficients in linear-response theory are given by 
\begin{equation}
L^\pm_{\alpha\beta}=-\lim_{\omega \to 0}\frac{Q^{\pm,R}_{\alpha\beta}(\omega)-Q^{\pm,R}_{\alpha\beta}(0)}{i\omega}.
\label{eq:A6}
\end{equation}
Writing the formula in a more compact form, we obtain 
\begin{equation}
L^{\pm}_{\alpha\beta}=i\frac{dQ^{\pm,R}_{\alpha\beta}(\omega)}{d\omega}\Big |_{\omega=0}
\label{eq:A7},
\end{equation}
where 
\begin{equation}
 Q^{\pm}_{11}(i\omega_n)=-\frac{1}{ \mathcal N}\int_{0}^{\beta}d\tau e^{i\omega_n \tau}\langle T_\tau { \mathcal J_{M,\pm}^z(\tau) \mathcal J^z_{M,\pm}(0)}\rangle,
 \label{eq:A8}
 \end{equation}
\begin{equation}
 Q^{\pm}_{12}(i\omega_n)=-\frac{1}{ \mathcal N}\int_{0}^{\beta}d\tau e^{i\omega_n \tau}\langle T_\tau { \mathcal J_{M,\pm}^z(\tau) \mathcal J_{th,\pm}(0)}\rangle,
 \label{eq:A9}
 \end{equation}
\begin{equation}
 Q^{\pm}_{22}(i\omega_n)=-\frac{1}{ \mathcal N}\int_{0}^{\beta}d\tau e^{i\omega_n \tau}\langle T_\tau { \mathcal J_{th,\pm}(\tau) \mathcal J_{th,\pm}(0)}\rangle.
 \label{eq:A10}
 \end{equation}
We define Green's function for a free magnon gas 
\begin{equation}
 \mathcal D_{\bm q\pm}(\tau)=-\langle T_\tau b_{\bm q\pm}(\tau)b^\dagger_{\bm q\pm}(0)\rangle=\frac{1}{\beta}\sum_{i\omega_m}\mathcal D_{\bm q\pm}(i\omega_m)e^{-i\omega_m\tau}.
 \label{eq:A11}
\end{equation}

Inserting Eq.~(\ref{eq:A1}) into Eqs.~(\ref{eq:A8})--(\ref{eq:A10}), we obtain \cite{aoya2019,aoya2022,abrikosov}
\begin{equation}
\sum_{i\omega_m}\mathcal D_{\bm q\pm}(i\omega_m)\mathcal D_{\bm q\pm}(i\omega_n+i\omega_m)=\int_{-\infty}^{\infty}\frac{dx}{2\pi i}\left(\mathcal D^R_{\bm q\pm}(x)-\mathcal D^A_{\bm q\pm}(x)\right)\left(\mathcal D^R_{\bm q\pm}(x+i\omega_n)+\mathcal D^A_{\bm q\pm}(x-i\omega_n)\right)n_B(x),
\label{eq:A12}
\end{equation}
where 
\begin{equation}
\mathcal D^R_{\bm q\pm}(\omega)=\frac{1}{\omega-\omega_{\bm q\pm}+i\alpha \omega}.
\label{eq:A13}
\end{equation}
Magnon Green's function explicitly include the Gilbert damping parameter $\alpha$. This parameter plays a critical role in ensuring that derived physical quantities remain finite. 


By analytically continuing the Matsubara frequency $i\omega_n \to \omega+i0^+$ and then taking the derivative with respect to $\omega$ as indicated in Eq.~(\ref{eq:A7}), we obtain 

\begin{equation}
L^{\pm}_{\alpha\beta}=\frac{1}{4\pi}\int_{-\infty}^{\infty}dx \frac{dn_B(x)}{dx}\mathcal L^\pm_{\alpha\beta}(x),
\label{eq:A14}
\end{equation}
where 





\begin{equation*}
\mathcal L^\pm_{11}=\frac{(g\mu_B)^2}{\mathcal N}\sum_{\bm q}(v^\pm_{\bm q \mu })^2(\mathcal D^R_{\bm q\pm}(x)-\mathcal D^A_{\bm q\pm}(x))^2=-(g\mu_B)^2K_{-3/2}\int_{0}^{\infty}\frac{u^{3/2} du}{\left[\left(\frac{x-\Delta_{gp}^\pm}{k_BT}-u\right)^2+\Big(\frac{\alpha x}
{k_BT}\Big)^2\right]^2}
\end{equation*}
\begin{equation}
=-\frac{2}{3\pi}\frac{  (g\mu_B)^2}{\alpha  \sqrt{|J|D^\pm}}\theta(x-\Delta^\pm_{gp})\frac{(x-\Delta^\pm_{gp})^{3/2}}{x},
\label{eq:A15}
\end{equation}
\begin{equation*}
\mathcal L^\pm_{12}=\frac{g\mu_B}{\mathcal N}\sum_{\bm q}\omega_{\bm q\pm}(v^\pm_{\bm q\mu })^2(\mathcal D^R_{\bm q\pm}(x)-\mathcal D^A_{\bm q\pm}(x))^2=\frac{\Delta^\pm_{gp}}{g\mu_B}\mathcal L^\pm_{11}-g\mu_BK_{-1/2}\int_{0}^{\infty}\frac{u^{5/2} du}{\left[\left(\frac{x-\Delta^\pm_{gp}}{k_BT}-u\right)^2+\Big(\frac{\alpha x}
{k_BT}\Big)^2\right]^2}
\end{equation*}
\begin{equation}
=\frac{\Delta^\pm_{gp}}{g\mu_B}\mathcal L^\pm_{11}-\frac{2}{3\pi}\frac{ g\mu_B}{\alpha  \sqrt{|J|D^\pm}}\theta(x-\Delta^\pm_{gp})\frac{(x-\Delta^\pm_{gp})^{5/2}}{x},
\label{eq:A16}
\end{equation}
\begin{equation*}
\mathcal L^\pm_{22}=\frac{1}{\mathcal N}\sum_{\bm q}(\omega_{\bm q\pm})^2(v^\pm_{\bm q\mu })^2(\mathcal D^R_{\bm q\pm}(x)-\mathcal D^A_{\bm q\pm}(x))^2=-\left(\frac{\Delta_{gp}^\pm}{g\mu_B}\right)^2\mathcal L^\pm_{11}+2\frac{\Delta^\pm_{gp}}{g\mu_B}\mathcal L_{12}^\pm-K_{1/2}\int_{0}^{\infty}\frac{u^{7/2} du}{\left[\left(\frac{x-\Delta^\pm_{gp}}{k_BT}-u\right)^2+\Big(\frac{\alpha x}
{k_BT}\Big)^2\right]^2}
\end{equation*}
\begin{equation}
=-\left(\frac{\Delta^\pm_{gp}}{g\mu_B}\right)^2 \mathcal L^\pm_{11}+2\frac{\Delta^\pm_{gp}}{g\mu_B}\mathcal L_{12}^\pm-\frac{2}{3\pi}\frac{1}{\alpha  \sqrt{|J|D^\pm}}\theta(x-\Delta^\pm_{gp})\frac{(x-\Delta^\pm_{gp})^{7/2}}{x},
\label{eq:A17}
\end{equation}
where $K_\beta$ is given by
\begin{equation}
K_\beta=\frac{4}{3\pi^2}\frac{\alpha^2x^2}{\sqrt{D^\pm}}(k_BT)^{\beta}.
\label{eq:A18}
\end{equation}
In the above formulas, we have used the limit $\mathcal N \to \infty$, replacing the sum with the integral:
\begin{equation}
\frac{1}{\mathcal N}\sum_{\bm q} \to\frac{1}{(2\pi)^3}\int q^2dq\int \sin\theta d\theta\int d\phi.
\label{eq:A19}
\end{equation}
We have used the following identity for $\alpha \ll1$
\begin{equation}
\frac{1}{[(x-u)^2+(\alpha x)^2]^2}=\frac{\pi}{2(\alpha x)^3}\delta(x-u).
\label{eq:A20}
\end{equation}


By inserting Eqs.~(\ref{eq:A15})--(\ref{eq:A17}) into Eq.~(\ref{eq:A14}), we obtain the following integrals
\begin{equation}
L^\pm_{11}=-\frac{ (g\mu_B)^2}{6\pi^2\alpha  (D^\pm)^{1/2}}\int_{\Delta^\pm_{gp}}^{\infty}dx \frac{dn_B(x)}{dx}\frac{(x-\Delta^\pm_{gp})^{3/2}}{x},
\label{eq:A21}
\end{equation}
\begin{equation}
L^\pm_{12}=\frac{\Delta^\pm_{gp}}{g\mu_B} L^\pm_{11}-\frac{ g\mu_B}{6\pi^2\alpha  (D^\pm)^{1/2}}\int_{\Delta^\pm_{gp}}^{\infty}dx \frac{dn_B(x)}{dx}\frac{(x-\Delta^\pm_{gp})^{5/2}}{x},
\label{eq:A22}
\end{equation}
\begin{equation}
L^\pm_{22}=-\left(\frac{\Delta^\pm_{gp}}{g\mu_B}\right)^2 L^\pm_{11}+2\frac{\Delta^\pm_{gp}}{g\mu_B} L^\pm_{12}-\frac{1}{6\pi^2\alpha  (D^\pm)^{1/2}}\int_{\Delta^\pm_{gp}}^{\infty}dx \frac{dn_B(x)}{dx}\frac{(x-\Delta^\pm_{gp})^{7/2}}{x}.
\label{eq:A23}
\end{equation}
To proceed, we introduce the integral 
\begin{equation}
\int_{\Delta}^{\infty}dx\frac{dn_B(x)}{dx} \frac{(x-\Delta)^{\mu/2}}{x}=
\begin{cases}
	-\Gamma(\mu/2+1)(k_BT)^{\mu/2}e^{-\Delta/k_BT}/\Delta, & \text{when } \Delta/k_BT \gg 1 \\\\
-k_BT \Delta^{\mu/2-2}B(\mu/2+1,2-\mu/2), & \text{when } \Delta/k_BT \ll 1
\end{cases}
\label{eq:A24}
\end{equation}
where $B(z_1,z_2)=\Gamma(z_1)\Gamma(z_2)/\Gamma(z_1+z_2)$ is Beta function. 


\section{Spin conductivity, thermal conductivity, and the Wiedemann-Franz law }
\label{sec:B}
\subsection{Zero magnetic field}
\label{subsec:B1}
 Using the analytical expressions for the transport coefficients derived in the previous section, we obtain the temperature dependence of $\sigma(T)$ and $\kappa(T)$ by summing the contributions from both dispersive magnon branches 
\begin{equation}
\sigma(T)/(g\mu_B)^2=\frac{1}{8\alpha \pi^{3/2}}\left(\frac{k_B T}{|J|} \right)^{3/2}\sum_{\gamma=\pm}\sqrt{\frac{|J|}{D^\gamma}}\frac{1}{\Delta^\gamma} e^{-|J|\Delta^\gamma/k_BT},
\label{eq:B1}
\end{equation}
\begin{equation}
\kappa(T)/k_B|J|=\frac{5}{16\alpha\pi^{3/2}}\left( \frac{k_BT}{|J|}\right)^{5/2}\sum_{\gamma=\pm}\sqrt{\frac{|J|}{D^\gamma}}\frac{1}{\Delta^\gamma}e^{-|J|\Delta^\gamma/k_BT}.
\label{eq:B2}
\end{equation}

Wiedemann-Franz law is defined as
\begin{equation}
\frac{\kappa^\pm}{\sigma^\pm T}=\frac{1}{T^2}\left[\frac{L^\pm_{22}}{L^\pm_{11}}-\left(\frac{L^\pm_{12}}{L^\pm_{11}}\right)^2\right]=L,
\label{eq:B3}
\end{equation}
where 
\begin{equation}
L=\left[\frac{\Gamma(9/2)}{\Gamma(5/2)}-\left(\frac{\Gamma(7/2)}{\Gamma(5/2)}\right)^2 \right]\left(\frac{k_B}{g\mu_B}\right)^2=\frac{5}{2}\left(\frac{k_B}{g\mu_B} \right)^2.
\label{eq:B4}
\end{equation}





\subsection{Nonzero magnetic field}
\label{subsec:B2}
In the presence of the nonzero magnetic field ($H\neq0$), both the spin and thermal conductivities develop explicit dependence on $H$

 \begin{equation}
\sigma(H)/(g\mu_B)^2=\frac{1}{8\alpha \pi^{3/2}}\left(\frac{k_B T}{|J|} \right)^{3/2}\sum_{\gamma=\pm}\sqrt{\frac{|J|}{D^\gamma}}\frac{1}{(\Delta^\gamma+g\mu_B H/|J|)} e^{-|J|\Delta^\gamma/k_BT}e^{-\frac{g\mu_BH}{|J|} \frac{|J|}{k_BT}},
\label{eq:B6}
\end{equation}
\begin{equation}
\kappa(H)/k_B|J|=\frac{5}{16\alpha\pi^{3/2}}\left( \frac{k_BT}{|J|}\right)^{5/2}\sum_{\gamma=\pm}\sqrt{\frac{|J|}{D^\gamma}}\frac{1}{(\Delta^\gamma+g\mu_BH/|J|)}e^{-|J|\Delta^\gamma/k_BT}e^{-\frac{g\mu_BH}{|J|} \frac{|J|}{k_BT}}.
\label{eq:B7}
\end{equation}


