\section{Commutativity of the blockwise direct sum operator}
\label{bds_vs_mmul}
\renewcommand{\theproposition}{\Alph{section}\arabic{proposition}}


\begin{proposition} \label{prop:bds_vs_mmul}
Let \(S\) be a set of all matrix sequences of length \(k\), and let the
sequence \(\seq{\A} \equiv \seq{\A_i | 1 \leq i \leq k}\) be an element
in \(S\). Let the matrix \(\Adsum\) represent the direct sum over the
elements in \(\seq{\A}\). For any function \(f: S \rightarrow S\), if
\(f \brac{\seq{\A}}\) can be expressed as a sequence \( \seq{\M_i \A_i}
\equiv \seq{\M_i \A_i | 1 \leq i \leq k}\) for some arbitrary sequence
of matrices \(\seq{\M_i | 1 \leq i \leq k}\), then \( f
\left(\seq{\A} \right)^{\oplus}_v = \left[ f \left( \seq{\Adsum_v} \right)
\right]_v \). If \( f \left(\seq{\A}\right) \) can be expressed as a
sequence \(\seq{\A_i \M_i} \equiv \seq{\A_i \M_i | 1 \leq i \leq k}\)
for an arbitrary sequence of matrices \(\seq{\M_i | 1 \leq i \leq k}\),
then \( f \brac{ \seq{\A} }^{\oplus}_h = \left[ f \brac{ \seq{\Adsum_h}
} \right]_h \). \end{proposition}

\begin{proof}
For a block matrix \(\A\), take \(\seq{\A}\) to denote the sequence of
the blocks in \(\A\). For a sequence of matrices \(\seq{\A}\), denote
its \(i\)'th element by \(\seq{\A}_i\). For the case of
left-multiplication we then have:

\begin{flalign*}
& f  \brac{ \seq{\A} }^{\oplus}_v
  = \seq{\M_i \A_i}^{\oplus}_v
  = \brac{ \begin{array}{cccc}
      \M_1 \A_1, & \0, & \cdots & \0 \\ \hline
      \0, & \M_2 \A_2, & \cdots & \0 \\ \hline
      \vdots & \vdots & \ddots & \vdots \\ \hline
      \0, & \0, & \cdots & \M_k \A_k
    \end{array} } & \\[10pt]
& \left[ f \brac{ \seq{\Adsum_v} } \right]_v
  = \left[ \seq{\M_i \seq{\Adsum_v}_i | 1 \leq i \leq k} \right]_v
  = \brac{ \begin{array}{c}
      \M_1 \seq{\Adsum_v}_1 \\ \hline
      \M_2 \seq{\Adsum_v}_2 \\ \hline
      \vdots \\ \hline
      \M_k \seq{\Adsum_v}_k
    \end{array} } = & \\[10pt]
& \hspace{1em} = \brac{ \begin{array}{c}
      \M_1 \begin{pmatrix} \A_1, & \0, & \cdots, & \0 \end{pmatrix} \\ \hline
      \M_2 \begin{pmatrix} \0, & \A_2, & \cdots, & \0 \end{pmatrix} \\ \hline
      \vdots \\ \hline
      \M_k \begin{pmatrix} \0, & \0, & \cdots, & \A_k \end{pmatrix}
    \end{array} }
  = \brac{ \begin{array}{cccc}
      \M_1 \A_1, & \0, & \cdots & \0 \\ \hline
      \0, & \M_2 \A_2, & \cdots & \0 \\ \hline
      \vdots & \vdots & \ddots & \vdots \\ \hline
      \0, & \0, & \cdots & \M_k \A_k
    \end{array} } = f \brac{\seq{\A}}^{\oplus}_v &
\end{flalign*}

For the case of right-multiplication we have:

\begin{flalign*}
& f \brac{\seq{\A}}^{\oplus}_h
  = \seq{\A_i \M_i}^{\oplus}_h
  = \brac{ \begin{array}{c|c|c|c}
      \A_1 \M_1 & \0 & \cdots & \0 \\
      \0 & \A_2 \M_2 & \cdots & \0 \\
      \vdots & \vdots & \ddots & \vdots \\
      \0 & \0 & \cdots & \A_k \M_k
    \end{array} } & \\[10pt]
& \left[ f \brac{\seq{\Adsum_h}} \right]_h
  = \left[ \seq{\seq{\Adsum_h}_i \M_i | 1 \leq i \leq k} \right]_v
  = \left[ \begin{array}{c|c|c|c}
      \seq{\Adsum_v}_1 \M_1 &
      \seq{\Adsum_v}_2 \M_2 &
      \cdots &
      \seq{\Adsum_v}_k \M_k
    \end{array} \right] = & \\[10pt]
& \hspace{1em} = \brac{ \begin{array}{c|c|c|c}
      \begin{bmatrix} \A_1 \\ \0 \\ \vdots \\ \0 \end{bmatrix} \M_1 &
      \begin{bmatrix} \0 \\ \A_2 \\ \vdots \\ \0 \end{bmatrix} \M_2 &
      \cdots &
      \begin{bmatrix} \0 \\ \0 \\ \vdots \\ \A_k \end{bmatrix} \M_k 
    \end{array} }
  = \brac{ \begin{array}{c|c|c|c}
      \A_1 \M_1 & \0 & \cdots & \0 \\
      \0 & \A_2 \M_2 & \cdots & \0 \\
      \vdots & \vdots & \ddots & \vdots \\
      \0 & \0 & \cdots & \A_k \M_k
    \end{array} } = & \\[10pt]
& \hspace{1em} = f  \brac{ \seq{\A} }^{\oplus}_h &
\end{flalign*}
\end{proof}
\section{Blockwise Kronecker Product Factorisation for Vectors}
\label{block_kron_factorisation}

\begin{proposition} \label{prop:block_kron_factorisation}
Let \(\a\) and \(\vb\) be two column vectors, each comprised of \(k\)
row blocks of arbitrary lengths. The blockwise Kronecker product \(\a
\odot \vb\) can be factorised as \(\a \odot \vb = \brac{\a \odot
I_{\vb}} \vb = \brac{ I_{\a} \odot \vb } \a\), where \(I_{\vb}\) and
\(I_{\a}\) are identity matrices with the same number of rows and row
block structure as \(\vb\) and \(\a\), respectively.
\end{proposition}

\begin{proof}
Let the vector \(\a\) have dimensions \(M \times 1\) and \(\seq{\a}
\equiv \seq{\underset{m_i \times 1}{\a_i} | 1 \leq i \leq k}\) be the
sequence of vectors which represent the row blocks in \(\a\) such that
\(\sum_{i = 1}^k{m_i} = M\). Similarly, let the vector \(\vb\) have
dimensions \(N \times 1\) and the sequence of vectors \(\seq{\vb} \equiv
\seq{\underset{n_i \times 1}{\vb_i} | 1 \leq i \leq k}\) represent the
row blocks in \(\vb\) such that \(\sum_{i = 1}^k{n_i} = N\).

The blockwise Kronecker product \(\a \odot \vb\) can then be defined as:

\begin{flalign*}
& \a \odot \vb = \brac{
    \begin{array}{c}
      \a_1 \otimes \vb_1 \\ \hline
      \a_2 \otimes \vb_2 \\ \hline
      \vdots \\ \hline
      \a_k \otimes \vb_k
    \end{array}
} &
\end{flalign*}

Note that by the properties of the Kronecker product the following holds
for any two matrices \(\A\) and \(\B\):

\begin{flalign} \label{eqn:kron_factorisation_matrices}
& \underset{m \times p}{\A} \otimes \underset{n \times q}{\B}
  = \brac{\A \otimes I_n} \brac{I_p \otimes \B}
  = \brac{I_m \otimes \B} \brac{\A \otimes I_q} &
\end{flalign}

In the special case of a Kronecker product between two vectors, \(p\)
and \(q\) reduce to \(1\) and the identity matrices \(I_p\) and \(I_q\)
become \(1\) by association. As a result, for any given Kronecker
product \(\a_i \otimes \vb_i\), the following holds:

\begin{flalign} \label{eqn:kron_factorisation_vectors}
& \underset{m_i \times 1}{\a_i} \otimes \underset{n_i \times 1}{\vb_i}
  = \brac{\a_i \otimes I_p} \vb_i
  = \brac{I_m \otimes \vb_i} \a_i &
\end{flalign}

This allows us to rewrite the blockwise Kronecker product \(\a \odot
\vb\) in two alternative ways:

\begin{subequations}
\begin{flalign}
& \a \odot \vb = \brac{
    \begin{array}{c}
      \brac{\a_1 \otimes I_{n_1}} \vb_1 \\ \hline
      \brac{\a_2 \otimes I_{n_2}} \vb_2 \\ \hline
      \vdots \\ \hline
      \brac{\a_k \otimes I_{n_k}} \vb_k
    \end{array}
} & \label{eqn:bk_deriv_1a} \\[15pt]
& \a \odot \vb = \brac{
    \begin{array}{c}
      \brac{I_{m_1} \otimes \vb_1} \a_1 \\ \hline
      \brac{I_{m_2} \otimes \vb_2} \a_2 \\ \hline
      \vdots \\ \hline
      \brac{I_{m_k} \otimes \vb_k} \a_k
    \end{array}
} & \label{eqn:bk_deriv_1b}
\end{flalign}
\end{subequations}

Define a sequence of matrices \(\seq{\a_i \otimes I_{n_i} | 1 \leq i
\leq k}\), or \(\seq{\a_i \otimes I_{n_i}}\) for short, and another
sequence \(\seq{I_{m_i} \otimes \vb_i | 1 \leq i \leq k} \equiv
\seq{I_{m_i} \otimes \vb_i} \). We can then rewrite
(\ref{eqn:bk_deriv_1a}) and (\ref{eqn:bk_deriv_1b}) using the blockwise
direct sum operator introduced in Section \ref{blockwise_direct_sum}:

\begin{subequations}
\begin{flalign}
& \a \odot \vb = \seq{\a_i \otimes I_{n_i}}^{\oplus} \vb & \label{eqn:bk_deriv_2a} \\[10pt]
& \a \odot \vb = \seq{I_{m_i} \otimes \vb_i}^{\oplus} \a & \label{eqn:bk_deriv_2b}
\end{flalign}
\end{subequations}

It then remains to show that \(\seq{\a_i \otimes I_{n_i}}^{\oplus}\) and
\(\seq{I_{m_i} \otimes \vb_i}^{\oplus}\) can be written as \( \a \odot
I_{\vb} \) and \( I_{\a} \odot \vb \), respectively. This can be done
with the help of Proposition \ref{prop:bds_vs_mmul}.

First of all, consider the sequences of identity matrices
\(\seq{I_{m_i}} \equiv \seq{I_{m_i} | 1 \leq i \leq k}\) and
\(\seq{I_{n_i}} \equiv \seq{I_{n_i} | 1 \leq i \leq k}\) on a standalone
basis. The sequences \(\seq{I_{m_i} \otimes \vb_i}\) and \(\seq{\a_i
\otimes I_{n_i}}\) can then be expressed as functions \(f: S \rightarrow
S\) and \(g: S \rightarrow S\) where \(S\) represents the set of all
matrix sequences of length \(k\). such that:

\begin{flalign*}
& f \brac{\seq{I_{m_i}}}
  = \seq{\seq{I_{m_i}}_i \otimes \seq{\vb}_i | 1 \leq i \leq k}
  \equiv \seq{I_{m_i} \otimes \vb_i | 1 \leq i \leq k}
  \equiv \seq{I_{m_i} \otimes \vb_i} & \\[10pt]
& g \brac{\seq{I_{n_i}}}
  = \seq{\seq{\a}_i \otimes \seq{I_{n_i}}_i | 1 \leq i \leq k}
  \equiv \seq{\a_i \otimes I_{n_i} | 1 \leq i \leq k}
  \equiv \seq{\a_i \otimes I_{n_i}} &
\end{flalign*}

Proposition \ref{prop:bds_vs_mmul} applies because we can express
\(\seq{\a_i \otimes I_{n_i}}\) and \(\seq{I_{m_i} \otimes \vb_i}\) as
left-multiplications over the sequences of identity matrcies
\(\seq{I_{m_i}}\) and \(\seq{I_{n_i}}\):

\begin{flalign*}
& \seq{I_{m_i} \otimes \vb_i} = \seq{\brac{I_{m_i} \otimes \vb_i} I_{m_i}} & \\[10pt]
& \seq{\a_i \otimes I_{n_i}} = \seq{\brac{\a_i \otimes I_{n_i}} I_{n_i}} &
\end{flalign*}

It then follows that:

\begin{flalign*}
& f \brac{\seq{I_{m_i}}}^{\oplus}_v
  = \left[ f \brac{\seq{\seq{I_{m_i}}^{\oplus}_v}} \right]_v & \\[10pt]
& g \brac{\seq{I_{n_i}}}^{\oplus}_v
  = \left[ g \brac{\seq{\seq{I_{n_i}}^{\oplus}_v}} \right]_v &
\end{flalign*}

Next, note that \(\seq{I_{m_i}}^{\oplus}_v\) produces an identity matrix
of size \(M\) with a row block structure of \(\a\), while
\(\seq{I_{n_i}}^{\oplus}_v\) produces an identity matrix of size \(N\)
with a row block structure of \(\vb\). In other words,
\(\seq{I_{m_i}}^{\oplus}_v = I_{\a}\) and \(\seq{I_{m_i}}^{\oplus}_v =
I_{\vb}\). This means:

\begin{flalign*}
& \left[ f \brac{\seq{\seq{I_{m_i}}^{\oplus}_v}} \right]_v
  = \left[ f \brac{\seq{I_{\a}}} \right]_v
  = \left[ \seq{ \seq{ I_{\a} }_i \otimes \vb_i } \right]_v & \\[10pt]
& \left[ g \brac{\seq{\seq{I_{n_i}}^{\oplus}_v}} \right]_v
  = \left[ g \brac{\seq{I_{\vb}}} \right]_v
  = \left[ \seq{ \a_i \otimes \seq{I_{\vb}}_i } \right]_v &
\end{flalign*}

Lastly, we note that the matrix representation of a pairwise Kronecker
product over two sequences of matrices is the same as a blockwise
Kronecker product if the sequences represent matrix blocks along the
same dimension. For example, \(\left[ \seq{ \a_i \otimes \seq{I_{\vb}}_i
} \right]_v = \a \odot I_{\vb}\) because \(\a_i\) and
\(\seq{I_{\vb}}_i\) are row blocks of \(\a\) and \(I_{\vb}\),
respectively.

Putting all the steps together we have:

\begin{align}
& \a \odot \vb = \seq{\a_i \otimes I_{n_i}}^{\oplus} \vb
               = \left[ \seq{\a_i \otimes \seq{\seq{I_{n_i}}^{\oplus}_v}_i} \right]_v \vb
               = \left[ \seq{ \a_i \otimes \seq{I_{\vb}}_i } \right]_v \vb
               = \brac{ \a \odot I_{\vb} }  \vb \label{eqn:bk_deriv_3a} \\[10pt]
& \a \odot \vb = \seq{I_{m_i} \otimes \vb_i}^{\oplus} \a
               = \left[ \seq{\seq{\seq{I_{m_i}}^{\oplus}_v }_i \otimes \vb_i} \right]_v \a
               = \left[ \seq{\seq{I_{\vb}}_i \otimes \vb } \right]_v \a
               = \brac{ I_{\a} \odot \vb } \a \label{eqn:bk_deriv_3b}
\end{align}
\end{proof}
\section{Derivation: Lagrange Multipliers for the Dependent}
\label{derivation_ry_rl}
Recalling that \(\ry = (1 + \ly)\) and \(\r_l = \frac{\l_l}{2}\),
rewrite equation (\ref{eqn:clarx_derivation_w_short}) as:


\begin{flalign} \label{eqn:clarx_ry_1}
& \ry \, \Sm_{Y} \w = \tv_1 + \tv_2 - \r_l \1_n &
\end{flalign}

To solve for \(\r_l\), pre-multiply both sides of (\ref{eqn:clarx_ry_1}) by
\(\1_n'\) and re-arrange:


\begin{flalign*}
& \ry \, \1_n' \Sm_{Y} \w = \1_n' \left( \tv_1 + \tv_2 \right) - n \r_l & \\[10pt]
& n \r_l = \1_n' \left( \tv_1 + \tv_2 \right) - \ry \, \1_n' \Sm_{Y} \w &
\end{flalign*}

Dividing both sides by \(n\) produces:


\begin{flalign} \label{eqn:clarx_solution_rl}
& \r_l = \frac{1}{n} \1_n' \left( \tv_1 + \tv_2 \right) -  \frac{1}{n} \ry \, \1_n' \Sm_{Y} \w &
\end{flalign}

We can find an alternative solution for \(\r_l\) by pre-multiplying both
sides of (\ref{eqn:clarx_ry_1}) with \(\w'\) and recalling \(\w' \Sm_{Y} \w =
\s2_y\) and \(\w' \1_n = l_y\):


\begin{flalign*}
& \ry \s2_y = \w' \left( \tv_1 + \tv_2 \right) - \r_l l_y & \\[10pt]
& \r_l l_y = \w' \left( \tv_1 + \tv_2 \right) - \ry \s2_y &
\end{flalign*}

dividing both sides by \(l_y\) we get:


\begin{flalign} \label{eqn:clarx_solution_rl_alt}
& \r_l = \frac{1}{l_y} \w' \left( \tv_1 + \tv_2 \right) -
  \frac{\s2_y}{l_y}\ry &
\end{flalign}

This alternative solution is not very practical because it does not
allow for the case of \(l_y = 0\). However, we can use it in conjunction
with (\ref{eqn:clarx_solution_rl}) to eliminate \(\r_l\) and solve for
\(\r_y\):


\begin{flalign*}
& \frac{1}{n} \1_n' \left( \tv_1 + \tv_2 \right) -  \frac{1}{n} \ry \, \1_n' \Sm_{Y} \w
  = \frac{1}{l_y} \w' \left( \tv_1 + \tv_2 \right) - \frac{\s2_y}{l_y}\ry & \\[10pt]
& \frac{\s2_y}{l_y}\ry - \frac{1}{n} \ry \, \1_n' \Sm_{Y} \w
  = \frac{1}{l_y} \w' \left( \tv_1 + \tv_2 \right) - \frac{1}{n} \1_n' \left( \tv_1 + \tv_2 \right) & \\[10pt]
& \ry \frac{n \s2_y - l_y \1_n' \Sm_{Y} \w}{n l_y}
  = \frac{\left( n \w - l_y \1_n \right)' \left( \tv_1 + \tv_2 \right) }{n l_y} &
\end{flalign*}

Rearranging for \(\ry\) we get:


\begin{flalign} \label{eqn:clarx_solution_ry}
& \ry = \frac{ \left( n \w - l_y \1_n \right)' \left( \tv_1 + \tv_2 \right) }
             {n \s2_y - l_y \1_n' \Sm_{Y} \w} &
\end{flalign}
\section{Derivation: Lagrange Multipliers for the Explanatory}
\label{derivation_tlx_tlp}
Start from the first-order condition for \(\o\). Expressing in terms of
\(\tl_p\), we get:


\begin{flalign} \label{eqn:deriv_tlpx_1}
& \t1od \tl_p = 2 \tv_3 - 2 \tv_4 - 2 \ui' \Smd_X \ui \od \tl_x &
\end{flalign}

Define the following shorthand notations for convenience:


\begin{flalign*}
& \underset{K \times K}{\V} = \diag(\ts2_x) = \begin{pmatrix}
    \s2_{x,1}, & 0, & \cdots & 0 \\
    0, & \s2_{x,2}, & \cdots & 0 \\
    \vdots & \vdots & \ddots & \vdots \\
    0, & 0, & \cdots & \s2_{x,K}
\end{pmatrix}, \underset{K \times K}{\P} = \diag(\lp) = \begin{pmatrix}
    l_{p,1}, & 0, & \cdots & 0 \\
    0, & l_{p,2}, & \cdots & 0 \\
    \vdots & \vdots & \ddots & \vdots \\
    0, & 0, & \cdots & l_{p,K}
\end{pmatrix}, & \\[10pt]
& \underset{K \times K}{\M_1} = \left( \t1od \right)' \t1od = \begin{pmatrix}
    m_1, & 0, & \cdots & 0 \\
    0, & m_2, & \cdots & 0 \\
    \vdots & \vdots & \ddots & \vdots \\
    0, & 0, & \cdots & m_K
\end{pmatrix}, \quad \underset{K \times K}{\M_2} = \ui' \Smd_X \ui &
\end{flalign*}

A system of two vector equations, each with \(K\) rows and \(K\)
unknowns, is produced by pre-multiplying the first-order condition for
\(\o\) with \(\brac{\od}'\) and \(\brac{\t1od}'\), respectively:


\begin{subnumcases}{\hspace{-15em}}
\P \tl_p = 2 \odt \left( \tv_3 - \tv_4 \right) - 2 \V \tl_x
    \label{eqn:deriv_tlpx_cond_1} \\[10pt]
\M_1 \tl_p = 2 \left( \t1od \right)' \left( \tv_3 - \tv_4 \right)
                 - 2 \left( \t1od \right)' \M_2 \od \tl_x
    \label{eqn:deriv_tlpx_cond_2}
\end{subnumcases}

Pre-multiplying \ref{eqn:deriv_tlpx_cond_1} and
\ref{eqn:deriv_tlpx_cond_2} by \(\P^{-1}\) and \(\M_1^{-1}\),
respectively, we get:


\begin{subnumcases}{\hspace{-12em}}
\tl_p = 2 \P^{-1} \odt \left( \tv_3 - \tv_4 \right) - 2 \P^{-1} \V \tl_x &
    \label{eqn:clarx_solution_tlp_a} \\[10pt]
\tl_p = 2 \M_1^{-1} \left( \t1od \right)' \left( \tv_3 - \tv_4 \right) -
                2 \M_1^{-1} \left( \t1od \right)' \M_2 \od \tl_x &
    \label{eqn:clarx_solution_tlp_b}
\end{subnumcases}

The solution for \(\tl_p\) given by \ref{eqn:clarx_solution_tlp_b} is
more practical because \ref{eqn:clarx_solution_tlp_a} does not allow for
the case of zero-sum weights (zeros on the diagonal of \(\P\) would
make it uninvertible).

The solution for \(\tl_x\) can be derived by setting the right-hand side
of \ref{eqn:clarx_solution_tlp_a} equal to the right-hand side of
\ref{eqn:clarx_solution_tlp_b}:


\begin{flalign*}
& 2 \P^{-1} \odt \left( \tv_3 - \tv_4 \right) - 2 \P^{-1} \V \tl_x =
  2 \M_1^{-1} \left( \t1od \right)' \left( \tv_3 - \tv_4 \right) -
  2 \M_1^{-1} \left( \t1od \right)' \M_2 \od \tl_x &
\end{flalign*}

We can pre-multiply both sides by \(\M_1 \P\) to avoid problems with
inverting \(\P\) in the presence of zero-sum weight constraints (note
that \(\M_1 \P = \P \M_1\) because both are diagonal):


\begin{flalign*}
& 2 \M_1 \odt \left( \tv_3 - \tv_4 \right) - 2 \M_1 \V \tl_x =
  2 \P \left( \t1od \right)' \left( \tv_3 - \tv_4 \right) - 2 \P \left( \t1od \right)' \M_2 \od \tl_x &
\end{flalign*}

Re-arranging for \(\tl_x\) we get:


\begin{equation} \label{eqn:clarx_solution_tlx}
\tl_x = \left[ \M_1 \V - \P \left( \t1od \right)' \M_2 \od \right]^{-1}
  \left( \od \M_1 - \t1od \P \right)' \left( \tv_3 - \tv_4 \right)
\end{equation}
