\section{Main result \label{s3}}

The main process of the algorithm is divided into three steps: The first step is to construct the reversibility graph. The second step is to find all circuits in the reversibility graph and construct the circuit graph. The third step is to list the expressions of all irreversible vertices and ultimately provide the reversibility period and sequence. %In this article, the ``circuit" is assumed to refer to ``elementary circuit" by default. 

\subsection{Reversibility graph \label{ss31}}

\begin{definition}
	For FCA = $\{Z^1,S,N_m,f,``n"\}$ $(m=l+1+r)$, its reversibility graph $G_R=(V,E)$ is defined as follows:
	\begin{itemize}
		\item $V=\{v : v \subseteq S^{m-1},\text{ and there is a path from $v_{root}$ to $v$}\}$.
		\item $v_{root} = \{a_1,\cdots,a_{m-1}:a_1,\cdots,a_{m-1} \in S^{m-1} \text{ and } \forall i \in \{1,\cdots,l\},a_i=0\}$.
		\item $v_{end} = \{a_1,\cdots,a_{m-1}:a_1,\cdots,a_{m-1} \in S^{m-1} \text{ and } \forall i \in \{l+1,\cdots,m-1\},a_i=0\}$.
		\item For $u,v \in V$, there is an edge $(u,v)$ labeled $e$ from $u$ to $v$ iff $\forall a=\{a_1,\cdots,a_{m-1}\} \in v$ and $i\in \{1,\cdots,m-2\}$, $ \exists b=\{b_1,\cdots,b_{m-1}\} \in u$, there are $a_i=b_{i+1}$ and $f(b_1,a_1,\cdots,a_{m-1})=e$
	\end{itemize}
\end{definition}

\begin{definition}
	For FCA = $\{Z^1,S,N_m,f,``p"\}$ $(m=l+1+r)$, its reversibility graph $G_R=(V,E)$ is defined as follows:
	\begin{itemize}
		\item $V=\{v : v \subseteq S^{2m-2},\text{and there is a path from $v_{root}$ to $v$}\}$.
		\item $v_{root} = v_{end} = \{a_1,\cdots,a_{2m-2}:a_1,\cdots,a_{2m-2} \in S^{2m-2} \text{ and } \forall i \in \{1,\cdots,m-1\},a_i=a_{i+m-1}\}$.
		\item For $u,v \in V$, there is an edge $(u,v)$ labeled $e$ from $u$ to $v$ iff $\forall a=\{a_1,\cdots,a_{m-1}\} \in v$, $i\in \{1,\cdots,m-2\}$, and $j\in \{1,\cdots,m-1\}$, $ \exists b=\{b_1,\cdots,b_{m-1}\} \in u$, there are $a_j=b_j$, $a_{i+m-1}=b_{i+m}$ and $f(b_m,a_m,\cdots,a_{2m-2})=e$
	\end{itemize}
\end{definition}

\begin{definition}
	The negative vertex set $V_N = \{v \in V:v \cap end \ne \emptyset\}$.
\end{definition}

\begin{theorem}
	FCA = $\{Z^1,S,N_m,f, b\}$ is strictly reversible iff $V_N = \emptyset$ in $G_R$.
\end{theorem}
\begin{proof}
	$G_R$ is very similar to the tree constructed by Amoroso's algorithm introduced in Subsection \ref{s24}. The difference lies in the removal of duplicate vertices from the tree and the addition of $v_{root}$ and $v_{end}$ to accommodate the boundary conditions of FCA, thus the proofs are also similar.

	If there are no negative vertices in $G_R$, for any configuration $c$, there exists a corresponding path starting from $v_{root}$, and among the vertices the path traverses, there must be a valid configuration $c'$ that satisfies $\tau(c')=c$. Since any configurations can find predecessors through the vertices on the path, this FCA is strictly reversible. 
	Conversely, if there is at least one negative vertex in $G_R$, the corresponding configurations have no predecessors and are Garden-of-Eden configurations, meaning that the FCA is not strictly reversible. 
\end{proof}

\begin{proposition}
	$G_R$ can be constructed within $O(s^mV)$.
\end{proposition}
\begin{proof}
	For FCA, the complexity of the rule $f$ is $s^m$. Therefore, the complexity of $G_R$ is linearly related to both $V$ and the rule complexity $s^m$, resulting in an overall complexity of $O(s^mV)$. Fig. \ref{RG} and Algorithm \ref{a} shows the structure and a detailed pseudocode of $G_R$.
\end{proof}
\begin{figure}[h]
	\center
	\includegraphics[width=0.48\linewidth]{./RG.png}
	\caption{The left side is the reversibility graph for FCA=$\{Z^1,\{0,1\},N_3,10100101,``n"\}$, while the right side is for FCA = $\{Z^1,\{0,1\},N_3,10011001,``p"\}$. Negative vertices are marked in red.}
	\label{RG}
\end{figure}
\begin{algorithm}[H]
	\small
	\SetAlgoLined
	\label{a}
	\KwData{one-dimensional finite CA $\{Z^1, S, N_m, f, b\} (m = l + 1 + r)$}
	\KwResult{reversibility graph $G_R$}
	let $G_R$ be an empty directed graph, $Q$ be an empty queue\;
	\eIf{b==``n"}{
		$v_{root} = \{a_1a_2\cdots a_{m-1}|a_1a_2\cdots a_{m-1}\in S^{m-1}, a_j=0, 1\leq j\leq l\}$\;
		$v_{end} = \{a_1a_2\cdots a_{m-1}|a_1a_2\cdots a_{m-1}\in S^{m-1}, a_j=0, m - r\leq j\leq m-1\}$\;
	}(b==``p"){
		$v_{root} = v_{end} = \{a_1a_2\cdots a_{m-1}b_1b_2\cdots b_{m-1}|a_1a_2\cdots a_{m-1}b_1b_2\cdots b_{m-1} \in S^{2m-2}, a_i = b_i, 1\leq i\leq m-1\}$\;
	}
	$d(v_{root}) = 0$\;
	add $v_{root}$ to $G_R$ and $Q$\; 
	\While{$Q$ is not empty}{
		pop the first vertex in $Q$ and denote it with $v_{cur}$\;
		\If{$v_{cur} \cap v_{end} == \emptyset$}{
			mark $v_{cur}$ red\;
		}
		\For{each $e \in S$}{	
			\eIf{b==``n"}{
				$v_e = \{a_1a_2\cdots a_{m-1}|a_1a_2\cdots a_{m-1}\in S^{m-1}, \exists a_0 \in S, a_0a_1\cdots a_{m-2} \in v_{cur}$ and $f(a_0a_1\cdots a_{m-1}) = e\}$\;
			}(b==``p"){
				$v_e = \{a_1a_2\cdots a_{m-1}b_1b_2\cdots b_{m-1}|a_1a_2\cdots a_{m-1}b_1b_2\cdots b_{m-1} \in S^{2m-2}, \exists b_0 \in S, a_1a_2\cdots a_{m-1}b_0b_1\cdots b_{m-2} \in v_{cur}$ and $f(b_0b_1\cdots b_{m-1}) = e \}$\;
			}
			\eIf{$\exists v_{same} == v_e$ in $G_R$}{
				add an edge $(v_{cur},v_{same})$ labeled $e$ into $G_R$\;
			}{
				$d(v_e) = d(v_{cur})+1$ \;
				add an edge $(v_{cur},v_{e})$ labeled $e$ into $G_R$\;
				add $v_e$ to $G_R$ and $Q$\;
			}		
		}
	}

	return $G_R$\;
	\caption{the reversibility graph $G_R$}
\end{algorithm}

\subsection{Circuit graph and reversibility period}
In the previous section, we introduce the construction of the reversibility graph $G_R$ and use it to determine if an FCA is strictly reversible. For FCA with a specific number of cells, $G_R$ remains available, but the concept of ``depth" needs to be introduced.
\begin{definition}
	The depth of $v \in V$ in $G_R$ is $d(v)=min\{d(u)+1:(u,v)\in E\}$ ($d(v_{root})=0$). 
\end{definition}
\begin{figure}[h]
	\center
	\includegraphics[width=0.5\linewidth]{./depth.png}
	\caption{Replace the content of each vertex $v$ of $G_R$ in Fig. \ref{RG} with its depth $d(v)$.}
	\label{depth}
\end{figure}

\begin{theorem}
	If $v \in V_N$, then the FCA is irreversible when it has $d(v)$ cells.
\end{theorem}
\begin{proof}
	There is always a path from $v_{root}$ to $v$. The configuration corresponding to this path cannot find predecessors, indicating the existence of a ``Garden of Eden" configuration. For example, in Fig. \ref{RG} left, the configuration with one cell, 0, is a ``Garden-of-Eden" configuration.
\end{proof}


\begin{theorem}
	If $v \in V_N$, and $v$ is included in $i$ elementary circuits of length $r_1,r_2,\cdots,r_i$ . then the FCA is irreversible when it has $d(v)+x_1r_1+x_2r_2+\cdots+x_ir_i$ cells $(x_1,x_2,\cdots,x_i \in \mathbb{N}_0)$.
\end{theorem}
\begin{proof}
	Starting from $v$, there are $i$ different paths that return to $v$, and continuing the search, there are $i$ different paths again, essentially forming a linear combination of $r_1,r_2,\cdots,r_i$.
\end{proof}

The aforementioned theorems are still not sufficient. We can find that in Fig. \ref{RG} left, 000(01)*10 is also a ``Garden-of-Eden" configuration, yet we have not included it in our calculations. To address this issue, we define a new type of graph called the "circuit graph."

\begin{definition}
	For FCA = $\{Z^1,S,N_m,f,b\}$, its circuit graph $G_C=(V_C,E_C)$ is defined as follows:
	\begin{itemize}
		\item $G_C$ is an undirected graph.
		\item $V_C = V_{E} \cup V_N $, where $V_E$ is the set of elementary circuit in $G_R$.
		\item For $u,v \in V_C$, there is $(u,v) \in E_C$ iff $u$ and $v$ include at least one same vertex.
		\item For $u \in V_N$, $v \in V_C$, there is $(u,v) \in E_C$ iff $u$ is included in $v$.
		\item The $d(u)$ of $u \in V_N$ is its depth in $G_R$ and $l(v)$ of $v \in V_C$ is its length in $G_R$.
	\end{itemize}
\end{definition}

\begin{theorem}
	If  $v \in V_N$, $v_1,\cdots,v_i \in V_E$ and they are connected to $v$ in $G_C$, then the FCA is irreversible when it has $k+x_1l(v_1)+x_2l(v_2)+\cdots+x_il(v_i)$ cells where $x_1,x_2,\cdots,x_i \in \mathbb{N}_0$ and the subgraph consisting of $v_j$ where $x_j \ne 0$ and their related edges is a connected graph.
\end{theorem}
\begin{example}
	\label{example}
	The proof of this theorem is similar to that of the previous theorems, so we use an example in place of a formal proof here. Fig. \ref{CG} provides $G_C$ corresponding to $G_R$ in Fig. \ref{RG} right. For convenience of representation, we assign an order number to each vertex in the top left corner.
	\begin{figure}[h]
		\center
		\includegraphics[width=0.4\linewidth]{./CG.png}
		\caption{The circuit graph $G_C$ of $FCA = \{Z^1,\{0,1\},N_3,10011001,``p"\}$.}
		\label{CG}
	\end{figure}

	We can quickly list the irreversible number for the FCA based on the above theorems. 
	\begin{equation}
		\left\{\begin{matrix}
			1+3x_1+2x_2+x_3+4x_4+3x_5+x_6 \ \ \\
			2+3y_1+2y_2+y_3+4y_4+3y_5+y_6 \ \  
		\end{matrix}\right.
	\end{equation}

	From $G_C$, we know that $y_1=y_3=y_4=0$ is a sufficient condition for $y_5=y_6=0$. Many similar conditions are all easy to discern, so we will not list them all here. The union of all these irreversible number forms the reversibility sequence of the FCA. Ultimately, we can determine that the reversibility sequence for this FCA is: \underline{0}.
\end{example}

\begin{definition}
	For a connected component $G_{sub}=(V_{sub},E_{sub})$ of $G_C$, the sub-period is $\gcd(V_{sub} \cap V_C)$, where the function $\gcd$ is to find the maximum common divisor of the lengths of all circuits in set. 
\end{definition}

\begin{theorem}
	The reversibility period of FCA is $\mathrm{lcm}(P)$, where $P$ is the set of sub-periods and function $\mathrm{lcm}$ is to get the minimum common multiple of a set, then . 
\end{theorem}
\begin{proof}	
	The proof of this theorem stems from the Frobenius Coin Problem \cite{bardomero2020frobenius,shallit2008frobenius}. This problem can be briefly described as determining the largest amount of money that cannot be made with given denominations of coins. The problem has been widely explored in number theory and combinatorial mathematics. In this paper, we utilize it to calculate the reversibility period.
\end{proof}


\begin{corollary}
	\label{c1}
	If $v \in V_N$, $\exists u \in V_E$ in $G_C$ and $l(u)=1$, then the FCA is irreversible when the number $n$ of cells satisfies
	\begin{equation}
		n \ge d(v)+\sum_{w \in V_E}l(w).
	\end{equation}
\end{corollary}
\begin{corollary}
	\label{c2}
	If $v \in V_N$, $\exists u_1,u_2 \in V_E$ in $G_C$ and $\gcd(l(u_1),l(u_2))=1$, then the number $n$ of cells satisfies
	\begin{equation}
		n>d(v)+l_1l_2+\sum_{w \in V_E \setminus \{u_1,u_2\}}l(w).
	\end{equation}
\end{corollary}
\begin{proof}
	Corollary \ref{c1} is obvious, while the proof of Corollary \ref{c2} comes from the precise conclusion of the Frobenius Coin Problem.
\end{proof}
These two corollaries can help us make reversibility determinations more quickly and directly, sometimes even eliminating the need to construct $G_C$. In Example \ref{example}, we can determine that the FCA is irreversible when the number of cells is greater than or equal to 2, simply by finding there is a negative vertex in $G_R$ with a self-circuit.

Through the aforementioned analysis, we have resolved the most significant issues. Only two minor problems remain to be addressed: one is finding all the circuits in $G_R$, and the other is the construction of $G_C$.

\begin{proposition}
	\cite{johnson1975finding} We can find all elementary circuits of a directed graph in time bounded by $O((V + E)(l + 1))$, where there are $V$ vertices, $E$ edges and $l$ circuits in the graph. 
\end{proposition}
We can find all the circuits of $G_R$ in $O(sVl)$, where the FCA has $s$ states and $G_R$ has $V$ vertices and $l$ circuits. 

\begin{proposition}
	We can construct $G_C$ in time bounded by $O(Vl^2)$, where there are $V$ vertices and $l$ circuits in $G_R$. 
\end{proposition}
\begin{proof}		
	In $G_C$, there are $l$ points, so there are at most $l^2$ edges. When determining whether two points are adjacent, we need to check whether at most $V$ vertices appear simultaneously in these two circuits. Therefore, the complexity is $O(Vl^2)$. Algorithm \ref{b} shows the  detailed pseudocode of $G_C$.
\end{proof}

\begin{algorithm}[h]
	\small
	\SetAlgoLined
	\label{b}
	\KwData{a reversibility graph $G_R=(V,E)$}
	\KwResult{the circuit graph $G_C$}
	let $G_C=(V_C,E_C)$ be an empty directed graph\;
	Get the negative vertex set $V_N$ in $G_R$\;
	Calculate the elementary circuit set$ V_E$ in $G_R$ by algorithm in \cite{johnson1975finding}\;
	$V_C=V_N \cup V_E$\;
	\For{each $v,v' \in V_E$}{
		\If{$u$ and $v$ include at least one same vertex}{
			add $(v,v')$ into $E_C$\;
		}
	}
	\For{each $v \in V_N,v' \in V_E$}{
		\If{$v$ is included in $v'$}{
			add $(v,v')$ into $E_C$\;
		}
	}
	return $G_C=(V_C,E_C)$\;
	\caption{the circuit graph $G_C$}
\end{algorithm}


Thus, the reversibility problem of one-dimensional FCA has been efficiently resolved. Actually, determining whether an FCA with $n$ cells is reversible is not straightforward. However, we approach this problem from a novel perspective: we list all the irreversible scenarios, and what remains are naturally reversible, as a substitute for individually determining the reversibility for every cell count. This approach significantly simplifies the complexity of analyzing the entire problem. Next, let's fully recapitulate our algorithm.

\begin{description}
	\item[Step 1] Construct $G_R$ according to Algorithm \ref{a} with the complexity of $O(s^mV)$.
	\item[Step 2] Find all circuits using Johnson's algorithm with the complexity of $O(sVl)$ \cite{johnson1975finding}.
	\item[Step 3] Construct $G_C$ according to Algorithm \ref{b} with the complexity of $O(Vl^2)$.
	\item[Step 4] List all irreversible number polynomials and solve the reversibility sequence.
\end{description}


