\title{Theory of Magnon Spintronics: Non-Abelian 
Gauge Theory of Electron Spintronics}

\author{Y. M. Cho}
\email{ymcho0416@gmail.com}
\affiliation{School of Physics and Astronomy,
Seoul National University, Seoul 08826, Korea}
\affiliation{Center for Quantum Spacetime, 
Sogang University, Seoul 04107, Korea}  
\author{Franklin H. Cho}
\email{cho.franklin@qns.science}
