\begin{thm} \label{Apery_set1}
Let $\gcd(V_1,V_2)=\gcd(V_n,F_d)=1$, where $d$ is even. Let $\k$ be the smallest positive integer for which $F_{\k d}/F_d \ge V_n$. Then the Ap\'{e}ry set for 
\[ S = \la  V_n, V_{n+d}, V_{n+2d}, \ldots \ra =  \la V_n, V_{n+d}, V_{n+2d}, \ldots, V_{n+(\k-1)d} \ra \] 
is given by  
\[ \Ap(S,V_n) = \left\{ V_{n+d}\,x - \left\lf \frac{F_{(\k-2)d}\,x}{F_{(\k-1)d}} \right\rf V_n: 0 \le x \le V_n-1 \right\}. \] 
\end{thm}

\begin{Pf}
For $x \in \{1,\ldots,V_n-1\}$, let ${\m}(x)$ denote the least integer in $S$ that is congruent to $x$ modulo $V_n$. Since $\gcd(V_n,V_{n+d})=1$, 
\[ \Ap(S,V_n) = \big\{{\m}(V_{n+d}\,x): 0 \le x \le V_n-1\big\}. \] 

\noindent Fix $x \in \{1,\ldots,V_n-1\}$. To determine ${\m}(V_{n+d}\,x)$, we must minimize $m$ for which the equation  
\begin{equation} \label{Apery1}
\sum_{i=1}^{\k-1} V_{n+id}\,x_i = m\,V_n + V_{n+d}\,x
\end{equation}
has a solution in nonnegative integers $x_i$. 

\noindent Reducing both sides of eqn.~\eqref{Apery1} modulo $V_n$ yields $x \equiv \sum_{i=1}^{\k-1} \left(F_{id}/F_d\right)\,x_i \pmod{V_n}$ by Proposition \ref{F_identity}, part (ii), since $\gcd(V_n,V_{n+d})=1$. 
\end{Pf}
\vskip 5pt


\begin{thm} \label{genus_special}
Let $\{{\s}_k\}$ be the second order recurrence given by 
\[ {\s}_k = 3{\s}_{k-1} - {\s}_{k-2} + F_{n+4k-1} + F_{2k-1} F_{n+2k}, \quad k \ge 2, \]
with ${\s}_0=0$ and ${\s}_1=3F_{n+2}$. Let $\{{\r}_k\}$ be the related second order recurrence given by 
\[ {\r}_k = {\s}_k - 2{\s}_{k-1} - F_{2k+1}F_{n+2k}, \quad k \ge 2.  \]
If $S=\la F_n, F_{n+2}, F_{n+4}, \ldots \ra$ and $\e(S)=\k$, then  
\[ \g(S) = \begin{cases} 
                 \ds\frac{{\s}_{\k-2}+{\r}_{\k-1}}{F_n} - \ds\frac{F_n-1}{2} & \mbox{ if $n=2\k-1$}; \\[8pt]
                 \ds\frac{{\s}_{\k-1}}{F_n} - \ds\frac{F_n-1}{2} & \mbox{ if $n=2\k$}.
                \end{cases}
\]
\end{thm}

\begin{Pf}
Applying Theorem \ref{Frob_gen}, part (ii) to $V_n=F_n$, we must show 
\[ \sum_{x=1}^{F_n-1} s(x) = \begin{cases}
                                                {\s}_{\k-2}+{\r}_{\k-1} & \mbox{ if $n=2\k-1$}; \\
                                                {\s}_{\k-1} & \mbox{ if $n=2\k$}.
                                              \end{cases}
\] 
\vskip 5pt

\noindent For positive integer $k$ and $\ell \in \{1,2\}$, define 
\begin{equation} \label{newsums}
{\r}_{k,\ell} = \sum_{x=F_{2k}}^{F_{2k+\ell}-1} s(x), \quad {\s}_k = \sum_{x=1}^k {\r}_{x,2} = \sum_{x=1}^{F_{2k+2}-1} s(x). 
\end{equation}

\noindent Fix $x \in \{1,\ldots,F_n-1\}$, and let $k$ be defined by $F_{2k} \le x < F_{2k+2}$. Then ${\l}_k \ge 1$ by the Greedy Algorithm, so that $s(x)=s(x-F_{2k})+F_{n+2k}$. Hence  
\[ {\r}_{k,2} = \sum_{x=F_{2k}}^{F_{2k+2}-1} \big( s(x-F_{2k})+F_{n+2k} \big) = \left( \sum_{x=1}^{F_{2k+1}-1} s(x) \right) + F_{2k+1} F_{n+2k} = {\s}_{k-1} + {\r}_{k,1} + F_{2k+1} F_{n+2k}, \]
so that 
\begin{equation} \label{eqn1}
{\s}_k = {\s}_{k-1} + {\r}_{k,2} = {\s}_{k-1} + {\s}_{k-1} + {\r}_{k,1} + F_{2k+1} F_{n+2k} = 2{\s}_{k-1} + {\r}_{k,1} + F_{2k+1} F_{n+2k}. 
\end{equation} 
Similarly
\begin{equation} \label{eqn2}
{\r}_{k,1} = \sum_{x=F_{2k}}^{F_{2k+1}-1} \big( s(x-F_{2k})+F_{n+2k} \big) = \left( \sum_{x=1}^{F_{2k-1}-1} s(x) \right) + F_{2k-1} F_{n+2k} = {\s}_{k-2} + {\r}_{k-1,1} + F_{2k-1} F_{n+2k}. 
\end{equation}
Replacing $k$ by $k-1$ in eqn.~\eqref{eqn1}, we get
\begin{equation} \label{eqn3}
{\s}_{k-1} = 2{\s}_{k-2} + {\r}_{k-1,1} + F_{2k-1} F_{n+2k-2}. 
\end{equation} 
From eqns.~\eqref{eqn1}, \eqref{eqn2}, \eqref{eqn3}, and using Proposition \ref{V_identity}, part (i), we have
\begin{eqnarray*} 
{\s}_k - {\s}_{k-1} & = & 2{\s}_{k-1} -  2{\s}_{k-2} + \big( {\r}_{k,1} - {\r}_{k-1,1} \big) + \big( F_{2k+1} F_{n+2k} - F_{2k-1} F_{n+2k-2} \big) \\
& = & 2{\s}_{k-1} - {\s}_{k-2} +  F_{2k-1} F_{n+2k} + \big( F_{2k+1} F_{n+2k} + F_{2k} F_{n+2k-1} \big) \\
& & - \big( F_{2k} F_{n+2k-1} + F_{2k-1} F_{n+2k-2} \big) \\
& = & 2{\s}_{k-1} - {\s}_{k-2} +  F_{2k-1} F_{n+2k} + F_{n+4k} - F_{n+4k-2} \\
& = & 2{\s}_{k-1} - {\s}_{k-2} +  F_{2k-1} F_{n+2k} + F_{n+4k-1},
\end{eqnarray*}
so that 
\begin{equation} \label{sigma}
{\s}_k = 3{\s}_{k-1} - {\s}_{k-2} +  F_{2k-1} F_{n+2k} + F_{n+4k-1}. 
\end{equation}
\vskip 5pt

\noindent Thus, $\{{\s}_k\}$ satisfies the recurrence given in the Theorem. Moreover, ${\s}_0=0$ and ${\s}_1=s(1)+s(2)=F_{n+2}+2F_{n+2}=3F_{n+2}$. 
\vskip 5pt

\noindent Now  
\[ {\r}_{k,1} = {\s}_k - 2{\s}_{k-1} - F_{2k+1} F_{n+2k} \]
can be used to determine ${\r}_{k,1}$ from the sequence $\{{\s}_k\}$; this is the recurrence for the sequence $\{{\r}_k\}$ with ${\r}_k$ being used for ${\r}_{k,1}$ here.  
\vskip 5pt

\noindent Recall that $\e(S)=\k$ where $F_{2(\k-1)} \le F_n-1 < F_{2\k}$ by Theorem \ref{embed_dim}. If $n=2\k$, then $\sum_{x=1}^{F_n-1} s(x) = \sum_{x=1}^{F_{2\k}-1} s(x) = {\s}_{\k-1}$. If $n=2\k-1$, then $\sum_{x=1}^{F_n-1} s(x) = \sum_{x=1}^{F_{2\k-1}-1} s(x) = {\s}_{\k-2}+{\r}_{k-1,1}$. 

\noindent This completes the proof of the Theorem. 
\end{Pf}
\vskip 5pt

\begin{prop} \label{F_identity}
Let $d$ be even.  
\begin{itemize}
\item[{\rm (i)}]
If $k \ge 2$, then 
\[ F_{kd} -  (L_d-1) F_{(k-1)d} = F_{(k-1)d} - F_{(k-2)d}. \]
\item[{\rm (ii)}]
If $k \ge 3$, then 
\[ \left\lf \frac{F_{kd}}{F_{(k-1)d}} \right\rf = L_d-1. \]
\item[{\rm (iii)}]
If $k-1 \ge t \ge 2$, then 
\[ F_{kd} = (L_d-1) F_{(k-1)d} + (L_d-2) \sum_{i=t}^{k-2} F_{id} + (L_d-1) F_{(t-1)d} - F_{(t-2)d}. \]
In particular, 
\[ F_{kd} = (L_d-1) F_{(k-1)d} + (L_d-2) \sum_{i=2}^{k-2} F_{id} + (L_d-1) F_d. \]
\item[{\rm (iv)}]
If $k \ge t \ge 1$, then 
\[ (L_d-2) \sum_{i=t}^k V_{n+id} = \left( V_{n+(k+1)d} - V_{n+kd} \right) - \left( V_{n+td} - V_{n+(t-1)d} \right). \]
In particular, 
\[ (L_d-2) \sum_{i=1}^k V_{n+id} = \left( V_{n+(k+1)d} - V_{n+kd} \right) - \left( V_{n+d} - V_n \right). \]
\end{itemize}
\end{prop}

\begin{Pf}
\begin{itemize}
\item[{\rm (i)}]
Applying Proposition \ref{V_identity}, part (iii) to $V=F$ and $n=d$, and replacing $k$ by $k-1$, we have 
\begin{equation} \label{F_kd_eqn}
F_{kd} = \frac{F_{(k-1)d}}{F_d} F_{2d} - \frac{F_{(k-2)d}}{F_d} F_d = L_d F_{(k-1)d} - F_{(k-2)d} = (L_d-1) F_{(k-1)d} + \big( F_{(k-1)d} - F_{(k-2)d} \big). 
\end{equation}
\item[{\rm (ii)}]
Since $0<F_{(k-1)d} - F_{(k-2)d}<F_{(k-1)d}$ for $k \ge 3$, part (ii) follows upon dividing both sides of eqn.~\eqref{F_kd_eqn} by $F_{(k-1)d}$. 
\item[{\rm (iii)}]
Summing both sides of the identity in part (i) from $i=t$ to $i=k$, we have 
\[ \sum_{i=t}^k \left( F_{id} -  (L_d-1) F_{(i-1)d} \right) = \sum_{i=t}^k \left( F_{(i-1)d} - F_{(i-2)d} \right). \]
Thus, 
\[ \sum_{i=t}^k F_{id} -  (L_d-1) \sum_{i=t}^k F_{(i-1)d} = F_{kd} - (L_d-2) \sum_{i=t}^{k-1} F_{id} - (L_d-1) F_{(t-1)d} = F_{(k-1)d} - F_{(t-2)d}, \]
which gives the desired result. 
\item[{\rm (iv)}]
From part (iii), 
\[ (L_d-2) \sum_{i=t}^k F_{id} = \left( F_{(k+1)d} - F_{kd} \right) - \left( F_{td} - F_{(t-1)d} \right). \]  
Summing both sides of the identity in Proposition \ref{V_identity}, part (iii) from $i=t$ to $i=k$ and multiplying both sides by $L_d-2$, we have 
\begin{eqnarray*} 
(L_d-2) \sum_{i=t}^k V_{n+id} & = & (L_d-2) \sum_{i=t}^k \frac{F_{id}}{F_d} V_{n+d} - (L_d-2) \sum_{i=t}^k \frac{F_{(i-1)d}}{F_d} V_n \\
& = & \Big( \left( F_{(k+1)d} - F_{kd} \right) - \left( F_{td} - F_{(t-1)d} \right) \Big) \frac{V_{n+d}}{F_d} \\
& & - \Big( \left( F_{kd} - F_{(k-1)d} \right) - \left( F_{(t-1)d} - F_{(t-2)d} \right) \Big) \frac{V_n}{F_d} \\ 
& = & \left( \frac{F_{(k+1)d}}{F_d} V_{n+d} - \frac{F_{kd}}{F_d} V_n \right) - \left( \frac{F_{kd}}{F_d} V_{n+d} - \frac{F_{(k-1)d}}{F_d} V_n \right) \\
& & - \left( \frac{F_{td}}{F_d} V_{n+d} - \frac{F_{(t-1)d}}{F_d} V_n \right) + \left( \frac{F_{(t-1)d}}{F_d} V_{n+d} - \frac{F_{(t-2)d}}{F_d} V_n \right) \\
& = & \left( V_{n+(k+1)d} - V_{n+kd} \right) - \left( V_{n+td} - V_{n+(t-1)d} \right).
\end{eqnarray*}
\end{itemize}
\end{Pf}
\vskip 5pt

\section{The Greedy Knapack Problem} \label{knapsack}
\vskip 10pt

The Frobenius Problem we discuss in this paper is a case of the Integer Linear Programming where we are required to optimize a linear equation with integer coefficients subject to a constraint in the form of  another linear equation with integer coefficients. We follow the recent work of Rybin \cite{Ryb24} to resolve the results in Section \ref{even}. We need some notations from \cite{Ryb24} to state the main result which is crucial to our main result in Section \ref{even}. 

\begin{defn} \label{preorder}
An {\tt additive preorder\/} on $\left({\Z}_{\ge 0}\right)^n$ is a reflexive and transitive relation ${\le}_p$ for which 
\begin{itemize}
\item[{\rm (i)}] 
$(0,\ldots,0) \,{\le}_p\, \textbf{a}$ for each $\textbf{a} \in \left({\Z}_{\ge 0}\right)^n$, 
\item[{\rm (ii)}]
If $\textbf{a} \,{\le}_p\, \textbf{b}$ and $\textbf{c} \,{\le}_p\, \textbf{d}$, then $\textbf{a}+\textbf{c} \,{\le}_p\, \textbf{b}+\textbf{d}$.  
\end{itemize}
\end{defn}
\vskip 5pt

\noindent Given $c_1,\ldots,c_n \in {\R}_{\ge 0}$ and $\textbf{v}=(v_1,\ldots,v_n) \in \left({\Z}_{\ge 0}\right)^n$, we define the {\tt cost} function {\sc Cost}$(\textbf{v})=\sum_{i=1}^n c_iv_i$. The Greedy Algorithm is the following statement: 
\begin{quote}
For $C \ge 0$, we denote by {\sc Greedy}$(C,m)$ the list $(g_1,\ldots,g_n) \in \left({\Z}_{\ge 0}\right)^n$ given recursively by 
\[ g_k = \begin{cases}
               \left\lf \frac{C - \sum_{i=k+1}^m c_ig_i}{c_k} \right\rf & \mbox{ for } k=m, m-1, m-2, \ldots, 1; \\[8pt]
                0 & \mbox{ for } k>m. 
              \end{cases}
\]
\end{quote}
\vskip 5pt

\begin{defn} \label{optimal}
A list $\textbf{v} \in \left({\Z}_{\ge 0}\right)^n$ is {\tt optimal} for cost bound $X$ if for each $\textbf{u} \in \left({\Z}_{\ge 0}\right)^n$ with {\sc Cost}$(\textbf{u}) \le X$, we have $\textbf{u} \,{\le}_p\, \textbf{v}$.     
\end{defn}

\begin{thm} \label{greedy_characterization}
For an additive preorder ${\le}_p$ on $\left({\Z}_{\ge 0}\right)^n$ and costs $c_1,\ldots,c_n \in {\R}_{\ge 0}$, the greedy list {\sc Greedy}$(X,n)$ is optimal for any cost bound $X$ if and only if for any $j \in \{2,\ldots,n\}$ the list {\sc Greedy}$(c_j,j-1)=(g_1,\ldots,g_{j-1},0,\ldots,0) \in \left({\Z}_{\ge 0}\right)^n$ satisfies the two conditions: 
\begin{itemize}
\item[{\rm (i)}]
\[ \text{\sc Greedy}(c_j,j-1) \,{\le}_p\, \textbf{e}_j, \]
\item[{\rm (ii)}]
for any $i<j$ such that $\sum_{k=i}^{j-1} c_kg_k < c_j$, the inequality 
\[ \textbf{h}_{i,j} \,{\le}_p\, \text{\sc Greedy}\left({\sc Cost}(\textbf{h}_{i,j},n)\right) \]
holds, where $\textbf{h}_{i,j}=(0,\ldots,0,g_i,\ldots,g_{j-1},0,\ldots,0)+\textbf{e}_i$ and $\textbf{e}_i=(0,\ldots,0,1,0,\ldots,0)$ with $1$ at the $i^{\text th}$ position.  
\end{itemize} 
\end{thm}
\vskip 10pt

\section{The Case where $d=2$} \label{two}
\vskip 10pt

Since $\gcd(V_n,V_{n+2})=1$, by Corollary \ref{V_gcd}, $\Ap(S,V_n)$ is the collection $\m(V_{n+2}\,x)$ as $x$ runs through the set $\{1,\ldots,V_n-1\}$. 

Fix $x \in \{1,\ldots,V_n-1\}$. To determine $\m(V_{n+2}\,x)$ we must minimize the integer $m_x$ for which   
\begin{equation} \label{min_class}
m_x\,V_n + V_{n+2}\,x = V_{n+d}\,x_1 + V_{n+2d}\,x_2 + \cdots + V_{n+(\k-1)d}\,x_{\k-1} 
\end{equation} 
has a solution in nonnegative integers $x_1,x_2,\ldots,x_k,\ldots $. Thus, $m_x\,V_n+V_{n+2}\,x \ge 0$ but $m_x$ may be zero or negative. 

By Corollary \ref{V_congruence}, $V_{n+kd} \equiv V_{n+2}\,F_{kd}\pmod{V_n}$. Reducing both sides of eqn.~\eqref{min_class} modulo $V_n$ gives 
\[ x \equiv F_d\,x_1 + F_{2d}\,x_2 + F_{3d}\,x_3 + \cdots + F_{(\k-1)d}\,x_{\k-1} \pmod{V_n} \]
since $\gcd(V_n,V_{n+2})=1$. Hence, 
\begin{equation} \label{min_class_eq}
F_d\,x_1 + F_{2d}\,x_2 + F_{3d}\,x_3 + \cdots + F_{(\k-1)d}\,x_{\k-1} = x+V_n\,t
\end{equation}
for some $t \ge 0$. 

Since $F_d \mid F_{kd}$ for each $k \ge 1$, the collection of all nonnegative integers of the form given in the LHS of eqn.~\eqref{min_class_eq} is the set of all nonegative multiples of $F_d$. Thus, eqn.~\eqref{min_class_eq} has a nonnegative integer solution $t$ if and only if $F_d \mid (x+V_n\,t)$. So if $t_1$ and $t_2$ are any two values of $t$ for which eqn.~\eqref{min_class_eq} has a solution, then $t_1 \equiv t_2\pmod{F_d}$ since $\gcd(F_d,V_n)=1$. 

Let $t_x$ denote the least nonnegative integer satisfying $F_d \mid (x+V_n\,t_x)$; we may assume $0 \le t_x < F_d$. Thus, the problem of minimizing $m_x$ in eqn.~\eqref{min_class} reduces to the problem of 
\begin{eqnarray} \label{constrained_min}
\text{minimizing} \:\: \sum_{k=1}^{\k -1} V_{n+kd}\,x_k \:\: \text{subject to}\:\: \sum_{k=1}^{\k -1} F_{kd}\,x_k = x+V_n\,t_x.
\end{eqnarray}
\vskip 5pt

\begin{thm} 
Let $a,b,n$ be positive integers. Let $S=\la V_n, V_{n+2}, V_{n+4},\ldots \ra$, where $V_1=a$, $V_2=b$, $\gcd(a,b)=1$. Then the  Ap\'{e}ry set $\text{Ap}(S,V_n)$ is given by  
\end{thm}

\begin{Pf}
Let ${\m}_x$ denote the smallest positive integer in $S$ that is congruent to $x$ modulo $V_n$. Then $\gcd(V_n,V_{n+2})=1$ since $S$ is a numerical semigroup by Theorem \ref{existence}. Thus, $\text{Ap}(S,V_n)$ is the collection ${\m}_{V_{n+2}x}$ as $x$ runs through the set $\{1,\ldots,V_n-1\}$. 

Fix $x \in \{1,\ldots,V_n-1\}$. To determine ${\m}_{V_{n+2}x}$ we must minimize nonnegative integer $m$ for which   
\begin{equation} \label{min_class}
mV_n + V_{n+2}x = V_nx_0 + V_{n+2}x_1 + V_{n+4}x_2 + \cdots + V_{n+2k}x_k + \cdots 
\end{equation} 
has a solution in nonnegative integers $x_0,x_1,x_2,\ldots $. 

By Proposition \ref{V_identity}
\[ V_{n+2k} = F_{2k-1} V_n + F_{2k} V_{n+1}, \]
so that $V_{n+2k} \equiv F_{2k} V_{n+1} \equiv F_{2k} V_{n+2}\pmod{V_n}$. Reducing both sides of eqn.~\eqref{min_class} modulo $V_n$ gives 
\[ x \equiv x_1 + F_4 x_2 + F_6 x_3 + \cdots + F_{2k} x_k + \cdots \pmod{V_n}. \]
Hence, $x_1 + F_4 x_2 + F_6 x_3 + \cdots + F_{2k} x_k + \cdots = x+V_n t$ for some $t \ge 0$, and we seek nonengative integers $x_0,x_1,x_2,\ldots $ such that the expression on the RHS of eqn.~\eqref{min_class} is minimized. Hence, we must choose $x_0=0$ and $t=0$, and so 
\begin{eqnarray} \label{constrained_min}
\text{minimize} & V_{n+2} x_1 + V_{n+4} x_2 + \cdots + V_{n+2k} x_k + \cdots \quad \nonumber \\
\text{subject to} & x_1 + F_4 x_2 + F_6 x_3 + \cdots + F_{2k} x_k + \cdots = x.  
\end{eqnarray}
Since $x \le V_n-1$, $x_k=0$ for each $k$ satisfying $F_{2k} \ge V_n$. Let $m$ denote the largest positive integer for which $F_{2m}<V_n$. 
\end{Pf}

\begin{thm}
The embedding dimension of $S=\la V_n, V_{n+2}, V_{n+4}, \ldots \ra$, $n \ge 3$, is given by 
\[ e(S) = m \] 
where $F_{2m-2} < V_n \le F_{2m}$. In particular, the embedding dimension of numerical semigroups corresponding to $V_n=F_n$ and $V_n=L_n$ are $\lc\frac{n}{2}\rc$ and $\lc\frac{n}{2}\rc+1$, respectively.  
\end{thm}

\begin{Pf}
We prove this separately for $n$ odd and $n$ even. 
\vskip 5pt

\noindent {\sc Case} II. ($n=2m+1$ is odd) 
\vskip 5pt

\noindent {\sc Case} I. ($n=2m$ is even) In this case $S=\la V_{2m},V_{2m+2},V_{2m+2},\ldots \ra$, and we must show that $e(S)=m$. 

Since $F_{2\lc n/2\rc-2}< F_n \le F_{2\lc n/2\rc}$, the embedding dimension for number semigroups corresponding to $V_n=F_n$ is $\lc\frac{n}{2}\rc$. 

From $L_n=F_{n+1}+F_{n-1}$, we have $F_{n+1}<L_n<F_{n+2}$. Thus $F_{2\lc n/2\rc}< L_n \le F_{2\lc n/2\rc+2}$, and so the embedding dimension for number semigroups corresponding to $V_n=L_n$ is $\lc\frac{n}{2}\rc+1$. 
\end{Pf}

\bibitem{Tri08}
A. Tripathi, On the Frobenius Problem for Geometric Sequences, {\it Integers\/} {\bf 8} (2008), Article A43, 5 pp. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\noindent The following bounds for $F_m V_n$ for the cases $V_n=F_n$ and $V_n=L_n$ when $d$ is even are useful in determining $\e(S)$; see Theorem \ref{e(S)=k}.  

\begin{lem} \label{prod_ineq}
Let $m$ and $n$ be positive integers.  
\begin{itemize}
\item[]
\item[{\rm (i)}]
If $m \ge n \ge 3$, then 
\[ F_{m+n-2} < F_m F_n < F_{m+n-1}. \]
If $m \ge n=2$, then $F_{m+n-2}=F_m F_n<F_{m+n-1}$. \\
If $m \ge n=1$, then $F_{m+n-2}=F_m F_n$ if and only if $m=2$ and $F_m F_n=F_{m+n-1}$ holds for each $m$. 
\item[{\rm (ii)}]
If $n \ge 3$, then 
\[ F_{m+n-1} < F_m L_n < F_{m+n}. \]
If $n=2$, then $F_{m+n-1}<F_m L_n$ and $F_m L_n=F_{m+n}$ if and only if $m=2$. \\
If $n=1$, then $F_{m+n-1}=F_m L_n$ holds for each $m$ and $F_m L_n=F_{m+n}$ if and only if $m=1$. 
\end{itemize}
\end{lem}

\begin{Pf}
\begin{itemize}
\item[{\rm (i)}]
We may assume, without of generality, that $m \ge n$. The cases $n=1,2,3$ are easily verified. Assume the inequality holds for each positive integer $<n$, so that we have $F_{m+k-2}<F_m F_k<F_{m+k-1}$ for $k=n-1$ and $k=n-2$. Adding the two inequalities gives the desired inequality for $F_m F_n$. 
\item[{\rm (ii)}]
The cases $n=1,2,3$ are easily verified. Assume the inequality holds for each positive integer $<n$, so that we have $F_{m+k-1}<F_m L_k<F_{m+k}$ for $k=n-1$ and $k=n-2$. Adding the two inequalities gives the desired inequality for $F_m L_n$. 
\end{itemize}
\end{Pf}
\vskip 5pt

\begin{thm} \label{ApSet_even}
Let $S=\la V_n,V_{n+d},V_{n+2d}, \ldots \ra$, where $V_1=a$ and $V_2=b$ are positive and coprime integers, $\gcd(V_n,F_d)=1$ and $d$ is even. Then the  Ap\'{e}ry set is given by  
\[ \Ap(S,V_n) = \left\{ \m\big(V_{n+d}\,x\big): 1 \le x \le V_n-1 \right\} \: \bigcup \: \{0\}, \]
where 
\[  \m\big(V_{n+d}\,x\big) = \sum_{k=1}^{\k-1} V_{n+kd}\,x_k^{\star}, \]
$\k$ is the smallest positive integer for which $F_{\k d}/F_d \ge V_n$, and the sequence $x_1^{\star},\ldots,x_{\k-1}^{\star}$ is determined by the Greedy Algorithm applied to the equation
\[ \sum_{k=1}^{\k-1} \frac{F_{kd}}{F_d}\,x_k = x. \] 
\end{thm}

\begin{Pf}
By Theorem \ref{e(S)=k}, the embedding dimension $\e(S)=\k$, where $\k$ is the smallest positive integer for which $F_{\k d}/F_d \ge V_n$. Let $\m(x)$ denote the smallest positive integer in $S$ that is congruent to $x$ modulo $V_n$. Since $\gcd(V_n,V_{n+d})=1$, by Corollary \ref{V_gcd}, $\Ap(S,V_n)$ is the collection $\m(V_{n+d}\,x)$ as $x$ runs through the set $\{1,\ldots,V_n-1\}$. 

\noindent Fix $x \in \{1,\ldots,V_n-1\}$. To determine $\m(V_{n+d}\,x)$ we must minimize the integer $m_x$ for which   
\begin{equation} \label{min_class}
V_n\,m_x + V_{n+d}\,x = V_{n+d}\,x_1 + V_{n+2d}\,x_2 + \cdots + V_{n+(\k-1)d}\,x_{\k-1} 
\end{equation} 
has a solution in nonnegative integers $x_1,x_2,\ldots,x_k,\ldots $. Thus, $V_n\,m_x+V_{n+d}\,x \ge 0$ but $m_x$ may be zero or negative. 

\noindent From Proposition \ref{V_identity}, part (iii),  
\begin{equation} \label{switch}
V_{n+kd} = -\frac{F_{(k-1)d}}{F_d}\,V_n + \frac{F_{kd}}{F_d}\,V_{n+d} 
\end{equation}
for $k \ge 1$. Using this in eqn.~\eqref{min_class} gives 
\begin{eqnarray} \label{min_class_eq}
V_n\,m_x + V_{n+d}\,x & = & \sum_{k=1}^{\k-1} V_{n+kd}\,x_k \nonumber \\
& = & -\left( \sum_{k=1}^{\k-1} \frac{F_{(k-1)d}}{F_d}\,x_k \right) V_n + \left( \sum_{k=1}^{\k-1} \frac{F_{kd}}{F_d}\,x_k  \right) V_{n+d}.
\end{eqnarray} 
Therefore
\[ x \equiv  \sum_{k=1}^{\k-1} \frac{F_{kd}}{F_d}\,x_k \pmod{V_n} \]
since $\gcd(V_n,V_{n+d})=1$. Thus, we may write 
\[ x = \sum_{k=1}^{\k-1} \frac{F_{kd}}{F_d}\,x_k - V_n\,t \]
with $t \ge 0$ since $1 \le x<V_n$. 

\noindent Thus, the problem of minimizing $m_x$ in eqn.~\eqref{min_class} reduces to the problem of 
\begin{eqnarray} \label{constrained_min}
\text{minimizing} \:\: \sum_{k=1}^{\k-1} V_{n+kd}\,x_k \:\: \text{subject to}\:\: \sum_{k=1}^{\k-1} \frac{F_{kd}}{F_d}\,x_k = x+V_n\,t.
\end{eqnarray}
For a fixed $t \ge 0$, eqn.~\eqref{switch} reduces the above minimization to the problem of 
\begin{eqnarray} \label{constrained_max}
\text{maximizing} \:\: \sum_{k=1}^{\k-1} F_{(k-1)d}\,x_k \:\: \text{subject to}\:\: \sum_{k=1}^{\k-1} \frac{F_{kd}}{F_d}\,x_k = x+V_n\,t.
\end{eqnarray}
\vskip 5pt

\noindent We claim that the optimal solution to the optimization problem in eqn.~\eqref{constrained_max} is obtained by the Greedy Algorithm in Definition \ref{greedy_algo}. Let $(x_1,\ldots,x_{\k-1})$ be any optimal feasible solution to 
\[ F_d\,x_1 + \cdots + F_{(\k-1)d}\,x_{\k-1} = (x+V_n\,t)F_d = X. \]
Define 
\[ k^{\star} = \min \left\{ k: x_k \ne \left\lf \frac{X - \sum_{i=k+1}^{\k-1} F_{id}\,x_i}{F_{kd}} \right\rf \right\}, \]
if such a $k$ exists. If no such $k$ exists, the optimal feasible solution is greedy, as desired. Since 
\[ \left\lf \frac{X - \sum_{k=k^{\star}+1}^{\k-1} F_{kd}\,x_k}{F_{k^{\star}d}} \right\rf = \left\lf \frac{\sum_{k=1}^{k^{\star}} F_{kd}\,x_k}{F_{k^{\star}d}} \right\rf = x_{k^{\star}} +  \left\lf \frac{\sum_{k=1}^{k^{\star}-1} F_{kd}\,x_k}{F_{k^{\star}d}} \right\rf,
\]
we have $\left\lf \frac{\sum_{k=1}^{k^{\star}-1} F_{kd}\,x_k}{F_{k^{\star}d}} \right\rf > 0$. This is equivalent to
\begin{equation} \label{kstar} 
\sum_{k=1}^{k^{\star}-1} F_{kd}\,x_k \ge F_{k^{\star}d}. 
\end{equation}
\vskip 5pt

\noindent Let the greedy solution to the equation 
\[ \sum_{k=1}^{k^{\star}-1} F_{kd}\,g_k = F_{k^{\star}d} \]
be denoted by $g_k^{\star}$, $k=k^{\star}-1,\ldots,1$. By Proposition \ref{greedy_algo_for_F_kd}, 
\[ g_k^{\star} = \begin{cases}
                           L_d-1 & \mbox{ for } k=1, k^{\star}-1; \\
                           L_d-2 & \mbox{ for } 2 \le k \le k^{\star}-2.
                         \end{cases}
\]
\vskip 5pt

\noindent We consider two cases: (i) $x_k=g_k^{\star}$ for all $k<k^{\star}$, and (ii) otherwise.  
\vskip 5pt

\noindent {\sc Case} (i). Define 
\[ {\ov{x}}_k = \begin{cases}
                        0 & \mbox{ for } k<k^{\star}; \\
                        x_k+1 & \mbox{ for } k=k^{\star}; \\
                        x_k & \mbox{ for } k>k^{\star}.
                      \end{cases}
\]
Note that $(x_1,\ldots,x_{\k-1}) \:{\preceq}_r\: ({\ov{x}}_1,\ldots,{\ov{x}}_{\k-1})$. We have 
\[ \sum_{k=1}^{\k-1} F_{kd}\,{\ov{x}}_k = F_{k^{\star}d} + \sum_{k=k^{\star}}^{\k-1} F_{kd}\,x_k = \sum_{k=1}^{k^{\star}-1} F_{kd}\,g_k^{\star} + \sum_{k=k^{\star}}^{\k-1} F_{kd}\,x_k =  \sum_{k=1}^{\k-1} F_{kd}\,x_k = X. 
\]
Moreover, 
\begin{eqnarray*}
\sum_{k=1}^{\k -1} F_{(k-1)d}\,x_k & = & \sum_{k=1}^{k^{\star}-1} F_{(k-1)d}\,g_k^{\star} + \sum_{k=k^{\star}}^{\k -1} F_{(k-1)d}\,x_k \\
& = & \left( (L_d-2) \sum_{k=1}^{k^{\star}-3} F_{kd} + (L_d-1) F_{(k^{\star}-2)d} \right) + \sum_{k=k^{\star}}^{\k -1} F_{(k-1)d}\,x_k \\
& = & \left( F_{(k^{\star}-1)d} - F_d \right) + \sum_{k=k^{\star}}^{\k -1} F_{(k-1)d}\,x_k \\
& < & F_{(k^{\star}-1)d} + \sum_{k=k^{\star}}^{\k -1} F_{(k-1)d}\,x_k \\
& = & \sum_{k=1}^{\k -1} F_{(k-1)d}\,{\ov{x}}_k. 
\end{eqnarray*}
\vskip 5pt

\noindent {\sc Case} (ii). Define $j=\max\{ i<k^{\star}: x_i \ne g_i \}$. By eqn.~\eqref{kstar} and the definition of $g_k^{\star}$, 
\[ \sum_{k=1}^{k^{\star}-1} F_{kd}\,x_k \ge F_{k^{\star}d} = \sum_{k=1}^{k^{\star}-1} F_{kd}\,g_k^{\star}. \]
Thus, for $j \le \ell < k^{\star}$, 
\[ \sum_{k=1}^{\ell} F_{kd}\,x_k \ge \sum_{k=1}^{\ell} F_{kd}\,g_k^{\star}, \]
so that 
\[ x_{\ell} = \left\lf \frac{\sum_{k=1}^{\ell} F_{kd}\,x_k}{F_{\ell d}} \right\rf \ge \left\lf \frac{\sum_{k=1}^{\ell} F_{kd}\,g_k^{\star}}{F_{\ell d}} \right\rf = g_{\ell}^{\star}. \]
In particular, $x_j>g_j$. 
\vskip 5pt

\noindent Define 
\[ {\ov{x}}_k = \begin{cases}
                        x_k & \mbox{ for } k<j-1, k>k^{\star}; \\
                        x_{k+1} & \mbox{ for } k=j-1, k^{\star}; \\
                        x_k - g_k^{\star} - 1 & \mbox{ for } k=j; \\
                        x_k - g_k^{\star} & \mbox{ for } j<k<k^{\star}.
                      \end{cases}
\]
Note that $(x_1,\ldots,x_{\k-1}) \:{\preceq}_r\: ({\ov{x}}_1,\ldots,{\ov{x}}_{\k-1})$. We have 
\begin{eqnarray*}
\sum_{k=1}^{\k-1} F_{kd}\,{\ov{x}}_k & = & \sum_{k=1}^{\k-1} F_{kd}\,x_k + F_{k^{\star}d} + F_{(j-1)d} - (L_d-1) F_{(k^{\star}-1)d} - (L_d-2) \sum_{k=j+1}^{k^{\star}-2} F_{kd} - (L_d-1) F_{jd} \\
& = & \sum_{k=1}^{\k-1} F_{kd}\,x_k \;\; \text{by Proposition \ref{F_identity}, part (i)} \\
& = & X. 
\end{eqnarray*}
\vskip 5pt

\noindent It remains to show that the feasible solution ${\ov{x}}_1,\ldots,{\ov{x}}_{\k-1}$ is greedy in this case. 
\vskip 5pt

\noindent If $j=1$, then
\begin{eqnarray*}
\sum_{k=1}^{\k -1} F_{(k-1)d}\,{\ov{x}}_k & = & \sum_{k=1}^{\k -1} F_{(k-1)d}\,x_k - (L_d-2) \sum_{k=1}^{k^{\star}-3} F_{kd} - (L_d-1) F_{(k^{\star}-2)d} + F_{(K^{\star}-1)d} \\
& = & \sum_{k=1}^{\k -1} F_{(k-1)d}\,x_k + F_d \;\; \text{by Proposition \ref{F_identity}, part (i)} \\
& = & X + F_d. 
\end{eqnarray*}
\vskip 5pt

\noindent If $j>1$, then 
\begin{eqnarray*}
\sum_{k=1}^{\k -1} F_{(k-1)d}\,{\ov{x}}_k & = & \sum_{k=1}^{\k -1} F_{(k-1)d}\,x_k - (L_d-2) \sum_{k=j}^{k^{\star}-3} F_{kd} - (L_d-1) F_{(k^{\star}-2)d} - (L_d-1) F_{(j-2)d} \\
& & + F_{(K^{\star}-1)d} + F_{(j-2)d} \\
& = & \sum_{k=1}^{\k -1} F_{(k-1)d}\,x_k \;\; \text{by Proposition \ref{F_identity}, part (i)} \\
& = & X. 
\end{eqnarray*}
\vskip 5pt

\noindent Therefore, we have proved that the optimal solution to the optimization problem in eqn.~\eqref{constrained_max} is obtained by the Greedy Algorithm in Definition \ref{greedy_algo} for fixed $x \in \{1,\ldots,V_n-1\}$ and fixed $t \ge 0$. We now show that the optimization problem in eqn.~\eqref{constrained_min} is obtained by taking $t=0$ for fixed $x$. 

\noindent As before, fix $x \in \{1,\ldots,V_n-1\}$, and let $x_1^{\star},\ldots,x_{\k -1}^{\star}$ be the greedy solution to
\[ \sum_{k=1}^{\k-1} \frac{F_{kd}}{F_d}\,x_k = x+V_n\,t. \]
Set 
\[ \S(T) = \sum_{k=1}^{\k-1} V_{n+kd}\,x_k^{\star}, \]
where $T=x+V_n\,t$, $t \ge 0$. 
\vskip 5pt

\noindent Set 
\[ \ov{\S}(T) = \sum_{k=1}^K V_{n+kd}\,X_k^{\star}, \]
where $K$ is defined by $F_{Kd}/F_d \le T < F_{(K+1)d}/F_d$ and $X_1^{\star},\ldots,X_K^{\star}$ is the greedy solution to $\sum_{k=1}^K F_{kd}\,x_k=T\,F_d$. We claim that $\ov{\S}(T) \ge \ov{\S}(T-1)$ by inducting on $T$. 
\vskip 5pt

\noindent We have 
\[ \ov{\S}(1) = V_{n+d} < 2\,V_{n+d} = \ov{\S}(2). \]
If $T=F_{Kd}/F_d$, then 
\[ \ov{\S}(T) = V_{n+Kd} \ge V_{n+Kd} - V_{n+d} = \ov{\S}(T-1). \]
If $T \ne F_{Kd}/F_d$, then 
\[ \ov{\S}(T) = \ov{\S}\left(T-\tfrac{F_{Kd}}{F_d}\right) + V_{n+Kd} \ge  \ov{\S}\left(T-\tfrac{F_{Kd}}{F_d}-1\right) + V_{n+Kd} = \ov{\S}(T-1). \]
Thus, $\ov{\S}(T) \ge \ov{\S}(T-1)$ by induction on $T$. 

\noindent Hence 
\[ \S(x) = \ov{\S}(x) \le \ov{\S}(x+V_n\,t) \le \S(x+V_n\,t). \]
\end{Pf}

