    \begin{minipage}[c]{0.5\linewidth}
    \includegraphics[width=\linewidth]{figures/S4,3.pdf}
    \end{minipage}
    \caption{The braid $(\sigma_1^{-1}\sigma_2\sigma_3)^3$ and its closure, the spiral knot $S(4,3,(-1,1,1))$.
    \label{fig:spiral}}
\end{figure}

In this paper, we will usually adapt the convention that $\varepsilon_1 = 1$. Note that given $S(p,q,\varepsilon)$, the knot $S(p,q,-\varepsilon)$ is its mirror image, but we will generally not distinguish between knots and their mirrors in this work. Similarly, we only consider $\varepsilon$ vectors up to inverting the order of the coordinates, as this does not change the knot type; for instance, we consider $(1,-1,1,1)$ and $(1,1,-1,1)$ to be the same $\varepsilon$ vector.

\subsection{Invariants of torus and spiral knots}
Torus knots are well-understood in the sense that many of their invariants have been computed and admit simple formulas.
Recall the following invariants of knots $K\subset S^3$:
\begin{itemize}
\item The \emph{genus} of $K$ is the minimum genus $g(K)$ of an orientable (Seifert) surface in $S^3$ which $K$ bounds.
\item The \emph{Alexander polynomial} of $K$ is $\Delta_K(t)=\det(M-tM^T)$, where $M$ is a Seifert matrix corresponding to any Seifert surface for $K$.
\item The \emph{determinant} of $K$ is $\det(K)=\det(M+M^T)$, where $M$ is again a Seifert matrix for $K$. Note that $\det(K)=\Delta_K(-1)$.
\end{itemize}
For the torus knot $T_{p,q}$, we have genus
\[
g(T_{p,q}) = \frac{(p-1)(q-1)}{2}
\]
and Alexander polynomial
\[
\Delta_{T_{p,q}}(t) = \frac{(t^{pq}-1)(t-1)}{(t^p-1)(t^q-1)}.
\]
As a consequence, Breiland-Oesper-Taalman \cite{BOT} note that the determinant of $T_{p,q}$ is
\[
\det(T_{p,q}) = \begin{cases}
    1, & \text{$p$ and $q$ are both odd}\\
    p, & \text{$p$ is odd and $q$ is even}\\
    q, & \text{$q$ is odd and $p$ is even}
\end{cases}.
\]

It is shown in \cite{BETVWWY} that the above genus formula holds more generally for spiral knots $S(p,q,\varepsilon)$ when $q$ is a prime power.
In \autoref{Ther:genus} we show that this formula holds for \emph{all} spiral knots.
In contrast, Kim, Taalman, and the last author demonstrate that determinants of spiral knots exhibit very different patterns than the simple formula for torus knots \cite{KST}. 
Indeed, we show in \autoref{Ther:Alex} that the Alexander polynomials of spiral knots exhibit a more complicated formula than the one above for torus knots.



