\section{The Alexander polynomials of spiral knots} \label{sec:alexander}

For the sake of notation, throughout this section and the next we will often write $\Delta(t)$ to mean $\Delta_{S(p,q,\varepsilon)}(t)$.

\subsection{Calculating the Seifert matrix}
Let $S(p,q,\varepsilon)$ be a spiral knot. Recall that the Alexander polynomial for any knot can be computed from a Seifert matrix of that knot. To find a form for this matrix given $p$, $q$, and $\varepsilon$, we first obtain a Seifert surface for the spiral knot $S(p,q,\varepsilon)$ using Seifert's algorithm. We refer to the surface given by Seifert's algorithm on the braid form of a spiral knot $S(p,q,\varepsilon)$ as the \textit{cake surface} for $S(p,q,\varepsilon)$, because of the resemblance it bears to a tiered cake; see \autoref{fig:cake}.

\begin{figure}[h]
    \begin{minipage}[c]{0.25\linewidth}   
    \includegraphics[width=\linewidth, ]{figures/SpiralKnot.png}
    \end{minipage}
    \hfill
    \begin{minipage}[c]{0.4\linewidth}
    \includegraphics[width=\linewidth, ]{figures/SeifertSurface.png}
    \end{minipage}
    \hfill
    \begin{minipage}[c]{0.3\linewidth}
    \includegraphics[width=\linewidth, ]{figures/Cake.pdf}
    % Tex seems unhappy with the png version of the file, but likes the pdf for whatever reason
    \end{minipage}   
    \caption{An example of the ``cake surface'' (center and right) for the spiral knot $S(4,3,(1,-1,1))$ (left), which is a Seifert surface for the knot and is made up of disks and half-twist bands connecting each disk to an adjacent disk. The bands are labeled $h_{i,j}$ according to their vertical and horizontal position. The rightmost ``cake surface'' image was generated using SeifertView \cite{SeifertView}.  \label{fig:cake}}
\end{figure}

The cake surface for $S(p,q,\varepsilon)$ has $p$ disks corresponding to Seifert circles and $q$ half-twist bands connecting each disk to an adjacent disk for $q(p-1)$ total twist bands. The half-twist bands of the cake surface are labeled $h_{ij}$ according to their vertical position $1 \leq i \leq p-1$ and horizontal position $1 \leq j \leq q$.
Because the braid form is periodic, the horizontal position of the band does not affect the direction of the twist of $h_{i,j}$ which is thus dictated by $\varepsilon_i$. 

\begin{definition} \label{def:basis}
The \textit{cake homology basis} of $S(p,q,\varepsilon)$ is the set of (homology classes of) loops $\alpha_{ij}$ on the cake surface of $S(p,q,\varepsilon)$ where $1 \leq i \leq p-1$ and $1 \leq j \leq q-1$, and $\alpha_{ij}$ passes up through the half-twist band $h_{ij}$ once, then down through the half-twist band $h_{i,j+1}$ once, and not through any other bands.\footnote{This is the basis developed by Collins \cite{Collins2016} for use in her Seifert matrix computation algorithm \cite{SeifertMatrixCompuations}.}
\end{definition}

\begin{lemma}\label{lem:basis}
    The cake homology basis is a homology basis for the cake surface of $S(p,q,\varepsilon)$.
\end{lemma}

\begin{figure}[h]
    \begin{minipage}[c]{0.3\linewidth}
    \includegraphics[width=\linewidth,]{figures/Surface1.png}
    \end{minipage}
    \hfill
    \begin{minipage}[c]{0.3\linewidth}
    \includegraphics[width=\linewidth,]{figures/Surface2.png}
    \end{minipage}
    \hfill
    \begin{minipage}[c]{0.3\linewidth}
    \includegraphics[width=\linewidth,]{figures/Surface3.png}
    \end{minipage}
    \caption{Finding a homology basis for the cake surface. The left shows an example of the cake homology basis $\alpha_{ij}$ on a cake surface. The center and right show a deformation retraction from the cake surface to a wedge of circles, as described in the proof of \autoref{lem:basis}. \label{fig:retract}}
\end{figure}

\begin{proof}
Let $A = \{\alpha_{ij}\}$ be the cake homology basis of $S(p,q,\varepsilon)$, with the loops oriented clockwise as depicted in \autoref{fig:retract} (left), and let $X$ denote the cake surface. Let $Y$ be the wedge of $(p-1)(q-1)$ circles. To show that $A$ generates the first homology of $X$, we describe a deformation retraction of $X$ onto $Y$. First retract every band $h_{ij}$ to a line as shown in \autoref{fig:retract} (left)-(center). The set of $p$ disks along with the half-twist bands $h_{iq}$ form a contractible subspace of $X$. This subspace can be retracted to a point as in \autoref{fig:retract} (center)-(right). These retractions give us a deformation retraction $f \colon X \to Y$. Note that $H_1(Y)$ has rank $(p-1)(q-1)$. 

For each half-twist band $h_{ij}$, let $\beta_{ij}$ be (the homology class of) a loop in $Y$ corresponding to the image of $h_{ij}$ under $f$ with orientation as depicted in \autoref{fig:retract} (center). Let $B = \{\beta_{ij}\}$. Note that the $\beta_{iq}$ are trivial loops in $Y$ for every $i$ and that there is a bijective correspondence between non-trivial $\beta_{ij} \in B$ and factors in the wedge of circles $Y$. It follows that $B$ is a homology basis for $Y$.  

% Let $A_* = \{a_{ij}\} \subset H_1(X)$ and $B_* = \{b_{ij}\} \subset H_1(Y)$ be the sets of equivalence classes of loops in $A$ and $B$ respectively and
Let $f_* \colon H_1(X) \to H_1(Y)$ be the homomorphism induced by $f$. Note that $f_*(\beta_{iq})=0$ for every $i$. 
Since $\alpha_{ij}$ traverses up $h_{ij}$ then down $h_{i,j+1}$, we have $f_*(\alpha_{ij}) = \beta_{ij} - \beta_{i,j+1}$. Any $\beta_{ij}$ can therefore be written as 
\[\begin{alignedat}{1}\beta_{ij} &= (\beta_{ij} - \beta_{i,j+1}) + (\beta_{i,j+1}-\beta_{i,j+2}) + \cdots + (\beta_{i,q-2}-\beta_{i,q-1}) + (\beta_{i,q-1} + 0) \\
&= f_*(\alpha_{ij}) + f_*(\alpha_{i,j+1}) + \cdots + f_*(\alpha_{i,q-2}) + f_*(\alpha_{i,q-1} ).
\end{alignedat}\]

Thus the subgroup generated by $f_*(A)$ contains $B$, which is a homology basis for $Y$, so  $f_*(A)$ generates $H_1(Y)$. But $f$, being a deformation retraction, is a homotopy equivalence. So the induced map $f_* \colon H_1(X) \to H_1(Y)$ is an isomorphism. It follows that $H_1(X)$ has rank $(p-1)(q-1)$ and $(f_*)^{-1}(f_*(A)) = A$ generates $(f_*)^{-1}(H_1(Y)) = H_1(X)$.
% Now note that $A$ has $(p-1)(q-1)$ elements. Thus,
% \[\text{rk}(A_*) \leq (p-1)(q-1) = \text{rk}(H_1(Y)) = \text{rk}((f_*)^{-1}(H_1(Y)))= \text{rk}(H_1(X)).\] 
% Since $A_*$ generates $H_1(X)$ but does not have higher rank, it follows that $A_*$ is a homology basis for $X$. 
Since $|A|=(p-1)(q-1)=\text{rk}(H_1(X))$, it follows that $A$ is a homology basis for $X$.
\end{proof}

Because the cake homology basis has $(p-1)(q-1)$ elements, the cake surface has genus $(p-1)(q-1)/2$, giving us the following upper bound.

\begin{corollary}\label{lem:upgenus}
The genus $g$ of a spiral knot $S(p,q,\varepsilon)$ satisfies 
\[g(S(p,q,\varepsilon)) \leq \frac{(p-1)(q-1)}{2}.\]
\end{corollary} 

We can now use the cake homology basis of a spiral knot to find general forms for the Seifert matrix  and Alexander polynomial of a spiral knot. One consequence of this will be to achieve the corresponding lower bound for the genus (see \autoref{Ther:genus}). Throughout this paper, we will adopt the convention that blank entries of a matrix are 0. 

\begin{lemma}\label{lem:matrix}
The Seifert matrix $M \in M_{(p-1)(q-1)}(\mathbb{Z})$ for the cake surface of $S(p,q,\varepsilon)$ has the $(q-1) \times (q-1)$ block tri-diagonal form\footnote{This form for $M$ was discovered using \cite{SeifertMatrixCompuations}.}
\[M = \begin{bmatrix} 
-(K+L)& K & & \\
L & \ddots & \ddots & \\
& \ddots & \ddots & K \\
 & & L & -(K+L)
\end{bmatrix}
\]
where $K = [k_{ij}]$ and $L = [l_{ij}]$ are $(p-1)\times(p-1)$ submatrices defined by 
\[k_{ij} = \begin{cases} -1, & j = i,\ \varepsilon_i = -1 \\
0, & \text{otherwise} \end{cases} \text{ and } l_{ij} = \begin{cases} 1, & j = i,\ \varepsilon_i = 1 \\
-1, & j = i+1 \\
0, & \text{otherwise} \end{cases}.\]    
\end{lemma}

\begin{proof}
Consider $S(p,q,\varepsilon)$ and its cake homology basis given by \autoref{def:basis}. Then the Seifert matrix $M$ for the cake surface of $S(p,q,\varepsilon)$ can be expressed in the $(q-1) \times (q-1)$ block form
\[M = \begin{bmatrix} 
M_{11} & \dots & M_{1,q-1} \\
\vdots & \ddots & \vdots \\
M_{q-1,1} & \dots & M_{q-1,q-1} \\
\end{bmatrix}\]
where $M_{nm}$ is a $(p-1) \times (p-1)$ matrix defined by 
\[M_{nm} = [\lk(\alpha_{i,n}, \alpha_{j,m}^+)]  = \begin{bmatrix} 
\lk(\alpha_{1,n},\alpha_{1,m}^+) & \dots & \lk(\alpha_{1,n},\alpha_{p-1,m}^+)\\
\vdots & \ddots & \vdots \\
\lk(\alpha_{p-1,n},\alpha_{1,m}^+) & \dots & \lk(\alpha_{p-1,n},\alpha_{p-1,m}^+)\\
\end{bmatrix}\]
and $\lk(\alpha,\alpha')$ denotes the linking number of loops $\alpha$ and $\alpha'$. See \autoref{fig:loops}.

\begin{figure}[h]
\centering
    \includegraphics[width=.5\linewidth]{figures/Loops.png}
    \caption{A portion of the cake homology basis on a cake surface, used for reference in the construction of the Seifert matrix in the proof of \autoref{lem:matrix}. \label{fig:loops}}
\end{figure}

Note that by construction, the loop $\alpha_{ij}$ will only intersect the loops $\alpha^+_{ij}$, $\alpha^+_{i,j\pm 1}$, $\alpha^+_{i\pm1,j}$, and $\alpha^+_{i \mp 1, j \pm 1}$. 
It follows that $\lk(a_{ij}, a^+_{i',j'})$ will be zero when $|j-j'| > 1$, and therefore $M_{nm} = 0$ if $|n-m| > 1$. Since half-twist bands with the same vertical position $i$ twist in the same direction, it follows that $\lk(\alpha_{i,j},\alpha_{i',j'}^+) =  \lk(\alpha_{i,j+1},\alpha_{i',j'+1}^+)$, which implies that $M_{nm} = M_{n+1,m+1}$. Thus $M$ has the form 
\[M = \begin{bmatrix} 
M_{11} & M_{12} & & \\
M_{21} & \ddots & \ddots & \\
& \ddots & \ddots & M_{12} \\
 & & M_{21} & M_{11}
\end{bmatrix}
.\]
We will now compute $M_{21}$, $M_{11}$, and $M_{12}$:
 \[(M_{21})_{ij} = \lk(\alpha_{i,2},\alpha_{j,1}^+) = \begin{cases}
\lk(\alpha_{i,2},\alpha_{i,1}^+),  & j = i, \varepsilon_i = 1 \\
\lk(\alpha_{i,2},\alpha_{i,1}^+),  & j = i, \varepsilon_i = -1 \\
\lk(\alpha_{i,2},\alpha_{i+1,1}^+),  & j = i+1 \\
\lk(\alpha_{i,2},\alpha_{j,1}^+),  & \text{otherwise}
\end{cases} 
= \begin{cases}
1, & j = i, \varepsilon_i = 1 \\
0, & j = i, \varepsilon_i = -1 \\
-1, & j = i+1 \\
0, & \text{otherwise},
\end{cases}\]
\[(M_{11})_{ij} = \lk(\alpha_{i,1},\alpha_{j,1}^+) = \begin{cases}
 \lk(\alpha_{i,1},\alpha_{i-1,1}^+),  & j = i-1 \\
 \lk(\alpha_{i,1},\alpha_{i,1}^+), & j = i, \varepsilon_i = 1 \\
 \lk(\alpha_{i,1},\alpha_{i,1}^+),  & j = i, \varepsilon_i = -1 \\
 \lk(\alpha_{i,1},\alpha_{i+1,1}^+),  & j = i+1 \\
 \lk(\alpha_{i,1},\alpha_{j,1}^+),  & \text{otherwise}
\end{cases}
= \begin{cases}
0, & j = i - 1 \\
-1, & j = i , \varepsilon_i = 1 \\
1, & j = i , \varepsilon_i = -1 \\
1, & j = i + 1 \\
0, & \text{otherwise},
\end{cases}\]
 \[(M_{12})_{ij} = \lk(\alpha_{i,1},\alpha_{j,2}^+) = \begin{cases}
 \lk(\alpha_{i,1},\alpha_{i-1,2}^+), & j = i - 1 \\
 \lk(\alpha_{i,1},\alpha_{i,2}^+), & j = i, \varepsilon_i = 1 \\
 \lk(\alpha_{i,1},\alpha_{i,2}^+), & j = i, \varepsilon_i = -1 \\
 \lk(\alpha_{i,1},\alpha_{j,2}^+), & \text{otherwise}
\end{cases}
= \begin{cases}
0, & j = i - 1 \\
0, & j = i, \varepsilon_i = 1 \\
-1, & j = i, \varepsilon_i = -1 \\
0, & \text{otherwise}.
\end{cases}\]
Setting $L = M_{21}$ and $K = M_{12}$ gives the result. 
\end{proof}

\subsection{Proof of main theorem}
We now present and prove our main theorem. 

\Alex

The simple recursive structure of this formula allows us to more easily track the effects of changes in $q$ and $\varepsilon$ than directly computing the Alexander polynomial from the Seifert matrix, illuminating several properties about both the degree and coefficients of the polynomial, detailed in \autoref{subsec:properties}. Note that although it may not seem so at first glance, the $\mathcal{C}_k$ do depend heavily on $\varepsilon$, as their recursive definition depends on $\mu$, which in turn depends on $\varepsilon$. As a convention, we define $\mu(i)=0$ when $i\notin\{1,\dots,p-1\}$ in order to make certain arguments more concise.

Our results throughout this paper are phrased for the case of knots, but \autoref{Ther:Alex} also holds for the single-variable Alexander polynomials of spiral links. 
We discuss this further in \autoref{sec:future}.

\begin{proof} 
Consider a tri-diagonal block matrix with no corners, that is, a matrix of the form 
\[\begin{bmatrix} 
A_1 & B_1 & & \\
C_1 & \ddots & \ddots & \\
& \ddots & \ddots & B_{n-1} \\
 & & C_{n-1} & A_{n}
\end{bmatrix}
\]
where $A_i,B_i,C_i$ are $m\times m$ matrices. A result of Molinari \cite{Molinari_2008} states that the determinant of this matrix is 
\[(-1)^{mn} \det (R_n) \det (B_1\cdot \cdot \cdot B_{n-1})\]
where $R_n$\footnote{Molinari denotes $R_n$ as $T(n)_{11}$.} satisfies the recurrence relation
\[R_k = -B_k^{-1}A_kR_{k-1} - B_k^{-1}C_{k-1}R_{k-2}\]
with $R_0 = I_{m}$ and $R_1 = -B_1^{-1}A_1$. 

Let $M$ be the Seifert matrix for the cake homology basis of $S(p,q,\varepsilon)$. \autoref{lem:matrix} shows that $M-tM^T$ has the form
\[M-tM^T = \begin{bmatrix} 
-(K+L)+t(K+L)^T& K-tL^T & & \\
L-tK^T & \ddots & \ddots & \\
& \ddots & \ddots & K-tL^T \\
 & & L-tK^T & -(K+L)+t(K+L)^T
\end{bmatrix}.
\]
Note that $M-tM^T$ is a tri-diagonal block matrix with no corners, with  
\begin{align*}
    A_1 &= \cdots = A_{q-1} = -(K+L)+t(K+L)^T
    \\B_1 &= \cdots = B_{q-2} = K-tL^T
    \\C_1 &= \cdots = C_{q-2} = L-tK^T
\end{align*}
(where here $m=p-1$ and $n = q-1$). We can substitute these submatrices into the equation for $R_k$ to get 
\[\Delta(t) = \det(M-tM^T) = (-1)^{(p-1)(q-1)}\det(R_{q-1})\det((K-tL^T)^{q-2}).\]
Let $\mathbf{A} = B_k^{-1}C_k = (K-tL^T)^{-1}(L-tK^T)$.
It follows that for all $k=1,\ldots,q-1$,
\[\begin{alignedat}{1}
-B_k^{-1}A_k &= -(K-tL^T)^{-1}(-K-L+t(K+L)^T) \\
&= (K-tL^T)^{-1}(K+L-t(K+L)^T) \\
&= (K-tL^T)^{-1}(K-tL^T+L-tK^T) \\
&= (K-tL^T)^{-1}(K-tL^T)+(K-tL^T)^{-1}(L-tK^T) \\
&= I+\mathbf{A} .\\
\end{alignedat}\]

We induct on $k$ to show that $R_k=I+\mathbf{A}+ \cdots +\mathbf{A}^k$.
This holds for $k=0,1$ since $R_0 = I$ and $R_1 = -B_1^{-1}A_1 = I+\mathbf{A}$. 
Suppose that $R_i = I + \mathbf{A} + \cdots + \mathbf{A}^i$ for all $i < k$. Then 
\[\begin{alignedat}{1}
R_k &= -B_k^{-1}A_k R_{k-1} - B_k^{-1}C_{k-1}R_{k-2} \\
&= (I+\mathbf{A})R_{k-1}-\mathbf{A}R_{k-2} \\
&= R_{k-1} + \mathbf{A}(R_{k-1} - R_{k-2}) \\
&= I + \mathbf{A} + \cdots + \mathbf{A}^{k-1} + \mathbf{A}(\mathbf{A}^{k-1})\\
&= I + \mathbf{A} + \cdots + \mathbf{A}^k. \\
\end{alignedat}\]
Thus $R_{q-1} = I + \mathbf{A}+ \cdots + \mathbf{A}^{q-1}$. Note that $K-tL^T$ is a lower triangular matrix with $-t$'s and $-1$'s on the diagonal. So $\det((K-tL^T)^{q-2})= \pm t^n$ for some $n \in \mathbb{N}$. Since the Alexander polynomial is defined up to multiplication by $\pm t^\ell$ for $\ell \in \mathbb{Z}$, we have
\[\Delta(t) = \det(M-tM^T)=\det(R_{q-1}) = \det(I+ \mathbf{A} + \cdots + \mathbf{A}^{q-1}). \]

Let $\mathbf{A} = P J P^{-1}$, where $J$ is the Jordan normal form of $\mathbf{A}$. Then we have
\[\begin{alignedat}{1}
\Delta(t) &= \det(I + \mathbf{A}+ \cdots + \mathbf{A}^{q-1}) \\
&= \det(P J^0 P^{-1} + PJP^{-1}+ \cdots + P J^{q-1} P^{-1}) \\
&= \det(P(J^0 + \cdots +J^{q-1} )P^{-1}) \\
&= \det(J^0 + \cdots +J^{q-1} ). \\
\end{alignedat}\]
Let $\lambda_m$ for $1 \leq m \leq p-1$ be the eigenvalues of $\mathbf{A}$. Then the matrix $J^0 + \cdots +J^{q-1}$ is an upper triangular matrix with diaognal entries $[J^0+\cdots+J^{q-1}]_{ii}=\lambda_i^0 + \cdots + \lambda_i^{q-1}$. The determinant is the product of these entries:
\[
\Delta(t) = \det(J^0 + \cdots +J^{q-1} ) = \prod\limits_{m = 1}^{p-1} (\lambda_m^0 + \cdots + \lambda_m^{q-1}) = \prod\limits_{m = 1}^{p-1} \sum_{j=0}^{q-1}\lambda_m^j.
\]
Noting that the polynomial $f(y)=\sum_{j=0}^{q-1} y^j$ has $q-1$ roots given by $e^\frac{2 \pi \ell i}{q}$ where  $\ell \in \mathbb{Z}$ and $1 \le \ell \le q-1$, and the characteristic polynomial $\chi(x)$ of $\mathbf{A}$ has roots given by the eigenvalues $\lambda_m$ where $m \in \mathbb{Z}$ and $1 \le m \le p-1$, we can factor both of these polynomials.
\begin{align*}
    f(y) &= (y-e^\frac{2\pi i}{q})(y-e^\frac{2\pi 2 i}{q})\cdots(y-e^\frac{2\pi (q-1) i}{q}) = \prod_{\ell=1}^{q-1}(y-e^\frac{2\pi \ell i}{q})\\
    \chi(x) &= (x-\lambda_1)(x-\lambda_2)\cdots(x-\lambda_{p-1}) = \prod_{m=1}^{p-1}(x-\lambda_m)
\end{align*}

Thus, we can simplify the determinant of $J^0+\cdots+J^{q-1}$ to
\[
\prod\limits_{m = 1}^{p-1} \sum_{j=0}^{q-1}\lambda_m^j
=\prod\limits_{m = 1}^{p-1} f(\lambda_m)
= \prod\limits_{m = 1}^{p-1} \prod_{\ell = 1}^{q-1} (\lambda_m - e^\frac{2\pi \ell i}{q})
=(-1)^{(p-1)(q-1)}\prod\limits_{m = 1}^{p-1} \prod_{\ell = 1}^{q-1} (e^\frac{2\pi \ell i}{q} - \lambda_m).
\]
Because $\gcd(p,q)=1$, at least one of $p$ or $q$ must be odd, so $(p-1)(q-1)$ is even.\footnote{Note that even if we did not have $\gcd(p,q)=1$, that is, if we had a spiral \textit{link}, this would not cause a problem here as the Alexander polynomial is defined up to multiplication by $\pm 1$.} Furthermore, we can switch the order of the products to get
\[
(-1)^{(p-1)(q-1)}\prod\limits_{m = 1}^{p-1} \prod_{\ell = 1}^{q-1} (e^\frac{2\pi \ell i}{q} - \lambda_m)
= \prod_{\ell = 1}^{q-1} \prod\limits_{m = 1}^{p-1} (e^\frac{2\pi \ell i}{q} - \lambda_m)
= \prod_{\ell = 1}^{q-1} \chi(e^\frac{2\pi \ell i}{q}).
\]
% This is the point at which the footnote breaks
In \autoref{sec:lemmaproofs} we will prove the following lemma. 
\begin{restatable}{lemma}{char}
\label{lem:char}%
The characteristic polynomial $\chi$ of $\mathbf{A}$ is given by $\chi(x) = \mathcal{C}_{p-1}(x,t)$.
\end{restatable}

Therefore by \autoref{lem:char} we have
\[
\Delta(t) = \prod_{\ell = 1}^{q-1} \chi(e^\frac{2\pi \ell i}{q})
= \prod_{\ell = 1}^{q-1} \mathcal{C}_{p-1}(e^\frac{2\pi\ell i}{q},t),
\] 
and we are done.
\end{proof}

\subsection{Properties of the Alexander polynomial} \label{subsec:properties}
To find general properties of $\Delta (t)$, we first look into the general form of the $\mathcal{C}_k(x,t)$ defined recursively in \autoref{Ther:Alex}. We define the following notation to aid in this endeavor.

\begin{itemize}
    \item  Let $\alpha_k$ be the number of $1$'s and $\beta_k$ the number of $-1$'s in the first $k$ terms of $\varepsilon$. Then $\alpha_{p-1}$ and $\beta_{p-1}$ are the numbers of $1$'s and $-1$'s, respectively, in $\varepsilon$. We define $\alpha_0 = \beta_0 = 0$. Note that $\alpha_k + \beta_k = k$.
    \item Call a string of consecutive positive $1$'s in $\varepsilon$ a \textit{positive block} and a row of consecutive $-1$'s a \textit{negative block}. Let $A_k$ and $B_k$ be the number of positive and negative blocks in the first $k$ terms of $\varepsilon$, respectively.
    \item Let $\gamma_k$ be the number of times that $\varepsilon$ changes sign in its first $k$ entries. Note that $\gamma_k = A_k+B_k-1$.
\end{itemize}

For example, if $\varepsilon = (1,1,-1,-1,-1,1,1,\ldots)$ then $\alpha_7=4$, $\beta_7=3$, $A_7=2$, $B_7=1$, and $\gamma_7=2$. We can then describe the general form of $\mathcal{C}_k(x,t)$ as follows.

\begin{restatable}{lemma}{cform}
\label{lem:cform}%
$\mathcal{C}_k(x,t)$ has the form
    \[\mathcal{C}_k(x,t) = \frac{1}{t^{\alpha_k}}\left(\mathcal{C}_k^0(x) + \mathcal{C}_k^1(x)t + \dots + \mathcal{C}_k^k(x)t^k\right) = \sum_{i = 0}^k\mathcal{C}_k^i(x)t^{i-\alpha_k},\]
    where $\mathcal{C}_k^0(x) = x^{\beta_k}$, $\mathcal{C}_k^1(x) = (A_kx-\gamma_k+\frac{B_k}{x})x^{\beta_k}$, and $\mathcal{C}_k^k(x) = x^{\alpha_k}$. 
\end{restatable}

Together, \autoref{Ther:Alex} and \autoref{lem:cform} give the following form for $\Delta(t)$:
\[
    \Delta(t) = \prod\limits_{\ell = 1}^{q-1} 
\mathcal{C}_{p-1}\left(e^\frac{2\pi \ell i}{q},t\right) = \prod\limits_{\ell = 1}^{q-1}\sum_{j = 0}^{p-1}\mathcal{C}_{p-1}^j(e^\frac{2\pi \ell i}{q})t^{j-\alpha_{p-1}}.
\]

We defer the proof of \autoref{lem:cform} to \autoref{sec:lemmaproofs}, but first we point out several properties that follow from this expression.

\begin{corollary} \label{cor:deg}
    The Alexander polynomial of the spiral knot $S(p,q,\varepsilon)$ has degree $(p-1)(q-1)$.
\end{corollary}
\begin{proof}
We know from \autoref{lem:cform} that $\mathcal{C}_{p-1}^{0}(e^\frac{2\pi \ell i}{q}) = (e^\frac{2\pi \ell i}{q})^{\beta_{p-1}} \neq 0$ and $\mathcal{C}_{p-1}^{p-1}(e^\frac{2\pi \ell i}{q}) = (e^\frac{2\pi \ell i}{q})^{\alpha_{p-1}} \neq 0$ for all $\ell$. Therefore, the lowest power of $t$ in $\Delta(t)$ comes from multiplying the lowest power of $t$ in each summand within the product to get $t^{(q-1)(-\alpha_{p-1})}$. Likewise, the highest power of $t$ in $\Delta(t)$ is $t^{(q-1)(p-1-\alpha_{p-1})}$.
The degree of the Alexander polynomial of $S(p,q,\varepsilon)$ is the degree of the highest power of $t$ minus the degree of the lowest power of $t$:
\[
    (q-1)(p-1-\alpha_{p-1}) - (q-1)(-\alpha_{p-1}) = (q-1)(p-1-\alpha_{p-1}+\alpha_{p-1}) = (q-1)(p-1).
\]
\end{proof}

In \autoref{subsec:invariants} we will use \autoref{cor:deg} to determine the genus of any spiral knot (see \autoref{Ther:genus}). The following two corollaries, which concern the first and second coefficients of the Alexander polynomial, will be useful for classifying low-complexity spiral knots in \autoref{subsec:examples}. We will additionally use \autoref{cor:coeff} to conclude that $S(p,q,\varepsilon) = S(q,p,\varepsilon')$ for some $\varepsilon'$ if and only if $S(p,q,\varepsilon)$ is a torus knot (see \autoref{Ther:swappq}). 

As the Alexander polynomial is symmetric, the coefficients of the highest and second highest powers of $t$ equal the coefficients of the lowest and second lowest powers, respectively, and in the proofs that follow we calculate the coefficients of the lower powers for the sake of ease of notation.
We denote the coefficients of the lowest and second lowest powers of $t$ by $\Delta^0$ and $\Delta^1$, respectively.

\begin{corollary} \label{cor:monic}
    All spiral knots have monic Alexander polynomial.
\end{corollary}

\begin{proof}
Recall that the Alexander polynomial is symmetric.
Collecting the coefficients of $t^{(q-1)(-\alpha_{p-1})}$ and then applying \autoref{lem:cform}, we get:
\[\Delta^0 = \prod_{\ell =1}^{q-1}\mathcal{C}_{p-1}^0(e^\frac{2 \pi \ell  i}{q}) = \prod_{\ell =1}^{q-1}e^\frac{2 \pi \ell  \beta_{p-1} i}{q} = e^\frac{2 \pi \left(\sum_{\ell =1}^{q-1}\ell \right) \beta_{p-1} i}{q } = e^\frac{2 \pi \frac{(q-1)(q)}{2} \beta_{p-1} i}{q} = e^{ \pi (q-1) \beta_{p-1} i} = \pm 1. \]
\end{proof}

\begin{corollary} \label{cor:coeff}
    The second coefficient of the Alexander polynomial of the spiral knot $S(p,q,\varepsilon)$ is $\pm (q\gamma_{p-1} + 1)$.
\end{corollary}

\begin{proof}
Recall that the Alexander polynomial is symmetric. Collecting the coefficients of $t^{-(q-1)\alpha_{p-1}+1}$ then applying \autoref{lem:cform}, we get the following string of equalities. Note that $\mathcal{C}_{p-1}^{0}(e^\frac{2\pi \ell i}{q}) = (e^\frac{2\pi \ell i}{q})^{\beta_{p-1}} \neq 0$. 

\begin{align*}
 \Delta^1 &= \sum_{j=1}^{q-1} \left( 
\mathcal{C}_{p-1}^1 (e^{\frac{2\pi j i}{q}})\prod_{\substack{\ell=1 \\ \ell \neq j}}^{q-1} \mathcal{C}_{p-1}^0 (e^{\frac{2\pi \ell i}{q}}) \right)
\\&=\sum_{j = 1}^{q-1} \left( \prod_{\ell =1}^{q-1}C_{p-1}^0(e^\frac{2 \pi \ell  i}{q}) \right) \frac{C_{p-1}^1(e^\frac{2 \pi j i}{q})}{C_{p-1}^0(e^\frac{2 \pi j i}{q})}
\\&=\sum_{j = 1}^{q-1} \Delta^0 \frac{C_{p-1}^1(e^\frac{2 \pi j i}{q})}{C_{p-1}^0(e^\frac{2 \pi j i}{q})}
\\&= \pm \sum_{j = 1}^{q-1} \frac{C_{p-1}^1(e^\frac{2 \pi j i}{q})}{e^\frac{2 \pi j \beta_{p-1} i}{q}}
\\& = \pm \sum_{j = 1}^{q-1} \frac{(A_{p-1}e^{\frac{2\pi j i}{q}} - \gamma_{p-1} + B_{p-1}e^{-\frac{2\pi j i}{q}} )(e^{\frac{2\pi j \beta_{p-1} i}{q}})}{e^\frac{2 \pi j \beta_{p-1} i}{q}}
\\&= \pm \sum_{j = 1}^{q-1}A_{p-1}e^{\frac{2\pi j i}{q}} - \gamma_{p-1} + B_{p-1}e^{-\frac{2\pi j i}{q}}  \\
&= \pm \left(A_{p-1}\sum_{j = 1}^{q-1}e^{\frac{2\pi j i}{q}} - \sum_{j = 1}^{q-1}\gamma_{p-1} + B_{p-1}\sum_{j = 1}^{q-1}e^{-\frac{2\pi j i}{q}} \right) \\
&= \pm\left(-A_{p-1} - (q-1)\gamma_{p-1} - B_{p-1} \right) \\
&= \mp\left( (q-1)\gamma_{p-1} +A_{p-1}+ B_{p-1} \right) \\
&= \mp(q\gamma_{p-1}+1).
\end{align*}
\end{proof}

To our knowledge, \autoref{cor:deg}, \autoref{cor:monic}, and \autoref{cor:coeff} (and their consequences) are the first known obstructions to a knot being spiral which are not obstructions to a knot being periodic. 
Known periodicity obstructions include the Murasugi conditions \cites{Murasugi,DavisLivingston}, discussed in \autoref{sec:future}, and the Edmonds conditions \cite{Edmonds}, which we note in \autoref{subsec:invariants} can be used to give an alternative proof of \autoref{Ther:genus}.

Observe that, for example, the knot $5_2$ is a hyperbolic periodic knot with period 2 and no other nontrivial period (see KnotInfo \cite{KnotInfo}). If $5_2$ was a spiral knot, then we would have $5_2=S(p,2,\varepsilon)$. Its Alexander polynomial is $\Delta_{5_2}(t)=2t^2-3t+2$. We can employ each of \autoref{cor:deg}, \autoref{cor:monic}, and \autoref{cor:coeff} to show $5_2$ is not spiral.

\autoref{cor:monic} immediately proves this, since $\Delta_{5_2}(t)$ has leading coefficient 2. Alternatively, we could apply \autoref{cor:deg} to see that if $5_2$ was spiral, we would have $p=3$. Performing a census of all spiral knots $S(3,2,\varepsilon)$, as we do in \autoref{subsec:examples}, then shows that $5_2$ is not spiral. (The only such knots are the right-handed trefoil, its mirror, and the figure-eight knot.) Instead of identifying spiral knots $S(3,2,\varepsilon)$, we could further apply \autoref{cor:coeff} to see that if $5_2$ was spiral, $\varepsilon$ would satisfy $\gamma_{p-1}=2$, which is impossible since $\gamma_{p-1}<p-1$. 

\subsection{Proofs of technical lemmas}
\label{sec:lemmaproofs}
We will now prove \autoref{lem:char} and \autoref{lem:cform}.

\char*

\begin{proof} We first find a general form for the matrix $\mathbf{A}$. Let $B \vcentcolon = K-tL^T$ and $C \vcentcolon = L-tK^T$. We have $\mathbf{A} = B^{-1}C = (K-tL^T)^{-1}(L-tK^T)$, where $K = [k_{ij}]$ and $L = [l_{ij}]$ are as previously defined: 
\[k_{ij} = \begin{cases} -1, & j=i,\ \varepsilon_i = -1 \\
0, & \text{otherwise} \end{cases} \text{ and } l_{ij} = \begin{cases} 1, & j=i,\ \varepsilon_i = 1 \\
-1, & j = i + 1 \\
0, & \text{otherwise} \end{cases}.\] 
Recall that $\mu$ is defined as $\mu(i) = \begin{cases}
1, & \varepsilon_i = 1 \\
t, & \varepsilon_i = -1 \\
0, & \text{otherwise}
\end{cases}$. Then $B = [b_{ij}]$ and $C = [c_{ij}]$ are given by: 
\begin{align*}
b_{ij} &= k_{ij} - tl_{ji} = \begin{cases}
-\frac{t}{\mu(i)}, & j=i \\
t, & j = i-1 \\
0, & \text{otherwise}
\end{cases},
\\
c_{ij} &= l_{ij} - tk_{ji} = \begin{cases}
\mu(i), & j=i \\
-1, & j = i+1 \\
0, & \text{otherwise}
\end{cases}.
\end{align*}
Let $D = [d_{ij}]$ be defined by $d_{ij} = \begin{cases}
-\frac{1}{t}\prod\limits_{j \leq l \leq i} \mu(l), & j \leq i \\
0, & \text{otherwise}
\end{cases}.$

We show that $D = B^{-1}$ by calculating the $(i,j)$ entry of the product $BD$. 
\[\begin{alignedat}{1}
[BD]_{ij} = \sum\limits_{k=1}^{p-1} b_{ik}d_{kj} &= b_{i,i-1}d_{i-1,j} + b_{ii}d_{ij} \\
&= td_{i-1,j} - \frac{t}{\mu(i)}d_{ij} \\
&= \begin{cases}
\frac{1}{\mu(i)} \prod\limits_{i \leq l \leq i} \mu(l), & j=i \\
-\prod\limits_{j \leq l \leq i-1} \mu(l) + \frac{1}{\mu(i)} \prod\limits_{j \leq l \leq i} \mu(l), & j < i \\
0, & \text{otherwise} 
\end{cases} \\
&= \begin{cases}
1, & j=i \\
0, & \text{otherwise}
\end{cases} \\
\end{alignedat}\]

So we have $BD = I$. Since $B$ is invertible, we have $\mathbf{A} = B^{-1}C = DC$. The general form for $\mathbf{A} = [a_{ij}]$ is therefore given by the following.
\begin{align*}
a_{ij} = \sum\limits_{k=1}^{p-1} d_{ik}c_{kj} &= d_{ij}c_{jj} + d_{i,j-1}c_{j-1,j} \\
&= \mu(j)d_{ij} - d_{i,j-1} \\
&= \begin{cases}
\frac{1}{t}\prod\limits_{i \leq l \leq i} \mu(l), & j = i+1\\
-\frac{1}{t}\left(\mu(j)\prod\limits_{j \leq l \leq i} \mu(l) - \prod\limits_{j-1 \leq l \leq i} \mu(l)\right), & 1 \leq j \leq i \\
0, & \text{otherwise} \\
\end{cases} \\
&= \begin{cases}\frac{1}{t}\mu(i), & j = i+1\\
\frac{1}{t}\Big(\mu(j-1) - \mu(j) \Big)\prod\limits_{j \leq l \leq i} \mu(l),  & 1 \leq j \leq i \\
0, & \text{otherwise} \\
\end{cases} \\
\end{align*}
When $j < i$, note that 
\[a_{ij} = \frac{\mu(j-1)-\mu(j)}{t}\prod\limits_{j \leq l \leq i} \mu(l) 
= \mu(i)\left(\frac{\mu(j-1)-\mu(j)}{t}\prod\limits_{j \leq l \leq i-1} \mu(l)\right) = \mu(i)a_{i-1,j}.\] Additionally, when $j=i$, we have \[a_{jj}=\frac{\mu(j-1)-\mu(j)}{t}\mu(j).\]

We now want to find the characteristic polynomial of $\mathbf{A}$. Define $P_k$ to be the submatrix given by the first $k$ rows and columns of $xI-\mathbf{A}$. We take $P_0$ to be the empty matrix.
Given a square matrix $A$, define $\widehat{A}$ to be the submatrix obtained by deleting the second-to-last row and last column from $A$. If $A$ is a $1\times 1$ matrix, $\widehat{A}$ is the empty matrix. For the sake of convenience, we take the determinant of the empty matrix to be 1. The matrices $\widehat{P}_k$ will appear in our computation of the determinant of $xI-\mathbf{A}$ via cofactor expansion.

We can utilize the general form for $\mathbf{A}$ to write down the following matrices. We have 

\[
\renewcommand{\arraystretch}{1.3}
P_k = \left[\begin{array}{c|c}
  \begin{matrix}
  & & & & \\
  & &P_{k-1}& & \\
  & & & &\\
  \end{matrix}
  & 
  \begin{matrix}
  0 \\
  \vdots \\
  0 \\
  -a_{k-1,k}
  \end{matrix}
  \\
\hline
  \begin{matrix}
-\mu(k)a_{k-1,1} & \dots & -\mu(k)a_{k-1,k-2} &-\mu(k)a_{k-1,k-1}
  \end{matrix} &
   x-a_{kk}
\end{array}\right]
\]
so that
\[\renewcommand{\arraystretch}{1.3}
\widehat{P}_k = \left[\begin{array}{c|c}
  \begin{matrix}
  & & & & \\
  & &P_{k-2}& & \\
  & & & &\\
  \end{matrix}
  & 
  \begin{matrix}
  0 \\
  \vdots \\
  0 \\
  -a_{k-2,k-1}
  \end{matrix}
  \\
\hline
  \begin{matrix}
-\mu(k)a_{k-1,1} & \dots & -\mu(k)a_{k-1,k-2}
  \end{matrix} &
  -\mu(k)a_{k-1,k-1}
\end{array}\right] 
\]
and
\[\renewcommand{\arraystretch}{1.3}
P_{k-1} = \left[\begin{array}{c|c}
  \begin{matrix}
  & & & & \\
  & &P_{k-2}& & \\
  & & & &\\
  \end{matrix}
  & 
  \begin{matrix}
  0 \\
  \vdots \\
  0 \\
  -a_{k-2,k-1}
  \end{matrix}
  \\
\hline
  \begin{matrix}
-a_{k-1,1} & \dots & -a_{k-1,k-2}
  \end{matrix} &
  x-a_{k-1,k-1}
\end{array}\right].
\]
We would like to compare the matrices $\widehat{\widehat{P\, }}_k$ and $\widehat{P}_{k-1}$. These are given by
\[\renewcommand{\arraystretch}{1.3}
\widehat{\widehat{P\, }}_k = \left[\begin{array}{c|c}
  \begin{matrix}
  & & & & \\
  & &P_{k-3}& & \\
  & & & &\\
  \end{matrix}
  & 
  \begin{matrix}
  0 \\
  \vdots \\
  0 \\
  -a_{k-3,k-2}
  \end{matrix}
  \\
\hline
  \begin{matrix}
-\mu(k)a_{k-1,1} & \dots & -\mu(k)a_{k-1,k-3}
  \end{matrix} &
  -\mu(k)a_{k-1,k-2}
\end{array}\right] 
\]
and
\[\renewcommand{\arraystretch}{1.3}
\widehat{P}_{k-1} = \left[\begin{array}{c|c}
  \begin{matrix}
  & & & & \\
  & &P_{k-3}& & \\
  & & & &\\
  \end{matrix}
  & 
  \begin{matrix}
  0 \\
  \vdots \\
  0 \\
  -a_{k-3,k-2}
  \end{matrix}
  \\
\hline
  \begin{matrix}
-a_{k-1,1} & \dots & -a_{k-1,k-3}
  \end{matrix} &
  -a_{k-1,k-2}
\end{array}\right]. 
\]

We can see that $\widehat{\widehat{P\, }}_k$ is given by multiplying the bottom row of $\widehat{P}_{k-1}$ by $\mu(k)$. It follows that, for $k\geq 3$, $\det(\widehat{\widehat{P\, }}_k) = \mu(k)\det(\widehat{P}_{k-1})$. We cofactor expand along the last column of $\widehat{P}_k$ to get
\[\begin{alignedat}{1}
\det(\widehat{P}_k) &= -\mu(k)a_{k-1,k-1}\det(P_{k-2}) + a_{k-2,k-1} \det(\widehat{\widehat{P\, }}_k) \\
&= -\mu(k)a_{k-1,k-1}\det(P_{k-2}) + a_{k-2,k-1} \mu(k) \det(\widehat{P}_{k-1}).
\end{alignedat}\]
Then, we cofactor expand along the last column of $P_{k-1}$ and rearrange the equation to get
\[\begin{alignedat}{2}
&& \quad \det(P_{k-1}) &= (x-a_{k-1,k-1})\det(P_{k-2}) + a_{k-2,k-1} \det(\widehat{P}_{k-1}) \\
\Leftrightarrow && \quad a_{k-2,k-1} \det(\widehat{P}_{k-1}) &= \det(P_{k-1}) -  (x-a_{k-1,k-1})\det(P_{k-2}). & 
\end{alignedat}\]
Plugging $a_{k-2,k-1} \det(\widehat{P}_{k-1})$ into $\det(\widehat{P}_k)$ gives
\[\begin{alignedat}{1}
\det(\widehat{P}_k) &= -\mu(k)a_{k-1,k-1}\det(P_{k-2}) + \mu(k)\big(\det(P_{k-1}) - (x-a_{k-1,k-1})\det(P_{k-2})\big) \\
&= \mu(k)\big(\det(P_{k-1}) - (x-a_{k-1,k-1})\det(P_{k-2}) - a_{k-1,k-1}\det(P_{k-2})\big) \\
&= \mu(k)\big(\det(P_{k-1}) - x\det(P_{k-2}) \big).
\end{alignedat}\]
By cofactor expanding along the last column of $P_k$, we can see that
\[\begin{alignedat}{1}
\det(P_k)={}& (x-a_{kk})\det(P_{k-1}) + a_{k-1,k}\det(\widehat{P}_k) \\
={}& (x-a_{kk})\det(P_{k-1}) + a_{k-1,k}\mu(k)\big(\det(P_{k-1})-x\det(P_{k-2})\big) \\
={}& (x-a_{kk}+ a_{k-1,k}\mu(k))\det(P_{k-1}) - a_{k-1,k}\mu(k)x\det(P_{k-2}) \\
={}& \left(x-\frac{\mu(k-1)-\mu(k)}{t}\mu(k)+ \frac{\mu(k-1)}{t}\mu(k)\right)\det(P_{k-1}) - \frac{\mu(k-1)}{t}\mu(k)x\det(P_{k-2}) \\
={}& \left(\frac{\mu(k)^2}{t}+x\right)\det(P_{k-1}) - \frac{\mu(k-1)\mu(k)x}{t}\det(P_{k-2}). \\
\end{alignedat}\]

Thus, $\det(P_k)$ satisfies the same recurrence relation as $\mathcal{C}_k(x,t)$ for $k\geq 3$. We check that $\det(P_k)=\mathcal{C}_k(x,t)$ for $0\leq k\leq 2$. By convention, $\det(P_{0}) = 1 = \mathcal{C}_0(x,t)$. When $k=1$, \[\det(P_1)=x-a_{11}=x+\frac{\mu(1)^2}{t}=\mathcal{C}_1(x,t).\] When $k=2$,
\begin{align*}
\det(P_2)&=(x-a_{11})(x-a_{22})-a_{12}a_{21} \\
&=x^2+\left(\frac{\mu(1)^2}{t}+\frac{\mu(2)^2}{t}-\frac{\mu(1)\mu(2)}{t}\right)x+\frac{\mu(1)^2\mu(2)^2}{t^2} \\
&=\mathcal{C}_2(x,t).
\end{align*}
Thus, $\det(P_k)$ and $\mathcal{C}_k(x,t)$ also have the same initial conditions. Therefore, \[\chi(x) = \det(P_{p-1}) = \mathcal{C}_{p-1}(x,t).\] 
\end{proof}

\cform*

\begin{proof}
Refer to \autoref{subsec:properties} for the definitions of $\alpha_k$, $\beta_k$, $A_k$, $B_k$, and $\gamma_k$. We use a strong induction argument to show that $\mathcal{C}_k$ has the above form. We check the base cases directly.
    \[\begin{alignedat}{1}
        \mathcal{C}_0(x,t) &= 1 = \frac{1}{t^0}(1) \\
        \mathcal{C}_1(x,t) &= \frac{\mu(1)^2}{t}+x =\begin{cases}
             \frac{1}{t}+x = \frac{1}{t^1}(x^0t^0+x^1t^1), &\ \varepsilon_1 = 1 \\
             t+x = \frac{1}{t^0}(x^1t^0 + x^0t^1), &\ \varepsilon_1 = -1             
             \end{cases}\\
        \mathcal{C}_2(x,t) &= \left(\frac{\mu(2)^2}{t}+x\right)\left(\frac{\mu(1)^2}{t}+x\right)-\frac{\mu(2)\mu(1)x}{t}   \\
        &= \frac{\mu(1)^2\mu(2)^2}{t^2} + \frac{\mu(1)^2x}{t} + \frac{\mu(2)^2x}{t} - \frac{\mu(2)\mu(1)x}{t} + x^2  \\
        &= \begin{cases}
             \frac{1}{t^2} + \frac{x}{t} + x^2 = \frac{1}{t^2}\left(x^0 + \big(1(x)-0+\frac{0}{x}\big)x^0t^1 + x^2t^2\right), &\ \varepsilon_1 = \varepsilon_2 = 1 \\
