&= \left(\frac{\mu(k)^2}{t}+x\right)\sum_{i = 0}^{k-1}\mathcal{C}_{k-1}^i(x)t^{i-\alpha_{k-1}} - \left(\frac{\mu(k-1)\mu(k)x}{t}\right)\sum_{i = 0}^{k-2}\mathcal{C}_{k-2}^i(x)t^{i-\alpha_{k-2}}. 
\end{align*}
