\begin{align*}
    \cR_t(x,y) &=    \sup \{t (f(x) - f(y)) - \cE(f) \mid f \in \cF(X)\}\\
    &\geq \sup \{t (f(x) - f(y)) - \cE(f) \mid \cE(f) \leq 1\}\\
    &\geq  t\sup \{ f(x) - f(y) \mid \cE(f) \leq 1\} - 1\\
    &= t R(x,y) - 1.
    \end{align*}
%
The inequality for $R_\infty$ can be inferred similarly. 
\end{proof}





